  if (t === "imp") { const st = d.imp || d.pres[3].replace(/ons$/, ""); return ENDS.imp.map(e => glue(st, e)); }
  if (t === "fut") return ENDS.fut.map(e => d.fut + e);
  if (t === "cond") return ENDS.cond.map(e => d.fut + e);
