/* ═══════════════════════════════════════════════════════════════════
   B1 lessons · part 1 — written for this app.
   Fields: rule{h,pts,ex,warn,vn}, cards[fr,en,exFr,exEn], sent[fr,en],
   nat[good,bad,why], mcq[q,answer,wrongs,why], gap[s,answers,hint,en,distractors],
   fix[s,bad,good,why,otherOptions], xf[instruction,from,to], chat[line,reply,wrongs,why]
   ═══════════════════════════════════════════════════════════════════ */
L({ id: "b1-pc-imp", lvl: "B1", tr: "recit", cat: "temps", t: "Passé composé ou imparfait", en: "Background and events in a past story",
  rule: { h: "The imparfait sets the scene; the passé composé moves the story forward.",
    pts: ["<b>Imparfait</b>: background, description, habits, actions in progress — <i>il faisait beau, j'habitais à Saïgon, je lisais</i>.",
      "<b>Passé composé</b>: completed events, one-off actions, a sequence of actions — <i>je suis sortie, j'ai pris le métro</i>.",
      "Together: an action in progress (imparfait) is interrupted by an event (passé composé) — <i>je dormais quand le téléphone a sonné</i>.",
      "Markers help: <i>soudain, tout à coup, un jour</i> → passé composé; <i>d'habitude, chaque été, autrefois</i> → imparfait."],
    ex: [["Quand j'étais petite, j'allais à la plage tous les dimanches.", "When I was little, I went to the beach every Sunday."], ["Il pleuvait quand nous sommes arrivés à Paris.", "It was raining when we arrived in Paris."], ["Hier, j'ai travaillé jusqu'à vingt heures.", "Yesterday I worked until 8 pm."], ["Je regardais un film quand Alex a appelé.", "I was watching a film when Alex called."]],
    warn: "Length does not decide the tense. <i>J'ai habité dix ans à Saïgon</i> is a closed period seen as a whole, so it takes the passé composé.",
    vn: "Tiếng Việt dùng <b>đã, đang</b> và ngữ cảnh. Tiếng Pháp bắt buộc phải chọn: <b>imparfait</b> ≈ «đang… / hồi đó thường…» (bối cảnh, thói quen); <b>passé composé</b> ≈ «đã… xong» (sự kiện)." },
  cards: [["autrefois", "in the past, formerly", "Autrefois, ce quartier était très calme.", "In the past, this area was very quiet."], ["d'habitude", "usually", "D'habitude, je prenais le bus.", "I usually took the bus."], ["soudain", "suddenly", "Soudain, la lumière s'est éteinte.", "Suddenly the light went out."], ["tout à coup", "all of a sudden", "Tout à coup, quelqu'un a frappé à la porte.", "All of a sudden someone knocked at the door."], ["un jour", "one day", "Un jour, j'ai reçu une lettre étrange.", "One day I received a strange letter."], ["à cette époque", "at that time", "À cette époque, je ne parlais pas français.", "At that time I didn't speak French."], ["pendant que", "while", "Pendant que je cuisinais, il mettait la table.", "While I was cooking, he was laying the table."], ["se rendre compte", "to realise", "Je me suis rendu compte que j'avais oublié mes clés.", "I realised I had forgotten my keys."]],
  sent: [["Quand nous sommes arrivés, il faisait déjà nuit.", "When we arrived, it was already dark."], ["Je travaillais à Hô Chi Minh-Ville quand j'ai rencontré Alex.", "I was working in Ho Chi Minh City when I met Alex."], ["Chaque été, ma famille allait à Vũng Tàu.", "Every summer my family went to Vũng Tàu."], ["Hier soir, nous avons dîné chez des amis.", "Last night we had dinner at some friends' place."], ["Le métro était bondé, alors j'ai marché.", "The metro was packed, so I walked."], ["Elle a vécu trois ans à Lyon.", "She lived in Lyon for three years."], ["Pendant que je lisais, le chat dormait sur le canapé.", "While I was reading, the cat was sleeping on the sofa."], ["Il était fatigué, mais il a fini son rapport.", "He was tired, but he finished his report."], ["Tout à coup, mon téléphone a sonné.", "Suddenly my phone rang."], ["Quand j'étais étudiante, je ne dormais pas beaucoup.", "When I was a student, I didn't sleep much."]],
  nat: [["Il faisait beau quand nous sommes partis.", "Il a fait beau quand nous partions.", "The weather is the background (imparfait); leaving is the event (passé composé)."], ["J'ai habité cinq ans à Lyon.", "J'habitais cinq ans à Lyon.", "A closed, measured period is seen as a whole: passé composé."], ["Je dormais quand tu as appelé.", "J'ai dormi quand tu appelais.", "The action in progress takes the imparfait; the interruption takes the passé composé."], ["D'habitude, elle prenait le bus.", "D'habitude, elle a pris le bus.", "A past habit takes the imparfait."]],
  mcq: [["Hier, je ___ au cinéma avec Alex.", "suis allée", ["allais", "vais", "irais"], "One completed event yesterday: passé composé. A woman speaking, so allée."], ["Quand j'étais petite, je ___ du piano.", "faisais", ["ai fait", "fais", "ferai"], "A childhood habit: imparfait."], ["Nous regardions la télé quand l'électricité ___.", "a été coupée", ["était coupée", "est coupée", "sera coupée"], "The event that interrupts takes the passé composé."], ["À cette époque, il n'y ___ pas de métro dans la ville.", "avait", ["a eu", "a", "aura"], "A description of the situation at the time: imparfait."]],
  gap: [["Il ___ quand je suis sortie.", "pleuvait", "pleuvoir", "It was raining when I went out.", ["a plu", "pleut", "pleuvra"]], ["Samedi dernier, nous ___ le musée d'Orsay.", "avons visité", "visiter", "Last Saturday we visited the Musée d'Orsay.", ["visitions", "visitons", "visiterons"]], ["Quand j'étais au lycée, je ___ beaucoup.", "lisais", "lire", "When I was at high school, I read a lot.", ["ai lu", "lis", "lirai"]], ["Soudain, le chat ___ sur la table.", "a sauté", "sauter", "Suddenly the cat jumped onto the table.", ["sautait", "saute", "sautera"]], ["Pendant que je ___, Alex préparait le café.", "m'habillais", "s'habiller", "While I was getting dressed, Alex was making coffee.", ["me suis habillée", "m'habille", "m'habillerai"]], ["Elle ___ ses clés et elle est partie.", "a pris", "prendre", "She took her keys and left.", ["prenait", "prend", "prendra"]]],
  fix: [["Quand j'ai été petite, j'habitais à Cần Thơ.", "j'ai été", "j'étais", "Childhood is a background state: imparfait.", ["je serai", "je suis"]], ["Hier, je travaillais toute la journée et puis je suis rentrée.", "je travaillais", "j'ai travaillé", "A completed day followed by another event: passé composé.", ["je travaille", "je travaillerai"]], ["Il faisait froid et le ciel était gris quand nous arrivions.", "nous arrivions", "nous sommes arrivés", "Arriving is the event; the weather is the background.", ["nous arrivons", "nous arriverons"]]],
  xf: [["Put it in the past: imparfait for the background, passé composé for the event.", "Il pleut. Je prends un taxi.", "Il pleuvait. J'ai pris un taxi.|Il pleuvait, j'ai pris un taxi.|Il pleuvait, alors j'ai pris un taxi."], ["Put it in the past.", "Je lis quand le téléphone sonne.", "Je lisais quand le téléphone a sonné."]],
  chat: [["Qu'est-ce que tu as fait ce week-end ?", "Samedi, il faisait beau, alors on est allés au parc.", ["Samedi, il a fait beau, alors on allait au parc.", "Samedi, il fait beau, alors on va au parc."], "Background in the imparfait, the event in the passé composé."], ["Tu habitais où avant Paris ?", "J'habitais à Hô Chi Minh-Ville, dans le troisième arrondissement.", ["J'habiterai à Hô Chi Minh-Ville.", "J'habite à Hô Chi Minh-Ville depuis demain."], "The question is about a past situation: answer in the imparfait."]]
});

L({ id: "b1-accord", lvl: "B1", tr: "recit", cat: "accords", t: "Être ou avoir, et l'accord", en: "Choosing the auxiliary and agreeing the past participle",
  rule: { h: "With être, the participle agrees with the subject; with avoir, it agrees only with a direct object placed before it.",
    pts: ["<b>Être</b> is used with about fifteen verbs of movement or change of state (aller, venir, partir, arriver, naître, mourir, rester, tomber, devenir…) and with all pronominal verbs (se lever, s'asseoir…).",
      "With être, add <b>-e</b> for a woman and <b>-s</b> for a plural: <i>elle est partie, nous sommes arrivés</i>.",
      "With avoir, no agreement with the subject: <i>elle a mangé</i>.",
      "With avoir, agree with a direct object placed <b>before</b> the verb (le, la, les, que…): <i>la robe que j'ai achetée, je les ai vus</i>."],
    ex: [["Lan Anh est arrivée à Paris en 2024.", "Lan Anh arrived in Paris in 2024."], ["Nous nous sommes levés tôt.", "We got up early."], ["Elle a acheté une robe.", "She bought a dress."], ["La robe qu'elle a achetée est rouge.", "The dress she bought is red."]],
    warn: "Some verbs change auxiliary when they have a direct object: <i>je suis sortie</i> (I went out) but <i>j'ai sorti la poubelle</i> (I took the bin out).",
    vn: "Tiếng Việt không có giống và số ở động từ. Trong tiếng Pháp, nếu chủ ngữ là nữ thì viết <b>-e</b> (elle est allé<b>e</b>). Khi nói thường không nghe khác, nhưng khi viết DELF bị chấm lỗi." },
  cards: [["arriver", "to arrive (être)", "Elle est arrivée en retard.", "She arrived late."], ["naître", "to be born (être)", "Je suis née à Hô Chi Minh-Ville.", "I was born in Ho Chi Minh City."], ["rester", "to stay (être)", "Nous sommes restés chez nous.", "We stayed at home."], ["tomber", "to fall (être)", "Elle est tombée dans l'escalier.", "She fell on the stairs."], ["devenir", "to become (être)", "Il est devenu professeur.", "He became a teacher."], ["se tromper", "to make a mistake", "Je me suis trompée de quai.", "I went to the wrong platform."], ["s'installer", "to settle, to move in", "Ils se sont installés à Montreuil.", "They moved to Montreuil."], ["sortir quelque chose", "to take something out (avoir)", "J'ai sorti les valises.", "I took the suitcases out."]],
  sent: [["Ma mère est venue à Paris l'année dernière.", "My mother came to Paris last year."], ["Nous sommes partis à sept heures.", "We left at seven."], ["Elle s'est inscrite à un cours de français.", "She enrolled in a French course."], ["Les photos que tu as prises sont magnifiques.", "The photos you took are beautiful."], ["Mes clés ? Je les ai laissées sur la table.", "My keys? I left them on the table."], ["Elles sont restées deux semaines au Viêt Nam.", "They stayed two weeks in Vietnam."], ["Je me suis réveillée trop tard.", "I woke up too late."], ["Alex a sorti le chat sur le balcon.", "Alex took the cat out onto the balcony."], ["Ils se sont rencontrés à Saïgon.", "They met in Saigon."], ["La lettre qu'il a écrite est très touchante.", "The letter he wrote is very moving."]],
  nat: [["Elle est partie hier.", "Elle a partie hier.", "Partir takes être."], ["Nous nous sommes promenés au bord de la Seine.", "Nous avons promené au bord de la Seine.", "Pronominal verbs take être: nous nous sommes promenés."], ["Les fleurs qu'il a offertes sont belles.", "Les fleurs qu'il a offert sont belles.", "Que (= les fleurs) is a direct object before avoir: agreement in -es."], ["Elle a mangé une soupe.", "Elle a mangée une soupe.", "With avoir, no agreement with the subject."]],
  mcq: [["Mes parents ___ au Viêt Nam en mars.", "sont rentrés", ["ont rentré", "sont rentré", "ont rentrés"], "Rentrer (to go home) takes être and agrees: sont rentrés."], ["Ces chaussures, je les ___ hier.", "ai achetées", ["ai acheté", "suis achetées", "ai achetés"], "Les (= ces chaussures, feminine plural) comes before avoir: achetées."], ["Elle ___ très tôt ce matin.", "s'est levée", ["a levé", "s'est levé", "est levée"], "Pronominal verb: être + agreement with elle."], ["Il ___ la poubelle avant de partir.", "a sorti", ["est sorti", "a sortie", "est sortie"], "With a direct object (la poubelle), sortir takes avoir."]],
  gap: [["Elle est ___ à Paris en septembre.", "arrivée", "arriver", "She arrived in Paris in September.", ["arrivé", "arrivés", "arrivées"]], ["Nous nous sommes ___ en 2022.", "rencontrés|rencontrées", "rencontrer", "We met in 2022.", ["rencontré", "rencontrer", "rencontrée"]], ["La maison qu'ils ont ___ est à Nice.", "achetée", "acheter", "The house they bought is in Nice.", ["acheté", "achetés", "achetées"]], ["Mes amies sont ___ tard.", "parties", "partir", "My (female) friends left late.", ["partis", "partie", "parti"]], ["Je me suis ___ de numéro.", "trompée|trompé", "se tromper", "I dialled the wrong number.", ["trompés", "tromper", "trompées"]], ["Les messages ? Je les ai ___ ce matin.", "lus", "lire", "The messages? I read them this morning.", ["lu", "lue", "lues"]]],
  fix: [["Hier, elle a allé chez le médecin.", "a allé", "est allée", "Aller takes être, and the participle agrees with elle.", ["est allé", "a allée"]], ["Les cadeaux qu'il a reçu sont arrivés.", "reçu", "reçus", "Que (= les cadeaux) comes before avoir: agreement in -s.", ["reçue", "reçues"]], ["Nous avons resté à la maison.", "avons resté", "sommes restés", "Rester takes être.", ["avons restés", "sommes resté"]]],
  xf: [["Rewrite with elle instead of il.", "Il est parti tôt et il s'est reposé.", "Elle est partie tôt et elle s'est reposée."], ["Replace la lettre with a pronoun.", "J'ai écrit la lettre.", "Je l'ai écrite."]],
  chat: [["Tu es arrivée quand en France ?", "Je suis arrivée en septembre 2024.", ["J'ai arrivé en septembre 2024.", "Je suis arrivé demain."], "Arriver takes être, and a woman writes arrivée."], ["Tu as vu mes lunettes ?", "Oui, je les ai mises dans ton sac.", ["Oui, je les ai mis dans ton sac.", "Oui, je suis mises dans ton sac."], "Les (= les lunettes, feminine plural) comes before avoir: mises."]]
});

L({ id: "b1-pqp", lvl: "B1", tr: "recit", cat: "temps", t: "Le plus-que-parfait", en: "Saying what had already happened",
  rule: { h: "The plus-que-parfait is a past before the past: avoir or être in the imparfait + past participle.",
    pts: ["Form: <i>j'avais fini, elle était partie, nous nous étions perdus</i>.", "Use it when one past action happened <b>before</b> another past action: <i>quand je suis arrivée, le film avait commencé</i>.", "Common with <i>déjà, pas encore, parce que, comme</i>: <i>il était fatigué parce qu'il n'avait pas dormi</i>.", "It is also used for a regret: <i>si seulement j'avais su !</i>"],
    ex: [["Quand nous sommes arrivés, le train était déjà parti.", "When we arrived, the train had already left."], ["Elle m'a dit qu'elle avait trouvé un travail.", "She told me she had found a job."], ["J'étais contente parce que j'avais réussi l'examen.", "I was happy because I had passed the exam."], ["Si seulement j'avais pris un parapluie !", "If only I had taken an umbrella!"]],
    warn: "Agreement rules are the same as for the passé composé: <i>elle était partie, les clés que j'avais perdues</i>.",
    vn: "Giống <b>«đã… rồi»</b> khi kể chuyện quá khứ: hành động xảy ra <b>trước</b> một hành động quá khứ khác. Ví dụ: Khi tôi đến thì tàu <b>đã chạy rồi</b> → le train <b>était parti</b>." },
  cards: [["déjà", "already", "Il était déjà parti.", "He had already left."], ["pas encore", "not yet", "Je n'avais pas encore mangé.", "I hadn't eaten yet."], ["la veille", "the day before", "La veille, j'avais préparé mon sac.", "The day before, I had packed my bag."], ["auparavant", "before, previously", "Elle n'était jamais venue auparavant.", "She had never come before."], ["oublier", "to forget", "J'avais oublié mon passeport.", "I had forgotten my passport."], ["prévenir", "to warn, to let know", "Personne ne m'avait prévenue.", "Nobody had told me."], ["rater", "to miss (a train), to fail", "Nous avions raté le dernier métro.", "We had missed the last metro."], ["regretter", "to regret", "Je regrette de ne pas être venue.", "I'm sorry I didn't come."]],
  sent: [["Quand je suis arrivée, la réunion avait déjà commencé.", "When I arrived, the meeting had already started."], ["Il m'a dit qu'il avait perdu son téléphone.", "He told me he had lost his phone."], ["Je n'avais jamais vu la neige avant de venir en France.", "I had never seen snow before coming to France."], ["Elle était épuisée parce qu'elle avait travaillé toute la nuit.", "She was exhausted because she had worked all night."], ["Nous avions réservé une table, heureusement.", "We had booked a table, luckily."], ["Ils étaient partis avant la fin du concert.", "They had left before the end of the concert."], ["Je pensais que tu avais reçu mon message.", "I thought you had received my message."], ["La veille, nous nous étions couchés très tard.", "The night before, we had gone to bed very late."], ["Comme il avait plu, la route était glissante.", "As it had rained, the road was slippery."], ["Si seulement je l'avais su plus tôt !", "If only I had known earlier!"]],
  nat: [["Quand je suis arrivée, il était déjà parti.", "Quand je suis arrivée, il est déjà parti.", "His leaving happened before my arrival: plus-que-parfait."], ["Elle a dit qu'elle avait fini.", "Elle a dit qu'elle a fini.", "In reported speech in the past, an earlier action becomes plus-que-parfait."], ["Nous avions oublié les billets.", "Nous étions oublié les billets.", "Oublier takes avoir."], ["Je n'avais pas encore dîné.", "Je n'ai pas encore dînais.", "Pas encore + plus-que-parfait: je n'avais pas encore dîné."]],
  mcq: [["Le film ___ quand nous sommes entrés dans la salle.", "avait commencé", ["commençait", "a commencé", "commencera"], "It started before we came in: plus-que-parfait."], ["Il était triste parce qu'il ___ son chat.", "avait perdu", ["perdait", "perdra", "perd"], "The loss happened before his sadness."], ["Elle m'a raconté qu'elle ___ au Japon l'été précédent.", "était allée", ["allait", "est allée", "ira"], "Earlier past in reported speech: plus-que-parfait with être."], ["Avant ce voyage, je n'___ jamais vu un si beau coucher de soleil.", "avais", ["étais", "aurai", "avait"], "Never before that moment in the past: plus-que-parfait with avoir."]],
  gap: [["Quand nous sommes arrivés, le train ___ déjà parti.", "était", "être or avoir?", "When we arrived, the train had already left.", ["avait", "est", "a"]], ["J'étais fatiguée parce que je n'avais pas ___.", "dormi", "dormir", "I was tired because I hadn't slept.", ["dormir", "dormais", "dors"]], ["Il a avoué qu'il ___ le rendez-vous.", "avait oublié", "oublier", "He admitted he had forgotten the appointment.", ["oubliait", "a oublié", "oubliera"]], ["Elle s'___ déjà couchée quand je l'ai appelée.", "était", "être or avoir?", "She had already gone to bed when I called her.", ["avait", "est", "a"]], ["Nous ___ une table pour huit heures.", "avions réservé", "réserver", "We had booked a table for eight.", ["étions réservés", "réservions", "avons réserver"]], ["Personne ne m'___.", "avait prévenue|avait prévenu", "prévenir", "Nobody had told me.", ["était prévenue", "prévenait", "a prévenir"]]],
  fix: [["Quand je suis rentrée, Alex a déjà préparé le dîner.", "a déjà préparé", "avait déjà préparé", "Dinner was ready before I came home: plus-que-parfait.", ["prépare déjà", "préparera déjà"]], ["Elle m'a dit qu'elle avait parti tôt.", "avait parti", "était partie", "Partir takes être, with agreement.", ["est partie", "avait partie"]], ["Il n'avait jamais prendre l'avion.", "prendre", "pris", "Compound tenses use the past participle.", ["prenait", "prend"]]],
  xf: [["Join the two sentences with quand, using the plus-que-parfait.", "Le spectacle commence. Puis nous arrivons.", "Quand nous sommes arrivés, le spectacle avait commencé.|Quand nous sommes arrivées, le spectacle avait commencé.|Quand nous sommes arrivés, le spectacle avait déjà commencé."], ["Report it in the past: Il a dit que…", "J'ai fini mon rapport.", "Il a dit qu'il avait fini son rapport."]],
  chat: [["Pourquoi tu es arrivée en retard ?", "J'avais raté le métro, donc j'ai dû attendre le suivant.", ["Je raterai le métro, donc j'attends.", "J'ai rater le métro."], "The missed metro came first: plus-que-parfait, then the passé composé."], ["Tu connaissais déjà Lyon ?", "Non, je n'y étais jamais allée avant ce voyage.", ["Non, je n'y vais jamais allée.", "Non, je n'y avais jamais aller."], "Never before that trip: plus-que-parfait."]]
});

L({ id: "b1-pronoms", lvl: "B1", tr: "phrase", cat: "pronoms", t: "Le, la, lui, leur", en: "Direct and indirect object pronouns",
  rule: { h: "Direct object (no preposition) → le, la, les. Indirect object (à + person) → lui, leur.",
    pts: ["Direct: <i>je vois <b>Alex</b> → je <b>le</b> vois</i>; <i>j'aime <b>ces chansons</b> → je <b>les</b> aime</i>.",
      "Indirect, with verbs built with <b>à quelqu'un</b> (parler, téléphoner, écrire, répondre, donner, demander, offrir…): <i>je parle <b>à ma mère</b> → je <b>lui</b> parle</i>.",
      "The pronoun goes <b>before the verb</b>, before the auxiliary in compound tenses, and before the infinitive: <i>je l'ai vu, je vais lui écrire</i>.",
      "Two pronouns together: <b>me/te/nous/vous → le/la/les → lui/leur</b>: <i>je te le donne, je le lui donne</i>.",
      "In a positive command, the pronoun follows with a hyphen: <i>appelle-<b>la</b>, donne-<b>lui</b>, dis-<b>le-moi</b></i>."],
    ex: [["Tu connais mes parents ? — Oui, je les connais.", "Do you know my parents? — Yes, I know them."], ["J'ai téléphoné à Claire. Je lui ai téléphoné.", "I phoned Claire. I phoned her."], ["Ce livre, je te le prête.", "This book, I'll lend it to you."], ["Écris-leur ce soir !", "Write to them tonight!"]],
    warn: "Some verbs are direct in French but not in English: <i>attendre, écouter, regarder, chercher</i> → <i>je l'attends</i> (I'm waiting <b>for</b> him). Others are indirect: <i>téléphoner à, répondre à, ressembler à</i> → <i>je lui réponds</i>.",
    vn: "Tiếng Việt thường lặp lại danh từ hoặc bỏ đi (Gặp mẹ chưa? — Gặp rồi). Tiếng Pháp phải dùng đại từ và đặt nó <b>trước động từ</b>: Je <b>l'</b>ai vue — «Tôi gặp bà <b>ấy</b> rồi»." },
  cards: [["le / la / les", "him, her, it, them (direct)", "Ce film, je l'ai vu deux fois.", "That film, I've seen it twice."], ["lui", "to him, to her", "Je lui ai envoyé un message.", "I sent him/her a message."], ["leur", "to them", "Nous leur avons offert des fleurs.", "We gave them flowers."], ["attendre quelqu'un", "to wait for someone", "Je t'attends devant la gare.", "I'm waiting for you outside the station."], ["répondre à", "to answer", "Elle ne m'a pas encore répondu.", "She hasn't answered me yet."], ["ressembler à", "to look like", "Elle ressemble à sa mère. Elle lui ressemble.", "She looks like her mother. She looks like her."], ["prêter", "to lend", "Tu peux me prêter ton stylo ?", "Can you lend me your pen?"], ["rendre", "to give back", "Je te le rends demain.", "I'll give it back to you tomorrow."]],
  sent: [["Ta sœur ? Je l'ai croisée au marché.", "Your sister? I ran into her at the market."], ["J'ai écrit à mes grands-parents et je leur ai envoyé des photos.", "I wrote to my grandparents and sent them photos."], ["Ce dossier, je vais le lire ce soir.", "This file, I'm going to read it tonight."], ["Tu peux lui dire que je serai en retard ?", "Can you tell him I'll be late?"], ["Les clés ? Je te les donne tout de suite.", "The keys? I'll give them to you right away."], ["Ne lui parle pas de la surprise !", "Don't talk to her about the surprise!"], ["Je ne les ai pas encore invités.", "I haven't invited them yet."], ["Alex m'a offert ce livre ; il me l'a offert pour mon anniversaire.", "Alex gave me this book; he gave it to me for my birthday."], ["Appelle-la avant midi.", "Call her before noon."], ["Nous l'attendons depuis vingt minutes.", "We've been waiting for him for twenty minutes."]],
  nat: [["Je lui téléphone ce soir.", "Je la téléphone ce soir.", "Téléphoner à quelqu'un → lui."], ["Je l'attends depuis une heure.", "Je lui attends depuis une heure.", "Attendre is direct: attendre quelqu'un → le/la."], ["Je le lui ai donné.", "Je lui l'ai donné.", "Order: le/la/les before lui/leur."], ["Dis-le-moi.", "Dis-moi-le.", "In a positive command: verb-le-moi."]],
  mcq: [["Tu as parlé à tes parents ? — Oui, je ___ ai parlé hier.", "leur", ["les", "lui", "leurs"], "Parler à + plural → leur (never leurs as a pronoun)."], ["Tu regardes la série ? — Oui, je ___ regarde tous les soirs.", "la", ["lui", "le", "leur"], "Regarder is direct; la série is feminine → la."], ["Le gâteau ? Je ___ ai apporté à Marie.", "le lui", ["lui le", "la lui", "le leur"], "Le (the cake) + lui (to Marie), in that order."], ["Tu as répondu à ton directeur ? — Non, je ne ___ ai pas encore répondu.", "lui", ["l'", "le", "leur"], "Répondre à quelqu'un → lui."]],
  gap: [["Mes amis ? Je ___ vois samedi.", "les", "", "My friends? I'm seeing them on Saturday.", ["leur", "lui", "leurs"]], ["Claire m'a écrit, mais je ne ___ ai pas répondu.", "lui", "", "Claire wrote to me, but I didn't answer her.", ["l'", "la", "leur"]], ["Cette chanson, je ___ adore !", "l'", "", "That song, I love it!", ["lui", "la", "le"]], ["Le contrat ? Je vous ___ envoie demain.", "l'", "", "The contract? I'll send it to you tomorrow.", ["lui", "le", "les"]], ["Tes parents ? Envoie-___ une carte !", "leur", "", "Your parents? Send them a card!", ["les", "lui", "leurs"]], ["La réunion ? Je ___ ai oubliée.", "l'", "", "The meeting? I forgot it.", ["lui", "la", "le"]]],
  fix: [["Je la ai vue hier.", "la ai", "l'ai", "Le/la elide before a vowel: je l'ai vue.", ["lui ai", "les ai"]], ["Mon frère ? Je le téléphone ce soir.", "le", "lui", "Téléphoner à quelqu'un → lui.", ["la", "les"]], ["Je vais les leurs envoyer.", "leurs", "leur", "The pronoun leur never takes an -s.", ["lui", "les"]]],
  xf: [["Replace the underlined words with pronouns: le livre, à Claire.", "J'ai prêté le livre à Claire.", "Je le lui ai prêté."], ["Make it a positive command with a pronoun.", "Tu dois appeler ta mère.", "Appelle-la.|Appelle-la !"]],
  chat: [["Tu as acheté les billets ?", "Oui, je les ai achetés ce matin.", ["Oui, je leur ai achetés ce matin.", "Oui, je lui ai acheté ce matin."], "Les billets is a direct object: les, and achetés agrees."], ["Tu as dit à Alex que le dîner est à huit heures ?", "Oui, je le lui ai dit.", ["Oui, je lui le ai dit.", "Oui, je l'ai dit lui."], "Le (that information) + lui (to Alex)."]]
});

L({ id: "b1-y-en", lvl: "B1", tr: "phrase", cat: "pronoms", t: "Les pronoms y et en", en: "Replacing places, quantities and de / à + thing",
  rule: { h: "En replaces de + something (and quantities); y replaces à + something (and places).",
    pts: ["<b>En</b> = <i>du, de la, des, de</i> + noun, or a quantity: <i>tu veux du café ? — oui, j'en veux. J'ai deux sœurs → j'en ai deux</i>.",
      "<b>En</b> with verbs built with <b>de</b>: parler de, avoir besoin de, s'occuper de: <i>j'en ai besoin</i>.",
      "<b>Y</b> = a place (à, en, chez, dans…): <i>je vais à Lyon → j'y vais</i>.",
      "<b>Y</b> with verbs built with <b>à + thing</b>: penser à, réfléchir à, s'intéresser à: <i>j'y pense</i>.",
      "For people, use <b>lui/leur</b> or <b>à lui, d'elle</b>: <i>je pense à Alex → je pense à lui</i>."],
    ex: [["Tu as des enfants ? — Non, je n'en ai pas.", "Do you have children? — No, I don't."], ["Tu vas à la banque ? — Oui, j'y vais cet après-midi.", "Are you going to the bank? — Yes, I'm going this afternoon."], ["Le mariage ? On en parle tous les jours.", "The wedding? We talk about it every day."], ["Ton examen ? N'y pense pas trop !", "Your exam? Don't think about it too much!"]],
    warn: "Keep the number with <i>en</i>: <i>j'ai trois valises → j'en ai trois</i>, not <i>je les ai trois</i>.",
    vn: "<b>y</b> và <b>en</b> không có từ tương đương trực tiếp trong tiếng Việt, vì tiếng Việt thường bỏ bổ ngữ (Đi Lyon chưa? — Đi rồi). Tiếng Pháp bắt buộc: J'<b>y</b> suis allée. Muốn bao nhiêu? — J'<b>en</b> veux deux." },
  cards: [["en", "some, of it, of them", "Des fraises ? J'en ai acheté un kilo.", "Strawberries? I bought a kilo."], ["y", "there, about it", "Paris ? J'y habite depuis deux ans.", "Paris? I've lived there for two years."], ["avoir besoin de", "to need", "Ton ordinateur ? J'en ai besoin ce soir.", "Your computer? I need it tonight."], ["penser à", "to think about", "Le voyage ? J'y pense souvent.", "The trip? I often think about it."], ["s'occuper de", "to take care of", "Les invitations ? Je m'en occupe.", "The invitations? I'll take care of them."], ["se souvenir de", "to remember", "Notre premier rendez-vous ? Je m'en souviens très bien.", "Our first date? I remember it very well."], ["tenir à", "to care about", "Cette bague ? J'y tiens beaucoup.", "This ring? It means a lot to me."], ["revenir de", "to come back from", "Le Viêt Nam ? J'en reviens à peine.", "Vietnam? I've only just come back from there."]],
  sent: [["Du pain ? Il en reste un peu.", "Bread? There's a little left."], ["Le marché ? J'y vais tous les samedis.", "The market? I go every Saturday."], ["Des photos du mariage ? On en a pris des centaines.", "Photos of the wedding? We took hundreds."], ["Ce projet ? Elle y travaille depuis six mois.", "This project? She's been working on it for six months."], ["Tu as besoin d'aide ? — Non, je n'en ai pas besoin, merci.", "Do you need help? — No, I don't, thanks."], ["La réunion de lundi ? Je n'y serai pas.", "Monday's meeting? I won't be there."], ["Le café vietnamien ? J'en bois un tous les matins.", "Vietnamese coffee? I drink one every morning."], ["La Bretagne ? Nous y sommes allés l'été dernier.", "Brittany? We went there last summer."], ["Les impôts ? Alex s'en occupe.", "Taxes? Alex deals with them."], ["Ta proposition ? J'y réfléchis encore.", "Your proposal? I'm still thinking it over."]],
  nat: [["J'ai deux frères. J'en ai deux.", "J'ai deux frères. Je les ai deux.", "With a number, use en and keep the number."], ["Je vais à Nice. J'y vais demain.", "Je vais à Nice. J'en vais demain.", "A destination is replaced by y."], ["Je pense à ma grand-mère. Je pense à elle.", "Je pense à ma grand-mère. J'y pense.", "For a person after penser à, use à + stressed pronoun."], ["Le dossier ? Je m'en occupe.", "Le dossier ? Je m'y occupe.", "S'occuper de → en."]],
  mcq: [["Tu veux du thé ? — Oui, j'___ veux bien.", "en", ["y", "le", "lui"], "Du thé (de + thing) → en."], ["Tu es déjà allée à Marseille ? — Non, je n'___ suis jamais allée.", "y", ["en", "l'", "lui"], "A place → y."], ["Tu te souviens de cette chanson ? — Oui, je m'___ souviens.", "en", ["y", "la", "lui"], "Se souvenir de → en."], ["Tu t'intéresses à la politique ? — Oui, je m'___ intéresse beaucoup.", "y", ["en", "la", "lui"], "S'intéresser à + thing → y."]],
  gap: [["Des pommes ? J'___ ai acheté trois.", "en", "", "Apples? I bought three.", ["y", "les", "lui"]], ["Le bureau ? J'___ arrive dans dix minutes.", "y", "", "The office? I'll be there in ten minutes.", ["en", "le", "lui"]], ["Ton passeport ? Tu ___ as besoin pour voyager.", "en", "", "Your passport? You need it to travel.", ["y", "le", "lui"]], ["Ce problème ? Je n'___ ai pas pensé.", "y", "", "This problem? I didn't think of it.", ["en", "le", "lui"]], ["Du fromage ? Il n'___ reste plus.", "en", "", "Cheese? There's none left.", ["y", "le", "lui"]], ["Le Japon ? Ils ___ sont partis hier.", "y", "", "Japan? They left for it yesterday.", ["en", "le", "lui"]]],
  fix: [["Des enfants ? Elle les a trois.", "les a", "en a", "A quantity is replaced by en: elle en a trois.", ["y a", "leur a"]], ["Lyon ? J'en vais la semaine prochaine.", "J'en", "J'y", "A destination is replaced by y.", ["Je le", "Je lui"]], ["Ma mère ? J'y pense souvent.", "J'y pense souvent", "Je pense souvent à elle", "For a person, use à + elle.", ["Je lui pense souvent", "J'en pense souvent"]]],
  xf: [["Replace the words in bold with y or en: de l'eau.", "Je bois de l'eau.", "J'en bois."], ["Answer in the negative with y.", "Tu vas au cinéma ce soir ?", "Non, je n'y vais pas.|Non, je n'y vais pas ce soir."]],
  chat: [["Il reste des croissants ?", "Oui, il en reste deux.", ["Oui, il les reste deux.", "Oui, il y reste deux."], "Quantity: en + number."], ["Tu penses encore à ton entretien d'embauche ?", "Oui, j'y pense tout le temps.", ["Oui, j'en pense tout le temps.", "Oui, je lui pense tout le temps."], "Penser à + thing → y."]]
});

L({ id: "b1-relatifs", lvl: "B1", tr: "phrase", cat: "relatifs", t: "Qui, que, où, dont", en: "Simple relative pronouns",
  rule: { h: "Choose the relative pronoun by the role it plays in the second clause.",
    pts: ["<b>Qui</b> = subject: <i>la femme <b>qui</b> parle est ma collègue</i>.", "<b>Que (qu')</b> = direct object: <i>le livre <b>que</b> je lis est passionnant</i>.", "<b>Où</b> = place or time: <i>la ville <b>où</b> je suis née, le jour <b>où</b> nous nous sommes rencontrés</i>.", "<b>Dont</b> replaces <b>de</b> + noun: <i>le collègue <b>dont</b> je t'ai parlé</i> (parler de), <i>la robe <b>dont</b> j'ai envie</i> (avoir envie de)."],
    ex: [["C'est Alex qui a choisi le restaurant.", "It was Alex who chose the restaurant."], ["Le film que nous avons vu était drôle.", "The film we saw was funny."], ["C'est le quartier où j'ai grandi.", "It's the area where I grew up."], ["Voici le livre dont tout le monde parle.", "Here is the book everybody is talking about."]],
    warn: "English often drops the relative pronoun (<i>the film we saw</i>). French never does: <i>le film <b>que</b> nous avons vu</i>.",
    vn: "Giống <b>«mà»</b> hoặc <b>«nơi mà»</b> trong tiếng Việt, nhưng tiếng Pháp phải chọn theo chức năng: <b>qui</b> (chủ ngữ), <b>que</b> (tân ngữ), <b>où</b> (nơi chốn, thời gian), <b>dont</b> (thay cho de + danh từ)." },
  cards: [["qui", "who, which (subject)", "J'ai une amie qui parle cinq langues.", "I have a friend who speaks five languages."], ["que", "that, whom (object)", "La chanson que tu chantes est belle.", "The song you are singing is beautiful."], ["où", "where, when", "Le jour où je suis arrivée, il neigeait.", "The day I arrived, it was snowing."], ["dont", "of which, whose, about which", "C'est un projet dont je suis fière.", "It's a project I'm proud of."], ["avoir envie de", "to feel like, to want", "Le voyage dont j'ai envie coûte cher.", "The trip I want is expensive."], ["être fier de", "to be proud of", "C'est le résultat dont elle est fière.", "It's the result she is proud of."], ["ce qui", "what (subject)", "Ce qui me plaît, c'est la lumière.", "What I like is the light."], ["ce que", "what (object)", "Ce que je préfère, c'est le marché.", "What I prefer is the market."]],
  sent: [["La collègue qui m'a aidée s'appelle Sophie.", "The colleague who helped me is called Sophie."], ["Le cours que je suis le mardi est très utile.", "The class I take on Tuesdays is very useful."], ["C'est le café où nous nous sommes rencontrés.", "It's the café where we met."], ["L'application dont je t'ai parlé est gratuite.", "The app I told you about is free."], ["Ce que j'aime à Paris, ce sont les petites librairies.", "What I like in Paris are the little bookshops."], ["Je cherche un appartement qui a un balcon.", "I'm looking for a flat that has a balcony."], ["La ville où elle est née s'appelle Đà Lạt.", "The town where she was born is called Đà Lạt."], ["C'est un souvenir dont je me souviendrai toujours.", "It's a memory I will always remember."], ["Le cadeau qu'il m'a offert est magnifique.", "The present he gave me is beautiful."], ["Ce qui m'inquiète, c'est le prix des loyers.", "What worries me is the price of rents."]],
  nat: [["Le livre que je lis est long.", "Le livre qui je lis est long.", "Je is the subject; the book is the object of lis → que."], ["La femme qui habite en face est médecin.", "La femme que habite en face est médecin.", "The woman is the subject of habite → qui."], ["Le film dont tu parles est sorti hier.", "Le film que tu parles est sorti hier.", "Parler de → dont."], ["La maison où j'ai grandi est à Cần Thơ.", "La maison que j'ai grandi est à Cần Thơ.", "A place → où."]],
  mcq: [["C'est la professeure ___ m'a appris le subjonctif.", "qui", ["que", "dont", "où"], "She is the subject of a appris."], ["Voici le restaurant ___ nous avons fêté nos fiançailles.", "où", ["que", "dont", "qui"], "A place → où."], ["C'est un sujet ___ on parle beaucoup en ce moment.", "dont", ["que", "où", "qui"], "Parler de → dont."], ["La robe ___ elle porte vient de Hội An.", "qu'", ["qui", "dont", "où"], "Elle is the subject; la robe is the object → qu'."]],
  gap: [["J'ai un voisin ___ joue du piano tous les soirs.", "qui", "", "I have a neighbour who plays the piano every evening.", ["que", "dont", "où"]], ["Le plat ___ je préfère, c'est le phở.", "que", "", "The dish I prefer is phở.", ["qui", "dont", "où"]], ["L'hôtel ___ nous avons dormi était près de la mer.", "où", "", "The hotel where we slept was near the sea.", ["que", "dont", "qui"]], ["C'est le document ___ j'ai besoin.", "dont", "", "It's the document I need.", ["que", "où", "qui"]], ["___ me fait peur, c'est l'examen oral.", "Ce qui", "", "What scares me is the oral exam.", ["Ce que", "Ce dont", "Qui"]], ["___ je voudrais, c'est un peu de calme.", "Ce que", "", "What I would like is a bit of quiet.", ["Ce qui", "Ce dont", "Que"]]],
  fix: [["C'est le film que tout le monde parle.", "que", "dont", "Parler de → dont.", ["qui", "où"]], ["Le jour que je suis arrivée, il pleuvait.", "que", "où", "With a time expression (le jour, l'année), French uses où.", ["dont", "qui"]], ["La personne que m'a appelée est ma tante.", "que", "qui", "The person is the subject of a appelée → qui.", ["dont", "où"]]],
  xf: [["Join the sentences with dont.", "J'ai rencontré un collègue. Je t'ai parlé de ce collègue.", "J'ai rencontré le collègue dont je t'ai parlé.|J'ai rencontré un collègue dont je t'ai parlé."], ["Join the sentences with où.", "Voici le parc. Nous nous promenons dans ce parc le dimanche.", "Voici le parc où nous nous promenons le dimanche."]],
  chat: [["Tu as aimé le restaurant ?", "Oui, c'est le meilleur restaurant où je sois allée cette année.", ["Oui, c'est le meilleur restaurant que je suis allée.", "Oui, c'est le meilleur restaurant dont je suis allée."], "A place → où. (After a superlative, the subjunctive sois is elegant.)"], ["De quoi tu as besoin pour ton dossier ?", "Ce dont j'ai besoin, c'est d'une lettre de recommandation.", ["Ce que j'ai besoin, c'est une lettre.", "Ce qui j'ai besoin, c'est une lettre."], "Avoir besoin de → ce dont."]]
});

L({ id: "b1-negation", lvl: "B1", tr: "phrase", cat: "negation", t: "Les négations", en: "ne… jamais, plus, rien, personne, aucun, que",
  rule: { h: "Ne goes before the verb; the second word tells you what kind of negation it is.",
    pts: ["<i>ne… pas</i> (not), <i>ne… jamais</i> (never), <i>ne… plus</i> (no longer), <i>ne… rien</i> (nothing), <i>ne… personne</i> (nobody), <i>ne… aucun(e)</i> (no, not any), <i>ne… ni… ni</i> (neither… nor).",
      "<i>Ne… que</i> is not a negation: it means <b>only</b>: <i>je n'ai que dix euros</i>.",
      "In compound tenses, <i>pas, jamais, plus, rien</i> go before the participle, but <i>personne</i> and <i>aucun</i> go after: <i>je n'ai rien vu</i> / <i>je n'ai vu personne</i>.",
      "Rien and personne can be subjects: <i>personne n'est venu, rien ne marche</i>.",
      "In spoken French, <i>ne</i> often disappears (<i>je sais pas</i>). Always write it in the exam."],
    ex: [["Je ne bois jamais de café le soir.", "I never drink coffee in the evening."], ["Elle n'habite plus à Saïgon.", "She no longer lives in Saigon."], ["Je n'ai vu personne.", "I didn't see anyone."], ["Il ne reste que deux places.", "There are only two seats left."]],
    warn: "After a negation, <i>un, une, du, de la, des</i> become <b>de</b>: <i>j'ai des frères → je n'ai pas de frères</i>. Exception: with être, <i>ce n'est pas un problème</i>.",
    vn: "Tiếng Việt chỉ cần một từ (<b>không, chưa, chẳng</b>). Tiếng Pháp cần <b>hai phần</b>: ne… pas, ne… jamais (không bao giờ), ne… plus (không còn), ne… rien (không gì cả), ne… personne (không ai)." },
  cards: [["ne… jamais", "never", "Il ne prend jamais l'avion.", "He never takes the plane."], ["ne… plus", "no longer, not any more", "Je ne fume plus.", "I don't smoke any more."], ["ne… rien", "nothing", "Je n'ai rien compris.", "I didn't understand anything."], ["ne… personne", "nobody", "Il n'y a personne à la maison.", "There's nobody at home."], ["ne… aucun", "no, not a single", "Je n'ai aucune idée.", "I have no idea."], ["ne… que", "only", "Je n'ai qu'une semaine de vacances.", "I only have one week of holiday."], ["ne… ni… ni", "neither… nor", "Elle ne mange ni viande ni poisson.", "She eats neither meat nor fish."], ["pas encore", "not yet", "Je n'ai pas encore fini.", "I haven't finished yet."]],
  sent: [["Je ne suis jamais allée en Corse.", "I've never been to Corsica."], ["Il n'y a plus de lait dans le frigo.", "There's no more milk in the fridge."], ["Personne ne m'a prévenue du changement.", "Nobody told me about the change."], ["Je n'ai rien acheté au marché.", "I didn't buy anything at the market."], ["Nous n'avons aucune nouvelle de lui.", "We have no news of him."], ["Elle ne parle que vietnamien avec sa mère.", "She only speaks Vietnamese with her mother."], ["Rien ne s'est passé comme prévu.", "Nothing went as planned."], ["Je ne connais personne dans ce quartier.", "I don't know anyone in this area."], ["Il ne boit ni thé ni café.", "He drinks neither tea nor coffee."], ["Ce n'est pas un problème.", "It's not a problem."]],
  nat: [["Je n'ai pas de voiture.", "Je n'ai pas une voiture.", "After a negation, un/une/des → de."], ["Je n'ai vu personne.", "Je n'ai personne vu.", "Personne goes after the participle."], ["Je n'ai rien mangé.", "Je n'ai mangé rien.", "Rien goes before the participle."], ["Personne n'est venu.", "Personne est venu.", "In writing, ne is required: personne n'est venu."]],
  mcq: [["Tu as encore faim ? — Non, je n'ai ___ faim.", "plus", ["jamais", "rien", "personne"], "No longer → ne… plus."], ["Tu as entendu quelque chose ? — Non, je n'ai ___ entendu.", "rien", ["personne", "aucun", "plus"], "Something → nothing: rien."], ["Il y avait du monde ? — Non, il n'y avait ___.", "personne", ["rien", "jamais", "aucun"], "People → nobody: personne."], ["Elle n'a ___ ami à Paris.", "aucun", ["aucune", "personne", "rien"], "Ami is masculine → aucun."]],
  gap: [["Je ne mange ___ de viande, je suis végétarienne.", "jamais|pas", "", "I never eat meat, I'm vegetarian.", ["rien", "personne", "aucun"]], ["Il n'y a ___ dans la salle : elle est vide.", "personne", "", "There's nobody in the room: it's empty.", ["rien", "aucun", "plus"]], ["Je n'ai ___ dix minutes, fais vite !", "que", "", "I only have ten minutes, be quick!", ["pas", "rien", "plus"]], ["Ce restaurant n'existe ___ : il a fermé.", "plus", "", "This restaurant no longer exists: it closed.", ["jamais", "rien", "que"]], ["Je n'ai ___ idée de l'heure.", "aucune", "", "I have no idea of the time.", ["aucun", "personne", "rien"]], ["___ ne fonctionne dans cet appartement !", "Rien", "", "Nothing works in this flat!", ["Personne", "Aucun", "Jamais"]]],
  fix: [["Je n'ai pas des enfants.", "pas des enfants", "pas d'enfants", "After a negation, des → de (d' before a vowel).", ["pas les enfants", "pas aucuns enfants"]], ["Je ne connais rien personne ici.", "rien personne", "personne", "One negation word is enough: je ne connais personne.", ["rien", "pas personne"]], ["Elle n'a mangé rien.", "n'a mangé rien", "n'a rien mangé", "Rien goes before the participle.", ["n'a mangé personne", "a rien mangé"]]],
  xf: [["Make it negative with ne… plus.", "J'habite à Lyon.", "Je n'habite plus à Lyon."], ["Make it negative.", "J'ai des questions.", "Je n'ai pas de questions.|Je n'ai aucune question."]],
  chat: [["Tu veux encore un peu de gâteau ?", "Non merci, je n'ai plus faim.", ["Non merci, je n'ai jamais faim.", "Non merci, j'ai plus pas faim."], "No longer hungry: ne… plus."], ["Quelqu'un a appelé pendant mon absence ?", "Non, personne n'a appelé.", ["Non, personne a appelé rien.", "Non, rien n'a appelé."], "Personne as the subject: personne n'a appelé."]]
});

L({ id: "b1-futur", lvl: "B1", tr: "futur", cat: "temps", t: "Le futur", en: "Futur proche, futur simple, and quand + futur",
  rule: { h: "Futur proche for what is planned or about to happen; futur simple for predictions, promises and more distant plans.",
    pts: ["<b>Futur proche</b>: aller + infinitive: <i>je vais appeler ma mère</i>.", "<b>Futur simple</b>: stem + <i>-ai, -as, -a, -ons, -ez, -ont</i>. Regular stem = the infinitive (minus final -e): <i>je parlerai, je prendrai</i>.", "Irregular stems to know: <i>être → ser-, avoir → aur-, aller → ir-, faire → fer-, venir → viendr-, voir → verr-, pouvoir → pourr-, vouloir → voudr-, devoir → devr-, savoir → saur-, falloir → faudr-</i>.", "After <b>quand, lorsque, dès que</b> referring to the future, French uses the future (English uses the present): <i>quand je serai à Paris, je t'appellerai</i>."],
    ex: [["Attention, tu vas tomber !", "Careful, you're going to fall!"], ["Nous nous marierons à Saïgon.", "We will get married in Saigon."], ["Quand j'aurai le DELF B2, je chercherai un nouveau poste.", "When I have the DELF B2, I'll look for a new job."], ["Il fera beau demain dans le sud.", "It will be fine tomorrow in the south."]],
    warn: "<i>Quand je <b>serai</b> à Paris</i>, not <i>quand je suis à Paris</i>, when you mean the future. After <b>si</b>, though, use the present: <i>si tu viens, je serai contente</i>.",
    vn: "Tiếng Việt dùng <b>sẽ</b> hoặc <b>sắp</b>. Gần giống: <b>sắp</b> ≈ futur proche (je vais partir), <b>sẽ</b> ≈ futur simple (je partirai). Nhưng sau <b>quand</b> tiếng Pháp vẫn dùng thì tương lai." },
  cards: [["bientôt", "soon", "Je finirai bientôt mon master.", "I will soon finish my master's."], ["dans deux ans", "in two years' time", "Dans deux ans, nous vivrons peut-être ailleurs.", "In two years we may be living elsewhere."], ["dès que", "as soon as", "Je t'écris dès que j'arrive.", "I'll write as soon as I arrive."], ["lorsque", "when (formal)", "Lorsque vous recevrez ce courrier, merci de répondre.", "When you receive this letter, please reply."], ["prévoir", "to plan, to forecast", "On prévoit de la pluie pour demain.", "Rain is forecast for tomorrow."], ["avoir l'intention de", "to intend to", "J'ai l'intention de passer le DELF en juin.", "I intend to take the DELF in June."], ["compter + infinitif", "to plan to, to expect to", "Nous comptons partir en août.", "We plan to leave in August."], ["un projet", "a plan, a project", "Quels sont vos projets pour l'été ?", "What are your plans for the summer?"]],
  sent: [["Je vais préparer le dîner, tu as faim ?", "I'm going to make dinner, are you hungry?"], ["Nous partirons au Viêt Nam en décembre.", "We will leave for Vietnam in December."], ["Quand tu seras prête, appelle-moi.", "When you're ready, call me."], ["Il faudra réserver la salle très tôt.", "We'll have to book the venue very early."], ["Je pourrai t'aider samedi.", "I'll be able to help you on Saturday."], ["Dès qu'il aura son diplôme, il cherchera un travail.", "As soon as he has his degree, he'll look for a job."], ["Tu verras, ce sera une belle fête.", "You'll see, it will be a lovely party."], ["Mes parents viendront à Paris au printemps.", "My parents will come to Paris in the spring."], ["Le train va partir, dépêche-toi !", "The train is about to leave, hurry up!"], ["Nous saurons les résultats dans un mois.", "We'll know the results in a month."]],
  nat: [["Quand je serai à Lyon, je t'appellerai.", "Quand je suis à Lyon, je t'appellerai.", "After quand referring to the future, use the future."], ["Si tu viens, je serai contente.", "Si tu viendras, je serai contente.", "After si, never the future: use the present."], ["Elle viendra demain.", "Elle venira demain.", "Venir has the irregular stem viendr-."], ["Nous irons à la mer.", "Nous allerons à la mer.", "Aller has the irregular stem ir-."]],
  mcq: [["L'année prochaine, je ___ en master.", "serai", ["suis", "serais", "étais"], "A future fact: futur simple of être."], ["Quand tu ___ le temps, lis ce livre.", "auras", ["as", "aurais", "avais"], "Quand + future meaning → futur."], ["Regarde ces nuages : il ___ pleuvoir.", "va", ["ira", "allait", "irait"], "Something about to happen, with a visible sign: futur proche."], ["Nous ___ vous voir dès que possible.", "viendrons", ["venirons", "venons", "viendrions"], "Venir → viendr-."]],
  gap: [["Demain, il ___ beau.", "fera", "faire", "Tomorrow it will be fine.", ["faira", "fait", "ferait"]], ["Quand je ___ mon diplôme, je fêterai ça.", "aurai", "avoir", "When I get my degree, I'll celebrate.", ["ai", "aurais", "avrai"]], ["Tu ___ me dire quand tu arrives ?", "pourras", "pouvoir", "Will you be able to tell me when you arrive?", ["pouvras", "peux", "pourrais"]], ["Ils ___ à Paris le 3 mai.", "arriveront", "arriver", "They will arrive in Paris on 3 May.", ["arrivent", "arriveraient", "arrivaient"]], ["Dès que nous ___ les billets, nous te dirons.", "aurons", "avoir", "As soon as we have the tickets, we'll tell you.", ["avons", "aurions", "avions"]], ["Il ___ partir avant six heures.", "faudra", "falloir", "We'll have to leave before six.", ["fallra", "faut", "faudrait"]]],
  fix: [["Quand je suis grande, je serai médecin.", "suis", "serai", "Quand + future → futur simple.", ["serais", "étais"]], ["Si il fera beau, nous irons à la plage.", "Si il fera", "S'il fait", "After si, use the present; si + il → s'il.", ["S'il fera", "Si il fait"]], ["Je voirai mes amis demain.", "voirai", "verrai", "Voir → verr-.", ["vois", "voyerai"]]],
  xf: [["Put it in the futur simple.", "Je vais finir ce rapport demain.", "Je finirai ce rapport demain."], ["Put it in the future, with quand.", "Quand je suis à Saïgon, je mange du phở.", "Quand je serai à Saïgon, je mangerai du phở."]],
  chat: [["Qu'est-ce que vous ferez après le mariage ?", "Nous partirons une semaine à Phú Quốc.", ["Nous partons hier à Phú Quốc.", "Nous partirions une semaine si Phú Quốc."], "A plan after an event: futur simple."], ["Tu m'appelles quand tu arrives ?", "Oui, je t'appellerai dès que je serai à la gare.", ["Oui, je t'appelle dès que je suis arrivée demain.", "Oui, je t'appellerais dès que j'étais à la gare."], "Dès que + future meaning → futur."]]
});

/* ── data/b1b.js ── */
/* B1 lessons · part 2 */
L({ id: "b1-cond", lvl: "B1", tr: "futur", cat: "temps", t: "Le conditionnel présent", en: "Politeness, wishes, advice and imagination",
  rule: { h: "The conditionnel = future stem + imparfait endings (-ais, -ais, -ait, -ions, -iez, -aient).",
    pts: ["Same stem as the future: <i>je voudrais, j'aimerais, tu pourrais, il faudrait, nous serions, ils auraient</i>.", "<b>Politeness</b>: <i>je voudrais un café, pourriez-vous m'aider ?</i>", "<b>Wishes</b>: <i>j'aimerais vivre près de la mer</i>.", "<b>Advice</b>: <i>tu devrais te reposer, à ta place, je prendrais le train</i>.", "<b>Unconfirmed information</b> (press): <i>le président serait malade</i>."],
    ex: [["Je voudrais réserver une table pour deux.", "I would like to book a table for two."], ["Tu devrais appeler ta mère.", "You should call your mother."], ["À ta place, je n'accepterais pas.", "If I were you, I wouldn't accept."], ["Ce serait génial de partir ensemble.", "It would be great to go away together."]],
    warn: "Do not confuse <i>je voudrai</i> (future, I will want) and <i>je voudrais</i> (conditional, I would like). The difference is one letter, and in speech the sound is almost the same.",
    vn: "Giống <b>«muốn… / nên… / sẽ…»</b> nói lịch sự. Trong tiếng Việt ta thêm <b>ạ, dạ, làm ơn</b>; tiếng Pháp đổi động từ: <i>je veux</i> (tôi muốn — hơi cộc) → <i>je voudrais</i> (tôi muốn ạ)." },
  cards: [["je voudrais", "I would like", "Je voudrais un renseignement, s'il vous plaît.", "I'd like some information, please."], ["j'aimerais", "I would love to", "J'aimerais apprendre à nager.", "I would love to learn to swim."], ["tu devrais", "you should", "Tu devrais dormir un peu.", "You should sleep a little."], ["il faudrait", "we/one should, it would be necessary", "Il faudrait acheter du pain.", "We should buy some bread."], ["pourriez-vous", "could you (formal)", "Pourriez-vous répéter, s'il vous plaît ?", "Could you repeat, please?"], ["à ta place", "if I were you", "À ta place, je dirais la vérité.", "If I were you, I'd tell the truth."], ["ça me plairait", "I would like that", "Un week-end à Bruxelles ? Ça me plairait beaucoup.", "A weekend in Brussels? I'd love that."], ["avoir envie de", "to feel like", "J'aurais envie d'un bol de phở.", "I'd feel like a bowl of phở."]],
  sent: [["Je voudrais deux billets pour Lyon, s'il vous plaît.", "I'd like two tickets to Lyon, please."], ["Pourriez-vous m'envoyer le document par e-mail ?", "Could you send me the document by email?"], ["On pourrait aller au cinéma ce soir.", "We could go to the cinema tonight."], ["Tu devrais demander conseil à ta collègue.", "You should ask your colleague for advice."], ["J'aimerais bien visiter la Normandie.", "I'd really like to visit Normandy."], ["Ce serait plus simple de prendre le RER.", "It would be simpler to take the RER."], ["À votre place, je réserverais dès maintenant.", "If I were you, I'd book right now."], ["Il faudrait que tu te reposes.", "You ought to rest."], ["Ça te dirait de dîner chez nous samedi ?", "Would you like to have dinner with us on Saturday?"], ["Selon la presse, le musée fermerait pendant deux ans.", "According to the press, the museum may close for two years."]],
  nat: [["Je voudrais un thé, s'il vous plaît.", "Je veux un thé.", "In a café, the conditional is the polite form."], ["Tu devrais te reposer.", "Tu devras te reposer.", "Advice → conditional (devrais), not future (devras)."], ["Pourriez-vous fermer la fenêtre ?", "Pouvriez-vous fermer la fenêtre ?", "Pouvoir → pourr- in the conditional."], ["Ce serait gentil de m'aider.", "Ce sera gentil de m'aider hier.", "A polite request: conditional."]],
  mcq: [["___-vous me dire où est la gare, s'il vous plaît ?", "Pourriez", ["Pourrez", "Pouviez", "Pourrions"], "Polite request: conditional."], ["Si j'étais toi, je ___ ce poste.", "prendrais", ["prendrai", "prends", "prenais"], "Advice/imagination: conditional."], ["Nous ___ bien venir, mais nous travaillons.", "aimerions", ["aimerons", "aimons", "aimions"], "A wish that cannot happen: conditional."], ["D'après les journaux, l'accident ___ dû à la pluie.", "serait", ["sera", "est", "était"], "Unconfirmed news: journalistic conditional."]],
  gap: [["Je ___ parler au responsable, s'il vous plaît.", "voudrais", "vouloir", "I'd like to speak to the manager, please.", ["voudrai", "veux", "voulais"]], ["Tu ___ mettre un manteau, il fait froid.", "devrais", "devoir", "You should put on a coat, it's cold.", ["devras", "dois", "devais"]], ["Il ___ partir plus tôt pour éviter les bouchons.", "faudrait", "falloir", "We should leave earlier to avoid the traffic.", ["faudra", "faut", "fallait"]], ["Ça ___ génial de se revoir !", "serait", "être", "It would be great to see each other again!", ["sera", "est", "était"]], ["Vous ___ un stylo à me prêter ?", "auriez", "avoir", "Would you have a pen to lend me?", ["aurez", "avez", "aviez"]], ["Nous ___ visiter Hanoï l'année prochaine.", "aimerions", "aimer", "We would like to visit Hanoi next year.", ["aimerons", "aimons", "aimions"]]],
  fix: [["Je voudrai un croissant, s'il vous plaît.", "voudrai", "voudrais", "A polite request in a shop: conditional, with -s.", ["veux", "voulais"]], ["Vous pouvriez m'aider ?", "pouvriez", "pourriez", "Pouvoir → pourr-.", ["pouviez", "pourrez"]], ["Tu devras voir un médecin, à mon avis.", "devras", "devrais", "Advice → conditional.", ["dois", "devais"]]],
  xf: [["Make the request more polite.", "Je veux un rendez-vous demain.", "Je voudrais un rendez-vous demain.|J'aimerais un rendez-vous demain.|Je voudrais un rendez-vous pour demain."], ["Give the same advice with à ta place.", "Tu dois parler à ton chef.", "À ta place, je parlerais à mon chef.|À ta place, je parlerais à ton chef."]],
  chat: [["Bonjour, vous désirez ?", "Je voudrais un café crème et un croissant, s'il vous plaît.", ["Je voudrai un café crème.", "Donnez café."], "In a café, je voudrais is the natural polite form."], ["Je ne sais pas si je dois accepter cette offre.", "À ta place, j'accepterais : c'est une belle opportunité.", ["À ta place, j'accepterai.", "À ta place, j'acceptais."], "Advice with à ta place takes the conditional."]]
});

L({ id: "b1-si", lvl: "B1", tr: "futur", cat: "hypothese", t: "Si + présent, si + imparfait", en: "Real and imaginary conditions",
  rule: { h: "Si + présent → futur (a real possibility). Si + imparfait → conditionnel (an imaginary situation).",
    pts: ["<b>Real</b>: <i>s'il pleut demain, nous resterons à la maison</i>.", "<b>Imaginary or unlikely</b>: <i>si j'avais une maison, j'aurais un chien</i>.", "Never put the future or the conditional right after <b>si</b> in these sentences.", "<i>Si</i> + <i>il / ils</i> → <b>s'il, s'ils</b>; but <i>si elle, si on</i>."],
    ex: [["Si tu veux, on peut se voir demain.", "If you want, we can meet tomorrow."], ["Si j'ai le temps, je passerai te voir.", "If I have time, I'll drop by."], ["Si j'étais riche, je voyagerais tout le temps.", "If I were rich, I'd travel all the time."], ["Si nous habitions à Saïgon, nous mangerions dehors tous les soirs.", "If we lived in Saigon, we'd eat out every evening."]],
    warn: "<i>Si j'aurais</i> is a very common mistake, even among French speakers. In the exam it costs points: write <i>si j'avais</i>.",
    vn: "<b>Nếu… thì…</b> Tiếng Việt không đổi động từ. Tiếng Pháp: <b>nếu có thể xảy ra</b> → si + présent, … futur. <b>Nếu chỉ là tưởng tượng</b> (nếu tôi là…) → si + imparfait, … conditionnel." },
  cards: [["si", "if", "Si tu viens, préviens-moi.", "If you come, let me know."], ["s'il", "if he / if it", "S'il fait beau, on ira au parc.", "If it's fine, we'll go to the park."], ["à condition de", "provided that", "Je viendrai à condition de finir tôt.", "I'll come provided I finish early."], ["sinon", "otherwise", "Dépêche-toi, sinon on va rater le train.", "Hurry up, otherwise we'll miss the train."], ["au cas où", "in case", "Prends un parapluie au cas où.", "Take an umbrella just in case."], ["imaginer", "to imagine", "Imagine : si on gagnait au loto…", "Imagine: if we won the lottery…"], ["gagner au loto", "to win the lottery", "Si je gagnais au loto, j'arrêterais de travailler.", "If I won the lottery, I'd stop working."], ["avoir le choix", "to have the choice", "Si j'avais le choix, je vivrais au bord de la mer.", "If I had the choice, I'd live by the sea."]],
  sent: [["Si tu as besoin d'aide, appelle-moi.", "If you need help, call me."], ["S'il fait beau samedi, nous irons à la plage.", "If it's fine on Saturday, we'll go to the beach."], ["Si j'avais plus de temps, j'apprendrais le piano.", "If I had more time, I'd learn the piano."], ["Si tu partais à l'étranger, où irais-tu ?", "If you went abroad, where would you go?"], ["Si nous partons tôt, nous éviterons les bouchons.", "If we leave early, we'll avoid the traffic."], ["Si j'étais toi, je ne dirais rien.", "If I were you, I wouldn't say anything."], ["Si le train est en retard, je prendrai un taxi.", "If the train is late, I'll take a taxi."], ["Si elle parlait mieux français, elle trouverait un poste plus facilement.", "If she spoke better French, she would find a job more easily."], ["Si vous voulez, je peux vous accompagner.", "If you like, I can go with you."], ["Si on avait un jardin, on planterait des herbes vietnamiennes.", "If we had a garden, we'd grow Vietnamese herbs."]],
  nat: [["Si j'avais une voiture, j'irais en Bretagne.", "Si j'aurais une voiture, j'irais en Bretagne.", "Never the conditional right after si: si j'avais."], ["S'il pleut, je resterai chez moi.", "Si il pleuvra, je resterai chez moi.", "Si + présent → futur; si + il → s'il."], ["Si tu veux, on y va.", "Si tu voudras, on y va.", "After si, the present."], ["Si elle était là, elle serait contente.", "Si elle serait là, elle était contente.", "Si + imparfait, then conditional."]],
  mcq: [["Si tu ___ fatiguée, repose-toi.", "es", ["seras", "serais", "étais été"], "A real situation now: si + présent."], ["Si j'___ ton numéro, je t'aurais appelée… mais non, je l'avais perdu.", "avais eu", ["aurais", "ai", "aurai"], "This one is a past regret: si + plus-que-parfait (see B2)."], ["Si nous ___ à Nice, nous nous baignerions tous les jours.", "habitions", ["habiterions", "habiterons", "habitons"], "Imaginary situation: si + imparfait."], ["S'il ne pleut pas, nous ___ en vélo.", "irons", ["irions", "allions", "allons aller"], "Real possibility: si + présent → futur."]],
  gap: [["Si j'___ le temps, je viendrais avec plaisir.", "avais", "avoir", "If I had time, I'd gladly come.", ["aurais", "ai", "aurai"]], ["Si tu ___ ce soir, on dînera ensemble.", "viens", "venir", "If you come tonight, we'll have dinner together.", ["viendras", "viendrais", "venais"]], ["Si j'étais à ta place, je ___ ce travail.", "prendrais", "prendre", "If I were you, I'd take this job.", ["prendrai", "prenais", "prends"]], ["Si nous ___ plus riches, nous achèterions une maison.", "étions", "être", "If we were richer, we'd buy a house.", ["serions", "sommes", "serons"]], ["S'il ___ demain, le match sera annulé.", "neige", "neiger", "If it snows tomorrow, the match will be cancelled.", ["neigera", "neigerait", "neigeait"]], ["Si elle parlait plus lentement, je la ___ mieux.", "comprendrais", "comprendre", "If she spoke more slowly, I'd understand her better.", ["comprendrai", "comprenais", "comprends"]]],
  fix: [["Si j'aurais su, je serais venue.", "j'aurais su", "j'avais su", "Never the conditional after si.", ["je saurais", "j'aurai su"]], ["Si il fait beau, on sortira.", "Si il", "S'il", "Si + il → s'il.", ["Si'l", "Si elle"]], ["Si tu viendras, je serai contente.", "viendras", "viens", "After si, the present.", ["viendrais", "venais"]]],
  xf: [["Make it imaginary (si + imparfait).", "Si j'ai de l'argent, je voyagerai.", "Si j'avais de l'argent, je voyagerais."], ["Complete the idea: real condition.", "Tu es libre ce soir → on va au cinéma.", "Si tu es libre ce soir, on ira au cinéma.|Si tu es libre ce soir, on va au cinéma."]],
  chat: [["Qu'est-ce que tu ferais si tu ne travaillais pas ?", "Si je ne travaillais pas, je voyagerais en Amérique du Sud.", ["Si je ne travaillerais pas, je voyagerais.", "Si je ne travaille pas, je voyageais."], "Si + imparfait, then the conditional."], ["Et s'il pleut dimanche ?", "S'il pleut, on ira au musée.", ["S'il pleuvra, on ira au musée.", "S'il pleut, on irait au musée hier."], "A real possibility: présent then futur."]]
});

L({ id: "b1-subj", lvl: "B1", tr: "opinion", cat: "subjonctif", t: "Le subjonctif présent", en: "Necessity, wishes and feelings",
  rule: { h: "The subjunctive follows que after verbs of necessity, will and emotion.",
    pts: ["Form: take the <b>ils</b> form of the present, drop <i>-ent</i>, add <i>-e, -es, -e, -ions, -iez, -ent</i>: <i>ils prennent → que je prenne</i>. Nous and vous look like the imparfait: <i>que nous prenions</i>.", "Irregular: <i>être (que je sois), avoir (que j'aie), aller (que j'aille), faire (que je fasse), pouvoir (que je puisse), savoir (que je sache), vouloir (que je veuille)</i>.", "After <b>necessity</b>: <i>il faut que, il est important que</i>.", "After <b>will</b>: <i>je veux que, je voudrais que, je souhaite que</i>.", "After <b>emotion</b>: <i>je suis contente que, j'ai peur que, c'est dommage que</i>."],
    ex: [["Il faut que tu viennes avec nous.", "You must come with us."], ["Je voudrais que tu sois là.", "I'd like you to be there."], ["Ma mère est contente que nous venions en janvier.", "My mother is happy that we are coming in January."], ["C'est dommage qu'il fasse si froid.", "It's a pity it's so cold."]],
    warn: "Same subject? Use the infinitive, not que: <i>je veux partir</i> (I want to leave), but <i>je veux que tu partes</i> (I want you to leave).",
    vn: "Tiếng Việt không có thức giả định. Mẹo: sau các cụm <b>«phải… / muốn ai đó… / vui vì…»</b> + <b>que</b> → dùng subjonctif. <i>Il faut que tu viennes</i> = Em phải đến." },
  cards: [["il faut que", "it is necessary that, must", "Il faut que je finisse ce dossier.", "I must finish this file."], ["vouloir que", "to want someone to", "Je veux que tu m'écoutes.", "I want you to listen to me."], ["souhaiter que", "to wish that", "Je souhaite que tout se passe bien.", "I hope everything goes well."], ["être content que", "to be happy that", "Je suis contente que tu sois là.", "I'm happy you're here."], ["avoir peur que", "to be afraid that", "J'ai peur qu'il soit en retard.", "I'm afraid he'll be late."], ["c'est dommage que", "it's a pity that", "C'est dommage que tu partes déjà.", "It's a pity you're already leaving."], ["il est important que", "it is important that", "Il est important que vous arriviez à l'heure.", "It's important that you arrive on time."], ["regretter que", "to be sorry that", "Je regrette que tu ne puisses pas venir.", "I'm sorry you can't come."]],
  sent: [["Il faut que nous réservions le restaurant.", "We must book the restaurant."], ["Mes parents veulent que je vienne pour le Têt.", "My parents want me to come for Tết."], ["Je suis ravie que vous aimiez la cuisine vietnamienne.", "I'm delighted you like Vietnamese food."], ["Il est important que chacun puisse s'exprimer.", "It is important that everyone can speak."], ["J'ai peur qu'il fasse trop chaud en avril.", "I'm afraid it will be too hot in April."], ["C'est dommage que ta sœur ne soit pas là.", "It's a pity your sister isn't here."], ["Je voudrais que tu me dises la vérité.", "I'd like you to tell me the truth."], ["Il faut que j'aille à la banque avant midi.", "I have to go to the bank before noon."], ["Le médecin souhaite que je fasse plus de sport.", "The doctor wants me to do more exercise."], ["Nous sommes heureux que vous ayez accepté notre invitation.", "We are happy you accepted our invitation."]],
  nat: [["Il faut que tu fasses attention.", "Il faut que tu fais attention.", "Il faut que + subjunctive: fasses."], ["Je veux partir tôt.", "Je veux que je parte tôt.", "Same subject: infinitive."], ["Je suis contente que tu sois là.", "Je suis contente que tu es là.", "Emotion + que → subjunctive."], ["Il faut que nous allions au marché.", "Il faut que nous aillons au marché.", "Aller: que nous allions (nous/vous are regular)."]],
  mcq: [["Il faut que tu ___ ce formulaire avant vendredi.", "remplisses", ["remplis", "rempliras", "remplissais"], "Il faut que + subjunctive."], ["Je voudrais que vous ___ patients.", "soyez", ["êtes", "serez", "soiez"], "Être → que vous soyez."], ["C'est dommage qu'il ne ___ pas venir.", "puisse", ["peut", "pourra", "pouvait"], "Emotion → subjunctive; pouvoir → puisse."], ["Je souhaite ___ le DELF B2 cette année.", "passer", ["que je passe", "que je passerai", "passe"], "Same subject → infinitive."]],
  gap: [["Il faut que je ___ à la poste.", "aille", "aller", "I have to go to the post office.", ["vais", "irai", "allais"]], ["Ma mère veut que nous ___ pour le Têt.", "venions", "venir", "My mother wants us to come for Tết.", ["venons", "viendrons", "viennions"]], ["Je suis triste que tu ___ si loin.", "sois", "être", "I'm sad you're so far away.", ["es", "seras", "étais"]], ["Il est important qu'elle ___ du repos.", "prenne", "prendre", "It's important that she rests.", ["prend", "prendra", "prenait"]], ["J'ai peur que nous n'___ pas assez de temps.", "ayons", "avoir", "I'm afraid we won't have enough time.", ["avons", "aurons", "aient"]], ["Il faut que tu ___ la vérité.", "saches", "savoir", "You need to know the truth.", ["sais", "sauras", "sachais"]]],
  fix: [["Il faut que tu vas chez le dentiste.", "vas", "ailles", "Il faut que + subjunctive of aller.", ["iras", "allais"]], ["Je veux que je réussisse.", "que je réussisse", "réussir", "Same subject: je veux réussir.", ["que je réussis", "réussis"]], ["Je suis contente que tu as trouvé un travail.", "as trouvé", "aies trouvé", "Emotion → subjunctive (here the past subjunctive).", ["avais trouvé", "auras trouvé"]]],
  xf: [["Begin with Il faut que…", "Tu dois faire tes devoirs.", "Il faut que tu fasses tes devoirs."], ["Begin with Je voudrais que…", "Tu viens avec moi.", "Je voudrais que tu viennes avec moi."]],
  chat: [["Je dois partir maintenant, désolée.", "Oh, c'est dommage que tu partes si tôt !", ["Oh, c'est dommage que tu pars si tôt !", "Oh, c'est dommage partir si tôt !"], "C'est dommage que + subjunctive."], ["Qu'est-ce qu'il faut faire pour s'inscrire ?", "Il faut que vous remplissiez ce formulaire et que vous le signiez.", ["Il faut que vous remplissez ce formulaire.", "Il faut vous remplirez ce formulaire."], "Il faut que + subjunctive, for each verb."]]
});

L({ id: "b1-opinion", lvl: "B1", tr: "opinion", cat: "subjonctif", t: "Donner son opinion", en: "Je pense que, je ne pense pas que, à mon avis",
  rule: { h: "Positive opinion verbs take the indicative; negative or questioning ones take the subjunctive.",
    pts: ["<i>Je pense que, je crois que, je trouve que, il me semble que</i> + <b>indicative</b>: <i>je pense que c'est une bonne idée</i>.", "<i>Je ne pense pas que, je ne crois pas que, pensez-vous que…?</i> + <b>subjunctive</b>: <i>je ne pense pas que ce soit une bonne idée</i>.", "Without a verb: <i>à mon avis, selon moi, pour moi, d'après moi</i>.", "To agree or disagree: <i>je suis d'accord avec toi, je ne suis pas d'accord, tu as raison, tu as tort</i>.", "To nuance: <i>c'est vrai que… mais, d'un côté… de l'autre</i>."],
    ex: [["Je trouve que Paris est une ville très chère.", "I find Paris a very expensive city."], ["Je ne pense pas qu'il ait raison.", "I don't think he's right."], ["À mon avis, le télétravail est une bonne chose.", "In my opinion, remote working is a good thing."], ["C'est vrai que c'est pratique, mais c'est cher.", "It's true that it's practical, but it's expensive."]],
    warn: "<i>Je suis d'accord <b>avec</b> toi</i> (not <i>je suis d'accord à toi</i>), and <i>avoir raison / avoir tort</i> use avoir, not être.",
    vn: "<b>Tôi nghĩ rằng…</b> → je pense que + indicatif. <b>Tôi không nghĩ là…</b> → je ne pense pas que + <b>subjonctif</b>. Tiếng Việt không đổi động từ, nên đây là lỗi rất hay gặp." },
  cards: [["à mon avis", "in my opinion", "À mon avis, il faut attendre.", "In my opinion, we should wait."], ["selon moi", "according to me", "Selon moi, c'est trop risqué.", "In my view, it's too risky."], ["avoir raison", "to be right", "Tu as raison, partons maintenant.", "You're right, let's go now."], ["avoir tort", "to be wrong", "Il a tort de s'inquiéter.", "He is wrong to worry."], ["être d'accord avec", "to agree with", "Je suis d'accord avec vous.", "I agree with you."], ["il me semble que", "it seems to me that", "Il me semble que c'est fermé le lundi.", "I think it's closed on Mondays."], ["je doute que", "I doubt that", "Je doute qu'il vienne.", "I doubt he'll come."], ["d'un côté… de l'autre", "on the one hand… on the other", "D'un côté c'est pratique, de l'autre c'est cher.", "On the one hand it's practical, on the other it's expensive."]],
  sent: [["Je pense que les transports à Paris sont efficaces.", "I think transport in Paris is efficient."], ["Je ne crois pas que ce soit nécessaire.", "I don't believe it's necessary."], ["À mon avis, les réseaux sociaux prennent trop de place.", "In my opinion, social media take up too much space."], ["Pensez-vous que ce projet puisse réussir ?", "Do you think this project can succeed?"], ["Je trouve que tu travailles trop.", "I find that you work too much."], ["Il me semble que la réunion est à dix heures.", "I think the meeting is at ten."], ["Je ne suis pas sûre que ce soit la bonne solution.", "I'm not sure it's the right solution."], ["Tu as raison, il vaut mieux attendre.", "You're right, it's better to wait."], ["C'est vrai que le loyer est élevé, mais le quartier est agréable.", "It's true the rent is high, but the area is nice."], ["Selon moi, apprendre une langue demande de la patience.", "In my view, learning a language takes patience."]],
  nat: [["Je pense que c'est vrai.", "Je pense que ce soit vrai.", "Positive opinion → indicative."], ["Je ne pense pas que ce soit vrai.", "Je ne pense pas que c'est vrai.", "Negative opinion → subjunctive (in careful French)."], ["Je suis d'accord avec toi.", "Je suis d'accord à toi.", "Être d'accord avec quelqu'un."], ["Tu as raison.", "Tu es raison.", "Avoir raison."]],
  mcq: [["Je crois qu'il ___ trop tard.", "est", ["soit", "sois", "être"], "Positive → indicative."], ["Je ne crois pas qu'il ___ trop tard.", "soit", ["est", "sera", "était"], "Negative → subjunctive."], ["___, ce film est un chef-d'œuvre.", "À mon avis", ["Je pense", "Selon que", "D'accord"], "À mon avis is followed directly by the sentence."], ["Il a ___ de refuser : c'était une bonne offre.", "eu tort", ["été tort", "fait tort", "eu raison de"], "Avoir tort de + infinitive."]],
  gap: [["Je trouve que ce restaurant ___ excellent.", "est", "être", "I find this restaurant excellent.", ["soit", "sera", "serait"]], ["Je ne pense pas qu'elle ___ venir ce soir.", "puisse", "pouvoir", "I don't think she can come tonight.", ["peut", "pourra", "pourrait"]], ["Penses-tu que nous ___ assez de temps ?", "ayons", "avoir", "Do you think we have enough time?", ["avons", "aurons", "avions"]], ["Je doute qu'il ___ la réponse.", "sache", "savoir", "I doubt he knows the answer.", ["sait", "saura", "savait"]], ["Il me semble que tu ___ fatiguée.", "es", "être", "You seem tired to me.", ["sois", "soit", "être"]], ["Je ne suis pas certaine que ce ___ une bonne idée.", "soit", "être", "I'm not sure it's a good idea.", ["est", "sera", "serait"]]],
  fix: [["Je ne crois pas qu'il a raison.", "a", "ait", "Negative opinion → subjunctive.", ["aura", "avait"]], ["Je pense que ce soit important.", "soit", "est", "Positive opinion → indicative.", ["sois", "être"]], ["Je suis d'accord à cette idée.", "à", "avec", "Être d'accord avec.", ["de", "pour"]]],
  xf: [["Make it negative: Je ne pense pas que…", "Je pense que c'est facile.", "Je ne pense pas que ce soit facile."], ["Give the same opinion with à mon avis.", "Je pense que la ville est trop bruyante.", "À mon avis, la ville est trop bruyante."]],
  chat: [["Tu penses que je devrais passer le DELF B2 ?", "Oui, je pense que tu es prête.", ["Oui, je pense que tu sois prête.", "Oui, je ne pense pas que tu es prête."], "Positive opinion → indicative."], ["Le télétravail, c'est mieux, non ?", "Je ne suis pas sûre que ce soit mieux pour tout le monde.", ["Je ne suis pas sûre que c'est mieux.", "Je suis pas d'accord à toi."], "Doubt → subjunctive."]]
});

L({ id: "b1-compar", lvl: "B1", tr: "opinion", cat: "syntaxe", t: "Comparer", en: "Comparatives and superlatives",
  rule: { h: "Plus / moins / aussi + adjective + que; with nouns, plus de / moins de / autant de.",
    pts: ["Adjectives and adverbs: <i>plus grand que, moins cher que, aussi vite que</i>.", "Nouns: <i>plus de temps que, moins de touristes que, autant d'argent que</i>.", "Verbs: <i>il travaille plus que moi, elle dort autant que lui</i>.", "Superlative: <i>le plus beau, la moins chère, les plus grands</i> + <b>de</b>: <i>la plus belle ville du monde</i>.", "Irregular: <i>bon → meilleur, le meilleur</i>; <i>bien → mieux, le mieux</i>; <i>mauvais → pire</i> (or plus mauvais)."],
    ex: [["Paris est plus grand que Lyon.", "Paris is bigger than Lyon."], ["Le phở de ma mère est meilleur que celui du restaurant.", "My mother's phở is better than the restaurant's."], ["Elle parle français mieux que moi.", "She speaks French better than me."], ["C'est le plus beau jour de ma vie.", "It's the most beautiful day of my life."]],
    warn: "<b>Meilleur</b> is an adjective (a better dish); <b>mieux</b> is an adverb (she cooks better). Never <i>plus bon</i> or <i>plus bien</i>.",
    vn: "<b>hơn</b> → plus… que; <b>kém hơn</b> → moins… que; <b>bằng</b> → aussi… que; <b>nhất</b> → le plus. Tiếng Pháp phân biệt <b>meilleur</b> (tính từ: món ngon hơn) và <b>mieux</b> (trạng từ: nấu giỏi hơn)." },
  cards: [["plus… que", "more… than", "Le train est plus rapide que le bus.", "The train is faster than the bus."], ["moins… que", "less… than", "Ce quartier est moins bruyant que le centre.", "This area is less noisy than the centre."], ["aussi… que", "as… as", "Il est aussi grand que son père.", "He is as tall as his father."], ["autant de… que", "as much / as many… as", "J'ai autant de travail que toi.", "I have as much work as you."], ["meilleur", "better (adjective)", "Ce café est meilleur.", "This coffee is better."], ["mieux", "better (adverb)", "Tu chantes mieux que moi.", "You sing better than me."], ["pire", "worse", "La situation est pire qu'hier.", "The situation is worse than yesterday."], ["de plus en plus", "more and more", "Il fait de plus en plus chaud.", "It's getting hotter and hotter."]],
  sent: [["Hô Chi Minh-Ville est plus peuplée que Paris.", "Ho Chi Minh City has more people than Paris."], ["Le métro est moins cher que le taxi.", "The metro is cheaper than a taxi."], ["Elle a autant d'expérience que son collègue.", "She has as much experience as her colleague."], ["C'est le restaurant le plus agréable du quartier.", "It's the nicest restaurant in the area."], ["Je comprends mieux quand tu parles lentement.", "I understand better when you speak slowly."], ["Cette année, il y a plus de touristes que l'an dernier.", "This year there are more tourists than last year."], ["Le meilleur moment de la journée, c'est le petit-déjeuner.", "The best moment of the day is breakfast."], ["Mon français est de moins en moins hésitant.", "My French is less and less hesitant."], ["Il fait aussi chaud à Paris qu'à Saïgon aujourd'hui !", "It's as hot in Paris as in Saigon today!"], ["C'est la pire grève de l'année.", "It's the worst strike of the year."]],
  nat: [["Ce gâteau est meilleur.", "Ce gâteau est plus bon.", "Bon → meilleur."], ["Elle danse mieux que moi.", "Elle danse meilleur que moi.", "With a verb: mieux (adverb)."], ["C'est la plus belle ville du monde.", "C'est la plus belle ville dans le monde.", "Superlative + de."], ["J'ai autant de livres que toi.", "J'ai aussi de livres que toi.", "With a noun: autant de."]],
  mcq: [["Ce vin est ___ que l'autre.", "meilleur", ["mieux", "plus bon", "bien"], "Adjective comparison of bon."], ["Tu conduis ___ que moi.", "mieux", ["meilleur", "plus bien", "bon"], "Adverb comparison of bien."], ["Il y a ___ monde qu'hier.", "moins de", ["moins", "moins que", "aussi"], "With a noun: moins de."], ["C'est l'étudiante la plus sérieuse ___ la classe.", "de", ["dans", "en", "que"], "Superlative + de."]],
  gap: [["Le TGV est ___ rapide que la voiture.", "plus", "", "The TGV is faster than the car.", ["plus de", "autant", "meilleur"]], ["Elle parle ___ bien que sa sœur : elles sont bilingues toutes les deux.", "aussi", "", "She speaks as well as her sister: they're both bilingual.", ["autant", "plus de", "si de"]], ["C'est le ___ film de l'année.", "meilleur", "", "It's the best film of the year.", ["mieux", "plus bon", "bien"]], ["Je travaille ___ que l'an dernier.", "plus|moins|autant", "", "I work more than last year.", ["meilleur", "plus de", "aussi de"]], ["Il y a ___ embouteillages le dimanche.", "moins d'", "", "There are fewer traffic jams on Sundays.", ["moins", "aussi", "pire"]], ["Ça va ___ qu'hier ? — Oui, merci.", "mieux", "", "Are you feeling better than yesterday? — Yes, thanks.", ["meilleur", "plus bien", "bon"]]],
  fix: [["Ce café est plus bon que l'autre.", "plus bon", "meilleur", "Bon → meilleur.", ["mieux", "plus bien"]], ["Elle cuisine meilleur que moi.", "meilleur", "mieux", "With a verb: mieux.", ["plus bon", "bien"]], ["C'est le plus grand musée dans Paris.", "dans", "de", "Superlative + de.", ["en", "que"]]],
  xf: [["Compare with plus… que.", "Le TGV est rapide. Le bus est lent.", "Le TGV est plus rapide que le bus."], ["Use the superlative.", "Ce quartier est très calme (de la ville).", "C'est le quartier le plus calme de la ville."]],
  chat: [["Tu préfères Paris ou Saïgon ?", "J'aime les deux, mais la cuisine est meilleure à Saïgon.", ["La cuisine est plus bonne à Saïgon.", "La cuisine est mieux à Saïgon que."], "Adjective cuisine: meilleure (feminine)."], ["Ton français progresse ?", "Oui, je comprends de mieux en mieux.", ["Oui, je comprends de meilleur en meilleur.", "Oui, je comprends plus bien."], "With a verb: de mieux en mieux."]]
});

L({ id: "b1-cause", lvl: "B1", tr: "logique", cat: "connecteurs", t: "Cause et conséquence", en: "Parce que, comme, grâce à, donc, c'est pourquoi",
  rule: { h: "Choose the cause word by its position and by what follows it (a clause or a noun).",
    pts: ["<b>Parce que</b> + clause, usually after the main clause: <i>je reste parce que je suis malade</i>.", "<b>Comme</b> + clause, always at the start: <i>comme je suis malade, je reste</i>.", "<b>Car</b> + clause, mid-sentence, more written.", "<b>Grâce à</b> + noun (positive), <b>à cause de</b> + noun (negative): <i>grâce à toi, à cause de la grève</i>.", "Consequence: <b>donc, alors, c'est pourquoi, du coup</b> (spoken): <i>il pleuvait, donc j'ai pris un taxi</i>."],
    ex: [["Comme il était tard, nous avons pris un taxi.", "As it was late, we took a taxi."], ["Je suis fatiguée parce que j'ai mal dormi.", "I'm tired because I slept badly."], ["Grâce à ma professeure, j'ai fait des progrès.", "Thanks to my teacher, I've made progress."], ["Le magasin était fermé, c'est pourquoi je n'ai rien acheté.", "The shop was closed, which is why I didn't buy anything."]],
    warn: "Answering <i>Pourquoi ?</i>, start with <b>parce que</b>, never with <i>car</i> or <i>comme</i>: <i>Pourquoi tu ris ? — Parce que c'est drôle.</i>",
    vn: "<b>vì</b> → parce que / car; <b>vì… nên…</b> → comme… (ở đầu câu); <b>nhờ</b> → grâce à; <b>tại / do</b> (xấu) → à cause de; <b>nên, vì vậy</b> → donc, c'est pourquoi." },
  cards: [["parce que", "because", "Je l'aime parce qu'elle est drôle.", "I love her because she's funny."], ["comme", "as, since (at the start)", "Comme il pleut, on reste ici.", "As it's raining, we're staying here."], ["grâce à", "thanks to", "Grâce à toi, j'ai trouvé la solution.", "Thanks to you, I found the solution."], ["à cause de", "because of", "À cause du bruit, je n'ai pas dormi.", "Because of the noise, I didn't sleep."], ["donc", "so, therefore", "Je suis malade, donc je reste chez moi.", "I'm ill, so I'm staying at home."], ["c'est pourquoi", "that's why", "Elle adore lire, c'est pourquoi elle va souvent en librairie.", "She loves reading, that's why she often goes to bookshops."], ["du coup", "so, as a result (spoken)", "Il n'y avait plus de bus, du coup j'ai marché.", "There were no more buses, so I walked."], ["en effet", "indeed (adds an explanation)", "Je suis inquiète. En effet, il n'a pas répondu.", "I'm worried. Indeed, he hasn't answered."]],
  sent: [["Je prends le vélo parce que c'est plus rapide.", "I take the bike because it's faster."], ["Comme tu es là, tu peux m'aider ?", "Since you're here, can you help me?"], ["Grâce à cette application, je révise tous les jours.", "Thanks to this app, I revise every day."], ["Le vol a été annulé à cause de la neige.", "The flight was cancelled because of the snow."], ["J'ai raté le bus, donc je suis arrivée en retard.", "I missed the bus, so I arrived late."], ["Le loyer est trop cher, c'est pourquoi nous déménageons.", "The rent is too high, that's why we're moving."], ["Il y avait une grève, du coup on a pris le RER.", "There was a strike, so we took the RER."], ["Elle est restée chez elle car elle était malade.", "She stayed at home as she was ill."], ["Pourquoi tu souris ? — Parce que je suis heureuse.", "Why are you smiling? — Because I'm happy."], ["À cause des travaux, la rue est fermée.", "Because of the roadworks, the street is closed."]],
  nat: [["Comme il pleut, je prends un parapluie.", "Je prends un parapluie comme il pleut.", "Comme expressing cause goes at the start."], ["Grâce à ton aide, j'ai réussi.", "Grâce à ton aide, j'ai raté.", "Grâce à introduces a positive cause."], ["À cause de la grève, je suis en retard.", "À cause que la grève, je suis en retard.", "À cause de + noun."], ["Pourquoi ? — Parce que je suis fatiguée.", "Pourquoi ? — Car je suis fatiguée.", "To answer pourquoi, use parce que."]],
  mcq: [["___ il faisait beau, nous avons mangé dehors.", "Comme", ["Parce que", "Car", "Grâce à"], "At the start of the sentence: comme."], ["Le match a été annulé ___ la pluie.", "à cause de", ["grâce à", "parce que", "comme"], "Negative cause + noun."], ["Je n'avais pas de clé, ___ j'ai attendu dehors.", "donc", ["car", "parce que", "comme"], "A consequence."], ["___ son travail, elle a obtenu une promotion.", "Grâce à", ["À cause de", "Parce que", "Car"], "Positive cause + noun."]],
  gap: [["Je suis en retard ___ le métro était en panne.", "parce que|car", "", "I'm late because the metro broke down.", ["comme", "grâce à", "donc"]], ["___ tu as faim, je vais préparer quelque chose.", "Comme", "", "As you're hungry, I'll make something.", ["Parce que", "Car", "Donc"]], ["___ du bruit, je n'entends rien.", "À cause", "", "Because of the noise, I can't hear anything.", ["Grâce", "Parce", "Comme"]], ["Il a beaucoup travaillé, ___ il a réussi.", "donc|alors", "", "He worked hard, so he passed.", ["car", "comme", "grâce à"]], ["___ à vos conseils, j'ai trouvé un appartement.", "Grâce", "", "Thanks to your advice, I found a flat.", ["À cause", "Parce", "Comme"]], ["Elle aime les langues, ___ elle apprend le coréen.", "c'est pourquoi|donc|alors", "", "She loves languages, that's why she's learning Korean.", ["parce que", "car", "comme"]]],
  fix: [["Je suis restée chez moi à cause de j'étais malade.", "à cause de", "parce que", "Before a clause (subject + verb): parce que.", ["grâce à", "comme"]], ["Il a réussi son examen à cause de son travail acharné.", "à cause de", "grâce à", "A positive cause: grâce à.", ["parce que", "car"]], ["J'ai raté mon train grâce à la grève.", "grâce à", "à cause de", "A negative cause: à cause de.", ["parce que", "car"]]],
  xf: [["Join the sentences with comme.", "Il est tard. Je rentre.", "Comme il est tard, je rentre."], ["Join the sentences with c'est pourquoi.", "J'adore la cuisine française. Je prends des cours.", "J'adore la cuisine française, c'est pourquoi je prends des cours."]],
  chat: [["Pourquoi tu apprends le français ?", "Parce que je vis en France et que je veux passer le DELF.", ["Car je vis en France.", "Comme je vis en France."], "Answering pourquoi: parce que."], ["Tu n'es pas venue à la fête ?", "Non, à cause de la grève, il n'y avait plus de train.", ["Non, grâce à la grève, il n'y avait plus de train.", "Non, parce que la grève, il n'y avait plus de train."], "Negative cause + noun: à cause de."]]
});

L({ id: "b1-temps", lvl: "B1", tr: "logique", cat: "syntaxe", t: "Depuis, il y a, pendant, en, dans", en: "Expressing time and duration",
  rule: { h: "Each time word answers a different question: since when, how long ago, for how long, how long it takes, how soon.",
    pts: ["<b>Depuis</b> + present: an action that is still going on: <i>j'habite à Paris depuis deux ans</i>.", "<b>Il y a</b> + past: a point in the past: <i>je suis arrivée il y a deux ans</i>.", "<b>Pendant</b>: a duration, finished or not: <i>j'ai étudié pendant trois heures</i>.", "<b>En</b>: the time needed to do something: <i>j'ai lu ce livre en deux jours</i>.", "<b>Dans</b>: a point in the future: <i>je pars dans dix minutes</i>."],
    ex: [["J'apprends le français depuis un an.", "I've been learning French for a year."], ["Nous nous sommes rencontrés il y a quatre ans.", "We met four years ago."], ["J'ai attendu pendant une heure.", "I waited for an hour."], ["Le train arrive dans cinq minutes.", "The train arrives in five minutes."]],
    warn: "English <i>for</i> has two translations: <i>depuis</i> (still true: <i>I have been here for a year</i>) and <i>pendant</i> (finished: <i>I was there for a year</i>).",
    vn: "<b>từ… đến nay / được… rồi</b> → depuis + hiện tại; <b>cách đây</b> → il y a; <b>trong (suốt)</b> → pendant; <b>mất (bao lâu)</b> → en; <b>(sau)… nữa</b> → dans: <i>dans dix minutes</i> = mười phút nữa." },
  cards: [["depuis", "since, for (still going on)", "Je suis ici depuis lundi.", "I've been here since Monday."], ["il y a", "ago", "Il est parti il y a une heure.", "He left an hour ago."], ["pendant", "for, during", "J'ai dormi pendant tout le vol.", "I slept during the whole flight."], ["en", "in (time taken)", "J'ai fait le trajet en vingt minutes.", "I did the journey in twenty minutes."], ["dans", "in (from now)", "On se voit dans une semaine.", "See you in a week."], ["jusqu'à", "until", "Je travaille jusqu'à dix-huit heures.", "I work until 6 pm."], ["à partir de", "from, starting", "À partir de lundi, je commence à huit heures.", "From Monday, I start at eight."], ["ça fait… que", "it's been… since", "Ça fait deux ans que je vis ici.", "I've been living here for two years."]],
  sent: [["Je travaille dans le digital learning depuis cinq ans.", "I've been working in digital learning for five years."], ["Je suis arrivée en France il y a deux ans.", "I arrived in France two years ago."], ["Nous avons vécu à Lyon pendant six mois.", "We lived in Lyon for six months."], ["Elle a appris à conduire en trois semaines.", "She learnt to drive in three weeks."], ["La réunion commence dans un quart d'heure.", "The meeting starts in a quarter of an hour."], ["Ça fait longtemps que je ne t'ai pas vue !", "It's been a long time since I saw you!"], ["Il pleut depuis ce matin.", "It's been raining since this morning."], ["Pendant les vacances, je lis beaucoup.", "During the holidays I read a lot."], ["Le mariage aura lieu dans quatorze mois.", "The wedding will take place in fourteen months."], ["J'ai terminé le dossier en une heure.", "I finished the file in an hour."]],
  nat: [["J'habite ici depuis trois ans.", "J'habite ici pendant trois ans.", "Still true now → depuis + present."], ["Il est parti il y a dix minutes.", "Il est parti depuis dix minutes.", "A point in the past with a completed action → il y a."], ["Je reviens dans cinq minutes.", "Je reviens en cinq minutes.", "From now → dans."], ["J'ai lu ce roman en deux jours.", "J'ai lu ce roman dans deux jours.", "Time needed → en."]],
  mcq: [["Je connais Alex ___ 2022.", "depuis", ["il y a", "pendant", "dans"], "A starting point that still matters now."], ["Elle a téléphoné ___ une heure.", "il y a", ["depuis", "dans", "en"], "A point in the past."], ["Le film commence ___ dix minutes, dépêche-toi !", "dans", ["en", "il y a", "depuis"], "From now → dans."], ["J'ai étudié ___ tout l'après-midi.", "pendant", ["depuis", "dans", "il y a"], "A finished duration."]],
  gap: [["J'attends le bus ___ vingt minutes !", "depuis", "", "I've been waiting for the bus for twenty minutes!", ["pendant", "il y a", "dans"]], ["Nous nous sommes fiancés ___ un an.", "il y a", "", "We got engaged a year ago.", ["depuis", "dans", "en"]], ["Il a couru le marathon ___ quatre heures.", "en", "", "He ran the marathon in four hours.", ["dans", "depuis", "il y a"]], ["Je serai prête ___ cinq minutes.", "dans", "", "I'll be ready in five minutes.", ["en", "depuis", "il y a"]], ["___ le confinement, j'ai appris à cuisiner.", "Pendant", "", "During lockdown, I learnt to cook.", ["Depuis que", "Dans", "En"]], ["Ça fait trois mois ___ je cherche un appartement.", "que", "", "I've been looking for a flat for three months.", ["depuis", "pendant", "dont"]]],
  fix: [["J'habite à Paris pendant deux ans et je l'adore.", "pendant", "depuis", "Still true now → depuis.", ["il y a", "dans"]], ["Je suis arrivée depuis trois jours.", "depuis", "il y a", "A completed action at a point in the past → il y a.", ["pendant", "en"]], ["On part en dix minutes, tu es prête ?", "en", "dans", "From now → dans.", ["pendant", "depuis"]]],
  xf: [["Say it with ça fait… que.", "J'apprends le français depuis un an.", "Ça fait un an que j'apprends le français."], ["Use il y a.", "Je suis arrivée à Paris en 2024. (two years before now)", "Je suis arrivée à Paris il y a deux ans."]],
  chat: [["Tu vis en France depuis combien de temps ?", "Depuis deux ans, je suis arrivée en 2024.", ["Il y a deux ans que je vis.", "Pendant deux ans, je vis."], "Since when, still true: depuis."], ["Le train part quand ?", "Dans dix minutes, quai numéro quatre.", ["En dix minutes, quai quatre.", "Il y a dix minutes."], "From now → dans."]]
});

L({ id: "b1-indirect", lvl: "B1", tr: "style", cat: "discours", t: "Le discours indirect", en: "Reporting words and questions",
  rule: { h: "To report speech, use que for statements, si for yes/no questions, and the question word for open questions.",
    pts: ["Statement: <i>« Je suis fatiguée. » → Elle dit <b>qu'</b>elle est fatiguée</i>.", "Yes/no question: <i>« Tu viens ? » → Il demande <b>si</b> je viens</i>.", "Open question: <i>« Où habites-tu ? » → Elle demande <b>où</b> j'habite</i>.", "<i>Qu'est-ce que</i> → <b>ce que</b>; <i>qu'est-ce qui</i> → <b>ce qui</b>: <i>il demande ce que je fais</i>.", "Command: <i>« Viens ! » → Il me dit <b>de</b> venir</i>.", "Change the pronouns and possessives: <i>je → elle, mon → son</i>."],
    ex: [["Alex dit qu'il sera en retard.", "Alex says he'll be late."], ["Ma mère me demande si j'ai bien mangé.", "My mother asks me if I've eaten well."], ["Le médecin veut savoir ce qui ne va pas.", "The doctor wants to know what's wrong."], ["Elle me demande de l'appeler ce soir.", "She asks me to call her tonight."]],
    warn: "No inversion and no question mark in reported questions: <i>il demande où j'habite</i>, not <i>où habite-je ?</i>. When the reporting verb is in the past (il a dit), the tenses shift: see the B2 lesson on the sequence of tenses.",
    vn: "Giống <b>«nói rằng… / hỏi xem… có… không»</b>: <i>dire que</i> = nói rằng; <i>demander si</i> = hỏi xem có… không; <i>demander de</i> + động từ = bảo/nhờ ai làm gì." },
  cards: [["dire que", "to say that", "Il dit qu'il a faim.", "He says he's hungry."], ["demander si", "to ask whether", "Je me demande si c'est une bonne idée.", "I wonder whether it's a good idea."], ["demander de", "to ask (someone) to", "Elle m'a demandé de fermer la porte.", "She asked me to close the door."], ["ce que", "what (object)", "Dis-moi ce que tu veux.", "Tell me what you want."], ["ce qui", "what (subject)", "Je ne sais pas ce qui s'est passé.", "I don't know what happened."], ["répondre que", "to answer that", "Il a répondu qu'il n'était pas sûr.", "He answered that he wasn't sure."], ["expliquer que", "to explain that", "Elle explique que le bureau est fermé.", "She explains that the office is closed."], ["vouloir savoir", "to want to know", "Il veut savoir à quelle heure on arrive.", "He wants to know what time we arrive."]],
  sent: [["Ma sœur dit qu'elle viendra en avril.", "My sister says she'll come in April."], ["Le serveur demande si nous avons choisi.", "The waiter asks if we've chosen."], ["Je me demande pourquoi il ne répond pas.", "I wonder why he isn't answering."], ["Elle veut savoir combien coûte le billet.", "She wants to know how much the ticket costs."], ["Dis-moi ce que tu en penses.", "Tell me what you think of it."], ["Il m'a demandé de ne pas oublier les clés.", "He asked me not to forget the keys."], ["Je ne comprends pas ce qui se passe.", "I don't understand what's going on."], ["Le professeur explique que l'examen dure deux heures.", "The teacher explains that the exam lasts two hours."], ["Ma mère me demande quand nous arrivons.", "My mother asks me when we're arriving."], ["Il répond qu'il n'a pas le temps.", "He answers that he doesn't have time."]],
  nat: [["Il demande si tu viens.", "Il demande est-ce que tu viens.", "Yes/no question → si."], ["Elle demande où j'habite.", "Elle demande où est-ce que j'habite ?", "No est-ce que and no question mark in reported questions."], ["Je ne sais pas ce que tu veux.", "Je ne sais pas qu'est-ce que tu veux.", "Qu'est-ce que → ce que."], ["Il me dit de venir.", "Il me dit que viens.", "A command → de + infinitive."]],
  mcq: [["« Tu as faim ? » → Elle me demande ___ j'ai faim.", "si", ["que", "ce que", "est-ce que"], "Yes/no question → si."], ["« Qu'est-ce que tu fais ? » → Il demande ___ je fais.", "ce que", ["qu'est-ce que", "que", "ce qui"], "Qu'est-ce que → ce que."], ["« Ferme la fenêtre ! » → Elle me dit ___ fermer la fenêtre.", "de", ["que", "si", "à"], "Command → de + infinitive."], ["« Qu'est-ce qui t'inquiète ? » → Il veut savoir ___ m'inquiète.", "ce qui", ["ce que", "qu'est-ce qui", "que"], "Qu'est-ce qui → ce qui."]],
  gap: [["« Je suis malade. » → Il dit ___ il est malade.", "qu'", "", "He says he's ill.", ["si", "ce qu'", "de"]], ["« Vous aimez le fromage ? » → Elle me demande ___ j'aime le fromage.", "si", "", "She asks me if I like cheese.", ["que", "ce que", "est-ce que"]], ["« Où est la gare ? » → Il demande ___ est la gare.", "où", "", "He asks where the station is.", ["si", "que", "ce qu'"]], ["« Rappelle-moi ! » → Elle me demande ___ la rappeler.", "de", "", "She asks me to call her back.", ["que", "si", "à"]], ["« Qu'est-ce que vous voulez ? » → Il nous demande ___ nous voulons.", "ce que", "", "He asks us what we want.", ["qu'est-ce que", "que", "ce qui"]], ["« Quand partez-vous ? » → Elle veut savoir ___ nous partons.", "quand", "", "She wants to know when we're leaving.", ["si", "que", "ce que"]]],
  fix: [["Il me demande qu'est-ce que je fais ce soir.", "qu'est-ce que", "ce que", "In reported questions: ce que.", ["que", "ce qui"]], ["Elle demande est-ce que tu es libre.", "est-ce que", "si", "Yes/no → si.", ["que", "ce que"]], ["Il m'a dit que je viens demain.", "que je viens", "de venir", "A command → de + infinitive.", ["que je venir", "si je viens"]]],
  xf: [["Report it: Elle demande…", "« Est-ce que tu as fini ? »", "Elle demande si j'ai fini.|Elle me demande si j'ai fini."], ["Report it: Il dit…", "« Je travaille demain. »", "Il dit qu'il travaille demain."]],
  chat: [["Qu'est-ce que ta mère t'a dit au téléphone ?", "Elle m'a demandé si nous viendrions pour le Têt.", ["Elle m'a demandé est-ce que nous venons pour le Têt ?", "Elle m'a demandé que nous venons."], "Yes/no question → si."], ["Le propriétaire voulait quoi ?", "Il voulait savoir ce que nous pensions de l'appartement.", ["Il voulait savoir qu'est-ce que nous pensions.", "Il voulait savoir ce qui nous pensions."], "Qu'est-ce que → ce que."]]
});

L({ id: "b1-ecrire", lvl: "B1", tr: "style", cat: "registre", t: "Écrire un message, une lettre", en: "Formulas for informal and formal writing",
  rule: { h: "Match the opening, the closing and tu/vous to the person you write to.",
    pts: ["<b>Friend</b>: <i>Salut Claire, / Chère Claire,</i> … <i>Bisous, / À bientôt, / Je t'embrasse</i>; tutoiement.", "<b>Formal</b>: <i>Madame, / Monsieur, / Madame, Monsieur,</i> … <i>Je vous prie d'agréer, Madame, Monsieur, l'expression de mes salutations distinguées.</i>; vouvoiement.", "Semi-formal e-mail: <i>Bonjour Madame Martin,</i> … <i>Cordialement, / Bien cordialement,</i>.", "Structure for DELF B1: greeting, why you write, your point of view with reasons and examples, a conclusion, closing formula.", "Useful openings: <i>Je vous écris pour…, Suite à votre annonce…, Je me permets de vous contacter car…</i>"],
    ex: [["Chère Sophie, merci beaucoup pour ton invitation !", "Dear Sophie, thank you very much for your invitation!"], ["Madame, Monsieur, je vous écris au sujet de votre annonce.", "Dear Sir or Madam, I am writing about your advertisement."], ["Je reste à votre disposition pour tout renseignement complémentaire.", "I remain at your disposal for any further information."], ["Dans l'attente de votre réponse, je vous prie d'agréer mes salutations distinguées.", "Looking forward to your reply, yours faithfully."]],
    warn: "Never mix tu and vous in one letter, and never write <i>Cher Madame</i>: in French you write simply <i>Madame,</i>.",
    vn: "Giống thư tiếng Việt: <b>viết cho bạn</b> thì thân mật (tu, Bisous), <b>viết cho cơ quan</b> thì trang trọng (vous, công thức kết thúc dài). Trong DELF, sai giọng văn (registre) bị trừ điểm." },
  cards: [["Je vous écris pour…", "I am writing to…", "Je vous écris pour demander des informations.", "I am writing to ask for information."], ["Suite à…", "Following…", "Suite à notre conversation, je vous envoie le document.", "Following our conversation, I'm sending you the document."], ["au sujet de", "about, regarding", "Je vous contacte au sujet de la facture.", "I'm contacting you about the invoice."], ["Cordialement", "Kind regards", "Cordialement, Lan Anh Pham", "Kind regards, Lan Anh Pham"], ["Je vous prie d'agréer…", "Yours faithfully (formal)", "Je vous prie d'agréer, Madame, l'expression de mes salutations distinguées.", "Yours faithfully."], ["rester à votre disposition", "to remain at your disposal", "Je reste à votre disposition.", "I remain at your disposal."], ["Je t'embrasse", "Love, hugs (to a friend)", "À très vite, je t'embrasse !", "Speak soon, love!"], ["Dans l'attente de votre réponse", "Looking forward to your reply", "Dans l'attente de votre réponse, je vous remercie.", "Looking forward to your reply, thank you."]],
  sent: [["Salut Thomas, ça fait longtemps ! Comment vas-tu ?", "Hi Thomas, it's been ages! How are you?"], ["Madame, Monsieur, je souhaiterais m'inscrire au cours du soir.", "Dear Sir or Madam, I would like to enrol in the evening class."], ["Je vous écris pour signaler un problème de chauffage.", "I am writing to report a heating problem."], ["Pourriez-vous m'indiquer les horaires d'ouverture ?", "Could you tell me the opening hours?"], ["Je vous remercie par avance de votre réponse.", "Thank you in advance for your reply."], ["Merci encore pour ce week-end, c'était super !", "Thanks again for this weekend, it was great!"], ["Suite à votre annonce, je suis intéressée par le poste.", "Following your advertisement, I am interested in the position."], ["Je reste à votre disposition pour un entretien.", "I am available for an interview."], ["Bien cordialement, Lan Anh", "Best regards, Lan Anh"], ["Donne-moi de tes nouvelles, je t'embrasse.", "Let me know how you are, love."]],
  nat: [["Madame, je vous écris au sujet de ma commande.", "Cher Madame, je t'écris au sujet de ma commande.", "Formal letter: Madame, and vous."], ["Cordialement, Lan Anh Pham", "Bisous, Lan Anh Pham (to the bank)", "To an institution: Cordialement."], ["Salut Claire, merci pour ton message !", "Salut Claire, merci pour votre message !", "A friend: tu, ton."], ["Je vous prie d'agréer mes salutations distinguées.", "Je vous prie d'agréer mes bisous distingués.", "The formal closing formula is fixed."]],
  mcq: [["Writing to your landlord, which opening fits?", "Madame, je vous écris au sujet du loyer.", ["Salut, je t'écris pour le loyer.", "Cher Madame, je te contacte.", "Coucou ! Le loyer…"], "Formal: Madame + vous."], ["Closing an e-mail to a colleague you don't know well:", "Cordialement", ["Bisous", "Je t'embrasse", "Salut"], "Neutral professional closing."], ["Which request is polite and formal?", "Pourriez-vous me confirmer la date ?", ["Confirme-moi la date.", "Tu peux confirmer ?", "Confirmez date."], "Conditional + vous."], ["Starting a reply to a job advert:", "Suite à votre annonce parue sur votre site…", ["Salut, j'ai vu ton annonce…", "Je veux le travail.", "Coucou l'équipe !"], "Formal opening."]],
  gap: [["Je vous écris ___ sujet de votre annonce.", "au", "", "I'm writing about your advertisement.", ["à", "du", "sur"]], ["___ à notre conversation, voici le document.", "Suite", "", "Following our conversation, here is the document.", ["Après", "Depuis", "Grâce"]], ["Je reste à votre ___ pour toute question.", "disposition", "", "I remain at your disposal for any question.", ["disponible", "service de", "attente"]], ["Dans l'___ de votre réponse, je vous remercie.", "attente", "", "Looking forward to your reply, thank you.", ["espoir", "attendre", "idée"]], ["Je vous ___ par avance de votre aide.", "remercie", "", "Thank you in advance for your help.", ["merci", "remerciez", "remercier"]], ["Merci pour ton invitation, je t'___ !", "embrasse", "", "Thanks for your invitation, love!", ["embrasser", "embrassez", "salue"]]],
  fix: [["Cher Madame Dupont, je vous écris…", "Cher Madame Dupont", "Madame", "In French formal letters: Madame, (no Cher, no surname).", ["Chère Dupont", "Salut Madame"]], ["Monsieur, je t'écris pour réserver une chambre.", "je t'écris", "je vous écris", "Formal letter: vous throughout.", ["je lui écris", "j'écris toi"]], ["Monsieur, je vous écris pour réserver une chambre. Bisous, Lan Anh", "Bisous", "Cordialement", "Don't mix registers in one letter.", ["Je t'embrasse", "Salut"]]],
  xf: [["Make it formal.", "Tu peux m'envoyer le programme ?", "Pourriez-vous m'envoyer le programme ?|Pourriez-vous m'envoyer le programme, s'il vous plaît ?"], ["Make it formal.", "Je t'écris pour le stage.", "Je vous écris au sujet du stage.|Je vous écris pour le stage."]],
  chat: [["(Your new manager, by e-mail) Pourriez-vous me confirmer votre disponibilité jeudi ?", "Bonjour Madame Leroy, je vous confirme que je suis disponible jeudi. Cordialement, Lan Anh", ["Salut ! Oui, jeudi ça marche. Bisous", "Ok jeudi."], "A manager you don't know well: formal or semi-formal register."], ["(A friend) Tu viens à mon anniversaire samedi ?", "Avec plaisir ! Merci pour l'invitation, à samedi !", ["Je vous prie d'agréer mes salutations distinguées.", "Madame, je viendrai."], "A friend: informal register."]]
});

/* ── data/b2a.js ── */
/* B2 lessons · part 1 */
L({ id: "b2-subj", lvl: "B2", tr: "nuance", cat: "subjonctif", t: "Subjonctif après les conjonctions", en: "Bien que, pour que, avant que, à condition que, jusqu'à ce que",
  rule: { h: "Some conjunctions always take the subjunctive; après que, pendant que and parce que take the indicative.",
    pts: ["<b>Concession</b>: <i>bien que, quoique</i> — <i>bien qu'il soit tard, je continue</i>.", "<b>Purpose</b>: <i>pour que, afin que, de sorte que (purpose)</i> — <i>je parle lentement pour que tu comprennes</i>.", "<b>Time</b>: <i>avant que, jusqu'à ce que, en attendant que</i> — <i>reste jusqu'à ce qu'il revienne</i>.", "<b>Condition</b>: <i>à condition que, pourvu que, à moins que</i> — <i>je viendrai à condition que tu m'invites</i>.", "<b>Indicative</b> after <i>après que, pendant que, parce que, depuis que, alors que</i>."],
    ex: [["Bien qu'il pleuve, nous sortons.", "Although it is raining, we are going out."], ["Je t'explique pour que tu saches quoi faire.", "I'm explaining so that you know what to do."], ["Rentre avant qu'il fasse nuit.", "Come home before it gets dark."], ["Elle viendra à condition qu'on finisse tôt.", "She'll come on condition that we finish early."]],
    warn: "With the same subject, use a preposition + infinitive: <i>je travaille <b>pour</b> réussir</i>, <i>appelle-moi <b>avant de</b> partir</i>. Que + subjunctive is for two different subjects.",
    vn: "Tiếng Việt: <b>mặc dù, để, trước khi, miễn là, cho đến khi</b> không đổi động từ. Tiếng Pháp: bien que, pour que, avant que, à condition que, jusqu'à ce que + <b>subjonctif</b>. Nhưng <b>après que</b> (sau khi) + indicatif." },
  cards: [["bien que", "although", "Bien qu'elle soit fatiguée, elle sort.", "Although she's tired, she goes out."], ["pour que", "so that", "Je répète pour que tout le monde entende.", "I'm repeating so everyone can hear."], ["avant que", "before", "Partons avant qu'il pleuve.", "Let's go before it rains."], ["jusqu'à ce que", "until", "J'attendrai jusqu'à ce que tu reviennes.", "I'll wait until you come back."], ["à condition que", "on condition that", "D'accord, à condition que tu m'aides.", "OK, on condition that you help me."], ["à moins que", "unless", "Je viendrai, à moins qu'il y ait une grève.", "I'll come, unless there's a strike."], ["pourvu que", "let's hope that, provided that", "Pourvu qu'il fasse beau demain !", "Let's hope it's fine tomorrow!"], ["après que", "after (+ indicative)", "Après qu'il est parti, j'ai rangé.", "After he left, I tidied up."]],
  sent: [["Bien que le loyer soit élevé, nous restons dans ce quartier.", "Although the rent is high, we're staying in this area."], ["Je t'envoie le lien pour que tu puisses t'inscrire.", "I'm sending you the link so you can sign up."], ["Il faut finir le projet avant que le client revienne.", "We need to finish the project before the client comes back."], ["Nous attendrons jusqu'à ce que tout le monde soit arrivé.", "We'll wait until everyone has arrived."], ["Je veux bien présenter le module, à condition que tu fasses la démo.", "I'm happy to present the module, provided you do the demo."], ["On partira à huit heures, à moins qu'il fasse trop froid.", "We'll leave at eight, unless it's too cold."], ["Pourvu que le vol ne soit pas annulé !", "Let's hope the flight isn't cancelled!"], ["Elle a fini son master bien qu'elle travaille à plein temps.", "She finished her master's although she works full time."], ["Après que nous avons signé le bail, nous avons fêté ça.", "After we signed the lease, we celebrated."], ["J'explique les consignes en vietnamien afin que mes parents comprennent.", "I explain the instructions in Vietnamese so that my parents understand."]],
  nat: [["Bien qu'il soit malade, il travaille.", "Bien qu'il est malade, il travaille.", "Bien que + subjunctive."], ["Appelle-moi avant de partir.", "Appelle-moi avant que tu partes.", "Same subject (tu): avant de + infinitive."], ["Après qu'il est arrivé, nous avons dîné.", "Après qu'il soit arrivé, nous avons dîné.", "Après que + indicative in careful French (the subjunctive is common in speech but criticised)."], ["Je travaille pour que mes enfants aient une bonne vie.", "Je travaille pour que mes enfants ont une bonne vie.", "Pour que + subjunctive."]],
  mcq: [["Je t'attends jusqu'à ce que tu ___.", "reviennes", ["reviens", "reviendras", "revenais"], "Jusqu'à ce que + subjunctive."], ["___ il fasse froid, les enfants jouent dehors.", "Bien qu'", ["Parce qu'", "Puisqu'", "Malgré qu'"], "Concession + subjunctive: bien que."], ["Je fais ça ___ réussir.", "pour", ["pour que", "afin que", "bien que"], "Same subject → pour + infinitive."], ["Il est parti ___ je puisse lui dire au revoir.", "avant que", ["après que", "parce que", "pendant que"], "Avant que + subjunctive."]],
  gap: [["Bien qu'elle ___ peur de l'avion, elle part au Japon.", "ait", "avoir", "Although she's afraid of flying, she's going to Japan.", ["a", "aura", "avait"]], ["Je parle fort pour que tout le monde m'___.", "entende", "entendre", "I speak loudly so that everyone hears me.", ["entend", "entendra", "entendait"]], ["Fermez la porte avant que le chat ___.", "sorte", "sortir", "Close the door before the cat gets out.", ["sort", "sortira", "sortait"]], ["Je te prête ma voiture à condition que tu ___ prudent.", "sois", "être", "I'll lend you my car provided you're careful.", ["es", "seras", "étais"]], ["Restez ici jusqu'à ce que je vous ___.", "appelle", "appeler", "Stay here until I call you.", ["appellerai", "appelais", "appelez"]], ["Pourvu qu'ils ___ à l'heure !", "arrivent", "arriver", "Let's hope they arrive on time!", ["arriveront", "arrivaient", "arriveraient"]]],
  fix: [["Bien qu'il fait beau, je reste chez moi.", "fait", "fasse", "Bien que + subjunctive.", ["fera", "faisait"]], ["Je t'appelle avant que je parte.", "avant que je parte", "avant de partir", "Same subject → avant de + infinitive.", ["avant que je pars", "avant partir"]], ["Je l'aide pour qu'il réussit.", "réussit", "réussisse", "Pour que + subjunctive.", ["réussira", "réussissait"]]],
  xf: [["Join with bien que.", "Il est riche. Il n'est pas heureux.", "Bien qu'il soit riche, il n'est pas heureux."], ["Join with pour que.", "Je t'envoie le plan. Tu trouves la maison.", "Je t'envoie le plan pour que tu trouves la maison."]],
  chat: [["Tu viens au séminaire vendredi ?", "Oui, à condition que la réunion du matin finisse à temps.", ["Oui, à condition que la réunion finit à temps.", "Oui, à condition de la réunion finisse."], "À condition que + subjunctive."], ["On part maintenant ?", "Attendons jusqu'à ce que la pluie s'arrête.", ["Attendons jusqu'à ce que la pluie s'arrêtera.", "Attendons jusqu'à la pluie s'arrête."], "Jusqu'à ce que + subjunctive."]]
});

L({ id: "b2-condpasse", lvl: "B2", tr: "temps2", cat: "hypothese", t: "Le conditionnel passé", en: "Regrets, reproaches and si + plus-que-parfait",
  rule: { h: "Si + plus-que-parfait → conditionnel passé: an imaginary past that did not happen.",
    pts: ["Form: <i>avoir / être</i> in the conditional + past participle: <i>j'aurais aimé, elle serait venue</i>.", "<b>Unreal past</b>: <i>si j'avais su, je serais venue</i> (but I didn't know, so I didn't come).", "<b>Regret</b>: <i>j'aurais dû t'écouter, j'aurais aimé être là</i>.", "<b>Reproach</b>: <i>tu aurais pu me prévenir !</i>", "<b>Mixed</b>: past condition, present result: <i>si j'avais pris ce poste, je vivrais à Lyon aujourd'hui</i>."],
    ex: [["Si nous étions partis plus tôt, nous n'aurions pas raté l'avion.", "If we had left earlier, we wouldn't have missed the plane."], ["J'aurais dû réserver plus tôt.", "I should have booked earlier."], ["Tu aurais pu m'appeler !", "You could have called me!"], ["Si j'avais appris le français enfant, je le parlerais sans accent.", "If I had learnt French as a child, I'd speak it without an accent."]],
    warn: "Never <i>si j'aurais su</i>: after si, the plus-que-parfait (<i>si j'avais su</i>).",
    vn: "<b>«Giá mà… thì đã…»</b>, <b>«lẽ ra… »</b>: <i>j'aurais dû</i> = lẽ ra tôi phải; <i>tu aurais pu</i> = lẽ ra bạn đã có thể; <i>si j'avais su, je serais venue</i> = giá mà biết thì tôi đã đến." },
  cards: [["j'aurais dû", "I should have", "J'aurais dû prendre un parapluie.", "I should have taken an umbrella."], ["tu aurais pu", "you could have", "Tu aurais pu me le dire !", "You could have told me!"], ["j'aurais aimé", "I would have liked", "J'aurais aimé rencontrer ton grand-père.", "I would have liked to meet your grandfather."], ["si j'avais su", "if I had known", "Si j'avais su, je ne serais pas venue.", "If I had known, I wouldn't have come."], ["regretter de", "to regret", "Je regrette de ne pas avoir appelé.", "I regret not calling."], ["un reproche", "a reproach", "Ce n'est pas un reproche, mais…", "It's not a criticism, but…"], ["à ta place, j'aurais…", "if I'd been you, I'd have…", "À ta place, j'aurais refusé.", "If I'd been you, I'd have refused."], ["sans toi", "without you", "Sans toi, je n'aurais jamais réussi.", "Without you, I'd never have succeeded."]],
  sent: [["Si j'avais su que tu étais à Paris, je t'aurais appelée.", "If I'd known you were in Paris, I'd have called you."], ["Nous aurions dû partir plus tôt.", "We should have left earlier."], ["Tu aurais pu me prévenir que tu serais en retard.", "You could have warned me you'd be late."], ["Elle serait venue si elle n'avait pas été malade.", "She would have come if she hadn't been ill."], ["J'aurais aimé que ma grand-mère voie notre mariage.", "I would have liked my grandmother to see our wedding."], ["Sans ton aide, je n'aurais jamais trouvé cet appartement.", "Without your help, I'd never have found this flat."], ["Si nous avions réservé, nous aurions eu une table.", "If we had booked, we'd have had a table."], ["À ta place, j'aurais demandé une augmentation.", "In your place, I would have asked for a raise."], ["Si tu avais pris le métro, tu serais déjà arrivée.", "If you'd taken the metro, you'd already be there."], ["Si j'avais accepté ce poste, je vivrais à Genève maintenant.", "If I'd accepted that job, I'd be living in Geneva now."]],
  nat: [["Si j'avais su, je serais venue.", "Si j'aurais su, je serais venue.", "After si: plus-que-parfait."], ["J'aurais dû t'écouter.", "J'aurais dû écouter toi.", "Pronoun before the infinitive."], ["Il serait venu s'il avait pu.", "Il aurait venu s'il avait pu.", "Venir takes être."], ["Si tu avais travaillé, tu aurais réussi.", "Si tu avais travaillé, tu réussiras.", "Unreal past → conditionnel passé."]],
  mcq: [["Si nous ___ le temps, nous serions passés te voir.", "avions eu", ["aurions eu", "avons eu", "aurons eu"], "Si + plus-que-parfait."], ["Tu ___ me demander avant de prendre ma voiture !", "aurais dû", ["devrais eu", "as dû", "devras"], "A reproach about the past: conditionnel passé of devoir."], ["Si elle avait pris le train, elle ___ à l'heure.", "serait arrivée", ["aurait arrivé", "arriverait été", "sera arrivée"], "Arriver → être; agreement with elle."], ["Si j'avais étudié le droit, je ___ avocate aujourd'hui.", "serais", ["aurais été", "serai", "étais"], "Mixed: past condition, present result → conditionnel présent."]],
  gap: [["Si tu m'avais demandé, je t'___ aidée.", "aurais", "avoir", "If you had asked me, I'd have helped you.", ["avais", "aurai", "aies"]], ["J'aurais ___ venir, mais j'étais malade.", "aimé", "aimer", "I would have liked to come, but I was ill.", ["aimer", "aimais", "aimée"]], ["Si nous ___ partis à l'heure, nous aurions eu le train.", "étions", "être", "If we'd left on time, we'd have caught the train.", ["serions", "avions", "sommes"]], ["Vous ___ dû réserver plus tôt.", "auriez", "avoir", "You should have booked earlier.", ["aurez", "aviez", "seriez"]], ["Sans ton message, je n'___ jamais su.", "aurais", "avoir", "Without your message, I'd never have known.", ["avais", "aurai", "ai"]], ["Elle ___ restée plus longtemps si elle avait pu.", "serait", "être", "She'd have stayed longer if she could have.", ["aurait", "sera", "était"]]],
  fix: [["Si j'aurais eu le temps, je serais venue.", "j'aurais eu", "j'avais eu", "After si: plus-que-parfait.", ["j'aurai eu", "j'ai eu"]], ["Il aurait venu avec nous.", "aurait venu", "serait venu", "Venir takes être.", ["aurait venue", "sera venu"]], ["Tu aurais pu me le dis.", "dis", "dire", "After pouvoir: infinitive.", ["dit", "disais"]]],
  xf: [["Express it as a regret with j'aurais dû.", "Je n'ai pas révisé.", "J'aurais dû réviser."], ["Make it an unreal past.", "Il pleut, donc je ne sors pas. (yesterday)", "S'il n'avait pas plu, je serais sortie.|S'il n'avait pas plu, je serais sorti."]],
  chat: [["J'ai raté l'entretien, j'étais trop stressée.", "Tu aurais dû me le dire, on se serait entraînées ensemble.", ["Tu devais me le dire, on s'entraînera.", "Tu aurais dû me le dis."], "Reproach and unreal past: conditionnel passé."], ["Tu regrettes d'être venue en France ?", "Non ! Si j'étais restée au Viêt Nam, je n'aurais pas rencontré Alex.", ["Si je serais restée au Viêt Nam…", "Si je restais au Viêt Nam, je ne rencontre pas Alex."], "Si + plus-que-parfait, then conditionnel passé."]]
});

L({ id: "b2-concordance", lvl: "B2", tr: "temps2", cat: "discours", t: "La concordance des temps", en: "Reported speech in the past",
  rule: { h: "When the reporting verb is in the past, the reported verbs move one step back.",
    pts: ["Présent → <b>imparfait</b>: <i>« Je suis fatiguée » → elle a dit qu'elle était fatiguée</i>.", "Passé composé → <b>plus-que-parfait</b>: <i>« J'ai fini » → il a dit qu'il avait fini</i>.", "Futur → <b>conditionnel présent</b>: <i>« Je viendrai » → elle a dit qu'elle viendrait</i>.", "Futur proche → <i>allait</i> + infinitive.", "Time words change: <i>aujourd'hui → ce jour-là, demain → le lendemain, hier → la veille, la semaine prochaine → la semaine suivante</i>."],
    ex: [["Elle m'a dit qu'elle habitait à Lyon.", "She told me she lived in Lyon."], ["Il a expliqué qu'il avait raté son train.", "He explained he had missed his train."], ["Ils ont promis qu'ils viendraient le lendemain.", "They promised they'd come the next day."], ["Je lui ai demandé s'il allait accepter.", "I asked him if he was going to accept."]],
    warn: "Imparfait, plus-que-parfait and conditional do not change: <i>« J'étais malade » → elle a dit qu'elle était malade</i>.",
    vn: "Tiếng Việt không đổi thì khi thuật lại (Cô ấy nói cô ấy <b>mệt</b>). Tiếng Pháp phải <b>lùi thì</b> khi động từ dẫn ở quá khứ: est → était, a fini → avait fini, viendra → viendrait." },
  cards: [["le lendemain", "the next day", "Il a dit qu'il partirait le lendemain.", "He said he'd leave the next day."], ["la veille", "the day before", "Elle a dit qu'elle était arrivée la veille.", "She said she had arrived the day before."], ["ce jour-là", "that day", "Il a dit qu'il était occupé ce jour-là.", "He said he was busy that day."], ["promettre que", "to promise that", "Il a promis qu'il rappellerait.", "He promised he would call back."], ["affirmer que", "to claim, to state that", "Elle a affirmé qu'elle n'avait rien vu.", "She stated she had seen nothing."], ["annoncer que", "to announce that", "Ils ont annoncé qu'ils se mariaient.", "They announced they were getting married."], ["avouer que", "to admit that", "Il a avoué qu'il avait oublié.", "He admitted he had forgotten."], ["la semaine suivante", "the following week", "Elle a dit qu'elle reviendrait la semaine suivante.", "She said she'd come back the following week."]],
  sent: [["Ma mère m'a dit qu'elle était fière de moi.", "My mother told me she was proud of me."], ["Le directeur a annoncé que l'entreprise allait recruter.", "The director announced the company was going to hire."], ["Elle a expliqué qu'elle avait perdu son badge.", "She explained she had lost her badge."], ["Ils nous ont promis qu'ils viendraient au mariage.", "They promised us they would come to the wedding."], ["Je lui ai demandé où elle avait acheté sa robe.", "I asked her where she had bought her dress."], ["Il a affirmé qu'il n'avait jamais reçu le colis.", "He claimed he had never received the parcel."], ["Le médecin m'a dit que je devais me reposer.", "The doctor told me I had to rest."], ["Alex a dit qu'il rentrerait le lendemain.", "Alex said he'd come home the next day."], ["Elle voulait savoir si nous avions déjà visité Hội An.", "She wanted to know if we had already visited Hội An."], ["Le guide a précisé que le musée fermait à dix-huit heures.", "The guide specified that the museum closed at six."]],
  nat: [["Il a dit qu'il était malade.", "Il a dit qu'il est malade hier.", "Past reporting verb → imparfait."], ["Elle a dit qu'elle viendrait.", "Elle a dit qu'elle viendra.", "Futur → conditionnel."], ["Il a avoué qu'il avait menti.", "Il a avoué qu'il a menti.", "Passé composé → plus-que-parfait."], ["Elle m'a dit qu'elle partait le lendemain.", "Elle m'a dit qu'elle partait demain.", "In a past story, demain → le lendemain."]],
  mcq: [["« Je suis contente. » → Elle a dit qu'elle ___ contente.", "était", ["est", "sera", "soit"], "Présent → imparfait."], ["« Nous partirons à six heures. » → Ils ont dit qu'ils ___ à six heures.", "partiraient", ["partiront", "partaient", "sont partis"], "Futur → conditionnel."], ["« J'ai trouvé un appartement. » → Il a annoncé qu'il ___ un appartement.", "avait trouvé", ["a trouvé", "trouvait", "trouverait"], "Passé composé → plus-que-parfait."], ["« Je pars demain. » → Elle a dit qu'elle partait ___.", "le lendemain", ["demain", "la veille", "hier"], "Demain → le lendemain."]],
  gap: [["« J'ai faim. » → Il a dit qu'il ___ faim.", "avait", "avoir", "He said he was hungry.", ["a", "aura", "aurait eu"]], ["« Je t'appellerai. » → Elle a promis qu'elle m'___.", "appellerait", "appeler", "She promised she would call me.", ["appellera", "appelait", "a appelé"]], ["« Nous avons visité Lyon. » → Ils ont dit qu'ils ___ Lyon.", "avaient visité", "visiter", "They said they had visited Lyon.", ["ont visité", "visitaient", "visiteraient"]], ["« Tu es libre ? » → Il m'a demandé si j'___ libre.", "étais", "être", "He asked me if I was free.", ["suis", "serai", "sois"]], ["« Je vais démissionner. » → Elle a dit qu'elle ___ démissionner.", "allait", "aller", "She said she was going to resign.", ["va", "ira", "irait"]], ["« Je suis arrivé hier. » → Il a dit qu'il était arrivé ___.", "la veille", "", "He said he had arrived the day before.", ["hier", "le lendemain", "demain"]]],
  fix: [["Elle m'a dit qu'elle viendra demain.", "viendra demain", "viendrait le lendemain", "Futur → conditionnel; demain → le lendemain.", ["viendrait demain", "vient le lendemain"]], ["Il a expliqué qu'il a perdu ses clés.", "a perdu", "avait perdu", "Passé composé → plus-que-parfait.", ["perdait", "perdra"]], ["Je lui ai demandé s'il est content.", "est", "était", "Présent → imparfait.", ["sera", "soit"]]],
  xf: [["Report in the past: Elle a dit que…", "« Je travaille à la maison aujourd'hui. »", "Elle a dit qu'elle travaillait à la maison ce jour-là."], ["Report in the past: Il a promis que…", "« Je finirai le rapport demain. »", "Il a promis qu'il finirait le rapport le lendemain."]],
  chat: [["Qu'est-ce que le propriétaire t'a dit ?", "Il m'a dit qu'il réparerait le chauffage la semaine suivante.", ["Il m'a dit qu'il réparera le chauffage la semaine prochaine.", "Il m'a dit qu'il répare le chauffage."], "Futur → conditionnel."], ["Et ta collègue, pourquoi elle est partie ?", "Elle a expliqué qu'elle avait trouvé un poste à Bordeaux.", ["Elle a expliqué qu'elle a trouvé un poste.", "Elle a expliqué qu'elle trouvera un poste."], "Passé composé → plus-que-parfait."]]
});

L({ id: "b2-futant", lvl: "B2", tr: "temps2", cat: "temps", t: "Le futur antérieur", en: "What will have happened before another future action",
  rule: { h: "The futur antérieur (avoir / être in the future + participle) marks an action completed before another future moment.",
    pts: ["Form: <i>j'aurai fini, elle sera partie, nous nous serons installés</i>.", "After <b>quand, dès que, lorsque, une fois que, après que</b>, when the action will be complete: <i>quand j'aurai fini, je t'appellerai</i>.", "Alone, with a time limit: <i>dans un an, j'aurai obtenu mon DALF</i>.", "To guess about the past: <i>il n'est pas là ? Il aura oublié</i> (he must have forgotten)."],
    ex: [["Quand tu auras lu ce livre, prête-le-moi.", "When you've read this book, lend it to me."], ["Dès que nous serons arrivés, nous t'enverrons un message.", "As soon as we've arrived, we'll send you a message."], ["D'ici juin, j'aurai terminé ma formation.", "By June, I'll have finished my training."], ["Il est en retard ; il aura raté son train.", "He's late; he must have missed his train."]],
    warn: "English uses the present perfect after <i>when</i> (<i>when I have finished</i>). French needs the futur antérieur: <i>quand j'aurai fini</i>.",
    vn: "Giống <b>«khi nào… xong thì…»</b>: <i>quand j'aurai fini</i> = khi nào tôi làm xong. Tiếng Việt chỉ thêm <b>xong, rồi</b>; tiếng Pháp cần một thì riêng." },
  cards: [["une fois que", "once", "Une fois que tu auras signé, c'est définitif.", "Once you've signed, it's final."], ["d'ici", "by (a deadline)", "D'ici ce soir, j'aurai fini.", "By tonight, I'll have finished."], ["dès que", "as soon as", "Dès qu'il sera rentré, on mangera.", "As soon as he's back, we'll eat."], ["terminer", "to finish", "Quand j'aurai terminé, je t'aiderai.", "When I've finished, I'll help you."], ["obtenir", "to obtain, to get", "D'ici un an, elle aura obtenu son diplôme.", "In a year's time she'll have got her diploma."], ["s'installer", "to settle in", "Quand nous nous serons installés, venez dîner.", "When we've settled in, come for dinner."], ["avoir oublié", "to have forgotten", "Il ne répond pas, il aura oublié son téléphone.", "He isn't answering, he must have forgotten his phone."], ["à la fin de", "at the end of", "À la fin de l'année, j'aurai lu vingt livres.", "By the end of the year, I'll have read twenty books."]],
  sent: [["Quand tu auras fini ton café, on y va.", "When you've finished your coffee, we'll go."], ["Dès que j'aurai reçu les résultats, je te préviendrai.", "As soon as I've got the results, I'll let you know."], ["D'ici décembre, nous aurons trouvé une salle pour la réception.", "By December, we'll have found a venue for the reception."], ["Une fois que vous aurez rempli le formulaire, envoyez-le.", "Once you've filled in the form, send it."], ["Lorsque les invités seront partis, nous rangerons.", "When the guests have left, we'll tidy up."], ["Dans deux ans, j'aurai passé le DALF C1.", "In two years, I'll have passed the DALF C1."], ["Elle n'est pas venue ; elle se sera trompée de jour.", "She didn't come; she must have got the day wrong."], ["Quand nous aurons visité le Louvre, nous irons au jardin des Tuileries.", "When we've visited the Louvre, we'll go to the Tuileries garden."], ["Après que tu auras parlé au directeur, appelle-moi.", "After you've spoken to the director, call me."], ["À la fin du stage, ils auront appris beaucoup de choses.", "By the end of the internship, they'll have learnt a lot."]],
  nat: [["Quand j'aurai fini, je sortirai.", "Quand j'ai fini, je sortirai.", "Completed before another future action: futur antérieur."], ["Dès qu'elle sera arrivée, on commencera.", "Dès qu'elle aura arrivé, on commencera.", "Arriver takes être."], ["D'ici lundi, j'aurai lu le rapport.", "D'ici lundi, j'ai lu le rapport.", "A deadline in the future: futur antérieur."], ["Une fois que nous aurons signé, nous fêterons ça.", "Une fois que nous signerons, nous avons fêté ça.", "Futur antérieur, then futur."]],
  mcq: [["Quand tu ___ tes devoirs, tu pourras jouer.", "auras fait", ["as fait", "feras", "aurais fait"], "Completed before the future action."], ["Dès que nous ___, nous vous écrirons.", "serons arrivés", ["aurons arrivé", "arrivons", "sommes arrivés"], "Arriver → être."], ["D'ici la fin du mois, j'___ tous mes cartons.", "aurai défait", ["ai défait", "aurais défait", "défaisais"], "A future deadline."], ["Il ne répond pas ? Il ___ son téléphone au bureau.", "aura laissé", ["laissera", "a laisser", "laissait"], "A guess about the past."]],
  gap: [["Quand j'___ terminé ce chapitre, j'irai me coucher.", "aurai", "avoir", "When I've finished this chapter, I'll go to bed.", ["ai", "aurais", "avais"]], ["Dès qu'elle ___ rentrée, nous dînerons.", "sera", "être", "As soon as she's home, we'll have dinner.", ["aura", "est", "serait"]], ["D'ici l'été, ils ___ trouvé un appartement.", "auront", "avoir", "By the summer, they'll have found a flat.", ["ont", "auraient", "avaient"]], ["Une fois que vous ___ payé, vous recevrez un reçu.", "aurez", "avoir", "Once you've paid, you'll receive a receipt.", ["avez", "auriez", "aviez"]], ["Lorsque nous nous ___ mariés, nous partirons en voyage.", "serons", "être", "When we've got married, we'll go travelling.", ["aurons", "sommes", "serions"]], ["Elle est en retard ; elle ___ raté le bus.", "aura", "avoir", "She's late; she must have missed the bus.", ["a", "aurait", "avait"]]],
  fix: [["Quand j'ai fini, je t'appellerai.", "j'ai fini", "j'aurai fini", "Completed before a future action: futur antérieur.", ["je finis", "j'aurais fini"]], ["Dès qu'il aura arrivé, on part.", "aura arrivé", "sera arrivé", "Arriver takes être.", ["est arrivé", "aurait arrivé"]], ["D'ici vendredi, j'aurai finir.", "finir", "fini", "Compound tenses use the participle.", ["finis", "finirai"]]],
  xf: [["Join with quand, using the futur antérieur.", "Je finis ma formation. Puis je chercherai un poste.", "Quand j'aurai fini ma formation, je chercherai un poste.|Quand j'aurai terminé ma formation, je chercherai un poste."], ["Use d'ici + futur antérieur.", "Je lis ce livre avant dimanche.", "D'ici dimanche, j'aurai lu ce livre."]],
  chat: [["On peut se voir après ton examen ?", "Oui, dès que j'aurai terminé, je t'enverrai un message.", ["Oui, dès que j'ai terminé, je t'envoie.", "Oui, dès que je terminerai, je t'ai envoyé."], "Completed before another future action."], ["Où est Alex ? Il devait être là à midi.", "Il aura oublié l'heure, comme d'habitude !", ["Il oubliait l'heure.", "Il oubliera l'heure demain."], "A guess about the past: futur antérieur."]]
});

L({ id: "b2-relcomp", lvl: "B2", tr: "phrase2", cat: "relatifs", t: "Lequel, auquel, duquel", en: "Compound relative pronouns after prepositions",
  rule: { h: "After a preposition, use lequel (agreeing with the noun); for people you can also use qui.",
    pts: ["<i>lequel, laquelle, lesquels, lesquelles</i> after <i>avec, pour, sans, dans, sur, par, parmi, entre</i>: <i>l'ordinateur avec lequel je travaille</i>.", "With <b>à</b>: <i>auquel, à laquelle, auxquels, auxquelles</i>: <i>le projet auquel je pense</i>.", "With <b>de</b> inside a phrase (<i>près de, à côté de, au cours de</i>): <i>duquel, de laquelle, desquels, desquelles</i>: <i>le parc près duquel j'habite</i>.", "For a person: <i>qui</i> is usual: <i>la collègue avec qui je travaille, l'ami à qui j'ai écrit</i>.", "Simple <b>de</b> (parler de, avoir besoin de): use <b>dont</b>, not duquel."],
    ex: [["Voici la raison pour laquelle je suis venue.", "Here is the reason why I came."], ["C'est un sujet auquel je réfléchis souvent.", "It's a subject I often think about."], ["La personne à qui j'ai parlé était très aimable.", "The person I spoke to was very kind."], ["L'immeuble en face duquel nous habitons est en travaux.", "The building opposite which we live is being renovated."]],
    warn: "Never <i>à lequel</i> or <i>de lequel</i>: contract them to <i>auquel, duquel</i> (and <i>auxquels, desquels</i>). <i>À laquelle, de laquelle</i> stay separate.",
    vn: "Tiếng Việt chỉ cần <b>mà</b> (cái máy <b>mà</b> tôi làm việc <b>với</b>). Tiếng Pháp đặt giới từ lên trước: <i>l'ordinateur <b>avec lequel</b> je travaille</i>, và lequel phải hợp giống, số với danh từ." },
  cards: [["avec lequel", "with which", "Le stylo avec lequel j'écris est neuf.", "The pen I'm writing with is new."], ["pour laquelle", "for which", "C'est la raison pour laquelle je pars.", "That's the reason why I'm leaving."], ["auquel", "to which (masc.)", "Le concours auquel j'ai participé était difficile.", "The competition I took part in was hard."], ["à laquelle", "to which (fem.)", "La conférence à laquelle j'assiste commence à 9 h.", "The conference I'm attending starts at 9."], ["duquel", "of which (masc.)", "Le jardin au milieu duquel il y a une fontaine…", "The garden in the middle of which there's a fountain…"], ["parmi lesquels", "among whom / which", "Des invités, parmi lesquels le maire.", "Guests, among them the mayor."], ["sans lequel", "without which", "Le badge sans lequel on ne peut pas entrer.", "The badge without which you can't get in."], ["grâce auquel", "thanks to which", "Le programme grâce auquel j'ai trouvé un emploi.", "The programme thanks to which I found a job."]],
  sent: [["Voilà l'outil avec lequel nous créons nos modules en ligne.", "Here's the tool we create our online modules with."], ["C'est la raison pour laquelle j'ai choisi ce master.", "That's why I chose this master's."], ["Le projet auquel je travaille sera lancé en mars.", "The project I'm working on will be launched in March."], ["La réunion à laquelle tu m'as invitée a été annulée.", "The meeting you invited me to was cancelled."], ["Les amis avec qui nous partons en vacances sont adorables.", "The friends we're going on holiday with are lovely."], ["C'est un problème auquel personne n'avait pensé.", "It's a problem nobody had thought of."], ["La table sur laquelle j'ai posé mes clés est dans l'entrée.", "The table I put my keys on is in the hall."], ["Le pont sous lequel passent les bateaux date du XVIIe siècle.", "The bridge under which the boats pass dates from the 17th century."], ["Plusieurs pays, parmi lesquels le Viêt Nam, ont signé l'accord.", "Several countries, including Vietnam, signed the agreement."], ["Le restaurant près duquel nous habitons est toujours plein.", "The restaurant near which we live is always full."]],
  nat: [["Le sujet auquel je pense est délicat.", "Le sujet à lequel je pense est délicat.", "À + lequel → auquel."], ["La raison pour laquelle je pars est simple.", "La raison pour lequel je pars est simple.", "Raison is feminine → laquelle."], ["Le livre dont je parle est épuisé.", "Le livre duquel je parle est épuisé.", "Simple de (parler de) → dont."], ["La collègue avec qui je travaille est italienne.", "La collègue avec que je travaille est italienne.", "After a preposition, never que: qui or laquelle."]],
  mcq: [["L'association ___ je participe aide les étudiants étrangers.", "à laquelle", ["auquel", "laquelle", "dont"], "Participer à + association (fem.) → à laquelle."], ["Ce sont des questions ___ je n'ai pas de réponse.", "auxquelles", ["auxquels", "dont", "lesquelles"], "Répondre / avoir une réponse à + questions (fem. pl.)."], ["Le collègue ___ j'ai prêté mon ordinateur est parti.", "à qui", ["que", "dont", "lequel"], "Prêter à + person → à qui (or auquel)."], ["Le bâtiment à côté ___ se trouve la gare est un musée.", "duquel", ["dont", "de lequel", "auquel"], "À côté de + bâtiment (masc.) → duquel."]],
  gap: [["Voici l'application avec ___ j'apprends le français.", "laquelle", "", "Here's the app I learn French with.", ["lequel", "qui", "que"]], ["C'est un détail ___ je n'avais pas fait attention.", "auquel", "", "It's a detail I hadn't paid attention to.", ["à lequel", "dont", "lequel"]], ["Les raisons pour ___ il est parti restent floues.", "lesquelles", "", "The reasons why he left remain unclear.", ["lesquels", "laquelle", "qui"]], ["La personne à ___ j'ai envoyé le dossier ne répond pas.", "qui|laquelle", "", "The person I sent the file to isn't answering.", ["que", "dont", "lequel"]], ["Le parc au milieu ___ se trouve le lac est magnifique.", "duquel", "", "The park in the middle of which there's a lake is magnificent.", ["dont", "auquel", "de lequel"]], ["Ce sont des conditions sans ___ nous ne signerons pas.", "lesquelles", "", "These are conditions without which we won't sign.", ["lesquels", "quoi", "qui"]]],
  fix: [["C'est le projet à lequel je pense.", "à lequel", "auquel", "À + lequel → auquel.", ["duquel", "dont"]], ["La raison pour lequel je t'appelle est simple.", "lequel", "laquelle", "Raison is feminine.", ["lesquels", "quoi"]], ["La femme avec que je travaille est sympa.", "que", "qui", "After a preposition, use qui for a person.", ["dont", "lequel"]]],
  xf: [["Join with a compound relative pronoun.", "Je travaille sur un projet. Ce projet est passionnant.", "Le projet sur lequel je travaille est passionnant."], ["Join with a compound relative pronoun.", "J'ai assisté à une conférence. La conférence était en anglais.", "La conférence à laquelle j'ai assisté était en anglais."]],
  chat: [["Pourquoi tu as quitté ton ancien poste ?", "La raison pour laquelle je suis partie, c'est le manque de perspectives.", ["La raison pour lequel je suis partie…", "La raison que je suis partie…"], "Raison (fem.) → pour laquelle."], ["C'est quoi, ce logiciel ?", "C'est l'outil avec lequel on conçoit nos formations en ligne.", ["C'est l'outil avec que on conçoit…", "C'est l'outil dont on conçoit avec."], "After avec: lequel."]]
});

L({ id: "b2-passif", lvl: "B2", tr: "phrase2", cat: "syntaxe", t: "La voix passive", en: "Passive voice and its alternatives",
  rule: { h: "Passive = être (in the tense of the active verb) + past participle agreeing with the subject; the agent is introduced by par.",
    pts: ["<i>Le directeur a signé le contrat → le contrat <b>a été signé</b> par le directeur</i>.", "The participle agrees with the subject: <i>la loi a été votée, les décisions seront prises</i>.", "<b>De</b> instead of par with verbs of feeling or description: <i>il est aimé de tous, la ville est entourée de montagnes</i>.", "French uses the passive less than English. Alternatives: <b>on</b> (<i>on m'a volé mon vélo</i>) and the <b>pronominal</b> form (<i>ce plat se mange froid, ça ne se fait pas</i>).", "Only verbs with a direct object can be passive: you cannot say <i>j'ai été demandé de…</i> → <i>on m'a demandé de…</i>."],
    ex: [["Le musée a été construit au XIXe siècle.", "The museum was built in the 19th century."], ["Les candidats seront informés par e-mail.", "Candidates will be informed by email."], ["On m'a offert un poste à Lyon.", "I was offered a job in Lyon."], ["Le vin blanc se boit frais.", "White wine is drunk chilled."]],
    warn: "English <i>I was told</i>, <i>I was given</i>, <i>I was asked</i> cannot be passive in French: <i>on m'a dit, on m'a donné, on m'a demandé</i>.",
    vn: "Tiếng Việt dùng <b>bị</b> (xấu) hoặc <b>được</b> (tốt). Tiếng Pháp chỉ có một cấu trúc trung tính: <b>être + participe</b>. Nhưng người Pháp hay dùng <b>on</b> hơn: <i>On m'a volé mon vélo</i> = Tôi bị mất cắp xe đạp." },
  cards: [["être construit", "to be built", "Ce pont a été construit en 1900.", "This bridge was built in 1900."], ["par", "by (agent)", "Le livre a été traduit par une poétesse.", "The book was translated by a poet."], ["être aimé de", "to be loved by", "Ce professeur est aimé de ses élèves.", "This teacher is loved by his students."], ["être entouré de", "to be surrounded by", "Le village est entouré de rizières.", "The village is surrounded by rice fields."], ["on m'a dit", "I was told", "On m'a dit que c'était fermé.", "I was told it was closed."], ["se vendre", "to sell, to be sold", "Ce livre se vend très bien.", "This book is selling very well."], ["ça ne se fait pas", "it's not done", "Arriver les mains vides, ça ne se fait pas.", "Arriving empty-handed is not done."], ["être prévu", "to be planned", "La réunion est prévue à 10 h.", "The meeting is scheduled for 10."]],
  sent: [["Le contrat a été signé hier soir.", "The contract was signed last night."], ["Les résultats seront publiés en juillet.", "The results will be published in July."], ["Cette formation a été conçue par notre équipe.", "This training course was designed by our team."], ["La cathédrale est visitée par des millions de touristes.", "The cathedral is visited by millions of tourists."], ["On m'a demandé de présenter le projet.", "I was asked to present the project."], ["Le phở se mange avec des baguettes et une cuillère.", "Phở is eaten with chopsticks and a spoon."], ["La décision n'a pas encore été prise.", "The decision has not yet been taken."], ["Ma grand-mère était respectée de tout le village.", "My grandmother was respected by the whole village."], ["Les invitations ont été envoyées la semaine dernière.", "The invitations were sent last week."], ["Le français se parle sur cinq continents.", "French is spoken on five continents."]],
  nat: [["On m'a donné un badge.", "J'ai été donné un badge.", "Donner à quelqu'un is indirect: use on."], ["La loi a été votée en 2023.", "La loi a été voté en 2023.", "Agreement with the subject: votée."], ["Il est aimé de tous.", "Il est aimé par tous.", "With feelings, de is preferred."], ["Ce plat se mange chaud.", "Ce plat est mangé chaud normalement par on.", "General rule: pronominal passive."]],
  mcq: [["Les travaux ___ l'année prochaine.", "seront terminés", ["seront terminé", "auront terminés", "terminera"], "Future passive, agreement with travaux."], ["___ que la réunion était annulée.", "On m'a dit", ["J'ai été dit", "Je suis dit", "Il m'a été dit par on"], "Dire à quelqu'un → on m'a dit."], ["La maison est entourée ___ un grand jardin.", "d'", ["par", "avec", "à"], "Description: entouré de."], ["Ce mot ne ___ plus aujourd'hui.", "s'emploie", ["est employé par on", "emploie", "s'est employé hier"], "A general habit: pronominal form."]],
  gap: [["Le rapport a été ___ par la directrice.", "validé", "valider", "The report was approved by the director.", ["validée", "valider", "validés"]], ["Les décisions ___ prises demain.", "seront", "être", "The decisions will be taken tomorrow.", ["auront", "sont été", "serons"]], ["Cette chanson est connue ___ tout le monde.", "de", "", "This song is known by everyone.", ["par", "à", "avec"]], ["___ m'a volé mon portefeuille dans le métro.", "On", "", "My wallet was stolen in the metro.", ["Il", "J'", "Ils m'"]], ["Les billets ___ vendus en ligne uniquement.", "sont", "être", "Tickets are sold online only.", ["ont", "se sont", "étaient été"]], ["Ce vin se ___ avec du fromage.", "boit", "boire", "This wine is drunk with cheese.", ["bu", "boire", "buvait été"]]],
  fix: [["J'ai été offert un cadeau.", "J'ai été offert", "On m'a offert", "Offrir à quelqu'un is indirect: on m'a offert.", ["Je suis offerte", "Il m'a été offert par on"]], ["La maison a été vendu en mai.", "vendu", "vendue", "Agreement with la maison.", ["vendus", "vendre"]], ["Le projet sera présenté de la directrice.", "de", "par", "An action with an agent → par.", ["à", "avec"]]],
  xf: [["Make it passive.", "Le jury annoncera les résultats.", "Les résultats seront annoncés par le jury."], ["Rewrite with on.", "J'ai été informée du changement.", "On m'a informée du changement.|On m'a informé du changement."]],
  chat: [["Tu as eu des nouvelles de ta candidature ?", "Oui, on m'a proposé un entretien jeudi.", ["Oui, j'ai été proposée un entretien.", "Oui, un entretien m'a proposé."], "Proposer à quelqu'un: use on."], ["Le nouveau module est en ligne ?", "Pas encore, il sera publié lundi après validation.", ["Il sera publiée lundi.", "Il publiera lundi par nous."], "Passive future with agreement."]]
});

L({ id: "b2-participe", lvl: "B2", tr: "phrase2", cat: "syntaxe", t: "Participe présent et gérondif", en: "-ant forms: en travaillant, ayant fini",
  rule: { h: "Gérondif (en + -ant) refers to the subject of the sentence; the participe présent (-ant alone) describes a noun, mostly in writing.",
    pts: ["Form: nous-form minus <i>-ons</i> + <b>-ant</b>: <i>parlons → parlant, finissons → finissant</i>. Irregular: <i>étant, ayant, sachant</i>.", "<b>Gérondif</b> = same subject, two simultaneous actions, or the manner / the condition: <i>j'écoute des podcasts en cuisinant; c'est en forgeant qu'on devient forgeron</i>.", "<b>Participe présent</b> = replaces <i>qui</i> + verb, or gives a cause, in written style: <i>les candidats ayant réussi recevront un mail; étant malade, il n'est pas venu</i>.", "Compound form <b>ayant / étant + participle</b> for an earlier action: <i>ayant terminé mon travail, je suis sortie</i>.", "<i>Tout en</i> + gérondif adds opposition: <i>tout en étant fatiguée, elle a continué</i>."],
    ex: [["Je me suis cassé le bras en tombant.", "I broke my arm falling."], ["En partant maintenant, tu arriveras à l'heure.", "If you leave now, you'll arrive on time."], ["Les personnes souhaitant participer doivent s'inscrire.", "People wishing to take part must sign up."], ["Ayant raté le train, elle a pris un taxi.", "Having missed the train, she took a taxi."]],
    warn: "The gérondif must refer to the subject. <i>En arrivant, le chat m'a accueillie</i> means the cat arrived. Say: <i>quand je suis arrivée, le chat m'a accueillie</i>.",
    vn: "<b>vừa… vừa…</b> hoặc <b>bằng cách…</b> → gérondif: <i>Tôi nghe nhạc trong khi nấu ăn</i> = j'écoute de la musique <b>en cuisinant</b>. Chủ ngữ của hai hành động phải giống nhau." },
  cards: [["en + -ant", "while / by doing", "Elle chante en travaillant.", "She sings while working."], ["tout en", "while (with contrast)", "Tout en étant timide, il parle bien.", "Although shy, he speaks well."], ["étant", "being", "Étant fatiguée, je suis rentrée.", "Being tired, I went home."], ["ayant", "having", "Ayant fini, il est parti.", "Having finished, he left."], ["sachant que", "knowing that", "Sachant que tu aimes le thé, j'en ai acheté.", "Knowing you like tea, I bought some."], ["souhaitant", "wishing", "Les candidats souhaitant s'inscrire…", "Candidates wishing to register…"], ["en attendant", "while waiting, meanwhile", "En attendant, prends un café.", "Meanwhile, have a coffee."], ["c'est en… que", "it's by… that", "C'est en pratiquant qu'on progresse.", "It's by practising that you improve."]],
  sent: [["J'ai appris beaucoup de vocabulaire en regardant des séries.", "I learnt a lot of vocabulary watching series."], ["En prenant le métro, tu gagnes vingt minutes.", "By taking the metro, you save twenty minutes."], ["Il est entré en souriant.", "He came in smiling."], ["Les participants ayant un badge peuvent entrer.", "Participants with a badge may enter."], ["Ayant vécu à Saïgon, Alex comprend un peu le vietnamien.", "Having lived in Saigon, Alex understands a little Vietnamese."], ["Tout en aimant Paris, elle rêve parfois de la mer.", "While loving Paris, she sometimes dreams of the sea."], ["En arrivant au bureau, j'ai vu le message.", "When I got to the office, I saw the message."], ["Étant donné l'heure, nous devrions partir.", "Given the time, we should leave."], ["Sachant que le musée ferme tôt, nous y sommes allés le matin.", "Knowing the museum closes early, we went in the morning."], ["C'est en écrivant tous les jours qu'on progresse à l'écrit.", "It's by writing every day that you improve in writing."]],
  nat: [["Quand je suis arrivée, le chat dormait.", "En arrivant, le chat dormait.", "The gérondif must share the subject of the sentence: here it would mean the cat was arriving."], ["Ayant fini mon travail, je suis partie.", "Ayant finie mon travail, je suis partie.", "Ayant + participle: no agreement here."], ["En lisant, on apprend.", "En lisons, on apprend.", "Gérondif: en + -ant."], ["Sachant cela, j'ai accepté.", "Savant cela, j'ai accepté.", "Savoir → sachant."]],
  mcq: [["Il s'est blessé ___ du ski.", "en faisant", ["faisant en", "à faire", "en fait"], "Gérondif: en faisant."], ["___ malade, elle n'est pas venue.", "Étant", ["En étant", "Été", "Être"], "Cause in written style: participe présent."], ["Les étudiants ___ le cours peuvent s'inscrire à l'examen.", "ayant suivi", ["en suivant", "suivant ayant", "ayant suivis"], "Compound participle replacing qui ont suivi."], ["On apprend à nager ___.", "en nageant", ["nageant en", "à nager en", "en nager"], "Manner: gérondif."]],
  gap: [["Elle écoute la radio ___ le petit-déjeuner.", "en préparant", "préparer", "She listens to the radio while making breakfast.", ["préparant", "en préparer", "en préparé"]], ["___ un peu de temps libre, elle est passée nous voir.", "Ayant", "avoir", "Having a little free time, she dropped by to see us.", ["Étant", "En ayant eu", "Eu"]], ["___ que tu étais occupée, je ne t'ai pas appelée.", "Sachant", "savoir", "Knowing you were busy, I didn't call you.", ["Savant", "En sachant", "Su"]], ["Il est parti ___ au revoir.", "sans dire", "dire", "He left without saying goodbye.", ["en ne disant pas", "sans disant", "sans dit"]], ["C'est en ___ qu'on devient forgeron.", "forgeant", "forger", "Practice makes perfect.", ["forgeons", "forgé", "forger"]], ["___ terminé ses études, elle est rentrée au Viêt Nam.", "Ayant", "avoir", "Having finished her studies, she went back to Vietnam.", ["Étant", "En ayant", "Avant"]]],
  fix: [["En arrivant à la gare, le train était déjà parti.", "En arrivant à la gare", "Quand je suis arrivée à la gare", "The gérondif would refer to le train. Use a clause.", ["En arrivant le train", "Arrivant"]], ["Il travaille en écoutant de la musique et en chante.", "en chante", "en chantant", "Gérondif: en + -ant.", ["chantant", "en chanter"]], ["Savant la vérité, il n'a rien dit.", "Savant", "Sachant", "Savoir → sachant.", ["Saviez", "Sachez"]]],
  xf: [["Use a gérondif.", "Pendant que je cuisine, j'écoute des podcasts.", "J'écoute des podcasts en cuisinant."], ["Use ayant + participle.", "Comme elle avait réussi l'examen, elle a fêté ça.", "Ayant réussi l'examen, elle a fêté ça."]],
  chat: [["Comment tu as appris le français si vite ?", "En lisant beaucoup et en parlant avec la famille d'Alex.", ["En lisons beaucoup.", "Lisant beaucoup en parlant."], "Manner: gérondif."], ["Tu as trouvé le bureau facilement ?", "Oui, en suivant le plan que tu m'as envoyé.", ["Oui, suivant en le plan.", "Oui, en suit le plan."], "Gérondif: en suivant."]]
});

L({ id: "b2-relief", lvl: "B2", tr: "phrase2", cat: "syntaxe", t: "La mise en relief", en: "C'est… qui / que, ce qui… c'est",
  rule: { h: "To highlight an element, French moves it into a frame: c'est… qui/que, or ce qui / ce que… c'est.",
    pts: ["Subject: <i><b>C'est</b> Alex <b>qui</b> a choisi le restaurant</i>.", "Other elements: <i><b>C'est</b> à Saïgon <b>que</b> nous nous sommes mariés</i>.", "<b>Ce qui</b> (subject) / <b>ce que</b> (object) / <b>ce dont</b> (de)… <b>c'est</b>: <i>ce que j'aime, c'est la lumière de Paris</i>.", "Dislocation in speech: <i>Paris, je l'adore. Moi, je trouve que…</i>", "With a person pronoun: <i>c'est moi qui ai raison</i> — the verb agrees with moi."],
    ex: [["C'est elle qui m'a appris à cuisiner.", "She's the one who taught me to cook."], ["C'est en 2022 que nous nous sommes rencontrés.", "It was in 2022 that we met."], ["Ce qui me manque, c'est le soleil.", "What I miss is the sun."], ["Ce dont j'ai besoin, c'est d'un peu de repos.", "What I need is a little rest."]],
    warn: "<i>C'est moi qui <b>ai</b> raison, c'est nous qui <b>avons</b> décidé</i>: the verb agrees with the pronoun, not with il.",
    vn: "Giống <b>«Chính… là người…»</b> hoặc <b>«Điều tôi… là…»</b>: <i>C'est Alex qui a choisi</i> = Chính Alex là người chọn. <i>Ce qui me manque, c'est…</i> = Điều tôi nhớ là…" },
  cards: [["c'est… qui", "it's… who/that (subject)", "C'est ma mère qui a fait ce gâteau.", "My mother is the one who made this cake."], ["c'est… que", "it's… that (other)", "C'est demain que tout se décide.", "It's tomorrow that everything is decided."], ["ce qui… c'est", "what… is (subject)", "Ce qui compte, c'est la santé.", "What matters is health."], ["ce que… c'est", "what… is (object)", "Ce que je préfère, c'est le printemps.", "What I prefer is spring."], ["ce dont… c'est", "what… is (de)", "Ce dont je rêve, c'est d'un jardin.", "What I dream of is a garden."], ["ce à quoi", "what (à)", "Ce à quoi je pense, c'est l'avenir.", "What I'm thinking about is the future."], ["moi, je", "as for me", "Moi, je préfère la mer.", "Me, I prefer the sea."], ["voilà pourquoi", "that's why", "Voilà pourquoi j'ai refusé.", "That's why I refused."]],
  sent: [["C'est Alex qui a fait la demande en mariage, à Hội An.", "Alex is the one who proposed, in Hội An."], ["C'est à Paris que j'ai découvert le fromage.", "It was in Paris that I discovered cheese."], ["Ce qui m'a surprise, c'est la gentillesse des gens.", "What surprised me was how kind people were."], ["Ce que je cherche, c'est un poste plus stratégique.", "What I'm looking for is a more strategic role."], ["Ce dont nous avons besoin, c'est d'une salle plus grande.", "What we need is a bigger room."], ["C'est nous qui organisons la fête cette année.", "We're the ones organising the party this year."], ["C'est pour toi que j'ai acheté ces fleurs.", "It's for you that I bought these flowers."], ["Le bruit, je ne le supporte plus.", "The noise, I can't stand it any more."], ["C'est en pratiquant chaque jour que j'ai progressé.", "It's by practising every day that I improved."], ["Ce à quoi je ne m'attendais pas, c'est la neige en avril.", "What I didn't expect was snow in April."]],
  nat: [["C'est moi qui ai raison.", "C'est moi qui a raison.", "Agreement with moi: ai."], ["Ce qui me plaît, c'est le calme.", "Ce que me plaît, c'est le calme.", "Subject of plaît → ce qui."], ["Ce dont j'ai envie, c'est d'un voyage.", "Ce que j'ai envie, c'est un voyage.", "Avoir envie de → ce dont… c'est de."], ["C'est en mai que nous partons.", "C'est en mai qui nous partons.", "A time complement → que."]],
  mcq: [["___ m'inquiète, c'est le prix.", "Ce qui", ["Ce que", "Ce dont", "Qui"], "Subject of inquiète."], ["C'est vous qui ___ choisi ?", "avez", ["a", "ont", "avons"], "Agreement with vous."], ["___ j'ai peur, c'est de l'échec.", "Ce dont", ["Ce que", "Ce qui", "Dont"], "Avoir peur de → ce dont."], ["C'est grâce à toi ___ j'ai réussi.", "que", ["qui", "dont", "où"], "A complement → c'est… que."]],
  gap: [["C'est ma sœur ___ m'a présenté Alex.", "qui", "", "My sister is the one who introduced me to Alex.", ["que", "dont", "ce qui"]], ["___ j'adore à Paris, ce sont les marchés.", "Ce que", "", "What I love in Paris are the markets.", ["Ce qui", "Ce dont", "Qu'"]], ["C'est toi qui ___ le dernier mot.", "as", "avoir", "You have the last word.", ["a", "ai", "avez"]], ["___ me fait rire, c'est son accent.", "Ce qui", "", "What makes me laugh is his accent.", ["Ce que", "Ce dont", "Qui"]], ["C'est en Bretagne ___ nous passons l'été.", "que", "", "It's in Brittany that we spend the summer.", ["qui", "où", "dont"]], ["___ je me souviens, c'est de son sourire.", "Ce dont", "", "What I remember is her smile.", ["Ce que", "Ce qui", "Dont"]]],
  fix: [["C'est nous qui a gagné.", "a gagné", "avons gagné", "Agreement with nous.", ["ont gagné", "ai gagné"]], ["Ce que me dérange, c'est le bruit.", "Ce que", "Ce qui", "Subject of dérange → ce qui.", ["Ce dont", "Qui"]], ["Ce que j'ai besoin, c'est de dormir.", "Ce que", "Ce dont", "Avoir besoin de → ce dont.", ["Ce qui", "Ce à quoi"]]],
  xf: [["Highlight the subject.", "Lan Anh a trouvé la salle.", "C'est Lan Anh qui a trouvé la salle."], ["Begin with Ce que… c'est.", "J'aime surtout la lumière du matin.", "Ce que j'aime surtout, c'est la lumière du matin.|Ce que j'aime, c'est la lumière du matin."]],
  chat: [["Qu'est-ce qui te plaît le plus dans ton travail ?", "Ce qui me plaît le plus, c'est de concevoir des parcours de formation.", ["Ce que me plaît le plus…", "Qui me plaît, c'est concevoir."], "Subject of plaît → ce qui."], ["C'est qui qui a choisi ce restaurant ?", "C'est moi qui l'ai choisi, il te plaît ?", ["C'est moi qui l'a choisi.", "C'est moi que l'ai choisi."], "C'est moi qui ai."]]
});

L({ id: "b2-demonstr", lvl: "B2", tr: "phrase2", cat: "pronoms", t: "Celui, le mien", en: "Demonstrative and possessive pronouns",
  rule: { h: "Celui / celle / ceux / celles replace a noun already mentioned; le mien / la tienne… replace a possessive + noun.",
    pts: ["<b>Celui-ci / celui-là</b> to choose: <i>quelle robe ? — celle-ci</i>.", "<b>Celui qui / que / dont / où</b>: <i>celui que je préfère, ceux dont je t'ai parlé</i>.", "<b>Celui de</b> for possession: <i>mon téléphone et celui d'Alex</i>.", "Possessives: <i>le mien, la mienne, les miens, les miennes; le tien…; le sien…; le nôtre, la nôtre, les nôtres; le vôtre…; le leur, la leur, les leurs</i>.", "With à and de: <i>je pense au tien, je parle du sien</i>."],
    ex: [["Quel gâteau tu veux ? — Celui au chocolat.", "Which cake do you want? — The chocolate one."], ["Ceux qui veulent venir sont les bienvenus.", "Those who want to come are welcome."], ["Mon vélo est cassé ; je peux prendre le tien ?", "My bike is broken; can I take yours?"], ["Leur appartement est plus grand que le nôtre.", "Their flat is bigger than ours."]],
    warn: "<i>Le nôtre, le vôtre</i> take a circumflex; <i>notre, votre</i> (adjectives) do not.",
    vn: "<b>cái này / cái kia</b> → celui-ci / celui-là; <b>của tôi</b> → le mien / la mienne. Tiếng Pháp phải chọn giống và số theo <b>danh từ được thay thế</b>, không theo người sở hữu: <i>la sienne</i> có thể là «của anh ấy»." },
  cards: [["celui-ci", "this one", "Je prends celui-ci.", "I'll take this one."], ["celle-là", "that one (fem.)", "Pas cette robe, celle-là.", "Not this dress, that one."], ["ceux qui", "those who", "Ceux qui ont fini peuvent partir.", "Those who've finished can leave."], ["celui de", "the one of / …'s", "Ce sac, c'est celui de ma mère.", "This bag is my mother's."], ["le mien", "mine (masc.)", "Ton café est froid ? Le mien aussi.", "Your coffee is cold? Mine too."], ["la tienne", "yours (fem., tu)", "Ma valise est rouge, et la tienne ?", "My suitcase is red, and yours?"], ["le nôtre", "ours", "Votre jardin est plus grand que le nôtre.", "Your garden is bigger than ours."], ["les leurs", "theirs (plural)", "Nos enfants jouent avec les leurs.", "Our children play with theirs."]],
  sent: [["Entre les deux appartements, je préfère celui qui a un balcon.", "Of the two flats, I prefer the one with a balcony."], ["Mes parents habitent à Đà Lạt, ceux d'Alex à Bordeaux.", "My parents live in Đà Lạt, Alex's in Bordeaux."], ["Ce n'est pas ton parapluie, c'est le mien.", "It's not your umbrella, it's mine."], ["Ceux qui arrivent en retard attendront dehors.", "Those who arrive late will wait outside."], ["Ta proposition est meilleure que la mienne.", "Your proposal is better than mine."], ["Parmi tous les cafés du quartier, celui-ci est mon préféré.", "Of all the cafés in the area, this one is my favourite."], ["Nos invités et les leurs seront à la même table.", "Our guests and theirs will be at the same table."], ["J'ai oublié mon chargeur ; tu peux me prêter le tien ?", "I forgot my charger; can you lend me yours?"], ["Celle dont je t'ai parlé travaille à l'OCDE.", "The woman I told you about works at the OECD."], ["Mon dossier est complet ; et le vôtre, madame ?", "My file is complete; what about yours, madam?"]],
  nat: [["Ma voiture est grise, la tienne est bleue.", "Ma voiture est grise, le tien est bleu.", "Voiture is feminine → la tienne."], ["Celui que je préfère, c'est le rouge.", "Celui qui je préfère, c'est le rouge.", "Object → celui que."], ["Notre maison est petite, la vôtre est grande.", "Notre maison est petite, la votre est grande.", "La vôtre takes a circumflex."], ["Ce livre, c'est celui de Marie.", "Ce livre, c'est le de Marie.", "Possession → celui de."]],
  mcq: [["Mes clés sont ici. Où sont ___ ?", "les tiennes", ["les tiens", "la tienne", "le tien"], "Clés is feminine plural."], ["Quelle chemise ? ___ que j'ai achetée hier.", "Celle", ["Celui", "Ceux", "Cette"], "Chemise is feminine."], ["Leurs enfants sont plus âgés que ___.", "les nôtres", ["les notres", "nos", "la nôtre"], "Plural, with circumflex."], ["___ qui ont réservé peuvent entrer.", "Ceux", ["Celui", "Ces", "Les uns"], "Plural people."]],
  gap: [["Ton idée est meilleure que la ___.", "mienne", "", "Your idea is better than mine.", ["mien", "miennes", "mon"]], ["Ces chaussures sont jolies, mais je préfère ___-là.", "celles", "", "These shoes are nice, but I prefer those.", ["ceux", "celle", "ces"]], ["Mon train part à 8 h ; ___ de Claire à 9 h.", "celui", "", "My train leaves at 8; Claire's at 9.", ["celle", "le sien", "ce"]], ["Notre mariage sera en janvier ; le ___ en juin ?", "vôtre", "", "Our wedding will be in January; yours in June?", ["votre", "vôtres", "vous"]], ["Elle a perdu son badge ; je lui ai prêté le ___.", "mien", "", "She lost her badge; I lent her mine.", ["mienne", "mon", "miens"]], ["___ dont tu parles n'existe plus.", "Celui|Celle", "", "The one you're talking about no longer exists.", ["Ce", "Lequel", "Cela"]]],
  fix: [["Ma valise est lourde, mais le tien est plus lourde.", "le tien", "la tienne", "Valise is feminine.", ["les tiens", "ton"]], ["Notre maison est plus petite que la votre.", "la votre", "la vôtre", "Pronoun → vôtre with a circumflex.", ["la vôtres", "votre"]], ["Ceux qui je connais sont gentils.", "Ceux qui", "Ceux que", "Object of connais → que.", ["Ceux dont", "Ceux où"]]],
  xf: [["Avoid repeating the noun.", "Mon ordinateur est lent. Ton ordinateur est rapide.", "Mon ordinateur est lent, le tien est rapide.|Mon ordinateur est lent. Le tien est rapide."], ["Avoid repeating the noun.", "Les gens qui sont venus étaient contents.", "Ceux qui sont venus étaient contents."]],
  chat: [["C'est ton écharpe, celle-ci ?", "Non, la mienne est bleue ; celle-ci doit être celle de Claire.", ["Non, le mien est bleu.", "Non, la mien est bleue."], "Écharpe is feminine."], ["Vos parents viennent au mariage ?", "Oui, les miens et ceux d'Alex seront là.", ["Oui, les miennes et celles d'Alex.", "Oui, mes et les d'Alex."], "Parents is masculine plural: les miens, ceux de."]]
});

/* ── data/b2b.js ── */
/* B2 lessons · part 2 */
L({ id: "b2-argu", lvl: "B2", tr: "argu", cat: "argumentation", t: "Structurer une argumentation", en: "Introducing, ordering, adding and concluding",
  rule: { h: "A B2 argument has a clear position, ordered arguments with examples, and a conclusion — each step announced by a connector.",
    pts: ["<b>Introduce</b>: <i>De nos jours, on entend souvent dire que… · La question se pose de savoir si…</i>", "<b>Order</b>: <i>d'abord / tout d'abord, ensuite, de plus, enfin · d'une part… d'autre part</i>.", "<b>Add and reinforce</b>: <i>en outre, par ailleurs, non seulement… mais aussi</i>.", "<b>Illustrate</b>: <i>par exemple, ainsi, notamment, prenons le cas de…</i>", "<b>Conclude</b>: <i>en somme, pour conclure, en définitive, c'est pourquoi je pense que…</i>"],
    ex: [["Tout d'abord, le télétravail permet de gagner du temps.", "First of all, remote work saves time."], ["De plus, il réduit la pollution liée aux transports.", "Moreover, it reduces transport pollution."], ["Prenons l'exemple des grandes villes comme Paris.", "Take the example of big cities like Paris."], ["En somme, ses avantages l'emportent sur ses inconvénients.", "In short, its advantages outweigh its drawbacks."]],
    warn: "One argument per paragraph, each with an example. A list of connectors with no example behind them reads as empty.",
    vn: "Bài nghị luận DELF B2 giống bài văn nghị luận ở Việt Nam: <b>mở bài – thân bài (2–3 luận điểm có ví dụ) – kết bài</b>. Khác biệt: người Pháp đánh giá cao <b>từ nối</b> rõ ràng và việc <b>xét cả ý kiến trái chiều</b>." },
  cards: [["tout d'abord", "first of all", "Tout d'abord, rappelons les faits.", "First of all, let's recall the facts."], ["en outre", "furthermore", "En outre, le coût est raisonnable.", "Furthermore, the cost is reasonable."], ["par ailleurs", "besides, in addition", "Par ailleurs, il faut penser aux enfants.", "Besides, we have to think of the children."], ["d'une part… d'autre part", "on the one hand… on the other", "D'une part c'est utile, d'autre part c'est agréable.", "On the one hand it's useful, on the other it's pleasant."], ["prenons l'exemple de", "take the example of", "Prenons l'exemple du Danemark.", "Take the example of Denmark."], ["l'emporter sur", "to outweigh, to prevail over", "Les avantages l'emportent sur les risques.", "The advantages outweigh the risks."], ["en définitive", "ultimately", "En définitive, tout dépend du contexte.", "Ultimately, everything depends on the context."], ["un argument de poids", "a strong argument", "Le prix est un argument de poids.", "Price is a strong argument."]],
  sent: [["De nos jours, de plus en plus d'entreprises proposent le télétravail.", "Nowadays more and more companies offer remote work."], ["La question est de savoir si cette mesure est efficace.", "The question is whether this measure is effective."], ["Tout d'abord, les transports en commun sont moins chers.", "First of all, public transport is cheaper."], ["Ensuite, ils sont meilleurs pour l'environnement.", "Next, they are better for the environment."], ["Non seulement le vélo est rapide, mais il est aussi bon pour la santé.", "Not only is cycling fast, it's also good for your health."], ["Prenons l'exemple d'Amsterdam, où le vélo est roi.", "Take the example of Amsterdam, where the bike is king."], ["Par ailleurs, il ne faut pas oublier le coût des travaux.", "Besides, we mustn't forget the cost of the work."], ["Enfin, cette solution profiterait à tous les habitants.", "Finally, this solution would benefit all residents."], ["En somme, je suis favorable à ce projet.", "In short, I'm in favour of this project."], ["C'est pourquoi je pense qu'il faut agir rapidement.", "That's why I think we must act quickly."]],
  nat: [["Tout d'abord, ensuite, enfin.", "Tout d'abord, enfin, ensuite.", "Keep the logical order."], ["En outre, le projet est coûteux.", "En outre que le projet est coûteux.", "En outre is an adverb: no que."], ["Non seulement c'est cher, mais c'est aussi inutile.", "Non seulement c'est cher, et inutile aussi non seulement.", "Non seulement… mais aussi."], ["Les avantages l'emportent sur les inconvénients.", "Les avantages emportent les inconvénients.", "L'emporter sur."]],
  mcq: [["___, je présenterai les avantages du projet.", "Tout d'abord", ["En somme", "Pourtant", "Bref"], "Opening an argument."], ["Le métro est rapide ; ___, il est peu cher.", "de plus", ["cependant", "en revanche", "donc"], "Adding an argument in the same direction."], ["___, la ville de Lyon a créé 200 km de pistes cyclables.", "Par exemple", ["En outre que", "Bien que", "Car"], "Illustrating."], ["___, cette réforme me semble nécessaire.", "En définitive", ["D'une part", "Tout d'abord", "Par exemple"], "Concluding."]],
  gap: [["___ d'abord, définissons le problème.", "Tout", "", "First of all, let's define the problem.", ["Tous", "Toute", "Pour"]], ["Le vélo est écologique ; ___, il est bon pour la santé.", "en outre|de plus|par ailleurs", "", "Cycling is green; furthermore, it's healthy.", ["pourtant", "en revanche", "car"]], ["___ l'exemple des pays nordiques.", "Prenons", "", "Take the example of the Nordic countries.", ["Prenez-nous", "Prendre", "Pris"]], ["D'une part, c'est utile ; d'autre ___, c'est agréable.", "part", "", "On the one hand it's useful; on the other, it's pleasant.", ["côté", "fois", "sorte"]], ["Les bénéfices l'___ sur les coûts.", "emportent", "emporter", "The benefits outweigh the costs.", ["emporte", "apportent", "importent"]], ["En ___, je suis favorable à cette idée.", "somme|conclusion|définitive", "", "In short, I'm in favour of this idea.", ["fait", "outre", "effet"]]],
  fix: [["En outre que les loyers sont chers, les transports sont saturés.", "En outre que les loyers sont chers,", "Les loyers sont chers ; en outre,", "En outre is used alone, not followed by que.", ["En outre de les loyers sont chers,", "Outre que les loyers chers,"]], ["Non seulement il est intelligent, et aussi drôle.", "et aussi drôle", "mais il est aussi drôle", "Non seulement… mais aussi.", ["et drôle", "aussi il est drôle"]], ["Enfin, je vais commencer par présenter le contexte.", "Enfin", "Tout d'abord", "Enfin announces the last point; to open, use tout d'abord.", ["En somme", "Pour conclure"]]],
  xf: [["Join the two arguments with non seulement… mais aussi.", "Le train est rapide. Le train est confortable.", "Non seulement le train est rapide, mais il est aussi confortable."], ["Write a one-sentence conclusion beginning with En somme.", "(avantages > inconvénients)", "En somme, les avantages l'emportent sur les inconvénients."]],
  chat: [["Alors, tu es pour ou contre la semaine de quatre jours ?", "Plutôt pour : d'une part, on se repose mieux ; d'autre part, on est plus efficace.", ["Pour, d'une part on se repose, et enfin d'abord efficace.", "Pour, en outre que on se repose."], "A clear position with two ordered arguments."], ["Tu peux me donner un exemple ?", "Prenons le cas de l'Islande, qui a testé ce modèle avec succès.", ["Prenons le cas que l'Islande.", "Par exemple de que l'Islande."], "Prenons le cas de + noun."]]
});

L({ id: "b2-concession", lvl: "B2", tr: "argu", cat: "connecteurs", t: "Opposer et concéder", en: "Mais, pourtant, alors que, même si, malgré, certes… mais",
  rule: { h: "Opposition sets two facts side by side; concession admits a fact and goes against its expected consequence.",
    pts: ["<b>Opposition</b>: <i>alors que, tandis que</i> (+ indicative), <i>en revanche, par contre (spoken), au contraire</i>: <i>il aime la ville, alors qu'elle préfère la campagne</i>.", "<b>Concession</b>: <i>pourtant, cependant, toutefois, néanmoins</i> (adverbs); <i>même si</i> + indicative; <i>bien que, quoique</i> + subjunctive; <i>malgré</i> + noun.", "<b>Certes… mais</b>: the key structure of nuanced argument: <i>certes, le projet est coûteux, mais il est indispensable</i>.", "<b>Avoir beau</b> + infinitive: <i>j'ai beau essayer, je n'y arrive pas</i> (however hard I try).", "<b>Quand même / tout de même</b>: <i>il pleuvait, on est sortis quand même</i>."],
    ex: [["Certes, Paris est cher, mais la vie culturelle y est incomparable.", "Admittedly Paris is expensive, but cultural life there is unrivalled."], ["Même s'il est tard, je t'appelle.", "Even though it's late, I'm calling you."], ["Malgré la fatigue, elle a terminé son rapport.", "Despite her tiredness, she finished her report."], ["J'ai beau réviser, j'oublie le subjonctif !", "However much I revise, I forget the subjunctive!"]],
    warn: "<i>Malgré que</i> is criticised: write <i>bien que</i> + subjunctive, or <i>malgré</i> + noun. <i>Même si</i> is never followed by the future or the conditional.",
    vn: "<b>mặc dù… nhưng…</b>: tiếng Việt dùng cả hai từ. Tiếng Pháp chỉ dùng <b>một</b>: <i>Bien qu'il pleuve, je sors</i> (không thêm mais). Ngoại lệ: <b>certes… mais</b> (đúng là… nhưng…)." },
  cards: [["certes… mais", "admittedly… but", "Certes, c'est difficile, mais c'est possible.", "Admittedly it's difficult, but it's possible."], ["pourtant", "yet, and yet", "Il a révisé ; pourtant, il a échoué.", "He revised; yet he failed."], ["toutefois", "however", "Le projet est bon ; toutefois, il est cher.", "The project is good; however, it's expensive."], ["alors que", "whereas", "Il est sportif alors que son frère déteste le sport.", "He's sporty whereas his brother hates sport."], ["même si", "even if, even though", "Même s'il pleut, on y va.", "Even if it rains, we're going."], ["malgré", "despite", "Malgré le bruit, j'ai bien dormi.", "Despite the noise, I slept well."], ["avoir beau", "however much", "Il a beau crier, personne ne l'écoute.", "However much he shouts, nobody listens."], ["quand même", "all the same, anyway", "C'était cher, mais je l'ai acheté quand même.", "It was expensive, but I bought it anyway."]],
  sent: [["Certes, le télétravail est confortable, mais il isole certains salariés.", "Admittedly remote work is comfortable, but it isolates some employees."], ["Elle parle trois langues, alors que son frère n'en parle qu'une.", "She speaks three languages, whereas her brother speaks only one."], ["Même si je suis fatiguée, je viendrai au dîner.", "Even though I'm tired, I'll come to the dinner."], ["Malgré la grève, la plupart des employés sont venus.", "Despite the strike, most employees came."], ["J'ai beau chercher, je ne trouve pas mes clés.", "However hard I look, I can't find my keys."], ["Le salaire est modeste ; en revanche, l'ambiance est excellente.", "The salary is modest; on the other hand, the atmosphere is excellent."], ["Il faisait froid ; nous avons quand même mangé en terrasse.", "It was cold; we ate outside all the same."], ["Ce restaurant est réputé ; pourtant, j'ai été déçue.", "This restaurant is famous; yet I was disappointed."], ["Bien qu'elle vive en France depuis peu, elle s'est bien intégrée.", "Although she hasn't lived in France long, she has settled in well."], ["Toutefois, il faut reconnaître que la situation s'améliore.", "However, it must be acknowledged that the situation is improving."]],
  nat: [["Bien qu'il pleuve, je sors.", "Bien qu'il pleuve, mais je sors.", "One concession word is enough (except certes… mais)."], ["Malgré la pluie, on est sortis.", "Malgré qu'il pleut, on est sortis.", "Malgré + noun."], ["Même s'il pleut demain, nous partirons.", "Même s'il pleuvra demain, nous partirons.", "Même si + present, never the future."], ["J'ai beau essayer, je n'y arrive pas.", "J'ai beau d'essayer, je n'y arrive pas.", "Avoir beau + infinitive, no de."]],
  mcq: [["___ le prix, nous avons acheté cette maison.", "Malgré", ["Bien que", "Même si", "Alors que"], "Malgré + noun."], ["Il est très riche ; ___, il vit simplement.", "pourtant", ["donc", "car", "ainsi"], "An unexpected consequence: pourtant."], ["___ s'il fait froid, je nage dans la mer.", "Même", ["Bien", "Malgré", "Alors"], "Même si + indicative."], ["Elle a ___ expliquer, il ne comprend pas.", "beau", ["bien", "malgré", "quand même"], "Avoir beau + infinitive."]],
  gap: [["___, c'est un beau projet, mais il coûte trop cher.", "Certes", "", "Admittedly it's a fine project, but it costs too much.", ["Pourtant", "Donc", "Malgré"]], ["Il adore la mer, ___ elle préfère la montagne.", "alors qu'|tandis qu'", "", "He loves the sea, whereas she prefers the mountains.", ["parce qu'", "donc", "pour qu'"]], ["___ la fatigue, elle a continué à travailler.", "Malgré", "", "Despite her tiredness, she kept working.", ["Bien que", "Même si", "Pourtant"]], ["Tu as ___ dire, je ne te crois pas.", "beau", "", "Say what you like, I don't believe you.", ["bien", "même", "malgré"]], ["Je n'avais pas faim, mais j'ai mangé ___.", "quand même|tout de même", "", "I wasn't hungry, but I ate anyway.", ["pourtant que", "malgré", "certes"]], ["Le film est long ; ___, il est passionnant.", "toutefois|cependant|pourtant|néanmoins", "", "The film is long; however, it's gripping.", ["donc", "car", "ainsi"]]],
  fix: [["Malgré qu'il soit malade, il travaille.", "Malgré qu'il", "Bien qu'il", "Malgré que is criticised: bien que + subjunctive.", ["Même qu'il", "Pourtant qu'il"]], ["Bien qu'il est riche, il n'est pas heureux.", "est", "soit", "Bien que + subjunctive.", ["sera", "était"]], ["Même si tu viendras, je ne serai pas là.", "viendras", "viens", "Même si + present.", ["viendrais", "venais"]]],
  xf: [["Rewrite with malgré.", "Bien qu'il pleuve, la fête continue.", "Malgré la pluie, la fête continue."], ["Rewrite with avoir beau.", "Même si j'essaie, je n'y arrive pas.", "J'ai beau essayer, je n'y arrive pas."]],
  chat: [["Tu ne trouves pas que les écrans sont dangereux pour les enfants ?", "Certes, il y a des risques, mais bien utilisés, ils peuvent aussi aider à apprendre.", ["Certes il y a des risques, donc ils aident.", "Malgré qu'il y a des risques…"], "Certes… mais: concede, then nuance."], ["Il pleut. On annule la balade ?", "Non, allons-y quand même, avec des parapluies.", ["Non, allons-y pourtant que.", "Non, malgré allons-y."], "Quand même = anyway."]]
});

L({ id: "b2-lettre", lvl: "B2", tr: "argu", cat: "registre", t: "La lettre formelle argumentée", en: "Writing to an institution, a manager or a newspaper",
  rule: { h: "A formal letter states its purpose at once, argues politely and firmly, and ends with a request and a fixed formula.",
    pts: ["Layout: your details, the recipient, place and date (<i>Paris, le 7 novembre 2026</i>), the subject line (<i>Objet : …</i>), <i>Madame, Monsieur,</i>.", "Purpose: <i>Je me permets de vous écrire afin de… · Je souhaiterais attirer votre attention sur…</i>", "Polite firmness: <i>Je tiens à souligner que… · Il me paraît essentiel que… · Je ne peux que regretter…</i>", "Request: <i>Je vous serais reconnaissante de bien vouloir… · Je vous saurais gré de…</i>", "Closing: <i>Je vous prie d'agréer, Madame, Monsieur, l'expression de mes salutations distinguées.</i>"],
    ex: [["Objet : demande de remboursement", "Subject: refund request"], ["Je me permets de vous écrire au sujet de la fermeture de la bibliothèque.", "I am writing to you about the closure of the library."], ["Je vous serais reconnaissante de bien vouloir examiner ma demande.", "I would be grateful if you would consider my request."], ["Je reste à votre disposition pour en discuter.", "I remain available to discuss it."]],
    warn: "<i>Reconnaissante</i> agrees with the writer: a woman writes <i>je vous serais reconnaissante</i>. And the subject line has no article: <i>Objet : réclamation</i>.",
    vn: "Thư trang trọng tiếng Pháp rất <b>công thức</b>: «Je vous serais reconnaissante de bien vouloir…» ≈ «Kính mong quý cơ quan vui lòng…». Ở DELF B2 phải dùng đúng các công thức này để được điểm phần «registre»." },
  cards: [["Objet :", "Subject: (letter)", "Objet : candidature au poste de cheffe de projet", "Subject: application for project manager"], ["je me permets de", "I take the liberty of", "Je me permets de vous relancer.", "I'm following up with you."], ["attirer l'attention sur", "to draw attention to", "Je souhaite attirer votre attention sur ce problème.", "I wish to draw your attention to this problem."], ["je tiens à", "I want to, I insist on", "Je tiens à vous remercier.", "I want to thank you."], ["je vous serais reconnaissante de", "I would be grateful if you", "Je vous serais reconnaissante de me répondre.", "I'd be grateful if you'd reply."], ["je vous saurais gré de", "I would be obliged if you", "Je vous saurais gré de bien vouloir m'envoyer le devis.", "I'd be obliged if you'd send me the quote."], ["une réclamation", "a complaint", "J'ai déposé une réclamation.", "I've filed a complaint."], ["dans l'attente de", "awaiting", "Dans l'attente de votre réponse…", "Awaiting your reply…"]],
  sent: [["Je me permets de vous écrire afin de contester cette décision.", "I am writing to contest this decision."], ["Je souhaiterais attirer votre attention sur l'état de l'immeuble.", "I would like to draw your attention to the state of the building."], ["Je tiens à souligner que ce problème dure depuis trois mois.", "I would stress that this problem has lasted three months."], ["Il me paraît essentiel que les habitants soient consultés.", "It seems essential to me that residents be consulted."], ["Je vous serais reconnaissante de bien vouloir me rembourser.", "I would be grateful if you would refund me."], ["Vous trouverez ci-joint une copie de ma facture.", "Please find attached a copy of my invoice."], ["Je ne peux que regretter l'absence de réponse de vos services.", "I can only regret the lack of response from your departments."], ["Dans l'attente de votre réponse, je reste à votre disposition.", "Awaiting your reply, I remain at your disposal."], ["Je vous prie d'agréer, Madame, l'expression de mes salutations distinguées.", "Yours faithfully."], ["Paris, le 7 novembre 2026", "Paris, 7 November 2026"]],
  nat: [["Je vous serais reconnaissante de me répondre rapidement.", "Je vous serai reconnaissant de me répondre vite, merci !", "Conditional + agreement for a woman; avoid the casual merci !"], ["Vous trouverez ci-joint mon CV.", "Vous trouverez ci-joint de mon CV.", "Ci-joint + noun."], ["Objet : demande de rendez-vous", "Objet : Une demande de rendez-vous.", "The subject line has no article."], ["Madame, Monsieur,", "Chers Madame et Monsieur,", "The standard opening when you don't know the person."]],
  mcq: [["___ de bien vouloir m'envoyer le formulaire.", "Je vous saurais gré", ["Envoie-moi", "Je veux", "Tu pourrais"], "Fixed formal formula."], ["Opening a complaint:", "Je me permets de vous écrire au sujet de…", ["Salut, j'ai un problème…", "Coucou, je râle…", "Hé, votre service…"], "Formal opening."], ["Attaching a document:", "Vous trouverez ci-joint…", ["Voici attaché…", "Je joins dedans…", "Regarde le fichier…"], "Ci-joint."], ["Closing: Je vous prie d'agréer, Monsieur, l'expression de mes ___.", "salutations distinguées", ["bisous", "amitiés sincères à bientôt", "meilleurs vœux de Noël"], "Fixed formula."]],
  gap: [["Je vous ___ reconnaissante de bien vouloir me répondre.", "serais", "être", "I'd be grateful if you'd reply.", ["serai", "suis", "étais"]], ["Je ___ à vous remercier pour votre accueil.", "tiens", "tenir", "I want to thank you for your welcome.", ["tient", "tiendrai", "tenais"]], ["Vous trouverez ___ une copie du contrat.", "ci-joint", "", "Please find attached a copy of the contract.", ["ci-jointe", "ici-joint", "joint-ci"]], ["Je souhaiterais ___ votre attention sur ce point.", "attirer", "", "I'd like to draw your attention to this point.", ["tirer", "attirez", "attiré"]], ["Dans l'___ de votre réponse, je vous prie d'agréer…", "attente", "", "Awaiting your reply, yours faithfully…", ["attendant", "espoir", "espérance"]], ["Je vous saurais ___ de m'informer de votre décision.", "gré", "", "I'd be obliged if you'd inform me of your decision.", ["grée", "grès", "gras"]]],
  fix: [["Je vous serai reconnaissante de me rappeler.", "serai", "serais", "A polite request: conditional (serais).", ["suis", "sois"]], ["Monsieur le Directeur, je t'écris au sujet de mon contrat.", "je t'écris", "je vous écris", "Formal letter: vous.", ["je lui écris", "je écris"]], ["Vous trouverez ci-joint de mes documents.", "ci-joint de mes documents", "ci-joint mes documents", "Ci-joint + noun directly.", ["ci-joint des mes documents", "joint ci mes documents"]]],
  xf: [["Make it formal.", "Envoyez-moi le devis.", "Je vous saurais gré de bien vouloir m'envoyer le devis.|Je vous serais reconnaissante de bien vouloir m'envoyer le devis.|Pourriez-vous m'envoyer le devis ?"], ["Make it formal.", "Je veux me plaindre du bruit.", "Je me permets de vous écrire au sujet du bruit.|Je souhaiterais attirer votre attention sur le bruit."]],
  chat: [["(Your bank) Que pouvons-nous faire pour vous ?", "Je vous serais reconnaissante de bien vouloir vérifier un prélèvement que je ne reconnais pas.", ["Vérifie mon compte.", "Je veux que tu vérifies."], "Formal register with an institution."], ["(Your manager) Vous vouliez me voir ?", "Oui, je tenais à vous parler de l'organisation du prochain séminaire.", ["Ouais, faut qu'on cause du séminaire.", "Oui, je tiens que vous parler."], "Polite and professional: je tenais à."]]
});

L({ id: "b2-cause", lvl: "B2", tr: "logique", cat: "connecteurs", t: "Cause et conséquence (B2)", en: "Puisque, étant donné que, faute de, si bien que, tellement… que",
  rule: { h: "At B2, choose the cause or consequence word that fits the nuance and the register.",
    pts: ["<b>Puisque</b>: a cause both speakers know: <i>puisque tu es là, aide-moi</i>.", "<b>Étant donné que, vu que, du fait que</b> (+ indicative); <b>en raison de, du fait de, vu</b> (+ noun, formal).", "<b>Faute de</b> + noun or infinitive: a lack: <i>faute de temps, faute d'avoir réservé</i>.", "<b>Sous prétexte que</b>: a cause you doubt.", "Consequence: <b>par conséquent, si bien que, de sorte que</b> (+ indicative); intensity: <b>si / tellement + adjective + que</b>, <b>tant de / tellement de + noun + que</b>: <i>il était si fatigué qu'il s'est endormi</i>."],
    ex: [["Puisque tu insistes, je viendrai.", "Since you insist, I'll come."], ["En raison des travaux, la ligne 4 est fermée.", "Owing to works, line 4 is closed."], ["Faute de place, nous avons dû refuser des invités.", "For lack of space, we had to turn down guests."], ["Il y avait tellement de monde que nous sommes partis.", "There were so many people that we left."]],
    warn: "<i>Si bien que</i> (consequence, + indicative) is different from <i>bien que</i> (concession, + subjunctive).",
    vn: "<b>vì (ai cũng biết)</b> → puisque; <b>do, vì lý do</b> (trang trọng) → en raison de; <b>vì thiếu</b> → faute de; <b>đến nỗi</b> → si… que / tellement… que." },
  cards: [["puisque", "since (known cause)", "Puisque c'est gratuit, profitons-en.", "Since it's free, let's make the most of it."], ["étant donné que", "given that", "Étant donné que tu pars tôt, couche-toi.", "Given that you're leaving early, go to bed."], ["en raison de", "owing to", "Fermé en raison d'une grève.", "Closed owing to a strike."], ["faute de", "for lack of", "Faute d'argent, ils ont renoncé.", "For lack of money, they gave up."], ["sous prétexte que", "on the pretext that", "Il n'est pas venu sous prétexte qu'il était malade.", "He didn't come, claiming he was ill."], ["par conséquent", "consequently", "Il a neigé ; par conséquent, l'école est fermée.", "It snowed; consequently, the school is closed."], ["si bien que", "so that, with the result that", "Il a plu, si bien que la route a été coupée.", "It rained, so the road was cut off."], ["tellement… que", "so… that", "C'était tellement drôle que j'ai pleuré.", "It was so funny that I cried."]],
  sent: [["Puisque tu connais le quartier, choisis le restaurant.", "Since you know the area, choose the restaurant."], ["Étant donné que le budget est serré, nous ferons une petite fête.", "Given the tight budget, we'll have a small party."], ["Le vol est retardé en raison du brouillard.", "The flight is delayed owing to fog."], ["Faute de temps, je n'ai pas pu relire mon texte.", "For lack of time, I couldn't reread my text."], ["Il a refusé sous prétexte qu'il était trop occupé.", "He refused on the pretext that he was too busy."], ["Les loyers ont augmenté ; par conséquent, beaucoup de familles partent.", "Rents have risen; consequently, many families are leaving."], ["Elle a beaucoup pratiqué, si bien qu'elle parle couramment.", "She practised a lot, so she speaks fluently."], ["Il faisait si chaud que nous sommes restés à l'intérieur.", "It was so hot that we stayed inside."], ["Il y a tant de choix que je ne sais pas quoi prendre.", "There's so much choice I don't know what to take."], ["Vu l'heure, nous devrions rentrer.", "Given the time, we should go home."]],
  nat: [["Faute de temps, je n'ai pas fini.", "Faute que je n'ai pas le temps, je n'ai pas fini.", "Faute de + noun."], ["Il était si fatigué qu'il s'est endormi.", "Il était si fatigué que pour s'endormir.", "Si + adjective + que + clause."], ["Puisque tu es là, aide-moi.", "Parce que tu es là, aide-moi.", "A known, obvious cause at the start: puisque."], ["Il a plu, si bien que le match a été annulé.", "Il a plu, bien que le match a été annulé.", "Consequence: si bien que."]],
  mcq: [["___ de moyens, le projet a été abandonné.", "Faute", ["Grâce", "Puisque", "Si bien"], "A lack: faute de."], ["Il parlait ___ vite que personne ne comprenait.", "si", ["tant de", "tellement de", "aussi"], "Si + adverb + que."], ["La gare est fermée ___ travaux.", "en raison de", ["puisque", "si bien que", "faute que"], "Formal cause + noun."], ["Il y avait ___ bruit que je n'ai pas dormi.", "tellement de", ["si", "tellement", "aussi de"], "With a noun: tellement de / tant de."]],
  gap: [["___ tu es libre, viens avec nous !", "Puisque", "", "Since you're free, come with us!", ["Faute de", "En raison de", "Si bien que"]], ["___ d'avoir réservé, nous n'avons pas eu de table.", "Faute", "", "Because we hadn't booked, we didn't get a table.", ["Malgré", "Grâce", "Sauf"]], ["Le train est en retard ; par ___, la réunion commencera plus tard.", "conséquent", "", "The train is late; consequently, the meeting will start later.", ["conséquence", "suite", "contre"]], ["Il a tant ___ travail qu'il ne prend jamais de vacances.", "de", "", "He has so much work he never takes holidays.", ["que", "du", "à"]], ["Elle est ___ timide qu'elle n'ose pas parler.", "si|tellement", "", "She's so shy she doesn't dare speak.", ["tant", "tant de", "aussi de"]], ["Le magasin est fermé ___ raison de l'inventaire.", "en", "", "The shop is closed for stocktaking.", ["à", "par", "de"]]],
  fix: [["Il était tellement de fatigué qu'il est parti.", "tellement de fatigué", "tellement fatigué", "Tellement + adjective (no de).", ["tant fatigué", "si de fatigué"]], ["Faute que nous n'avions pas d'argent, nous sommes restés.", "Faute que nous n'avions pas d'argent", "Faute d'argent", "Faute de + noun.", ["Faute que pas d'argent", "Faute de que nous n'avions pas d'argent"]], ["Il a beaucoup neigé, bien que les routes soient bloquées.", "bien que les routes soient bloquées", "si bien que les routes sont bloquées", "Consequence: si bien que + indicative.", ["bien que les routes sont bloquées", "si bien que les routes soient bloquées"]]],
  xf: [["Use si… que.", "Il est très tard. Je vais me coucher.", "Il est si tard que je vais me coucher.|Il est tellement tard que je vais me coucher."], ["Use faute de.", "Nous n'avons pas de temps, donc nous annulons.", "Faute de temps, nous annulons."]],
  chat: [["Pourquoi le séminaire est reporté ?", "En raison d'un problème de salle, il aura lieu la semaine prochaine.", ["Faute que la salle, il aura lieu.", "Puisque d'un problème de salle."], "Formal cause + noun: en raison de."], ["Tu as bien dormi à l'hôtel ?", "Pas du tout, il y avait tellement de bruit que je me suis réveillée trois fois.", ["Il y avait si bruit que…", "Il y avait tellement bruit que…"], "Tellement de + noun + que."]]
});

L({ id: "b2-but", lvl: "B2", tr: "logique", cat: "connecteurs", t: "Exprimer le but", en: "Pour, afin de, pour que, de peur que, en vue de",
  rule: { h: "Same subject → preposition + infinitive; different subjects → conjunction + subjunctive.",
    pts: ["<b>Pour / afin de</b> + infinitive: <i>je travaille pour payer mes études</i>.", "<b>Pour que / afin que</b> + subjunctive: <i>je t'explique pour que tu comprennes</i>.", "To avoid something: <b>pour ne pas, de peur de, de crainte de</b> + infinitive; <b>de peur que, de crainte que</b> + subjunctive (often with ne explétif): <i>parle doucement de peur qu'il ne se réveille</i>.", "<b>En vue de, dans le but de</b> (formal) + noun or infinitive: <i>en vue de l'examen</i>.", "<b>De sorte que, de façon à ce que</b> + subjunctive when it expresses purpose."],
    ex: [["Je me lève tôt pour éviter les bouchons.", "I get up early to avoid the traffic."], ["Je laisse la clé au voisin pour qu'il puisse nourrir le chat.", "I leave the key with the neighbour so he can feed the cat."], ["Elle a noté l'adresse de peur de l'oublier.", "She wrote down the address for fear of forgetting it."], ["Nous économisons en vue du mariage.", "We're saving for the wedding."]],
    warn: "<i>Pour</i> + infinitive needs the same subject: <i>je prends un taxi pour arriver à l'heure</i>; but <i>je prends un taxi pour que tu ne m'attendes pas</i>.",
    vn: "<b>để</b> → pour / afin de (+ động từ) khi cùng chủ ngữ; <b>để cho (ai đó)</b> → pour que + subjonctif; <b>sợ rằng / kẻo</b> → de peur que." },
  cards: [["pour", "in order to", "Je lis pour me détendre.", "I read to relax."], ["afin de", "in order to (formal)", "Afin de vous inscrire, remplissez ce formulaire.", "To register, fill in this form."], ["pour que", "so that", "Parle plus fort pour qu'on t'entende.", "Speak louder so we can hear you."], ["de peur de", "for fear of", "Il ne dit rien de peur de se tromper.", "He says nothing for fear of being wrong."], ["de peur que", "for fear that", "Je ferme la fenêtre de peur qu'il ne pleuve.", "I'm closing the window in case it rains."], ["en vue de", "with a view to", "Elle suit un cours en vue du DELF.", "She's taking a course for the DELF."], ["dans le but de", "with the aim of", "Dans le but de réduire les coûts…", "With the aim of reducing costs…"], ["pour ne pas", "so as not to", "Je note tout pour ne pas oublier.", "I write everything down so as not to forget."]],
  sent: [["J'apprends le français pour mieux comprendre la famille d'Alex.", "I'm learning French to understand Alex's family better."], ["Je t'envoie le programme afin que tu puisses te préparer.", "I'm sending you the programme so you can prepare."], ["Nous partons tôt pour ne pas rater le train.", "We're leaving early so as not to miss the train."], ["Elle a pris une assurance de peur d'avoir un accident.", "She took out insurance for fear of an accident."], ["Les invitations sont envoyées tôt pour que chacun puisse s'organiser.", "Invitations are sent early so everyone can plan."], ["Il parle lentement afin d'être compris de tous.", "He speaks slowly in order to be understood by all."], ["Nous avons créé ce module dans le but de former les nouveaux arrivants.", "We created this module to train newcomers."], ["Je baisse le son de peur que les voisins ne se plaignent.", "I'm turning the volume down for fear the neighbours complain."], ["Elle révise chaque soir en vue de l'examen de juin.", "She revises every evening for the June exam."], ["Range ta chambre pour que ta mère soit contente.", "Tidy your room so your mother is happy."]],
  nat: [["Je travaille pour gagner ma vie.", "Je travaille pour que je gagne ma vie.", "Same subject → pour + infinitive."], ["Je l'aide pour qu'il réussisse.", "Je l'aide pour qu'il réussit.", "Pour que + subjunctive."], ["Je pars tôt pour ne pas être en retard.", "Je pars tôt pour pas ne être en retard.", "Ne pas stay together before the infinitive."], ["Elle se tait de peur de dire une bêtise.", "Elle se tait de peur que dire une bêtise.", "Same subject → de peur de + infinitive."]],
  mcq: [["Je t'écris ___ te remercier.", "pour", ["pour que", "afin que", "de sorte que"], "Same subject → pour + infinitive."], ["Je laisse la lumière allumée ___ tu trouves le chemin.", "pour que", ["pour", "afin de", "de peur de"], "Different subjects → pour que."], ["Il emporte un pull de peur qu'il ___ froid.", "fasse", ["fait", "fera", "faisait"], "De peur que + subjunctive."], ["Nous faisons des économies ___ notre voyage.", "en vue de", ["pour que", "afin que", "de peur que"], "En vue de + noun."]],
  gap: [["Je prends des notes ___ ne rien oublier.", "pour|afin de", "", "I take notes so as not to forget anything.", ["pour que", "de sorte", "afin que"]], ["Je répète ___ que tout le monde comprenne.", "pour|afin", "", "I'm repeating so that everyone understands.", ["de peur", "faute", "malgré"]], ["Ferme la porte de peur que le chat ne ___.", "sorte", "sortir", "Close the door in case the cat gets out.", ["sort", "sortira", "sortait"]], ["Elle s'entraîne ___ vue du marathon.", "en", "", "She's training for the marathon.", ["à", "dans", "pour"]], ["Je mets un réveil ___ ne pas me lever en retard.", "pour", "", "I set an alarm so as not to get up late.", ["pour que", "afin que", "de peur que"]], ["Je vous donne mon numéro afin que vous ___ me joindre.", "puissiez", "pouvoir", "I'm giving you my number so you can reach me.", ["pouvez", "pourrez", "pouviez"]]],
  fix: [["Je travaille pour que je paie mon loyer.", "pour que je paie", "pour payer", "Same subject → pour + infinitive.", ["pour que je paye", "afin que je paie"]], ["Je t'explique afin que tu comprends.", "comprends", "comprennes", "Afin que + subjunctive.", ["comprendras", "comprenais"]], ["Je pars tôt pour pas être en retard.", "pour pas", "pour ne pas", "In writing: pour ne pas.", ["pas pour", "pour non"]]],
  xf: [["Join with pour que.", "Je baisse la musique. Le bébé dort.", "Je baisse la musique pour que le bébé dorme."], ["Join with de peur de.", "Il ne parle pas. Il a peur de se tromper.", "Il ne parle pas de peur de se tromper."]],
  chat: [["Pourquoi tu enregistres ta voix ?", "Pour améliorer ma prononciation avant l'oral du DELF.", ["Pour que j'améliore ma prononciation.", "Pour améliore ma prononciation."], "Same subject → pour + infinitive."], ["Tu pars déjà ?", "Oui, je pars tôt pour ne pas rater le dernier métro.", ["Oui, je pars tôt pour que je ne rate pas.", "Oui, je pars tôt de peur que rater."], "Pour ne pas + infinitive."]]
});

L({ id: "b2-doute", lvl: "B2", tr: "nuance", cat: "subjonctif", t: "Certitude, doute, probabilité", en: "Il est sûr que, il semble que, il se peut que",
  rule: { h: "Certainty and probability take the indicative; doubt and possibility take the subjunctive.",
    pts: ["<b>Indicative</b>: <i>il est sûr / certain / évident / probable que, je suis sûre que, sans doute, il me semble que</i>.", "<b>Subjunctive</b>: <i>il est possible que, il se peut que, il semble que, je doute que, il est peu probable que, il n'est pas sûr que</i>.", "<b>Il semble que</b> + subjunctive, but <b>il me semble que</b> + indicative.", "<b>Sans doute</b> = probably; <b>sans aucun doute</b> = certainly. At the start, <i>sans doute</i> causes inversion in formal writing: <i>sans doute a-t-il raison</i>.", "Adverbs: <i>peut-être, probablement, certainement, apparemment, visiblement</i>."],
    ex: [["Il est probable qu'il pleuvra demain.", "It will probably rain tomorrow."], ["Il se peut que je sois en retard.", "I may be late."], ["Je doute qu'il accepte.", "I doubt he'll accept."], ["Il me semble que tu as maigri.", "It seems to me you've lost weight."]],
    warn: "<i>Il est probable que</i> + indicative, but <i>il est possible que</i> + subjunctive. Learn them as a pair.",
    vn: "<b>chắc chắn / có lẽ</b> → indicatif; <b>có thể / không chắc / nghi ngờ</b> → subjonctif. Chú ý: <i>sans doute</i> nghĩa là «có lẽ» chứ không phải «không nghi ngờ gì»." },
  cards: [["il est probable que", "it's likely that (+ ind.)", "Il est probable qu'elle viendra.", "She'll probably come."], ["il est possible que", "it's possible that (+ subj.)", "Il est possible qu'elle vienne.", "She may come."], ["il se peut que", "it may be that (+ subj.)", "Il se peut que le train ait du retard.", "The train may be late."], ["il semble que", "it seems that (+ subj.)", "Il semble que la situation soit grave.", "It seems the situation is serious."], ["douter que", "to doubt that (+ subj.)", "Je doute que ce soit vrai.", "I doubt that's true."], ["sans doute", "probably", "Il est sans doute malade.", "He's probably ill."], ["sans aucun doute", "without any doubt", "C'est sans aucun doute le meilleur.", "It's undoubtedly the best."], ["apparemment", "apparently", "Apparemment, le magasin a fermé.", "Apparently the shop has closed."]],
  sent: [["Il est certain que le projet prendra du retard.", "It's certain the project will be delayed."], ["Il est possible que nous changions de date.", "We may change the date."], ["Il se peut qu'il neige ce week-end.", "It may snow this weekend."], ["Je doute que le colis arrive avant vendredi.", "I doubt the parcel will arrive before Friday."], ["Il semble que les prix aient encore augmenté.", "It seems prices have gone up again."], ["Il me semble que nous nous sommes déjà rencontrés.", "I think we've met before."], ["Elle a sans doute oublié le rendez-vous.", "She's probably forgotten the appointment."], ["Il est peu probable qu'ils viennent en voiture.", "They're unlikely to come by car."], ["Apparemment, la réunion est reportée.", "Apparently the meeting has been postponed."], ["Je suis convaincue que tu réussiras.", "I'm convinced you'll succeed."]],
  nat: [["Il est possible qu'il vienne.", "Il est possible qu'il viendra.", "Possibility → subjunctive."], ["Il est probable qu'il viendra.", "Il est probable qu'il vienne.", "Probability → indicative (in careful French)."], ["Il me semble que c'est fermé.", "Il me semble que ce soit fermé.", "Il me semble que → indicative."], ["Je doute qu'il ait raison.", "Je doute qu'il a raison.", "Douter que → subjunctive."]],
  mcq: [["Il se peut que nous ___ en avance.", "soyons", ["sommes", "serons", "étions"], "Il se peut que + subjunctive."], ["Je suis sûre qu'elle ___ raison.", "a", ["ait", "aie", "avoir"], "Certainty → indicative."], ["Il semble que le magasin ___ fermé.", "soit", ["est", "sera", "était été"], "Il semble que + subjunctive."], ["Il est ___ en retard : il n'est jamais à l'heure.", "sans doute", ["sans aucun doute que", "douteux", "doute"], "Sans doute = probably."]],
  gap: [["Il est possible que je ___ un peu en retard.", "sois", "être", "I may be a bit late.", ["suis", "serai", "étais"]], ["Je suis certaine que tu ___ le DELF.", "réussiras|vas réussir", "réussir", "I'm certain you'll pass the DELF.", ["réussisses", "réussisse", "réussirais"]], ["Je doute que ce restaurant ___ ouvert le lundi.", "soit", "être", "I doubt this restaurant is open on Mondays.", ["est", "sera", "serait"]], ["Il me semble que la porte ___ fermée.", "est", "être", "I think the door is closed.", ["soit", "sois", "être"]], ["Il est peu probable qu'il ___ le temps.", "ait", "avoir", "He's unlikely to have time.", ["a", "aura", "avait"]], ["Il est évident que nous ___ trouver une solution.", "devons|devrons", "devoir", "Obviously we must find a solution.", ["devions", "doivent", "dussions"]]],
  fix: [["Il est possible qu'il pleuvra.", "pleuvra", "pleuve", "Possibility → subjunctive.", ["pleut", "pleuvait"]], ["Je doute qu'elle viendra.", "viendra", "vienne", "Doubt → subjunctive.", ["vient", "venait"]], ["Il me semble que tu sois fatiguée.", "sois", "es", "Il me semble que → indicative.", ["seras", "soit"]]],
  xf: [["Rewrite with il se peut que.", "Peut-être que le train aura du retard.", "Il se peut que le train ait du retard."], ["Rewrite with je doute que.", "Je ne pense pas qu'il dise la vérité. (stronger)", "Je doute qu'il dise la vérité."]],
  chat: [["Tu crois que Claire viendra au dîner ?", "Il se peut qu'elle vienne, mais elle a beaucoup de travail.", ["Il se peut qu'elle viendra.", "Il se peut qu'elle vient."], "Possibility → subjunctive."], ["Le magasin est ouvert dimanche ?", "Il me semble qu'il est ouvert le matin.", ["Il me semble qu'il soit ouvert.", "Il semble qu'il est ouvert."], "Il me semble que → indicative."]]
});

L({ id: "b2-lexique", lvl: "B2", tr: "nuance", cat: "lexique", t: "Faux amis et anglicismes", en: "Words that look like English but are not",
  rule: { h: "Many French words look English but mean something else; at B2, the examiner notices.",
    pts: ["<i>actuellement</i> = currently (not actually → <i>en fait</i>); <i>éventuellement</i> = possibly (not eventually → <i>finalement</i>).", "<i>une librairie</i> = a bookshop (library = <i>une bibliothèque</i>); <i>sensible</i> = sensitive (sensible = <i>raisonnable</i>).", "<i>assister à</i> = to attend (to assist = <i>aider</i>); <i>une formation</i> = a training course.", "Anglicisms to avoid in writing: <i>faire du sens → avoir du sens</i>; <i>adresser un problème → traiter / aborder un problème</i>; <i>supporter un projet → soutenir</i>; <i>réaliser que → se rendre compte que</i> (accepted, but better).", "In your field: <i>e-learning → formation en ligne</i>, <i>feedback → retour</i>, <i>deadline → échéance, date limite</i>."],
    ex: [["Actuellement, je travaille sur un projet de formation en ligne.", "I'm currently working on an online training project."], ["En fait, je ne suis pas d'accord.", "Actually, I don't agree."], ["Ça n'a pas de sens.", "It doesn't make sense."], ["Nous devons aborder ce problème.", "We must address this problem."]],
    warn: "<i>Faire du sens</i> is a common anglicism; in exam writing use <i>avoir du sens</i> or <i>être logique</i>.",
    vn: "Người Việt học tiếng Anh trước thường mắc lỗi «bạn giả» (faux amis). Mẹo: khi một từ Pháp giống hệt tiếng Anh, hãy <b>kiểm tra nghĩa</b> trước khi dùng trong bài thi." },
  cards: [["actuellement", "currently", "Actuellement, elle vit à Lyon.", "Currently she lives in Lyon."], ["en fait", "actually, in fact", "En fait, je préfère le thé.", "Actually, I prefer tea."], ["éventuellement", "possibly", "On pourrait éventuellement reporter.", "We could possibly postpone."], ["finalement", "eventually, in the end", "Finalement, il a accepté.", "Eventually he accepted."], ["une bibliothèque", "a library", "Je travaille à la bibliothèque.", "I work at the library."], ["avoir du sens", "to make sense", "Cette décision a du sens.", "This decision makes sense."], ["aborder", "to address, to tackle", "Abordons la question du budget.", "Let's address the budget question."], ["soutenir", "to support", "Je soutiens ce projet.", "I support this project."]],
  sent: [["Actuellement, l'entreprise recrute des formateurs.", "The company is currently hiring trainers."], ["En fait, la réunion a été annulée.", "Actually, the meeting was cancelled."], ["Je pourrais éventuellement t'aider samedi.", "I could possibly help you on Saturday."], ["Finalement, nous avons choisi une salle à Saïgon.", "In the end we chose a venue in Saigon."], ["J'ai acheté ce dictionnaire dans une librairie près de la Sorbonne.", "I bought this dictionary in a bookshop near the Sorbonne."], ["Ta proposition a tout à fait du sens.", "Your proposal makes complete sense."], ["Le rapport aborde la question de l'égalité.", "The report addresses the question of equality."], ["J'ai assisté à une formation sur l'accessibilité numérique.", "I attended a training course on digital accessibility."], ["Merci pour ton retour sur le module.", "Thanks for your feedback on the module."], ["La date limite est fixée au 15 mars.", "The deadline is set for 15 March."]],
  nat: [["Ça n'a pas de sens.", "Ça ne fait pas de sens.", "Avoir du sens (faire sens is an anglicism)."], ["Je me suis rendu compte de mon erreur.", "J'ai réalisé mon erreur et ça fait du sens.", "Se rendre compte de; avoir du sens."], ["Nous devons aborder ce problème.", "Nous devons adresser ce problème.", "Adresser un problème is an anglicism."], ["J'ai assisté à la conférence.", "J'ai assisté la conférence.", "Assister à = to attend."]],
  mcq: [["___, je suis en congé. (= right now)", "Actuellement", ["Éventuellement", "Finalement", "En fait"], "Currently = actuellement."], ["I'll eventually understand: Je ___ par comprendre.", "finirai", ["éventuellement", "actuellement", "réaliserai"], "Finir par = to end up."], ["She attends a lecture: Elle ___ un cours magistral.", "assiste à", ["assiste", "aide", "attend"], "Assister à."], ["This makes sense: Cela ___.", "a du sens", ["fait du sens", "fait sens à", "est sens"], "Avoir du sens."]],
  gap: [["Je vais à la ___ pour emprunter des livres.", "bibliothèque", "", "I'm going to the library to borrow books.", ["librairie", "libraire", "livrerie"]], ["___, je ne suis pas d'accord avec toi. (actually)", "En fait", "", "Actually, I don't agree with you.", ["Actuellement", "Éventuellement", "Finalement"]], ["Cette idée a beaucoup de ___.", "sens", "", "This idea makes a lot of sense.", ["sentiment", "sensible", "sensé"]], ["Nous allons ___ ce sujet en réunion. (address)", "aborder|traiter", "", "We'll address this subject in the meeting.", ["adresser", "attendre", "assister"]], ["Merci pour ton ___ sur ma présentation. (feedback)", "retour", "", "Thanks for your feedback on my presentation.", ["retournement", "feed", "renvoi"]], ["Il est très ___ : il pleure facilement.", "sensible", "", "He's very sensitive: he cries easily.", ["raisonnable", "sensé", "sentimentaliste"]]],
  fix: [["Tu crois que j'ai dit oui ? Actuellement, j'ai dit non.", "Actuellement", "En fait", "Actually = en fait.", ["Éventuellement", "Finalement"]], ["Ça fait du sens.", "fait du sens", "a du sens", "Avoir du sens.", ["fait sens", "est du sens"]], ["Je dois adresser ce problème demain.", "adresser", "traiter", "Adresser un problème is an anglicism: traiter, aborder.", ["assister", "attendre"]]],
  xf: [["Remove the anglicism.", "On doit adresser la question du budget.", "On doit aborder la question du budget.|On doit traiter la question du budget."], ["Translate correctly.", "Actually, I'm currently on holiday.", "En fait, je suis actuellement en vacances.|En fait, actuellement, je suis en vacances."]],
  chat: [["Tu travailles toujours chez le même employeur ?", "Oui, actuellement je conçois des formations en ligne pour une école de commerce.", ["Oui, en fait je conçois des e-learnings.", "Oui, éventuellement je conçois."], "Currently = actuellement."], ["Tu as compris pourquoi il est parti ?", "Pas vraiment, ça n'a pas beaucoup de sens.", ["Pas vraiment, ça ne fait pas de sens.", "Pas vraiment, c'est pas sensible."], "Avoir du sens."]]
});

/* ── data/c1a.js ── */
/* C1 lessons · part 1 */
L({ id: "c1-nominal", lvl: "C1", tr: "ecrit", cat: "syntaxe", t: "La nominalisation", en: "Turning verbs and adjectives into nouns",
  rule: { h: "Formal French prefers nouns to verbs: 'the government decided' becomes 'la décision du gouvernement'.",
    pts: ["Verb → noun: <i>augmenter → l'augmentation, décider → la décision, partir → le départ, réduire → la réduction, choisir → le choix</i>.", "Adjective → noun: <i>efficace → l'efficacité, fragile → la fragilité, rare → la rareté, précis → la précision</i>.", "Common suffixes: <i>-tion / -sion, -ment, -age, -ure, -ée, -ité, -ence / -ance</i>; some nouns have no suffix: <i>le refus, le choix, l'appel</i>.", "Use it for headlines, plans, titles and the DALF synthèse: <i>« Les prix ont fortement augmenté » → « Forte augmentation des prix »</i>.", "The subject becomes a <b>de</b> complement, the adverb becomes an adjective: <i>les loyers baissent nettement → la nette baisse des loyers</i>."],
    ex: [["Le gouvernement a décidé de réformer les retraites. → La décision du gouvernement de réformer les retraites.", "The government decided to reform pensions. → The government's decision to reform pensions."], ["Les étudiants protestent → La protestation des étudiants", "Students protest → The students' protest"], ["Le musée rouvre en mai → Réouverture du musée en mai", "The museum reopens in May → Museum reopening in May"], ["Les inégalités sont persistantes → La persistance des inégalités", "Inequalities persist → The persistence of inequalities"]],
    warn: "Check the gender of the noun: <i>-tion, -sion, -ité, -ure, -ence, -ée</i> are feminine; <i>-ment, -age</i> are masculine (except <i>la page, la plage, la cage, l'image</i>…).",
    vn: "Tiếng Việt cũng có danh hóa bằng <b>sự, việc, cuộc</b> (sự tăng giá, việc ra đi). Tiếng Pháp danh hóa bằng <b>hậu tố</b> (-tion, -ment…), và đây là kỹ năng quan trọng cho bài <b>synthèse</b> của DALF C1." },
  cards: [["l'augmentation", "the increase", "L'augmentation des loyers inquiète les familles.", "The rise in rents worries families."], ["la baisse", "the fall, the drop", "On observe une baisse du chômage.", "A fall in unemployment is observed."], ["le recul", "the decline, the retreat", "Le recul de la biodiversité est alarmant.", "The decline of biodiversity is alarming."], ["la mise en place", "the setting up, implementation", "La mise en place du dispositif prendra un an.", "Setting up the scheme will take a year."], ["l'essor", "the rise, the boom", "L'essor du télétravail a changé les villes.", "The boom in remote work has changed cities."], ["la prise de conscience", "the awareness, realisation", "On assiste à une prise de conscience écologique.", "We're seeing an ecological awakening."], ["le maintien", "the keeping, the maintenance", "Le maintien de l'emploi est une priorité.", "Keeping jobs is a priority."], ["l'efficacité", "the effectiveness", "L'efficacité de la mesure reste à prouver.", "The measure's effectiveness remains to be proven."]],
  sent: [["La hausse des prix de l'énergie pèse sur les ménages.", "The rise in energy prices weighs on households."], ["Le développement de la formation en ligne s'est accéléré depuis 2020.", "The development of online training has accelerated since 2020."], ["La fermeture du site a provoqué la colère des salariés.", "The closure of the site angered the employees."], ["La réduction du temps de travail fait débat.", "The reduction of working time is debated."], ["L'arrivée du tramway a transformé le quartier.", "The arrival of the tram transformed the area."], ["La rareté de l'eau devient un enjeu majeur.", "The scarcity of water is becoming a major issue."], ["Le refus de la direction a surpris tout le monde.", "The management's refusal surprised everyone."], ["La mise en œuvre de la réforme est prévue pour 2027.", "The implementation of the reform is planned for 2027."], ["Forte progression des ventes de vélos électriques.", "Strong growth in e-bike sales."], ["L'adoption du texte a été repoussée.", "The adoption of the text was postponed."]],
  nat: [["La forte augmentation des loyers", "Le fort augmentement des loyers", "Augmenter → l'augmentation (feminine)."], ["Le départ du directeur", "Le partir du directeur", "Partir → le départ."], ["La nette baisse du chômage", "La baisse nettement du chômage", "The adverb becomes an adjective: nette."], ["L'efficacité du traitement", "L'efficace du traitement", "Efficace → l'efficacité."]],
  mcq: [["« Le gouvernement a choisi » → ___ du gouvernement", "le choix", ["la choisie", "le choisissement", "la choisition"], "Choisir → le choix."], ["« La ville s'est développée rapidement » → ___ de la ville", "le développement rapide", ["la développation rapide", "le rapidement développement", "la rapide développée"], "Adverb → adjective; développer → le développement."], ["« Les étudiants sont inquiets » → ___ des étudiants", "l'inquiétude", ["l'inquiétement", "l'inquiétion", "l'inquiet"], "Inquiet → l'inquiétude."], ["« On a interdit les voitures » → ___ des voitures", "l'interdiction", ["l'interdisement", "l'interdite", "l'interdisage"], "Interdire → l'interdiction."]],
  gap: [["« Le chômage a reculé » → Le ___ du chômage.", "recul", "reculer", "The decline in unemployment.", ["reculement", "reculade", "recule"]], ["« Les prix ont augmenté » → L'___ des prix.", "augmentation", "augmenter", "The rise in prices.", ["augmentement", "augmentage", "augmentée"]], ["« Le projet a échoué » → L'___ du projet.", "échec", "échouer", "The failure of the project.", ["échouement", "échouage", "échouation"]], ["« Le musée a été rénové » → La ___ du musée.", "rénovation", "rénover", "The renovation of the museum.", ["rénovement", "rénovage", "rénovée"]], ["« Les données sont précises » → La ___ des données.", "précision", "précis", "The precision of the data.", ["précisité", "précisement", "préciseté"]], ["« Les citoyens participent » → La ___ des citoyens.", "participation", "participer", "Citizens' participation.", ["participement", "participance", "participage"]]],
  fix: [["Le augmentation des loyers inquiète.", "Le augmentation", "L'augmentation", "Augmentation is feminine and starts with a vowel: l'.", ["La augmentation", "Les augmentation"]], ["La baisse rapidement des prix.", "La baisse rapidement", "La baisse rapide", "In a noun phrase, the adverb becomes an adjective.", ["La rapidement baisse", "Le baisse rapide"]], ["Le développage du numérique.", "Le développage", "Le développement", "Développer → le développement.", ["La développation", "Le développé"]]],
  xf: [["Nominalise (headline style).", "Les ventes de livres ont fortement augmenté.", "Forte augmentation des ventes de livres.|La forte augmentation des ventes de livres."], ["Nominalise.", "La bibliothèque ferme le dimanche.", "Fermeture de la bibliothèque le dimanche.|La fermeture de la bibliothèque le dimanche."]],
  chat: [["Comment tu résumerais cet article en une ligne ?", "Forte hausse du télétravail dans les grandes entreprises depuis 2020.", ["Ça a augmenté beaucoup le télétravail.", "Le télétravail augmentement fort."], "A summary line: nominalised."], ["Quel serait le titre de ta première partie ?", "L'essor de la formation en ligne : causes et conséquences.", ["La formation en ligne elle est devenue grande.", "Essorer la formation."], "A plan heading: noun phrase."]]
});

L({ id: "c1-concession", lvl: "C1", tr: "pensee", cat: "connecteurs", t: "La concession avancée", en: "Quoique, encore que, si… que, tout… que, quel que soit",
  rule: { h: "C1 concession uses literary connectors and fixed structures that admit a point while limiting it.",
    pts: ["<b>Quoique, encore que</b> + subjunctive (formal): <i>encore qu'il soit difficile de généraliser</i>.", "<b>Si / aussi + adjective + que</b> + subjunctive: <i>si étonnant que cela paraisse, c'est vrai</i>.", "<b>Tout + adjective + que</b> + indicative (or subjunctive): <i>tout brillant qu'il est, il manque d'expérience</i>.", "<b>Quel que soit, quelle que soit, quels que soient</b> + noun; <b>quoi que</b> + subjunctive (whatever); <b>qui que, où que</b>: <i>quelles que soient vos raisons…, quoi que tu fasses…</i>", "Text connectors: <i>certes… il n'en demeure pas moins que, il n'empêche que, toujours est-il que, pour autant</i>."],
    ex: [["Si surprenant que cela puisse paraître, le projet a été accepté.", "Surprising as it may seem, the project was accepted."], ["Quelles que soient les difficultés, nous continuerons.", "Whatever the difficulties, we will go on."], ["Quoi que tu décides, je te soutiendrai.", "Whatever you decide, I'll support you."], ["Certes, les chiffres sont encourageants ; il n'en demeure pas moins que le chômage reste élevé.", "Admittedly the figures are encouraging; the fact remains that unemployment is still high."]],
    warn: "<b>Quoi que</b> (two words) = whatever; <b>quoique</b> (one word) = although. <i>Quel que</i> agrees with the noun that follows: <i>quelle que soit l'heure, quels que soient les risques</i>.",
    vn: "Các cấu trúc nhượng bộ trang trọng: <i>quel que soit</i> ≈ <b>dù… thế nào đi nữa</b>; <i>quoi que tu fasses</i> ≈ <b>dù bạn làm gì</b>; <i>si… que</i> ≈ <b>dù… đến đâu</b>. Rất được đánh giá cao trong bài luận DALF." },
  cards: [["quoique", "although (+ subj.)", "Quoiqu'il soit tard, je continue.", "Although it's late, I'm carrying on."], ["encore que", "although, even though (+ subj.)", "C'est utile, encore que cela coûte cher.", "It's useful, though it's expensive."], ["quel que soit", "whatever, whichever", "Quel que soit le prix, je l'achète.", "Whatever the price, I'll buy it."], ["quoi que", "whatever (+ subj.)", "Quoi qu'il arrive, je serai là.", "Whatever happens, I'll be there."], ["si… que", "however… (+ subj.)", "Si difficile que ce soit, il faut essayer.", "However hard it is, we must try."], ["il n'en demeure pas moins que", "the fact remains that", "Il n'en demeure pas moins que la question reste ouverte.", "The fact remains that the question is still open."], ["il n'empêche que", "nevertheless", "Il n'empêche que tu aurais pu prévenir.", "All the same, you could have warned me."], ["pour autant", "for all that", "Il est riche ; il n'est pas heureux pour autant.", "He's rich; he's not happy for all that."]],
  sent: [["Quelle que soit votre décision, nous la respecterons.", "Whatever your decision, we will respect it."], ["Quoi qu'en disent les critiques, ce film m'a touchée.", "Whatever the critics say, this film moved me."], ["Si brillante qu'elle soit, elle reste modeste.", "Brilliant as she is, she remains modest."], ["Encore qu'il faille nuancer, la tendance est nette.", "Although this needs qualifying, the trend is clear."], ["Le télétravail a des avantages ; il n'en demeure pas moins qu'il isole.", "Remote work has advantages; the fact remains it isolates."], ["Il a beaucoup travaillé ; il n'a pas réussi pour autant.", "He worked hard; he didn't succeed for all that."], ["Toujours est-il que personne n'a répondu.", "The fact is that nobody answered."], ["Quels que soient les obstacles, ils ont tenu bon.", "Whatever the obstacles, they held on."], ["Où que tu ailles, emporte ce livre.", "Wherever you go, take this book."], ["Tout expérimenté qu'il est, il a commis une erreur.", "Experienced as he is, he made a mistake."]],
  nat: [["Quelle que soit l'heure, appelle-moi.", "Quel que soit l'heure, appelle-moi.", "Heure is feminine: quelle que soit."], ["Quoi que tu fasses, fais-le bien.", "Quoique tu fasses, fais-le bien.", "Whatever = quoi que (two words)."], ["Si étrange que cela paraisse, c'est vrai.", "Si étrange que cela paraît, c'est vrai.", "Si… que + subjunctive."], ["Il est riche ; il n'est pas heureux pour autant.", "Il est riche ; pour autant qu'il n'est pas heureux.", "Pour autant at the end, meaning 'for all that'."]],
  mcq: [["___ soient vos raisons, votre absence pose problème.", "Quelles que", ["Quelque", "Quel que", "Quoique"], "Raisons is feminine plural."], ["___ il arrive, ne panique pas.", "Quoi qu'", ["Quoiqu'", "Quel qu'", "Qu'importe qu'"], "Whatever happens = quoi qu'il arrive."], ["Certes, la mesure est populaire ; il n'en ___ pas moins qu'elle est coûteuse.", "demeure", ["reste que", "empêche", "va"], "Il n'en demeure pas moins que."], ["___ intelligent qu'il soit, il ne peut pas tout savoir.", "Si", ["Tant", "Tellement", "Aussi bien"], "Si + adjective + que + subjunctive."]],
  gap: [["___ que soit le résultat, je suis fière de toi.", "Quel", "", "Whatever the result, I'm proud of you.", ["Quelle", "Quels", "Quoi"]], ["___ que tu en penses, je pars demain.", "Quoi", "", "Whatever you think, I'm leaving tomorrow.", ["Quoique", "Quel", "Ce"]], ["Si coûteux que ce ___, ce projet est nécessaire.", "soit", "être", "However costly it is, this project is necessary.", ["est", "sera", "serait"]], ["Il n'___ que nous devons agir.", "empêche", "empêcher", "Nevertheless, we must act.", ["empêchent", "empêchait", "empêcherait"]], ["Elle est épuisée ; elle n'abandonne pas pour ___.", "autant", "", "She's exhausted; she's not giving up for all that.", ["tant", "aussi", "toujours"]], ["___ soient les risques, il faut essayer.", "Quels que", "", "Whatever the risks, we must try.", ["Quelles que", "Quel que", "Quoi que"]]],
  fix: [["Quel que soit la solution, il faut décider vite.", "Quel que soit", "Quelle que soit", "Solution is feminine.", ["Quels que soient", "Quoi que soit"]], ["Quoique tu dises, je ne changerai pas d'avis.", "Quoique", "Quoi que", "Whatever = quoi que.", ["Quel que", "Quoi qu'"]], ["Si fatiguée qu'elle est, elle continue.", "est", "soit", "Si… que + subjunctive.", ["sera", "était"]]],
  xf: [["Rewrite with quel que soit.", "Le temps n'a pas d'importance : nous partirons.", "Quel que soit le temps, nous partirons."], ["Rewrite with si… que.", "Bien que ce soit difficile, il faut le faire.", "Si difficile que ce soit, il faut le faire."]],
  chat: [["Tu penses que je dois accepter ce poste à Lyon ?", "Quelle que soit ta décision, je te soutiendrai.", ["Quel que soit ta décision…", "Quoique ta décision…"], "Décision is feminine: quelle que soit."], ["Les résultats sont bons, non ?", "Certes, mais il n'en demeure pas moins que l'objectif n'est pas atteint.", ["Certes, mais il ne demeure pas que…", "Certes, donc l'objectif est atteint."], "Certes… il n'en demeure pas moins que."]]
});

L({ id: "c1-hypothese", lvl: "C1", tr: "pensee", cat: "hypothese", t: "L'hypothèse au-delà de si", en: "Au cas où, à supposer que, pour peu que, à moins que, faute de quoi",
  rule: { h: "Beyond si, French expresses conditions with a range of conjunctions, each with its own mood.",
    pts: ["<b>Au cas où, dans le cas où</b> + conditional: <i>au cas où il pleuvrait, prends un parapluie</i>.", "<b>À supposer que, en admettant que, pour peu que, à condition que, pourvu que</b> + subjunctive.", "<b>À moins que</b> + subjunctive (+ ne in careful style): <i>à moins qu'il ne fasse froid</i>; <b>à moins de</b> + infinitive.", "<b>Sinon, faute de quoi, sans quoi</b> = otherwise: <i>inscrivez-vous avant lundi, faute de quoi votre place sera attribuée</i>.", "Without a conjunction: gérondif (<i>en partant tôt, tu l'éviterais</i>), <i>avec / sans</i> + noun (<i>sans ton aide, j'aurais échoué</i>), two conditionals (<i>tu me le dirais, je ne te croirais pas</i>)."],
    ex: [["Au cas où tu aurais besoin de moi, appelle.", "In case you need me, call."], ["À supposer qu'il accepte, qui le remplacera ?", "Supposing he accepts, who will replace him?"], ["Pour peu qu'on s'y prenne tôt, on trouve des billets.", "As long as you go about it early, you find tickets."], ["Envoyez le dossier avant le 30, faute de quoi il sera refusé.", "Send the file before the 30th, otherwise it will be rejected."]],
    warn: "<i>Au cas où</i> takes the conditional, not the subjunctive: <i>au cas où il <b>viendrait</b></i>.",
    vn: "<b>phòng khi</b> → au cas où + conditionnel; <b>giả sử</b> → à supposer que + subjonctif; <b>trừ khi</b> → à moins que + subjonctif; <b>nếu không thì</b> → faute de quoi / sinon." },
  cards: [["au cas où", "in case (+ cond.)", "Au cas où il neigerait, on reste.", "In case it snows, we'll stay."], ["à supposer que", "supposing that", "À supposer que ce soit vrai…", "Supposing that's true…"], ["en admettant que", "assuming that", "En admettant qu'il ait raison…", "Assuming he's right…"], ["pour peu que", "if only, as long as", "Pour peu qu'il fasse beau, ce sera parfait.", "As long as the weather's fine, it'll be perfect."], ["à moins que", "unless", "À moins qu'il ne pleuve, on sort.", "Unless it rains, we're going out."], ["à moins de", "unless (+ inf.)", "À moins de partir tout de suite, tu le rateras.", "Unless you leave now, you'll miss it."], ["faute de quoi", "failing which", "Payez avant vendredi, faute de quoi…", "Pay before Friday, failing which…"], ["sans quoi", "otherwise", "Dépêche-toi, sans quoi nous serons en retard.", "Hurry, otherwise we'll be late."]],
  sent: [["Au cas où le vol serait annulé, nous prendrions le train.", "In case the flight were cancelled, we'd take the train."], ["À supposer que la salle soit libre, la fête aura lieu le 8 janvier.", "Supposing the venue is free, the party will be on 8 January."], ["Pour peu que les invités arrivent à l'heure, tout se passera bien.", "As long as the guests arrive on time, all will go well."], ["Nous partirons à l'aube, à moins qu'il n'y ait une tempête.", "We'll leave at dawn, unless there's a storm."], ["À moins de travailler le week-end, je ne finirai pas à temps.", "Unless I work at the weekend, I won't finish in time."], ["Renvoyez le formulaire signé, faute de quoi votre inscription sera annulée.", "Return the signed form, failing which your registration will be cancelled."], ["En admettant que ce chiffre soit exact, il reste à l'expliquer.", "Assuming this figure is accurate, it still needs explaining."], ["Sans votre soutien, ce projet n'aurait jamais vu le jour.", "Without your support, this project would never have seen the light of day."], ["Dans le cas où vous ne pourriez pas venir, prévenez-nous.", "Should you be unable to come, let us know."], ["Il me le jurerait que je ne le croirais pas.", "Even if he swore it to me, I wouldn't believe him."]],
  nat: [["Au cas où tu aurais faim, il y a du riz.", "Au cas où tu aies faim, il y a du riz.", "Au cas où + conditional."], ["À moins qu'il ne pleuve, nous irons.", "À moins qu'il pleuvra, nous irons.", "À moins que + subjunctive."], ["À supposer qu'il soit d'accord…", "À supposer qu'il est d'accord…", "À supposer que + subjunctive."], ["Payez avant lundi, faute de quoi la réservation sera annulée.", "Payez avant lundi, faute de la réservation sera annulée.", "Faute de quoi = failing which."]],
  mcq: [["Au cas où il ___ en retard, commencez sans lui.", "serait", ["soit", "est", "sera"], "Au cas où + conditional."], ["Pour peu qu'on ___ attention, on évite les erreurs.", "fasse", ["fait", "fera", "ferait"], "Pour peu que + subjunctive."], ["___ partir maintenant, tu rateras ton train.", "À moins de", ["À moins que", "Au cas où", "Faute de quoi"], "À moins de + infinitive."], ["Réservez vite, ___ il n'y aura plus de place.", "sans quoi", ["au cas où", "à supposer que", "pour peu que"], "Otherwise = sans quoi."]],
  gap: [["Prends ta veste, au cas où il ___ froid ce soir.", "ferait", "faire", "Take your jacket in case it's cold tonight.", ["fasse", "fait", "fera"]], ["À supposer que tu ___ raison, que proposes-tu ?", "aies", "avoir", "Supposing you're right, what do you suggest?", ["as", "auras", "aurais"]], ["Nous viendrons, à moins qu'il n'y ___ un problème.", "ait", "avoir", "We'll come, unless there's a problem.", ["a", "aura", "aurait"]], ["Inscrivez-vous avant demain, faute de ___ vous perdrez votre place.", "quoi", "", "Sign up before tomorrow, or you'll lose your place.", ["que", "cela", "mieux"]], ["Pour ___ qu'il fasse beau, nous mangerons dehors.", "peu", "", "As long as the weather's fine, we'll eat outside.", ["moins", "autant", "tant"]], ["Dans le cas où vous ___ annuler, prévenez-nous.", "devriez", "devoir", "Should you have to cancel, let us know.", ["deviez", "devez", "deviez dû"]]],
  fix: [["Au cas où il vienne, préviens-moi.", "vienne", "viendrait", "Au cas où + conditional.", ["vient", "viendra"]], ["À moins qu'il fera beau, nous resterons.", "fera", "fasse", "À moins que + subjunctive.", ["fait", "ferait"]], ["À supposer qu'il a menti, que fais-tu ?", "a menti", "ait menti", "À supposer que + subjunctive.", ["aura menti", "aurait menti"]]],
  xf: [["Rewrite with au cas où.", "Si jamais le train est en retard, appelle-moi.", "Au cas où le train serait en retard, appelle-moi."], ["Rewrite with faute de quoi.", "Payez avant vendredi. Sinon, la commande sera annulée.", "Payez avant vendredi, faute de quoi la commande sera annulée."]],
  chat: [["On organise la réception en plein air ?", "Oui, mais prévoyons une tente au cas où il pleuvrait.", ["Oui, au cas où il pleuve.", "Oui, au cas où il pleut demain hier."], "Au cas où + conditional."], ["Tu penses que les deux familles s'entendront ?", "Pour peu que chacun fasse un effort, tout se passera bien.", ["Pour peu que chacun fait un effort…", "Pour peu de chacun…"], "Pour peu que + subjunctive."]]
});

L({ id: "c1-subj", lvl: "C1", tr: "pensee", cat: "subjonctif", t: "Subjonctif : les cas subtils", en: "Relatives, superlatives, le fait que, subjonctif passé",
  rule: { h: "At C1 the subjunctive also expresses uncertainty about a description, judgement after a superlative, and anteriority.",
    pts: ["<b>Relative clause</b> describing something sought, not yet known: <i>je cherche un appartement qui <b>soit</b> calme</i> (if one exists) vs <i>j'ai trouvé un appartement qui <b>est</b> calme</i>.", "After a <b>superlative</b> or <i>le seul, l'unique, le premier, le dernier</i>: <i>c'est le meilleur livre que j'aie lu</i> (subjective judgement).", "<b>Le fait que</b> + subjunctive (usually): <i>le fait qu'il soit absent m'inquiète</i>.", "<b>Subjonctif passé</b> (avoir / être in the subjunctive + participle) for an earlier action: <i>je suis contente que tu aies réussi</i>.", "After <b>que</b> at the start of a sentence: <i>qu'il soit compétent, personne n'en doute</i>."],
    ex: [["Je cherche quelqu'un qui puisse traduire ce document.", "I'm looking for someone who can translate this document."], ["C'est la plus belle ville que je connaisse.", "It's the most beautiful city I know."], ["Le fait que les prix augmentent inquiète les ménages.", "The fact that prices are rising worries households."], ["Je regrette qu'il soit parti si tôt.", "I'm sorry he left so early."]],
    warn: "The choice can change the meaning: <i>il n'y a personne qui sache</i> (nobody, as far as I can tell) — the subjunctive marks something hypothetical or judged.",
    vn: "Ở C1, subjonctif còn thể hiện <b>sự không chắc chắn</b> (tôi tìm một căn hộ <b>mà</b> yên tĩnh — chưa biết có hay không) và <b>đánh giá chủ quan</b> sau so sánh nhất (cuốn sách hay nhất <b>mà</b> tôi từng đọc)." },
  cards: [["le fait que", "the fact that", "Le fait qu'il ait menti est grave.", "The fact that he lied is serious."], ["le seul… qui", "the only one who", "C'est le seul qui comprenne.", "He's the only one who understands."], ["le meilleur… que", "the best… that", "Le meilleur film que j'aie vu.", "The best film I've seen."], ["chercher quelqu'un qui", "to look for someone who", "Je cherche quelqu'un qui parle coréen.", "I'm looking for someone who speaks Korean."], ["il n'y a personne qui", "there's nobody who", "Il n'y a personne qui sache le faire.", "There's nobody who knows how to do it."], ["subjonctif passé", "past subjunctive", "Bien qu'il ait fini, il reste.", "Although he has finished, he's staying."], ["que… (en tête)", "the fact that… (at the start)", "Qu'il soit en retard ne m'étonne pas.", "That he's late doesn't surprise me."], ["le premier… à", "the first to", "Elle a été la première à réagir.", "She was the first to react."]],
  sent: [["Nous cherchons une salle qui puisse accueillir deux cents invités.", "We're looking for a venue that can hold two hundred guests."], ["C'est la meilleure décision que nous ayons prise.", "It's the best decision we've made."], ["Le fait que tu sois là me rassure.", "The fact that you're here reassures me."], ["Je suis ravie que vous ayez pu venir.", "I'm delighted you were able to come."], ["Il n'y a rien qui puisse le faire changer d'avis.", "There's nothing that can make him change his mind."], ["C'est le seul restaurant qui serve du bún bò Huế dans le quartier.", "It's the only restaurant in the area that serves bún bò Huế."], ["Bien qu'elle soit arrivée tard, elle a tout préparé.", "Although she arrived late, she prepared everything."], ["Connaissez-vous un médecin qui soit disponible ce soir ?", "Do you know a doctor who'd be available tonight?"], ["Qu'il faille agir vite, tout le monde en convient.", "That we must act quickly, everyone agrees."], ["C'est le plus long voyage que j'aie jamais fait.", "It's the longest journey I've ever made."]],
  nat: [["C'est le meilleur roman que j'aie lu.", "C'est le meilleur roman que j'ai lu.", "After a superlative, the subjunctive is the careful choice."], ["Je suis contente que tu aies réussi.", "Je suis contente que tu as réussi.", "Emotion + earlier action → subjonctif passé."], ["Je cherche un stylo qui écrive bien.", "Je cherche un stylo qui écrit bien demain.", "Something sought → subjunctive."], ["Le fait qu'il soit parti m'attriste.", "Le fait qu'il est parti hier qu'il m'attriste.", "Le fait que + subjunctive."]],
  mcq: [["Je cherche un collègue qui ___ m'aider sur ce dossier.", "puisse", ["peut", "pourra", "pourrait être"], "Someone sought → subjunctive."], ["C'est le plus beau cadeau qu'on m'___ fait.", "ait", ["a", "aura", "avait"], "Superlative → subjunctive (subjonctif passé)."], ["Je regrette que vous ___ attendre.", "ayez dû", ["avez dû", "aviez dû", "aurez dû"], "Regret about an earlier action → subjonctif passé."], ["J'ai trouvé un appartement qui ___ un grand balcon.", "a", ["ait", "aie", "aurait eu"], "A real, known flat → indicative."]],
  gap: [["Je cherche un livre qui ___ simple et complet.", "soit", "être", "I'm looking for a book that is simple and complete.", ["est", "sera", "serait"]], ["C'est la seule personne qui me ___ vraiment.", "comprenne", "comprendre", "She's the only person who really understands me.", ["comprend", "comprendra", "comprenait"]], ["Le fait qu'il ___ pas répondu est étrange.", "n'ait", "avoir", "The fact that he hasn't answered is strange.", ["n'a", "n'aura", "n'avait"]], ["Je suis heureuse que vous ___ venus.", "soyez", "être", "I'm happy you came.", ["êtes", "serez", "étiez"]], ["Il n'y a personne qui ___ la réponse.", "sache", "savoir", "There's nobody who knows the answer.", ["sait", "saura", "savait"]], ["C'est le pire film que nous ___ vu.", "ayons", "avoir", "It's the worst film we've seen.", ["avons", "aurons", "avions"]]],
  fix: [["Je suis contente que tu as trouvé ce poste.", "as trouvé", "aies trouvé", "Emotion + past → subjonctif passé.", ["avais trouvé", "auras trouvé"]], ["Je cherche un traducteur qui parle vietnamien et qui est disponible en janvier.", "est disponible", "soit disponible", "Someone sought → subjunctive (ideally for both verbs: parle → parle is the same form).", ["sera disponible", "était disponible"]], ["Bien qu'il a fini, il reste.", "a fini", "ait fini", "Bien que + subjunctive (past).", ["avait fini", "aura fini"]]],
  xf: [["Begin with Le fait que…", "Il est absent. Cela pose problème.", "Le fait qu'il soit absent pose problème."], ["Express the earlier action with the subjonctif passé.", "Je suis contente : tu es venue.", "Je suis contente que tu sois venue."]],
  chat: [["Tu as aimé ce roman de Duras ?", "Oui, c'est l'un des plus beaux livres que j'aie lus.", ["Oui, c'est le plus beau livre que j'ai lu.", "Oui, c'est le plus beau que je lis."], "Superlative → subjunctive; lus agrees with livres."], ["Qu'est-ce que tu cherches pour le mariage ?", "Un photographe qui connaisse bien Saïgon et qui parle français.", ["Un photographe qui connaît… qui parle hier.", "Un photographe qui connaîtra."], "Someone sought → subjunctive."]]
});

L({ id: "c1-negation", lvl: "C1", tr: "pensee", cat: "negation", t: "Négation soutenue et ne explétif", en: "Ne… guère, nullement, ni… ni, sans que, ne seul",
  rule: { h: "Formal French has its own negations, and a ne that negates nothing.",
    pts: ["<b>Ne… guère</b> (hardly), <b>ne… nullement / aucunement</b> (not at all), <b>ne… point</b> (literary), <b>ne… nulle part</b>.", "<b>Ni… ni</b>: <i>il n'est ni riche ni célèbre</i>; with subjects: <i>ni Paul ni Marie ne sont venus</i>.", "<b>Ne explétif</b> (no negative meaning) after <i>avant que, à moins que, de peur que, craindre que</i> and comparisons: <i>avant qu'il ne parte; c'est plus difficile que je ne pensais</i>. It is optional and formal.", "<b>Ne</b> alone with <i>pouvoir, savoir, oser, cesser</i> in formal style: <i>je ne saurais dire, il ne cesse de pleuvoir</i>.", "<b>Sans que</b> + subjunctive, with no ne… pas: <i>il est parti sans que je le voie</i>."],
    ex: [["Il n'a guère le temps de lire.", "He hardly has time to read."], ["Je ne suis nullement opposée à ce projet.", "I am in no way opposed to this project."], ["Partons avant qu'il ne soit trop tard.", "Let's go before it's too late."], ["Je ne saurais vous dire à quel point je suis touchée.", "I cannot tell you how touched I am."]],
    warn: "<i>Avant qu'il ne parte</i> = before he leaves (not 'before he doesn't leave'). Don't add <i>pas</i>.",
    vn: "<b>ne explétif</b> là chữ <i>ne</i> «trang trí», <b>không mang nghĩa phủ định</b>: <i>avant qu'il ne pleuve</i> = trước khi trời mưa. Đây là dấu hiệu của văn phong trang trọng." },
  cards: [["ne… guère", "hardly", "Elle ne sort guère le soir.", "She hardly goes out at night."], ["ne… nullement", "not at all", "Cela ne me dérange nullement.", "That doesn't bother me at all."], ["ni… ni", "neither… nor", "Je n'ai ni faim ni soif.", "I'm neither hungry nor thirsty."], ["sans que", "without (+ subj.)", "Il est entré sans que personne le remarque.", "He came in without anyone noticing."], ["ne… nulle part", "nowhere", "Je ne trouve mes lunettes nulle part.", "I can't find my glasses anywhere."], ["je ne saurais", "I couldn't (formal)", "Je ne saurais trop vous remercier.", "I cannot thank you enough."], ["ne cesser de", "to keep on", "Il ne cesse de pleuvoir.", "It keeps on raining."], ["plus… que je ne", "more… than I (ne explétif)", "C'est plus loin que je ne croyais.", "It's further than I thought."]],
  sent: [["Il ne reste guère de places pour le concert.", "There are hardly any seats left for the concert."], ["Je ne suis nullement surprise par sa réaction.", "I'm not at all surprised by his reaction."], ["Ni le directeur ni son adjoint n'étaient au courant.", "Neither the director nor his deputy knew."], ["Rentrons avant que la nuit ne tombe.", "Let's go home before night falls."], ["Elle est partie sans que nous ayons pu lui dire au revoir.", "She left without our being able to say goodbye."], ["Le projet est plus complexe qu'il n'y paraît.", "The project is more complex than it seems."], ["Je ne saurais dire combien de temps cela prendra.", "I couldn't say how long it will take."], ["Depuis son arrivée, elle ne cesse de progresser.", "Since she arrived, she has kept improving."], ["Je crains qu'il ne soit déjà trop tard.", "I fear it may already be too late."], ["Ce n'est guère étonnant.", "It's hardly surprising."]],
  nat: [["Avant qu'il ne parte, dis-lui merci.", "Avant qu'il ne parte pas, dis-lui merci.", "Ne explétif: no pas."], ["Il est sorti sans que je le voie.", "Il est sorti sans que je ne le voie pas.", "Sans que: no negation."], ["Je n'ai ni le temps ni l'envie.", "Je n'ai pas ni le temps ni l'envie.", "Ni… ni replaces pas."], ["Il ne cesse de parler.", "Il ne cesse pas de parler ne.", "Formal: ne cesser de."]],
  mcq: [["Il n'a ___ dormi cette nuit : à peine deux heures.", "guère", ["nullement", "point de", "rien"], "Hardly = guère."], ["Je n'ai ___ l'intention de démissionner.", "nullement", ["guère de", "ni", "pas nullement"], "Not at all = nullement."], ["Partons avant qu'il ___ trop tard.", "ne soit", ["ne soit pas", "n'est", "sera"], "Ne explétif + subjunctive."], ["Il est parti sans que nous le ___.", "sachions", ["ne sachions pas", "savons", "saurons"], "Sans que + subjunctive, no negation."]],
  gap: [["Je n'ai ___ faim ni soif.", "ni", "", "I'm neither hungry nor thirsty.", ["pas", "guère", "point"]], ["Il ne ___ de neiger depuis hier.", "cesse", "cesser", "It hasn't stopped snowing since yesterday.", ["cesse pas", "cessait", "cessera"]], ["Ce n'est ___ surprenant : il est toujours en retard.", "guère", "", "It's hardly surprising: he's always late.", ["ni", "point de", "nul"]], ["Je crains qu'il ___ pleuve pendant la cérémonie.", "ne", "", "I fear it may rain during the ceremony.", ["ne pas", "pas", "n'en"]], ["Je ne trouve mon passeport nulle ___.", "part", "", "I can't find my passport anywhere.", ["où", "endroit", "lieu"]], ["Elle est entrée sans que nous la ___.", "remarquions", "remarquer", "She came in without our noticing her.", ["remarquons", "remarquerons", "remarquions pas"]]],
  fix: [["Avant qu'il ne parte pas, appelle-le.", "ne parte pas", "ne parte", "Ne explétif: no pas.", ["parte pas", "ne part"]], ["Je n'ai pas ni frère ni sœur.", "n'ai pas ni", "n'ai ni", "Ni… ni replaces pas.", ["ai ni", "n'ai point ni"]], ["Il est parti sans que je ne le sais.", "sais", "sache", "Sans que + subjunctive.", ["savais", "saurai"]]],
  xf: [["Make it formal with ne… guère.", "Il ne sort presque jamais.", "Il ne sort guère."], ["Use ni… ni.", "Il ne boit pas d'alcool et il ne fume pas.", "Il ne boit ni ne fume.|Il ne boit pas d'alcool ni ne fume."]],
  chat: [["Ça vous dérange si j'ouvre la fenêtre ?", "Pas du tout, cela ne me dérange nullement.", ["Cela ne me dérange nullement pas.", "Cela me dérange guère pas."], "Formal: ne… nullement."], ["Le dossier est simple ?", "Il est plus complexe qu'il n'y paraît, crois-moi.", ["Il est plus complexe qu'il n'y paraît pas.", "Il est plus complexe que paraître."], "Comparative + ne explétif."]]
});

L({ id: "c1-inversion", lvl: "C1", tr: "ecrit", cat: "syntaxe", t: "L'inversion du sujet", en: "Peut-être, aussi, ainsi, à peine, sans doute at the start",
  rule: { h: "In formal writing, some adverbs at the start of a sentence trigger subject–verb inversion.",
    pts: ["<b>Peut-être, sans doute, aussi (= therefore), ainsi, à peine, du moins, encore, rares sont…</b> + inversion: <i>peut-être a-t-il raison</i>.", "With a noun subject, keep the noun and add a pronoun: <i>sans doute <b>le directeur</b> acceptera-<b>t-il</b></i>.", "<b>Aussi</b> at the start means <i>therefore</i>: <i>aussi avons-nous décidé de reporter la réunion</i>.", "<b>À peine… que</b>: <i>à peine était-il arrivé que le téléphone sonna</i>.", "Spoken alternative: <i>peut-être que + normal order</i>: <i>peut-être qu'il a raison</i>."],
    ex: [["Peut-être viendra-t-elle demain.", "Perhaps she'll come tomorrow."], ["Aussi avons-nous décidé de reporter le projet.", "We have therefore decided to postpone the project."], ["À peine étions-nous sortis qu'il s'est mis à pleuvoir.", "No sooner had we gone out than it started to rain."], ["Ainsi s'achève notre visite.", "Thus ends our visit."]],
    warn: "Add <b>-t-</b> between a vowel and il / elle / on: <i>peut-être va-t-il venir, aussi a-t-elle refusé</i>.",
    vn: "Đảo ngữ sau <i>peut-être, aussi, à peine</i> là dấu hiệu văn viết trang trọng. Khi nói, dùng <i>peut-être que</i> + trật tự bình thường. Chú ý: <b>aussi</b> đứng đầu câu nghĩa là <b>vì vậy</b>, không phải «cũng»." },
  cards: [["peut-être + inversion", "perhaps", "Peut-être a-t-il oublié.", "Perhaps he forgot."], ["sans doute + inversion", "probably", "Sans doute est-ce la meilleure solution.", "This is probably the best solution."], ["aussi + inversion", "therefore", "Aussi faut-il agir vite.", "We must therefore act quickly."], ["à peine… que", "no sooner… than", "À peine était-elle partie qu'il est arrivé.", "No sooner had she left than he arrived."], ["ainsi + inversion", "thus", "Ainsi naquit le projet.", "Thus the project was born."], ["rares sont… qui", "few are… who", "Rares sont ceux qui le savent.", "Few people know it."], ["du moins", "at least", "Du moins le pensait-elle.", "At least, so she thought."], ["encore faut-il que", "provided, of course, that", "Encore faut-il qu'il accepte.", "Provided, of course, that he accepts."]],
  sent: [["Peut-être faudrait-il revoir le calendrier.", "Perhaps the schedule should be reviewed."], ["Sans doute les résultats seront-ils meilleurs l'an prochain.", "The results will probably be better next year."], ["Le budget est limité ; aussi devons-nous faire des choix.", "The budget is limited; we must therefore make choices."], ["À peine avait-elle fini son discours que la salle a applaudi.", "No sooner had she finished her speech than the room applauded."], ["Ainsi se termine la première partie de notre exposé.", "Thus ends the first part of our presentation."], ["Rares sont les villes qui ont réussi cette transition.", "Few cities have managed this transition."], ["Encore faut-il que les moyens suivent.", "Provided, of course, that the resources follow."], ["Peut-être que tu as raison, après tout.", "Maybe you're right, after all."], ["Du moins est-ce ce que prétend le rapport.", "At least, that's what the report claims."], ["Toujours est-il que la question reste posée.", "The fact remains that the question is still open."]],
  nat: [["Peut-être viendra-t-il.", "Peut-être il viendra.", "Peut-être at the start: inversion (or peut-être qu'il viendra)."], ["Aussi a-t-elle refusé.", "Aussi elle a refusé.", "Aussi = therefore: inversion."], ["Sans doute le ministre répondra-t-il.", "Sans doute répondra le ministre-il.", "Noun subject + verb + pronoun."], ["Peut-être qu'il pleuvra.", "Peut-être qu'il pleuvra-t-il.", "With que, no inversion."]],
  mcq: [["Peut-être ___ raison.", "a-t-il", ["il a", "a-il", "il a-t-il"], "Inversion with -t-."], ["Le temps presse ; aussi ___ prendre une décision.", "devons-nous", ["nous devons", "nous devons-nous", "devons nous-"], "Aussi = therefore → inversion."], ["À peine ___ arrivés que l'orage a éclaté.", "étions-nous", ["nous étions", "nous étions-nous", "étions nous-"], "À peine… que + inversion."], ["Peut-être ___ en retard.", "qu'il sera", ["sera il", "qu'il sera-t-il", "il sera-t-il"], "Peut-être que + normal order."]],
  gap: [["Sans doute ___ oublié notre rendez-vous.", "a-t-elle", "elle · avoir", "She has probably forgotten our appointment.", ["elle a", "a-elle", "a-t'elle"]], ["Peut-être ___ déjà la réponse.", "connaissez-vous", "vous · connaître", "Perhaps you already know the answer.", ["vous connaissez", "connaissez-vous-t", "connaître-vous"]], ["Aussi ___ démissionné.", "a-t-il", "il · avoir", "He therefore resigned.", ["il a", "a-il", "est-il"]], ["À peine ___ rentrée qu'il a appelé.", "étais-je", "je · être", "No sooner had I got home than he called.", ["j'étais", "étais-t-je", "je suis"]], ["Rares ___ les étudiants qui réussissent du premier coup.", "sont", "être", "Few students pass first time.", ["est", "étaient-ils", "soient"]], ["Encore ___ que le client soit d'accord.", "faut-il", "falloir", "Provided, of course, that the client agrees.", ["il faut", "faut-t-il", "faille-t-il"]]],
  fix: [["Peut-être il viendra demain.", "Peut-être il viendra", "Peut-être viendra-t-il", "Inversion after peut-être at the start (or peut-être qu'il).", ["Peut-être viendra-il", "Peut-être il viendra-t-il"]], ["Aussi nous avons décidé de partir.", "Aussi nous avons décidé", "Aussi avons-nous décidé", "Aussi = therefore: inversion.", ["Aussi avons nous-décidé", "Aussi avons-décidé nous"]], ["Peut-être va-il pleuvoir.", "va-il", "va-t-il", "Add -t- between two vowels.", ["va-t'il", "vat-il"]]],
  xf: [["Use peut-être with inversion.", "Il a peut-être raison.", "Peut-être a-t-il raison."], ["Use aussi (= therefore) with inversion.", "Le budget est serré, donc nous devons économiser.", "Le budget est serré ; aussi devons-nous économiser.|Le budget est serré, aussi devons-nous économiser."]],
  chat: [["Tu crois que la réforme passera ?", "Peut-être sera-t-elle adoptée, mais pas avant l'an prochain.", ["Peut-être elle sera adoptée-t-elle.", "Peut-être sera-elle adoptée."], "Peut-être + inversion with -t-."], ["(In a report) Quelle conclusion tirer ?", "Les coûts dépassent les bénéfices ; aussi convient-il de revoir le projet.", ["Aussi il convient de revoir le projet.", "Aussi convient-t-il."], "Aussi = therefore: inversion."]]
});

L({ id: "c1-passesimple", lvl: "C1", tr: "ecrit", cat: "temps", t: "Passé simple et passé antérieur", en: "Recognising the tenses of literature and history",
  rule: { h: "The passé simple replaces the passé composé in literary and historical narration; you need to recognise it, rarely to produce it.",
    pts: ["Three endings families: <i>-ai, -as, -a, -âmes, -âtes, -èrent</i> (all -er verbs: <i>il parla</i>); <i>-is, -is, -it, -îmes, -îtes, -irent</i> (<i>il finit, il prit, il fit</i>); <i>-us, -us, -ut, -ûmes, -ûtes, -urent</i> (<i>il fut, il eut, il put, il voulut</i>).", "Irregular: <i>venir → il vint, tenir → il tint, naître → il naquit, mourir → il mourut, voir → il vit</i>.", "Mostly 3rd person: <i>il / elle / ils / elles</i>.", "<b>Passé antérieur</b> (aux in the passé simple + participle) after <i>quand, dès que, après que, à peine</i>: <i>dès qu'il eut fini, il sortit</i>.", "Imparfait + passé simple work like imparfait + passé composé: <i>il pleuvait quand elle arriva</i>."],
    ex: [["Victor Hugo naquit à Besançon en 1802.", "Victor Hugo was born in Besançon in 1802."], ["Elle ouvrit la porte et resta immobile.", "She opened the door and stood still."], ["Ils vécurent heureux et eurent beaucoup d'enfants.", "They lived happily and had many children."], ["Quand il eut terminé sa lettre, il la relut.", "When he had finished his letter, he reread it."]],
    warn: "Careful: <i>il fit</i> (faire) vs <i>il fut</i> (être); <i>il vit</i> can be voir (passé simple) or vivre (present).",
    vn: "<b>Passé simple</b> là thì của văn chương và lịch sử, giống lối kể «Năm 1802, Victor Hugo <b>ra đời</b> tại…». Ở DALF C1, bạn cần <b>nhận biết</b> để hiểu văn bản, ít khi phải tự viết." },
  cards: [["il fut", "he was (être)", "Ce fut une soirée inoubliable.", "It was an unforgettable evening."], ["il eut", "he had (avoir)", "Il eut une idée brillante.", "He had a brilliant idea."], ["il fit", "he did / made (faire)", "Elle fit un geste de la main.", "She made a gesture with her hand."], ["il vint", "he came (venir)", "Le printemps vint enfin.", "Spring finally came."], ["il naquit", "he was born (naître)", "Elle naquit à Hué.", "She was born in Hué."], ["il mourut", "he died (mourir)", "Il mourut en exil.", "He died in exile."], ["ils prirent", "they took (prendre)", "Ils prirent la route du sud.", "They took the road south."], ["dès qu'il eut fini", "as soon as he had finished", "Dès qu'il eut fini, il partit.", "As soon as he had finished, he left."]],
  sent: [["Marie Curie reçut le prix Nobel à deux reprises.", "Marie Curie received the Nobel Prize twice."], ["Il faisait nuit quand ils arrivèrent au village.", "It was dark when they arrived at the village."], ["Elle prit sa valise et sortit sans un mot.", "She took her suitcase and left without a word."], ["Les deux hommes se regardèrent longtemps.", "The two men looked at each other for a long time."], ["Ce fut le début d'une longue amitié.", "It was the beginning of a long friendship."], ["Dès qu'elle eut lu la lettre, elle comprit tout.", "As soon as she had read the letter, she understood everything."], ["Hô Chi Minh vécut plusieurs années à Paris.", "Hô Chi Minh lived in Paris for several years."], ["La guerre éclata en 1914.", "War broke out in 1914."], ["Ils durent attendre jusqu'au matin.", "They had to wait until morning."], ["À peine fut-il parti qu'elle se mit à pleurer.", "No sooner had he left than she began to cry."]],
  nat: [["Il prit son manteau et sortit.", "Il prenit son manteau et sortit.", "Prendre → il prit."], ["Elle fut très surprise.", "Elle fit très surprise.", "Être → elle fut."], ["Ils vinrent nous voir.", "Ils venirent nous voir.", "Venir → ils vinrent."], ["Quand il eut fini, il partit.", "Quand il fut fini, il partit.", "Finir takes avoir: il eut fini."]],
  mcq: [["« Il fut » is the passé simple of…", "être", ["faire", "falloir", "fuir"], "Être → il fut."], ["« Elle naquit » means…", "she was born", ["she swam", "she knew", "she grew"], "Naître → elle naquit."], ["« Ils eurent » is the passé simple of…", "avoir", ["être", "aller", "ouvrir"], "Avoir → ils eurent."], ["Passé simple of « faire », il: ___", "fit", ["fut", "faisit", "fait"], "Faire → il fit."]],
  gap: [["Le roi ___ en 1715. (mourir)", "mourut", "mourir", "The king died in 1715.", ["mourit", "mourra", "meurt"]], ["Elle ___ la porte doucement. (ouvrir)", "ouvrit", "ouvrir", "She opened the door gently.", ["ouvra", "ouvrut", "ouvre"]], ["Ils ___ à Paris en 1925. (s'installer)", "s'installèrent", "s'installer", "They settled in Paris in 1925.", ["s'installirent", "s'installaient", "s'installeront"]], ["Il ___ une longue pause. (faire)", "fit", "faire", "He paused for a long time.", ["fut", "faisa", "fera"]], ["Dès qu'il ___ fini, il sortit.", "eut", "avoir", "As soon as he had finished, he went out.", ["fut", "avait été", "a"]], ["Ce ___ un moment inoubliable. (être)", "fut", "être", "It was an unforgettable moment.", ["fit", "était été", "sera"]]],
  fix: [["Elle prenit le train de nuit.", "prenit", "prit", "Prendre → elle prit.", ["prena", "prendit"]], ["Ils venirent à la fête.", "venirent", "vinrent", "Venir → ils vinrent.", ["venèrent", "vinèrent"]], ["Quand elle fut fini, elle se leva.", "fut fini", "eut fini", "Finir takes avoir: elle eut fini.", ["fut finie", "avait finit"]]],
  xf: [["Rewrite in the passé composé (spoken French).", "Il entra et s'assit près de la fenêtre.", "Il est entré et s'est assis près de la fenêtre."], ["Rewrite in the passé composé.", "Ils partirent à l'aube.", "Ils sont partis à l'aube."]],
  chat: [["Dans ce roman, qu'est-ce qui se passe au début ?", "Le héros arriva à Paris un soir d'hiver et ne connaissait personne.", ["Le héros arrivit à Paris…", "Le héros arriva et connut personne ne."], "Passé simple for the event, imparfait for the background."], ["Tu peux me dire ce que veut dire « il vint » ?", "C'est le passé simple de venir : il est venu.", ["C'est le présent de voir.", "C'est le futur de vivre."], "Venir → il vint."]]
});

L({ id: "c1-participe", lvl: "C1", tr: "ecrit", cat: "syntaxe", t: "Participes et infinitifs passés", en: "Après avoir, une fois terminé, la proposition participiale",
  rule: { h: "Compact structures with participles and past infinitives make formal writing tighter.",
    pts: ["<b>Après + infinitif passé</b>, same subject: <i>après avoir lu le rapport, elle a appelé le directeur; après être arrivés, nous avons dîné</i>.", "<b>Avant de</b> + infinitive; <b>sans</b> + infinitif passé: <i>il est parti sans avoir payé</i>.", "<b>Proposition participiale</b> (its own subject): <i>le dîner terminé, les invités sont partis; la pluie ayant cessé, nous sommes sortis</i>.", "<b>Une fois</b> + participle: <i>une fois le contrat signé, le travail commencera</i>.", "Agreement: <i>après s'être levée, elle…</i> (pronominal: agreement with the subject)."],
    ex: [["Après avoir fini mes études, je suis venue en France.", "After finishing my studies, I came to France."], ["La réunion terminée, chacun est rentré chez soi.", "The meeting over, everyone went home."], ["Une fois les invitations envoyées, nous pourrons souffler.", "Once the invitations are sent, we can breathe."], ["Le train ayant du retard, la conférence a commencé sans elle.", "The train being late, the talk started without her."]],
    warn: "<i>Après</i> is never followed by the present infinitive in this use: <i>après <b>avoir</b> mangé</i>, not <i>après manger</i> (common in speech, but avoid in writing).",
    vn: "<b>Sau khi</b> + động từ → <i>après avoir / être</i> + participe (cùng chủ ngữ). Cấu trúc <i>Le dîner terminé…</i> ≈ <b>Bữa tối xong…</b> — gọn và trang trọng." },
  cards: [["après avoir + p.p.", "after having done", "Après avoir dîné, ils sont sortis.", "After dinner, they went out."], ["après être + p.p.", "after having (être verbs)", "Après être rentrée, elle a dormi.", "After getting home, she slept."], ["sans avoir + p.p.", "without having", "Il est parti sans avoir dit au revoir.", "He left without saying goodbye."], ["une fois + p.p.", "once (done)", "Une fois le dossier complet, envoyez-le.", "Once the file is complete, send it."], ["la décision prise", "the decision (once) taken", "La décision prise, il faut s'y tenir.", "Once the decision is taken, we must stick to it."], ["cela dit", "that said", "Cela dit, je comprends ton point de vue.", "That said, I understand your point of view."], ["ceci étant", "this being so", "Ceci étant, rien n'est perdu.", "This being so, nothing is lost."], ["tout bien considéré", "all things considered", "Tout bien considéré, j'accepte.", "All things considered, I accept."]],
  sent: [["Après avoir étudié la question, le comité a rendu son avis.", "Having studied the question, the committee gave its opinion."], ["Après s'être mariés à Saïgon, ils feront une fête à Paris.", "After marrying in Saigon, they'll have a party in Paris."], ["Elle a signé le contrat sans l'avoir lu en entier.", "She signed the contract without reading it all."], ["Le budget validé, l'équipe a lancé le projet.", "With the budget approved, the team launched the project."], ["Une fois les valises faites, nous avons appelé un taxi.", "Once the cases were packed, we called a taxi."], ["La grève ayant été annulée, les trains circulent normalement.", "The strike having been called off, trains are running normally."], ["Cela dit, il faut reconnaître ses efforts.", "That said, his efforts must be acknowledged."], ["Avant de prendre une décision, consultons l'équipe.", "Before deciding, let's consult the team."], ["Après être restée dix ans à l'étranger, elle est rentrée chez elle.", "After ten years abroad, she went home."], ["Tout bien considéré, cette option est la plus raisonnable.", "All things considered, this option is the most sensible."]],
  nat: [["Après avoir mangé, nous sommes sortis.", "Après manger, nous sommes sortis.", "In writing: après + past infinitive."], ["Après être arrivée, elle a appelé.", "Après avoir arrivée, elle a appelé.", "Arriver → être."], ["Le dîner terminé, nous avons dansé.", "Le dîner terminant, nous avons dansé.", "Completed action → past participle."], ["Il est parti sans avoir payé.", "Il est parti sans payé.", "Sans + infinitive (past)."]],
  mcq: [["Après ___ le film, nous en avons discuté.", "avoir vu", ["voir", "avoir voir", "vu"], "Après + infinitif passé."], ["Après ___, elle a pris un café.", "s'être levée", ["se lever", "s'avoir levée", "levée s'être"], "Pronominal: être + agreement."], ["___ le travail terminé, ils sont partis.", "Une fois", ["Après", "Avant", "Pendant"], "Une fois + noun + participle."], ["La neige ___, l'école a fermé.", "ayant bloqué les routes", ["bloquant hier les routes", "en ayant bloquée", "avoir bloqué"], "Participial clause with its own subject."]],
  gap: [["Après ___ fini ses études, elle a voyagé.", "avoir", "", "After finishing her studies, she travelled.", ["être", "a", "ayant"]], ["Après ___ partis, ils ont regretté.", "être", "", "After leaving, they had regrets.", ["avoir", "étant", "sont"]], ["Il est sorti sans avoir ___ la porte.", "fermé", "fermer", "He went out without closing the door.", ["fermer", "fermait", "fermant"]], ["Une ___ le formulaire rempli, envoyez-le.", "fois", "", "Once the form is filled in, send it.", ["foi", "fois-ci", "fin"]], ["Le contrat ___, les travaux peuvent commencer.", "signé", "signer", "With the contract signed, the work can start.", ["signant", "signer", "signait"]], ["___ dit, je comprends ta position.", "Cela", "", "That said, I understand your position.", ["Ça a", "Ce", "Il"]]],
  fix: [["Après manger, nous avons fait une promenade.", "Après manger", "Après avoir mangé", "In writing: après + past infinitive.", ["Après mangé", "Après être mangé"]], ["Après avoir arrivé, il a téléphoné.", "avoir arrivé", "être arrivé", "Arriver takes être.", ["avoir arrivée", "étant arrivé"]], ["Une fois le dossier envoyer, j'étais soulagée.", "envoyer", "envoyé", "Une fois + noun + past participle.", ["envoyant", "envoyais"]]],
  xf: [["Use après + infinitif passé.", "Elle a lu le courrier, puis elle a répondu.", "Après avoir lu le courrier, elle a répondu."], ["Use a participial clause.", "Quand la réunion a été terminée, tout le monde est parti.", "La réunion terminée, tout le monde est parti."]],
  chat: [["Comment s'est passée ta soirée ?", "Après avoir dîné chez Claire, nous sommes allés voir un concert.", ["Après dîner chez Claire…", "Après avoir dîné, Claire nous sommes allés."], "Après + infinitif passé, same subject."], ["Quand commence le chantier ?", "Une fois le permis obtenu, les travaux pourront commencer.", ["Une fois obtenir le permis…", "Une fois le permis obtenant…"], "Une fois + noun + participle."]]
});

/* ── data/c1b.js ── */
/* C1 lessons · part 2 */
L({ id: "c1-accords", lvl: "C1", tr: "pensee", cat: "accords", t: "Accords difficiles", en: "Pronominal verbs, tout, même, quelque",
  rule: { h: "With pronominal verbs, agree with the reflexive pronoun only when it is a direct object.",
    pts: ["<i>Elle s'est lavée</i> (se = direct object) but <i>elle s'est lavé <b>les mains</b></i> (the direct object is les mains, after the verb).", "No agreement when se is indirect: <i>ils se sont parlé, elles se sont téléphoné, ils se sont écrit</i> (parler à, téléphoner à, écrire à).", "<b>Tout</b> adverb (= completely) is invariable, except before a feminine adjective starting with a consonant or aspirated h: <i>ils sont tout contents, elle est toute contente, elle est tout étonnée</i>.", "<b>Même</b>: adjective (agrees: <i>les mêmes erreurs, eux-mêmes</i>) or adverb (= even, invariable: <i>même les enfants</i>).", "<b>Quelque</b> + noun = some (agrees: <i>quelques jours</i>); <b>quel que</b> + être (see concession)."],
    ex: [["Elle s'est coupé le doigt.", "She cut her finger."], ["Nous nous sommes écrit pendant des années.", "We wrote to each other for years."], ["Elles étaient tout émues.", "They were deeply moved."], ["Même les plus sceptiques ont été convaincus.", "Even the most sceptical were convinced."]],
    warn: "Ask: <i>se</i> = whom? (direct) or to whom? (indirect). <i>Ils se sont souri</i> — sourire à quelqu'un → no agreement.",
    vn: "Đây là phần chính tả khó cả với người Pháp. Mẹo: hỏi <b>«ai/cái gì?»</b> (bổ ngữ trực tiếp → hợp giống, số) hay <b>«với ai / cho ai?»</b> (gián tiếp → không hợp)." },
  cards: [["s'écrire", "to write to each other", "Ils se sont écrit souvent.", "They often wrote to each other."], ["se parler", "to talk to each other", "Elles se sont parlé hier.", "They talked to each other yesterday."], ["se rencontrer", "to meet", "Nous nous sommes rencontrés à Saïgon.", "We met in Saigon."], ["se laver les mains", "to wash one's hands", "Elle s'est lavé les mains.", "She washed her hands."], ["tout", "completely (adverb)", "Ils sont tout seuls.", "They're all alone."], ["toute", "completely (before fem. consonant)", "Elle est toute seule.", "She's all alone."], ["même (adverb)", "even", "Même ma mère a ri.", "Even my mother laughed."], ["quelques", "a few, some", "Il reste quelques places.", "There are a few seats left."]],
  sent: [["Lan Anh et Alex se sont rencontrés en 2022.", "Lan Anh and Alex met in 2022."], ["Elles se sont téléphoné tous les dimanches.", "They phoned each other every Sunday."], ["Elle s'est brûlé la main en cuisinant.", "She burnt her hand while cooking."], ["Ils se sont souri sans rien dire.", "They smiled at each other without a word."], ["Les deux sœurs se sont disputées puis réconciliées.", "The two sisters quarrelled then made up."], ["Elle était toute surprise de nous voir.", "She was very surprised to see us."], ["Ils sont tout heureux de leur nouvelle maison.", "They're delighted with their new house."], ["Ce sont toujours les mêmes problèmes.", "It's always the same problems."], ["Même les enfants ont compris.", "Even the children understood."], ["Je reste quelques jours à Lyon.", "I'm staying a few days in Lyon."]],
  nat: [["Ils se sont parlé.", "Ils se sont parlés.", "Parler à → indirect: no agreement."], ["Elle s'est lavée.", "Elle s'est lavé.", "Se = herself, direct object: agreement."], ["Elle s'est lavé les cheveux.", "Elle s'est lavée les cheveux.", "The direct object (les cheveux) is after the verb: no agreement."], ["Elle est toute petite.", "Elle est tout petite.", "Tout before a feminine adjective with a consonant → toute."]],
  mcq: [["Elles se sont ___ pendant tout le voyage.", "écrit", ["écrites", "écrits", "écrite"], "Écrire à → indirect: no agreement."], ["Nous nous sommes ___ au café.", "retrouvés", ["retrouvé", "retrouvée", "retrouver"], "Se retrouver: se is direct → agreement."], ["Elle s'est ___ la cheville.", "foulé", ["foulée", "fouler", "foulés"], "Direct object (la cheville) after the verb."], ["Les filles étaient ___ contentes.", "toutes", ["tout", "toute", "tous"], "Tout before a feminine adjective with a consonant agrees: toutes."]],
  gap: [["Ils se sont ___ au téléphone. (parler)", "parlé", "parler", "They talked on the phone.", ["parlés", "parlée", "parler"]], ["Elle s'est ___ très tôt. (lever)", "levée", "se lever", "She got up very early.", ["levé", "levés", "lever"]], ["Elle s'est ___ les dents. (brosser)", "brossé", "se brosser", "She brushed her teeth.", ["brossée", "brossées", "brosser"]], ["Elles sont ___ étonnées. (tout)", "tout", "", "They are very surprised.", ["toutes", "toute", "tous"]], ["___ les experts se sont trompés. (même)", "Même", "", "Even the experts were wrong.", ["Mêmes", "Les même", "Même que"]], ["J'ai ___ questions à te poser. (quelque)", "quelques", "", "I have a few questions to ask you.", ["quelque", "quelle que", "quels que"]]],
  fix: [["Elles se sont téléphonées hier.", "téléphonées", "téléphoné", "Téléphoner à → indirect: no agreement.", ["téléphonée", "téléphonés"]], ["Elle s'est coupée les cheveux.", "coupée", "coupé", "The direct object is les cheveux, after the verb.", ["coupés", "coupées"]], ["Elle est tout seule à la maison.", "tout", "toute", "Feminine adjective with a consonant → toute.", ["tous", "toutes"]]],
  xf: [["Rewrite with elles.", "Ils se sont rencontrés et ils se sont plu.", "Elles se sont rencontrées et elles se sont plu."], ["Rewrite with elle.", "Il s'est lavé et il s'est lavé les mains.", "Elle s'est lavée et elle s'est lavé les mains."]],
  chat: [["Vous vous êtes connus comment ?", "Nous nous sommes rencontrés à Saïgon, puis nous nous sommes écrit pendant un an.", ["Nous nous sommes rencontré… écrits.", "Nous nous avons rencontrés."], "Se rencontrer: agreement; s'écrire: none."], ["Ta sœur va mieux ?", "Oui, mais elle s'est cassé le bras au ski.", ["Elle s'est cassée le bras.", "Elle a cassée le bras."], "Direct object after the verb: cassé."]]
});

L({ id: "c1-modal", lvl: "C1", tr: "nuance", cat: "argumentation", t: "Modaliser et nuancer", en: "Hedging, distancing, conceding with precision",
  rule: { h: "C1 writers show how sure they are: they hedge, distance themselves from a source, and qualify claims.",
    pts: ["<b>Cautious</b>: <i>il se pourrait que, il n'est pas exclu que</i> (+ subj.), <i>vraisemblablement, a priori, dans une certaine mesure</i>.", "<b>Distance from a source</b>: conditionnel journalistique (<i>le ministre aurait démissionné</i>), <i>selon, d'après, à en croire</i>, <i>prétendument</i>.", "<b>Firm</b>: <i>force est de constater que, il ne fait aucun doute que, il est indéniable que</i> (+ ind.).", "<b>Qualify</b>: <i>en partie, dans une large mesure, du moins, plus ou moins, à bien des égards</i>.", "<b>Attenuate</b> with the conditional: <i>on pourrait objecter que, il conviendrait de, il semblerait que</i>."],
    ex: [["Force est de constater que les mesures n'ont pas suffi.", "One has to admit that the measures were not enough."], ["Il se pourrait que la situation s'améliore.", "The situation might improve."], ["Selon l'agence, le projet aurait coûté deux millions.", "According to the agency, the project reportedly cost two million."], ["Cette hypothèse est, dans une large mesure, convaincante.", "This hypothesis is, to a large extent, convincing."]],
    warn: "In the DALF synthèse, report the documents' claims with distance (<i>selon le document 1…</i>) and never give your own opinion; keep the firm markers for the essai.",
    vn: "Tiếng Việt dùng <b>có lẽ, có thể, được cho là</b>. Tiếng Pháp C1 dùng <b>thức điều kiện</b> để giữ khoảng cách: <i>le ministre aurait démissionné</i> = Bộ trưởng <b>được cho là</b> đã từ chức." },
  cards: [["force est de constater que", "one has to admit that", "Force est de constater que rien n'a changé.", "One has to admit nothing has changed."], ["il se pourrait que", "it might be that (+ subj.)", "Il se pourrait qu'il pleuve.", "It might rain."], ["il n'est pas exclu que", "it cannot be ruled out that", "Il n'est pas exclu qu'elle démissionne.", "Her resignation can't be ruled out."], ["vraisemblablement", "in all likelihood", "Il viendra vraisemblablement demain.", "He'll most likely come tomorrow."], ["à en croire", "if we are to believe", "À en croire la presse, tout va bien.", "If we believe the press, all is well."], ["dans une large mesure", "to a large extent", "C'est dans une large mesure vrai.", "It's largely true."], ["à bien des égards", "in many respects", "À bien des égards, il a raison.", "In many respects, he's right."], ["il conviendrait de", "it would be advisable to", "Il conviendrait de vérifier ces chiffres.", "These figures ought to be checked."]],
  sent: [["Force est de constater que les inégalités se creusent.", "One has to admit that inequality is widening."], ["Il n'est pas exclu que la réunion soit reportée.", "The meeting may well be postponed."], ["D'après certains experts, la croissance ralentirait l'an prochain.", "According to some experts, growth would slow next year."], ["Il ne fait aucun doute que le numérique a transformé l'école.", "There's no doubt digital technology has transformed schools."], ["Dans une certaine mesure, cette critique est fondée.", "To some extent, this criticism is justified."], ["On pourrait objecter que le coût est trop élevé.", "One could object that the cost is too high."], ["Il conviendrait de nuancer ce constat.", "This observation should be qualified."], ["À en croire les sondages, l'opinion serait divisée.", "If the polls are to be believed, opinion is divided."], ["Ce modèle est, à bien des égards, une réussite.", "This model is in many respects a success."], ["Il semblerait que la tendance s'inverse.", "It would seem the trend is reversing."]],
  nat: [["Il se pourrait qu'il ait raison.", "Il se pourrait qu'il a raison.", "Il se pourrait que + subjunctive."], ["Force est de constater que c'est un échec.", "Force est de constater que ce soit un échec.", "Force est de constater que + indicative."], ["Le suspect aurait quitté le pays.", "Le suspect aura quitté le pays selon on.", "Distance: journalistic conditional."], ["Il conviendrait de vérifier.", "Il conviendra de vérifier peut-être que.", "Attenuation: conditional."]],
  mcq: [["___ que les objectifs n'ont pas été atteints.", "Force est de constater", ["Il se pourrait", "Il n'est pas exclu", "Il semble"], "Firm statement + indicative."], ["Il n'est pas exclu que le prix ___.", "augmente", ["augmentera", "augmente-t-il", "augmentait"], "+ subjunctive."], ["Selon le journal, l'entreprise ___ 200 emplois.", "supprimerait", ["supprimera", "supprime", "supprimât"], "Unconfirmed report: conditional."], ["Cette analyse est ___ pertinente, mais incomplète.", "dans une large mesure", ["force est de", "il se pourrait", "à en croire"], "Qualifying."]],
  gap: [["Il se ___ que nous changions de stratégie.", "pourrait", "pouvoir", "We might change strategy.", ["peut que", "pourra", "pouvait"]], ["___ est de constater que la réforme a échoué.", "Force", "", "One has to admit the reform failed.", ["Il", "Fort", "Forcé"]], ["À en ___ les experts, la crise sera courte.", "croire", "", "If the experts are to be believed, the crisis will be short.", ["croyant", "crois", "cru"]], ["Il ___ de vérifier ces sources.", "conviendrait", "convenir", "These sources ought to be checked.", ["convient que", "convenait", "conviendra que"]], ["D'après la police, le voleur ___ entré par le toit.", "serait", "être", "According to the police, the thief got in through the roof.", ["sera", "est", "soit"]], ["À bien des ___, ce projet est exemplaire.", "égards", "", "In many respects, this project is exemplary.", ["regards", "points", "fois"]]],
  fix: [["Il se pourrait qu'il viendra.", "viendra", "vienne", "Il se pourrait que + subjunctive.", ["vient", "viendrait"]], ["Force est de constater que la situation soit grave.", "soit", "est", "A firm statement → indicative.", ["sera", "serait"]], ["Selon les médias, le ministre a démissionné, mais rien n'est confirmé.", "a démissionné", "aurait démissionné", "Unconfirmed → conditionnel journalistique.", ["démissionnera", "démissionnait"]]],
  xf: [["Distance yourself from the source.", "Selon la presse, le festival est annulé.", "Selon la presse, le festival serait annulé."], ["Make it firmer.", "Il semble que la mesure a échoué.", "Force est de constater que la mesure a échoué.|Il ne fait aucun doute que la mesure a échoué."]],
  chat: [["Le directeur va vraiment partir ?", "Rien n'est officiel, mais il n'est pas exclu qu'il parte en juin.", ["Il n'est pas exclu qu'il partira.", "Il est exclu qu'il part."], "Il n'est pas exclu que + subjunctive."], ["Que dit le document 2 sur le télétravail ?", "Selon l'auteur, le télétravail renforcerait l'isolement des jeunes salariés.", ["Je pense que le télétravail isole.", "Le télétravail isole, c'est sûr."], "Report a source with distance, not your opinion."]]
});

L({ id: "c1-registres", lvl: "C1", tr: "nuance", cat: "registre", t: "Familier, courant, soutenu", en: "Switching register with control",
  rule: { h: "A C1 speaker understands familiar French and chooses the register that fits the situation.",
    pts: ["<b>Familier</b>: dropped <i>ne</i>, <i>on</i> for nous, <i>ça</i>, slang (<i>bosser, bouffe, truc, mec, nana, kiffer</i>), verlan (<i>ouf = fou, relou = lourd</i>), questions by intonation.", "<b>Courant</b>: complete negation, standard vocabulary, <i>est-ce que</i>.", "<b>Soutenu</b>: inversion (<i>pourriez-vous</i>), precise verbs (<i>se rendre</i> for aller, <i>effectuer</i> for faire), nominalisation, subjunctive and literary tenses.", "Many neutral verbs have a more precise formal equivalent: <i>avoir → disposer de, posséder; dire → affirmer, souligner; voir → constater</i>.", "In the DALF, write in courant-to-soutenu; in the oral, keep a courant register with the jury and avoid slang."],
    ex: [["J'ai pas capté. → Je n'ai pas compris. → Je n'ai pas saisi.", "I didn't get it."], ["On se fait une bouffe ? → On dîne ensemble ? → Vous joindrez-vous à nous pour le dîner ?", "Shall we have dinner?"], ["C'est ouf ! → C'est incroyable ! → C'est stupéfiant.", "It's crazy / incredible / astonishing."], ["Il a dit que… → Il a souligné que…", "He said that… → He stressed that…"]],
    warn: "Using soutenu everywhere sounds pompous; using familier in an exam sounds careless. The skill is to match the situation.",
    vn: "Giống tiếng Việt có văn nói, văn viết và văn trang trọng (ví dụ: <b>ăn – dùng bữa – xơi</b>). Ở C1, người chấm đánh giá khả năng <b>chọn đúng giọng văn</b>." },
  cards: [["bosser", "to work (fam.)", "Je bosse ce week-end.", "I'm working this weekend."], ["un truc", "a thing (fam.)", "C'est quoi, ce truc ?", "What's this thing?"], ["kiffer", "to love (fam.)", "Je kiffe ce quartier.", "I love this area."], ["ouf (verlan)", "crazy (fou)", "Ce concert était ouf !", "That concert was crazy!"], ["se rendre", "to go (formal)", "Je me rendrai à Lyon lundi.", "I'll go to Lyon on Monday."], ["effectuer", "to carry out (formal)", "Effectuer un paiement.", "To make a payment."], ["disposer de", "to have (formal)", "Nous disposons de deux salles.", "We have two rooms available."], ["constater", "to observe, to note", "On constate une baisse.", "A fall is observed."]],
  sent: [["T'as vu l'heure ? Faut qu'on y aille.", "Have you seen the time? We've got to go."], ["Il faut que nous partions, il est tard.", "We must leave, it's late."], ["Nous sommes contraints de prendre congé, l'heure étant avancée.", "We are obliged to take our leave, the hour being late."], ["Ce boulot me prend la tête.", "This job is doing my head in."], ["Ce travail est particulièrement éprouvant.", "This work is particularly demanding."], ["J'ai la flemme de sortir ce soir.", "I can't be bothered to go out tonight."], ["Je me rendrai à la réunion dès que possible.", "I will go to the meeting as soon as possible."], ["Vous pouvez effectuer le paiement en ligne.", "You can make the payment online."], ["On constate une nette amélioration des résultats.", "A clear improvement in results can be seen."], ["Le rapport souligne la nécessité d'agir.", "The report stresses the need to act."]],
  nat: [["(to a jury) Je n'ai pas bien compris la question.", "(to a jury) J'ai pas capté la question.", "Oral exam: courant register at least."], ["(to a friend) On se fait un ciné ?", "(to a friend) Vous joindrez-vous à moi pour une séance de cinéma ?", "Too formal for a friend."], ["(report) On observe une hausse des prix.", "(report) Les prix ont grave augmenté.", "Report: no slang."], ["(e-mail to HR) Je me permets de vous relancer.", "(e-mail to HR) Je vous relance, hein.", "Professional register."]],
  mcq: [["Soutenu for « aller à Paris »:", "se rendre à Paris", ["filer à Paris", "monter à Paris en vitesse", "bouger sur Paris"], "Se rendre = to go (formal)."], ["Familier for « travailler »:", "bosser", ["œuvrer", "effectuer", "se consacrer"], "Bosser is familier."], ["In a report, « Le document dit que… » is better as:", "Le document souligne que…", ["Le document balance que…", "Le doc fait que…", "Le document cause que…"], "A precise reporting verb."], ["« C'est relou » means:", "c'est pénible", ["c'est génial", "c'est rouge", "c'est loin"], "Relou = lourd (verlan), annoying."]],
  gap: [["Je me ___ à votre bureau demain matin. (go, formal)", "rendrai", "se rendre", "I'll come to your office tomorrow morning.", ["rends", "irais", "bougerai"]], ["Nous ___ de trois salles de réunion. (have, formal)", "disposons", "disposer", "We have three meeting rooms.", ["avons dispo", "possédez", "disposez"]], ["J'ai pas le temps, je ___ toute la journée. (fam.)", "bosse", "bosser", "I don't have time, I'm working all day.", ["œuvre", "effectue", "travail"]], ["L'auteur ___ l'importance de l'éducation. (stresses)", "souligne", "souligner", "The author stresses the importance of education.", ["dit grave", "cause", "balance"]], ["Vous pouvez ___ votre réservation en ligne. (make, formal)", "effectuer", "", "You can make your booking online.", ["faire genre", "bosser", "kiffer"]], ["On ___ une baisse du chômage. (observe)", "constate", "constater", "A fall in unemployment is observed.", ["capte", "kiffe", "voit genre"]]],
  fix: [["(DALF essay) Les réseaux sociaux, c'est trop relou pour les ados.", "c'est trop relou pour les ados", "posent de réels problèmes aux adolescents", "An essay needs a courant-to-soutenu register.", ["c'est grave nul pour les ados", "c'est relou pour les jeunes"]], ["(e-mail to a client) Salut, je vous envoie le truc.", "Salut, je vous envoie le truc.", "Bonjour, je vous envoie le document.", "A client e-mail: no salut, no truc.", ["Coucou, je vous envoie le truc.", "Salut, voici le machin."]], ["(oral exam) Bah, j'sais pas trop, en fait.", "Bah, j'sais pas trop, en fait.", "C'est une question complexe ; permettez-moi d'y réfléchir.", "Oral exam: avoid fillers and dropped ne.", ["Euh, j'sais pas.", "Bof, aucune idée."]]],
  xf: [["Make it courant.", "J'ai pas pigé ce qu'il a dit.", "Je n'ai pas compris ce qu'il a dit."], ["Make it soutenu.", "On a fait une enquête.", "Nous avons effectué une enquête.|Nous avons mené une enquête."]],
  chat: [["(A friend, by text) Ce soir resto ?", "Carrément ! On se retrouve à 20 h ?", ["Je me joindrai volontiers à vous pour le dîner.", "Nous effectuerons ce dîner."], "A friend: familier is natural."], ["(The jury) Pouvez-vous préciser votre position ?", "Bien sûr. Je considère que cette mesure, bien qu'utile, reste insuffisante.", ["Ben, c'est pas mal, mais bof.", "Ouais, c'est ouf mais relou."], "Exam: courant to soutenu."]]
});

L({ id: "c1-lexique", lvl: "C1", tr: "nuance", cat: "lexique", t: "Le mot juste", en: "Replacing faire, dire, avoir, il y a and chose",
  rule: { h: "C1 writing replaces general words with precise ones: the examiner counts 'étendue du vocabulaire'.",
    pts: ["<b>Faire</b> → <i>effectuer (un paiement), mener (une enquête), réaliser (un projet), commettre (une erreur), prononcer (un discours)</i>.", "<b>Dire</b> → <i>affirmer, souligner, rappeler, préciser, avancer, déclarer, reconnaître</i>.", "<b>Avoir</b> → <i>posséder, disposer de, présenter (un avantage), connaître (une croissance), comporter</i>.", "<b>Il y a</b> → <i>on observe, on constate, il existe, figurer, se trouver</i>.", "<b>Chose / problème</b> → <i>élément, aspect, phénomène, enjeu, difficulté, défi, obstacle</i>."],
    ex: [["Le gouvernement a mené une vaste réforme.", "The government carried out a sweeping reform."], ["L'auteure souligne que l'école reproduit les inégalités.", "The author stresses that school reproduces inequality."], ["Cette méthode présente plusieurs avantages.", "This method has several advantages."], ["L'enjeu principal reste le financement.", "The main issue remains funding."]],
    warn: "Each precise verb has its own construction: <i>souligner que, rappeler que, mettre l'accent sur, insister sur</i>. Learn them with their preposition.",
    vn: "Giống trong tiếng Việt học thuật, thay <b>«làm», «nói», «có»</b> bằng từ chính xác hơn (<b>tiến hành, nhấn mạnh, sở hữu</b>). Trong DALF, sự đa dạng từ vựng chiếm nhiều điểm." },
  cards: [["mener", "to carry out, to lead", "Mener une enquête, une politique.", "To carry out a survey, a policy."], ["réaliser", "to carry out, to achieve", "Réaliser un projet ambitieux.", "To carry out an ambitious project."], ["souligner", "to stress", "Il souligne l'urgence de la situation.", "He stresses the urgency of the situation."], ["avancer", "to put forward", "L'auteur avance plusieurs arguments.", "The author puts forward several arguments."], ["présenter", "to have, to show (advantages)", "Ce choix présente des risques.", "This choice involves risks."], ["connaître", "to experience (growth)", "Le secteur connaît une forte croissance.", "The sector is experiencing strong growth."], ["un enjeu", "an issue, what is at stake", "L'enjeu est considérable.", "The stakes are considerable."], ["un défi", "a challenge", "Relever un défi.", "To take up a challenge."]],
  sent: [["Les chercheurs ont mené une étude sur deux mille élèves.", "The researchers carried out a study of two thousand pupils."], ["La ville a réalisé d'importants travaux de rénovation.", "The city has carried out major renovation work."], ["Le rapport rappelle que l'accès à l'eau est un droit.", "The report recalls that access to water is a right."], ["Cette solution présente l'avantage d'être peu coûteuse.", "This solution has the advantage of being inexpensive."], ["Le tourisme connaît une reprise depuis deux ans.", "Tourism has been recovering for two years."], ["On observe une hausse du nombre d'étudiants étrangers.", "An increase in the number of foreign students is observed."], ["L'auteure reconnaît que son étude comporte des limites.", "The author acknowledges that her study has limitations."], ["La formation continue constitue un enjeu majeur pour les entreprises.", "Continuing education is a major issue for companies."], ["Le principal obstacle demeure le manque de financement.", "The main obstacle remains the lack of funding."], ["Il a commis une erreur de jugement.", "He made an error of judgement."]],
  nat: [["Mener une enquête", "Faire une enquête… et faire un rapport sur la chose", "Precise verbs and nouns."], ["Il a commis une erreur.", "Il a réalisé une erreur.", "Commettre une erreur."], ["Le secteur connaît une croissance rapide.", "Le secteur a une croissance rapide qui est là.", "Connaître une croissance."], ["L'auteur souligne que…", "L'auteur souligne sur le fait que…", "Souligner que (no sur)."]],
  mcq: [["___ une politique de réduction des déchets", "mener", ["faire faire", "commettre", "prononcer"], "Mener une politique."], ["___ un discours", "prononcer", ["effectuer", "mener", "commettre"], "Prononcer un discours."], ["Le marché ___ une baisse depuis 2024.", "connaît", ["a eu", "commet", "souligne"], "Connaître une baisse."], ["L'auteur ___ trois arguments.", "avance", ["fait", "commet", "connaît"], "Avancer des arguments."]],
  gap: [["Il faut ___ un paiement avant le 10. (make, formal)", "effectuer", "", "A payment must be made before the 10th.", ["commettre", "mener", "prononcer"]], ["La directrice a ___ un discours émouvant.", "prononcé", "prononcer", "The director gave a moving speech.", ["effectué", "mené", "commis"]], ["Le texte ___ que la mesure est temporaire. (specifies)", "précise", "préciser", "The text specifies that the measure is temporary.", ["commet", "connaît", "mène"]], ["Cette méthode ___ plusieurs inconvénients.", "présente|comporte", "", "This method has several drawbacks.", ["commet", "prononce", "effectue"]], ["L'___ principal de ce débat est l'égalité.", "enjeu", "", "The main issue in this debate is equality.", ["en jeu", "jeu", "enjoué"]], ["Il a ___ une grave erreur.", "commis", "commettre", "He made a serious mistake.", ["réalisé", "mené", "effectué"]]],
  fix: [["Le gouvernement a fait une enquête sur le logement.", "a fait", "a mené", "Mener une enquête.", ["a commis", "a prononcé"]], ["Il a réalisé une erreur grave.", "a réalisé", "a commis", "Commettre une erreur.", ["a mené", "a effectué"]], ["L'auteure dit que l'école doit changer.", "dit", "affirme", "A precise reporting verb.", ["fait", "cause"]]],
  xf: [["Replace faire with a precise verb.", "Nous avons fait un projet de formation en ligne.", "Nous avons réalisé un projet de formation en ligne.|Nous avons mené un projet de formation en ligne.|Nous avons conçu un projet de formation en ligne."], ["Replace il y a.", "Il y a une augmentation du chômage.", "On observe une augmentation du chômage.|On constate une augmentation du chômage."]],
  chat: [["Décris ton dernier projet en une phrase, version CV.", "J'ai conçu et piloté un parcours de formation en ligne pour trois cents collaborateurs.", ["J'ai fait un truc en ligne pour des gens.", "J'ai eu un projet de formation."], "Precise verbs: concevoir, piloter."], ["Que dit le document 1 ?", "Il souligne que la sobriété numérique devient un enjeu pour les entreprises.", ["Il dit des choses sur le numérique.", "Il fait que le numérique est un truc."], "Precise reporting verb and noun."]]
});

L({ id: "c1-synthese", lvl: "C1", tr: "methode", cat: "argumentation", t: "La synthèse de documents", en: "DALF C1 written paper, part 1",
  rule: { h: "A synthèse brings together the ideas of several documents, organised by theme, in your own words, with no opinion.",
    pts: ["Length: about <b>220–240 words</b>. Title required. No personal opinion, no information from outside the documents, no quotations.", "Read actively: find the shared theme, each document's main idea, where they agree and where they differ.", "Build a <b>thematic plan</b> (2 or 3 parts), not one paragraph per document: each part crosses the documents.", "Introduction: theme + problem in one or two sentences (and, if you like, the nature of the documents). Conclusion: a short summary, no opinion.", "Reformulate: nominalise, use synonyms, report with distance: <i>selon le document 1, les deux auteurs s'accordent à dire que, à l'inverse, le second texte nuance…</i>"],
    ex: [["Les deux documents s'accordent sur l'essor du télétravail.", "Both documents agree on the rise of remote work."], ["Si le premier texte en souligne les avantages, le second insiste sur ses risques.", "While the first text stresses its advantages, the second insists on its risks."], ["Les auteurs divergent quant aux solutions à envisager.", "The authors differ as to the solutions to consider."], ["En somme, le télétravail apparaît comme une avancée ambivalente.", "In short, remote work appears to be an ambivalent advance."]],
    warn: "The most common mistakes: giving your opinion, copying sentences from the texts, and summarising document 1 then document 2 without linking them.",
    vn: "Synthèse không phải là tóm tắt từng bài. Hãy <b>nhóm ý theo chủ đề</b>, so sánh các tài liệu với nhau, viết <b>bằng lời của mình</b> và <b>không nêu ý kiến cá nhân</b> (ý kiến để dành cho phần essai)." },
  cards: [["s'accorder à dire que", "to agree that", "Les auteurs s'accordent à dire que…", "The authors agree that…"], ["diverger", "to differ", "Les avis divergent sur ce point.", "Opinions differ on this point."], ["quant à", "as for, as to", "Quant au second document, il…", "As for the second document, it…"], ["à l'inverse", "conversely", "À l'inverse, l'article 2 nuance…", "Conversely, article 2 qualifies…"], ["mettre en lumière", "to highlight", "Le texte met en lumière les risques.", "The text highlights the risks."], ["aborder", "to deal with", "Les deux documents abordent la question de…", "Both documents deal with the question of…"], ["si… (opposition)", "while, whereas", "Si le premier se montre optimiste, le second…", "While the first is optimistic, the second…"], ["en somme", "in short", "En somme, il s'agit d'un phénomène complexe.", "In short, it's a complex phenomenon."]],
  sent: [["Les documents proposés abordent la question de la place des écrans à l'école.", "The documents deal with the place of screens in school."], ["Tous deux constatent une hausse rapide de l'usage du numérique.", "Both note a rapid rise in digital use."], ["Si l'article de presse en souligne les bénéfices pédagogiques, l'étude met en garde contre la surexposition.", "While the press article stresses the educational benefits, the study warns against overexposure."], ["Quant aux solutions, les auteurs divergent.", "As for solutions, the authors differ."], ["Le premier document préconise une formation des enseignants.", "The first document recommends teacher training."], ["À l'inverse, le second plaide pour une limitation stricte du temps d'écran.", "Conversely, the second argues for strict limits on screen time."], ["Les deux textes s'accordent toutefois sur la nécessité d'un accompagnement.", "Both texts agree, however, on the need for guidance."], ["En somme, le numérique apparaît comme un outil prometteur mais exigeant.", "In short, digital technology appears to be a promising but demanding tool."], ["Écrans à l'école : promesses et vigilance", "Screens at school: promise and vigilance"], ["Cette question suscite un débat entre partisans et détracteurs.", "This question gives rise to a debate between supporters and critics."]],
  nat: [["Selon le document 1, le télétravail améliore la productivité.", "Je pense que le télétravail améliore la productivité, comme le document 1.", "Synthèse: no personal opinion."], ["Les deux auteurs s'accordent sur ce constat.", "Le document 1 dit ça. Le document 2 dit ça aussi.", "Link the documents and reformulate."], ["Si le premier texte est optimiste, le second se montre réservé.", "Le premier texte est optimiste. Fin du document 1. Document 2 :", "Thematic, not document by document."], ["L'étude met en lumière les risques de l'isolement.", "« Le télétravail isole les salariés », écrit l'auteur.", "No quotations: reformulate."]],
  mcq: [["Which sentence belongs in a synthèse?", "Les deux documents soulignent le coût élevé du projet.", ["À mon avis, ce projet est trop cher.", "Moi, je trouve que c'est cher.", "« Le projet coûte cher », dit l'auteur."], "Objective, reformulated, linking documents."], ["The best plan for a synthèse is…", "thematic, with each part crossing the documents", ["one paragraph per document", "your opinion first, then the documents", "a list of quotations"], "Thematic plan."], ["The expected length of the DALF C1 synthèse is about…", "220–240 words", ["100 words", "500 words", "160 words"], "About 220–240 words."], ["___ au second document, il propose une autre solution.", "Quant", ["Selon", "Si", "Comme"], "Quant à = as for."]],
  gap: [["Les deux auteurs ___ à dire que la situation est préoccupante.", "s'accordent", "s'accorder", "Both authors agree that the situation is worrying.", ["s'accordant", "accordent", "s'accordaient à"]], ["___ le premier document insiste sur les avantages, le second souligne les risques.", "Si", "", "While the first document stresses the advantages, the second stresses the risks.", ["Comme", "Quant", "Puisque"]], ["Les avis ___ sur la question du financement.", "divergent", "diverger", "Opinions differ on the question of funding.", ["divergeant", "diverge", "convergent pas"]], ["___ à l'article 3, il adopte un point de vue économique.", "Quant", "", "As for article 3, it takes an economic point of view.", ["Selon", "Si", "Pour"]], ["L'étude met en ___ les effets de la chaleur sur la santé.", "lumière|évidence", "", "The study highlights the effects of heat on health.", ["lumineux", "valeur de", "clair"]], ["En ___, ce phénomène suscite à la fois espoirs et inquiétudes.", "somme", "", "In short, this phenomenon raises both hopes and fears.", ["sommes", "outre", "effet"]]],
  fix: [["Selon moi, le document 2 a raison.", "Selon moi, le document 2 a raison.", "Le document 2 nuance cette analyse.", "No personal opinion in the synthèse.", ["Je pense que le document 2 a raison.", "Personnellement, j'approuve le document 2."]], ["Le document 1 dit que « les villes étouffent ».", "dit que « les villes étouffent »", "souligne la saturation des villes", "Reformulate; no quotations.", ["écrit « les villes étouffent »", "cite que les villes étouffent"]], ["Document 1 : … Document 2 : …", "Document 1 : … Document 2 : …", "D'une part… d'autre part…", "Build a thematic plan, not a list of documents.", ["Texte 1, texte 2", "Premier doc, deuxième doc"]]],
  xf: [["Rewrite objectively for a synthèse.", "Je trouve, comme l'auteur, que le vélo est génial en ville.", "L'auteur souligne les atouts du vélo en milieu urbain.|Selon l'auteur, le vélo présente de nombreux atouts en ville."], ["Link the two ideas with si (opposition).", "Doc 1: le télétravail libère du temps. Doc 2: il isole.", "Si le premier document souligne que le télétravail libère du temps, le second insiste sur l'isolement qu'il provoque.|Si le premier document montre que le télétravail libère du temps, le second souligne qu'il isole."]],
  chat: [["Comment tu commences ta synthèse ?", "Par une phrase qui présente le thème commun et la problématique, sans donner mon avis.", ["Par mon opinion sur le sujet.", "Par une citation du document 1."], "Introduction: theme + problem."], ["Tu fais un paragraphe par document ?", "Non, je fais un plan thématique qui croise les documents.", ["Oui, c'est plus simple.", "Non, je cite tout."], "Thematic plan."]]
});

L({ id: "c1-essai", lvl: "C1", tr: "methode", cat: "argumentation", t: "L'essai argumenté", en: "DALF C1 written paper, part 2",
  rule: { h: "The essai answers a question linked to the documents with your own structured, nuanced point of view in at least 250 words.",
    pts: ["Read the prompt carefully: the <b>type</b> (article, letter, contribution to a debate) and the <b>addressee</b> decide the register and the layout.", "Introduction: <b>accroche</b> (a fact, a question), <b>problématique</b>, <b>annonce du plan</b>.", "Plans: <b>dialectique</b> (yes / but / so: thèse, antithèse, synthèse) or <b>thématique</b> (several aspects) — choose what the question asks.", "Each paragraph: one idea, an argument, an example; link with transitions (<i>Après avoir vu…, il convient à présent de…</i>).", "Conclusion: answer the question clearly, then an <b>ouverture</b> (a wider question)."],
    ex: [["Faut-il interdire les téléphones portables à l'école ?", "Should mobile phones be banned at school?"], ["Dans quelle mesure le télétravail transforme-t-il notre rapport au travail ?", "To what extent does remote work change our relationship with work?"], ["Après avoir examiné les avantages de cette mesure, il convient d'en mesurer les limites.", "Having examined the advantages of this measure, we should now assess its limits."], ["Reste à savoir si l'école saura s'adapter à ces nouveaux usages.", "It remains to be seen whether schools will adapt to these new practices."]],
    warn: "Unlike the synthèse, the essai <b>must</b> show your opinion — but nuanced, argued and illustrated. Keep at least 250 words.",
    vn: "Essai giống bài nghị luận xã hội: <b>mở bài</b> (dẫn dắt – vấn đề – giới thiệu bố cục), <b>thân bài</b> (2–3 phần có lập luận và dẫn chứng), <b>kết bài</b> (trả lời rõ ràng – mở rộng vấn đề)." },
  cards: [["une accroche", "a hook, an opening", "Commencer par une accroche frappante.", "Start with a striking hook."], ["la problématique", "the central question", "Formuler une problématique claire.", "Formulate a clear central question."], ["annoncer le plan", "to announce the plan", "Nous verrons d'abord…, puis…", "We'll first see…, then…"], ["un plan dialectique", "a thesis–antithesis plan", "Le plan dialectique convient aux questions fermées.", "The dialectical plan suits yes/no questions."], ["il convient de", "it is appropriate to", "Il convient à présent d'examiner…", "We should now examine…"], ["une transition", "a transition", "Une bonne transition résume et annonce.", "A good transition sums up and announces."], ["une ouverture", "an opening (final question)", "Terminer par une ouverture.", "End with a wider question."], ["dans quelle mesure", "to what extent", "Dans quelle mesure faut-il réguler l'IA ?", "To what extent should AI be regulated?"]],
  sent: [["Aujourd'hui, plus de neuf adolescents sur dix possèdent un smartphone.", "Today more than nine teenagers in ten own a smartphone."], ["Dès lors, faut-il bannir le téléphone de l'école ?", "Should phones therefore be banned from school?"], ["Nous verrons d'abord les arguments en faveur d'une interdiction, puis ses limites.", "We'll first look at the arguments for a ban, then its limits."], ["En premier lieu, le téléphone nuit indéniablement à la concentration.", "First, the phone undeniably harms concentration."], ["Cependant, une interdiction totale ne règle pas le problème de fond.", "However, a total ban does not address the underlying problem."], ["Après avoir souligné les risques, il convient d'envisager des solutions.", "Having highlighted the risks, we should consider solutions."], ["C'est pourquoi une éducation au numérique semble plus efficace qu'une interdiction.", "This is why digital education seems more effective than a ban."], ["En définitive, il s'agit moins d'interdire que d'apprendre à bien utiliser.", "Ultimately, it is less about banning than about learning good use."], ["Reste à savoir si les familles joueront le jeu.", "It remains to be seen whether families will play along."], ["Pour illustrer ce point, prenons l'exemple de la Suède.", "To illustrate this point, let's take the example of Sweden."]],
  nat: [["Nous verrons d'abord…, puis nous examinerons…", "Je vais parler de plein de trucs.", "Announce the plan clearly."], ["En définitive, une interdiction partielle semble la plus pertinente.", "En définitive, chacun pense ce qu'il veut.", "Answer the question in the conclusion."], ["Après avoir examiné les avantages, voyons les limites.", "Bon, maintenant les limites.", "A real transition."], ["Reste à savoir si cette solution sera adoptée.", "Fin.", "End with an opening."]],
  mcq: [["The minimum length of the DALF C1 essai is…", "250 words", ["160 words", "100 words", "180 words"], "At least 250 words."], ["Which is a problématique?", "Dans quelle mesure le numérique transforme-t-il l'école ?", ["Le numérique, c'est bien.", "Il y a des écrans à l'école.", "J'aime les tablettes."], "A real question to answer."], ["A plan for « Faut-il… ? » is often…", "dialectique (pour / contre / dépassement)", ["chronologique", "alphabétique", "un paragraphe par document"], "Dialectical plan."], ["The conclusion should…", "answer the question and open the debate", ["introduce a new argument", "copy the introduction", "quote the documents"], "Answer + ouverture."]],
  gap: [["Il ___ à présent d'examiner les limites de cette mesure.", "convient", "convenir", "We should now examine the limits of this measure.", ["conviendrait que", "faut que", "s'agit que"]], ["Après ___ vu les avantages, intéressons-nous aux inconvénients.", "avoir", "", "Having seen the advantages, let's turn to the drawbacks.", ["être", "ayant", "a"]], ["Dans quelle ___ faut-il réguler les réseaux sociaux ?", "mesure", "", "To what extent should social networks be regulated?", ["mesures", "façon que", "point que"]], ["___ à savoir si cette réforme portera ses fruits.", "Reste", "", "It remains to be seen whether this reform will bear fruit.", ["Rester", "Il reste que", "Restons"]], ["En premier ___, rappelons le contexte.", "lieu", "", "First, let's recall the context.", ["lieux", "temps", "place"]], ["Il s'agit moins d'interdire ___ d'éduquer.", "que", "", "It's less about banning than about educating.", ["de", "à", "mais"]]],
  fix: [["Dans ma conclusion, je présente un nouvel argument sur le coût.", "je présente un nouvel argument sur le coût", "je réponds à la question et j'ouvre le débat", "No new argument in the conclusion.", ["je recopie l'introduction", "je cite le document 1"]], ["Je vais parler de plein de choses.", "Je vais parler de plein de choses.", "Nous examinerons d'abord…, puis…", "Announce a clear plan.", ["Je parle de tout.", "On va voir."]], ["Comme le dit le document 2, « les écrans rendent idiots ».", "Comme le dit le document 2, « les écrans rendent idiots ».", "Plusieurs études suggèrent que l'excès d'écrans nuit à l'attention.", "Use your own words and nuance.", ["Les écrans, c'est nul.", "« Idiots », dit le texte."]]],
  xf: [["Turn the topic into a problématique.", "Le télétravail", "Dans quelle mesure le télétravail transforme-t-il notre rapport au travail ?|Le télétravail représente-t-il un progrès pour les salariés ?"], ["Write a transition.", "(part 1: avantages → part 2: limites)", "Après avoir examiné les avantages, il convient d'en mesurer les limites.|Si cette mesure présente des avantages, elle comporte toutefois des limites."]],
  chat: [["Comment tu termines ton essai ?", "Je réponds clairement à la question, puis j'ouvre sur une question plus large.", ["Je donne un nouvel argument.", "Je recopie mon introduction."], "Conclusion: answer + ouverture."], ["Tu donnes ton avis dans l'essai ?", "Oui, contrairement à la synthèse, mais de façon nuancée et argumentée.", ["Non, jamais.", "Oui, sans arguments."], "The essai is where your opinion goes."]]
});

L({ id: "c1-expose", lvl: "C1", tr: "methode", cat: "oral", t: "L'exposé oral et le débat", en: "DALF C1 speaking paper",
  rule: { h: "In one hour you prepare a structured presentation from a set of documents, then defend it in a discussion with the jury.",
    pts: ["Format: preparation <b>1 hour</b>; the exam lasts about <b>30 minutes</b>: a presentation (exposé), then a discussion with the jury.", "Use the documents as a starting point, but build <b>your own</b> problématique and plan; give your point of view.", "Structure out loud: introduction (theme, problématique, plan), two or three parts, conclusion with an ouverture. Signal transitions: <i>j'en viens maintenant à…</i>", "Speak from notes (keywords), not a written text; look at the jury.", "In the discussion: listen, rephrase the question, concede and defend: <i>c'est une remarque pertinente ; je maintiens néanmoins que…</i>"],
    ex: [["Le dossier que j'ai choisi porte sur la place des langues régionales.", "The dossier I chose is about regional languages."], ["Je me demanderai dans quelle mesure l'école doit les enseigner.", "I'll ask to what extent schools should teach them."], ["J'en viens maintenant à ma deuxième partie.", "I now come to my second part."], ["Si je comprends bien votre question, vous me demandez si…", "If I understand your question correctly, you're asking whether…"]],
    warn: "Don't read your notes aloud, and don't summarise the documents one by one: the jury wants your argument.",
    vn: "Phần thi nói C1 giống <b>thuyết trình có phản biện</b>: 1 giờ chuẩn bị, rồi khoảng 30 phút gồm trình bày và trao đổi với hội đồng. Cần <b>bố cục rõ</b>, <b>chuyển ý rõ</b> và giữ quan điểm một cách lịch sự." },
  cards: [["porter sur", "to be about", "Mon exposé porte sur la ville durable.", "My presentation is about the sustainable city."], ["je me demanderai", "I shall ask", "Je me demanderai si…", "I shall ask whether…"], ["j'en viens à", "I now come to", "J'en viens à ma conclusion.", "I now come to my conclusion."], ["c'est une remarque pertinente", "that's a relevant point", "C'est une remarque pertinente, mais…", "That's a fair point, but…"], ["je maintiens que", "I maintain that", "Je maintiens que cette mesure est utile.", "I maintain this measure is useful."], ["si je comprends bien", "if I understand correctly", "Si je comprends bien, vous pensez que…", "If I understand correctly, you think that…"], ["permettez-moi de", "allow me to", "Permettez-moi de nuancer.", "Allow me to qualify that."], ["pour conclure", "to conclude", "Pour conclure, je dirais que…", "To conclude, I would say that…"]],
  sent: [["Le dossier que j'ai choisi traite de l'intelligence artificielle dans l'éducation.", "The dossier I chose deals with AI in education."], ["Dans un premier temps, je présenterai les opportunités ; dans un second temps, les risques.", "First I'll present the opportunities, then the risks."], ["Pour illustrer mon propos, je prendrai l'exemple des plateformes d'apprentissage.", "To illustrate my point, I'll take the example of learning platforms."], ["J'en viens maintenant à ma deuxième partie.", "I now come to my second part."], ["C'est une question intéressante ; permettez-moi d'y réfléchir un instant.", "That's an interesting question; let me think for a moment."], ["Je vous rejoins sur ce point, mais je nuancerais.", "I agree with you on that, but I'd qualify it."], ["Je maintiens toutefois que la formation des enseignants est essentielle.", "I nevertheless maintain that teacher training is essential."], ["Si je comprends bien, vous me demandez si cette solution est réaliste.", "If I understand, you're asking whether this solution is realistic."], ["Pour conclure, je dirais que l'outil ne remplace pas l'enseignant.", "To conclude, I'd say the tool does not replace the teacher."], ["On pourrait aussi se demander quel rôle les parents ont à jouer.", "One could also ask what role parents have to play."]],
  nat: [["J'en viens maintenant à ma deuxième partie.", "Bon, deuxième truc.", "Signal transitions clearly."], ["C'est une remarque pertinente ; je maintiens néanmoins que…", "Non, vous avez tort.", "Concede, then defend politely."], ["Permettez-moi de réfléchir un instant.", "Euh… euh… euh…", "Gain time with a phrase, not fillers."], ["Si je comprends bien, vous me demandez si…", "Hein ? Quoi ?", "Rephrase the question."]],
  mcq: [["Preparation time for the DALF C1 oral is…", "1 hour", ["10 minutes", "30 minutes", "2 hours"], "One hour of preparation."], ["The DALF C1 oral lasts about…", "30 minutes", ["10 minutes", "15 minutes", "1 hour"], "About 30 minutes."], ["Best way to disagree with the jury:", "Je comprends votre point de vue ; je maintiens néanmoins que…", ["Vous avez tort.", "Bof, pas d'accord.", "Ce n'est pas ma question."], "Concede and defend."], ["Announcing a transition:", "J'en viens maintenant à…", ["Bon, ensuite, euh…", "Fin de la partie un.", "Passons, c'est pas important."], "A clear signpost."]],
  gap: [["Mon exposé ___ sur l'avenir des villes.", "porte", "porter", "My presentation is about the future of cities.", ["parle", "traite de", "porte de"]], ["J'en ___ maintenant à ma conclusion.", "viens", "venir", "I now come to my conclusion.", ["vais", "suis", "passe"]], ["C'est une remarque ___ ; néanmoins…", "pertinente", "", "That's a relevant point; however…", ["pertinent", "pertinence", "permanente"]], ["Je ___ que cette solution est la meilleure.", "maintiens", "maintenir", "I maintain that this solution is the best.", ["maintient", "maintenir", "maintenu"]], ["___-moi de nuancer votre propos.", "Permettez", "permettre", "Allow me to qualify your point.", ["Permet", "Permis", "Permettre"]], ["Si je ___ bien, vous pensez que c'est trop cher.", "comprends", "comprendre", "If I understand correctly, you think it's too expensive.", ["comprend", "compris", "comprenne"]]],
  fix: [["Le document 1 dit… Le document 2 dit… Le document 3 dit…", "Le document 1 dit… Le document 2 dit… Le document 3 dit…", "Je me demanderai dans quelle mesure…", "Build your own problématique rather than listing documents.", ["Document 1, document 2, document 3.", "Je vais lire les documents."]], ["Non, vous avez tort, c'est n'importe quoi.", "Non, vous avez tort, c'est n'importe quoi.", "Je comprends votre objection ; je maintiens néanmoins mon point de vue.", "Disagree politely with the jury.", ["Bof, pas d'accord.", "N'importe quoi."]], ["Euh… bah… deuxième partie.", "Euh… bah… deuxième partie.", "J'en viens maintenant à ma deuxième partie.", "Signal transitions clearly.", ["Bon, la suite.", "Euh, après."]]],
  xf: [["Announce a two-part plan.", "(partie 1: avantages ; partie 2: limites)", "Dans un premier temps, j'évoquerai les avantages, puis, dans un second temps, les limites.|Je présenterai d'abord les avantages, puis les limites."], ["Rephrase the jury's question.", "Le jury : « Et le coût, alors ? »", "Si je comprends bien, vous me demandez si cette solution est trop coûteuse.|Si je comprends bien, vous vous interrogez sur le coût."]],
  chat: [["(Jury) Vous ne trouvez pas que votre solution est utopique ?", "C'est une objection légitime ; toutefois, plusieurs villes l'ont déjà mise en œuvre avec succès.", ["Non, c'est vous qui êtes utopique.", "Bof, peut-être."], "Concede, then support with an example."], ["(Jury) Pouvez-vous préciser votre deuxième argument ?", "Bien sûr. Je voulais dire que la formation des enseignants conditionne la réussite du projet.", ["Euh, ben, c'était ça.", "Non, c'est clair."], "Clarify with precision."]]
});

