CO({ id: "co-d1l1", unit: "d1", num: 1, src: "Cosmopolite 3 · Dossier 1 · Leçon 1", t: "Vivre ailleurs ?", en: "Criteria for choosing a city abroad",
  task: "Choisir où s'expatrier et pour quelles raisons", sf: ["Identify criteria for choosing a city", "Report a ranking", "Warn about a social trend"], gram: ["Verbes prépositionnels de l'expatriation"], links: ["b1-y-en", "b1-compar"],
  rule: { h: "Many verbs about moving abroad are followed by à or de: learn them with their preposition.", pts: ["<i>s'adapter à, s'habituer à, s'intégrer à / dans, renoncer à, tenir à</i>", "<i>profiter de, avoir besoin de, s'occuper de, se méfier de, rêver de</i>", "To report a ranking: <i>arriver en tête, se classer en deuxième position, figurer parmi les dix premières</i>."], ex: [["Elle s'est vite habituée à la vie parisienne.", "She quickly got used to Parisian life."], ["Vienne arrive en tête du classement.", "Vienna comes top of the ranking."]] },
  sons: { t: "Liaison et enchaînement", tip: "Link a final consonant to the next vowel: <i>ils ont</i> sounds like « il-zont », <i>une ville agréable</i> like « vi-lagréable ».", ex: ["Ils ont un appartement en ville.", "Elle habite une ville agréable."] },
  cards: [["s'expatrier", "to move abroad", "Beaucoup de jeunes s'expatrient pour travailler.", "Many young people move abroad to work."], ["le coût de la vie", "the cost of living", "Le coût de la vie est élevé à Genève.", "The cost of living is high in Geneva."], ["la qualité de vie", "quality of life", "On y trouve une excellente qualité de vie.", "Quality of life there is excellent."], ["un classement", "a ranking", "Ce classement compare cinquante villes.", "This ranking compares fifty cities."], ["arriver en tête", "to come first", "Montréal arrive en tête pour les étudiants.", "Montreal comes first for students."], ["s'adapter à", "to adapt to", "Il faut du temps pour s'adapter à un nouveau pays.", "It takes time to adapt to a new country."], ["le mal du pays", "homesickness", "Le premier hiver, j'ai eu le mal du pays.", "The first winter, I was homesick."], ["mettre en garde", "to warn", "L'article met en garde contre la hausse des loyers.", "The article warns against rising rents."]],
  sent: [["Le critère le plus important pour moi, c'est la sécurité.", "The most important criterion for me is safety."], ["D'après ce classement, Lisbonne se classe en troisième position.", "According to this ranking, Lisbon is third."], ["Je me suis vite habituée au rythme de la ville.", "I quickly got used to the pace of the city."], ["Attention : les loyers augmentent très vite dans cette ville.", "Careful: rents are rising very fast in this city."], ["Il faut se méfier des annonces trop belles pour être vraies.", "Beware of adverts that are too good to be true."], ["Nous rêvons de vivre près de la mer.", "We dream of living near the sea."], ["Elle a renoncé à partir à cause de son travail.", "She gave up leaving because of her job."], ["Pour bien s'intégrer, il faut parler la langue.", "To fit in well, you need to speak the language."]],
  gap: [["Il s'est bien adapté ___ la vie à Lyon.", "à", "", "He adapted well to life in Lyon.", ["de", "en", "pour"]], ["Nous profitons ___ notre séjour pour visiter le pays.", "de", "", "We're making the most of our stay to visit the country.", ["à", "sur", "par"]], ["Paris arrive en ___ du classement des villes étudiantes.", "tête", "", "Paris comes first in the ranking of student cities.", ["haut", "premier", "début"]]],
  mcq: [["Je me méfie ___ ces offres de logement.", "de", ["à", "pour", "contre"], "Se méfier de."], ["Montréal ___ en deuxième position.", "se classe", ["classe", "arrive à", "se trouve à la"], "Se classer en deuxième position."]],
  nat: [["Elle s'est habituée à son nouveau travail.", "Elle s'est habituée de son nouveau travail.", "S'habituer à."]],
  chat: [["Pourquoi tu as choisi Paris ?", "Pour la qualité de vie culturelle, même si le coût de la vie est élevé.", ["Pour le coût de la vie bas.", "Parce que Paris arrive à la queue."], "Give a criterion and nuance it."], ["Tu t'es adaptée facilement ?", "Oui, assez vite, même si j'ai eu un peu le mal du pays le premier hiver.", ["Oui, je me suis adaptée de Paris.", "Non, j'ai le mal de la ville."], "S'adapter, le mal du pays."]]
});

CO({ id: "co-d1l2", unit: "d1", num: 2, src: "Cosmopolite 3 · Dossier 1 · Leçon 2", t: "Changer de vie", en: "Wishes, intentions and finding a home",
  task: "Choisir le logement idéal pour son expatriation", sf: ["Express wishes and intentions", "Make a polite request", "Describe a home"], gram: ["Le conditionnel présent (1) : demande polie, souhait"], links: ["b1-cond"],
  rule: { h: "Wishes and polite requests use the conditional; intentions use avoir l'intention de, compter, envisager de.", pts: ["Wish: <i>j'aimerais, je voudrais, ça me plairait de</i>.", "Intention: <i>j'ai l'intention de, je compte, j'envisage de, je projette de</i> + infinitive.", "Polite request: <i>pourriez-vous m'envoyer…, auriez-vous…</i>"], ex: [["J'envisage de m'installer à Bordeaux.", "I'm considering settling in Bordeaux."], ["Auriez-vous un deux-pièces avec balcon ?", "Would you have a two-room flat with a balcony?"]] },
  sons: { t: "Liaison et enchaînement", tip: "In polite questions the liaison is clear: <i>pourriez-vous</i>, <i>auriez-vous un</i> (« oriévou-zun »).", ex: ["Auriez-vous un appartement à louer ?", "Nous aimerions habiter en centre-ville."] },
  cards: [["un deux-pièces", "a two-room flat", "Nous cherchons un deux-pièces lumineux.", "We're looking for a bright two-room flat."], ["le loyer", "the rent", "Le loyer est de 1 100 euros charges comprises.", "The rent is 1,100 euros including service charges."], ["les charges", "service charges", "Les charges incluent le chauffage.", "The charges include heating."], ["meublé", "furnished", "C'est un studio meublé.", "It's a furnished studio."], ["le propriétaire", "the landlord", "Le propriétaire habite au rez-de-chaussée.", "The landlord lives on the ground floor."], ["une colocation", "a flatshare", "Elle vit en colocation avec deux amies.", "She lives in a flatshare with two friends."], ["envisager de", "to consider (doing)", "Ils envisagent de changer de vie.", "They're considering changing their life."], ["un dépôt de garantie", "a deposit", "Le dépôt de garantie correspond à un mois de loyer.", "The deposit is one month's rent."]],
  sent: [["J'aimerais vivre dans un quartier calme mais animé le soir.", "I'd like to live in a quiet area that's lively in the evening."], ["Nous avons l'intention de quitter Paris d'ici deux ans.", "We intend to leave Paris within two years."], ["Pourriez-vous m'indiquer le montant des charges ?", "Could you tell me how much the charges are?"], ["Je voudrais visiter l'appartement samedi matin.", "I'd like to see the flat on Saturday morning."], ["L'appartement est au quatrième étage sans ascenseur.", "The flat is on the fourth floor without a lift."], ["Ça me plairait d'avoir un petit jardin.", "I'd love to have a little garden."], ["Le logement est disponible à partir du 1er mars.", "The flat is available from 1 March."], ["Il compte s'installer à la campagne.", "He plans to settle in the countryside."]],
  gap: [["Je ___ visiter l'appartement demain, si c'est possible.", "voudrais|souhaiterais|aimerais", "vouloir", "I'd like to visit the flat tomorrow, if possible.", ["veux bien que", "voudrai", "voulais"]], ["Nous avons l'___ de déménager en été.", "intention", "", "We intend to move in the summer.", ["intentionné", "idée que", "envie que"]], ["Le loyer est de 900 euros, ___ comprises.", "charges", "", "The rent is 900 euros, charges included.", ["frais", "taxes", "loyers"]]],
  mcq: [["___-vous un studio meublé ?", "Auriez", ["Aurez", "Avez-vous eu", "Aviez"], "Polite request: conditional."], ["Ils ___ de changer de vie.", "envisagent", ["envisagent à", "comptent de", "projettent à"], "Envisager de + infinitive."]],
  nat: [["Je compte partir en mai.", "Je compte de partir en mai.", "Compter + infinitive, no de."]],
  chat: [["Agence Lumière, bonjour. Je peux vous aider ?", "Bonjour, je cherche un deux-pièces meublé ; auriez-vous quelque chose dans le 11e ?", ["Donnez-moi un appartement.", "Je veux un appart, vite."], "Polite request with the conditional."], ["Qu'est-ce que vous feriez si vous changiez de vie ?", "J'aimerais ouvrir une petite librairie-café au bord de la mer.", ["J'aimerai ouvrir hier une librairie.", "J'ouvre une librairie."], "A wish: conditional."]]
});

CO({ id: "co-d1l3", unit: "d1", num: 3, src: "Cosmopolite 3 · Dossier 1 · Leçon 3", t: "Vivre une ville", en: "Describing a place, advice and hypotheses",
  task: "Agir pour sa ville", sf: ["Characterise a place", "Give advice", "Describe a hypothetical situation"], gram: ["La place de l'adjectif", "Le conditionnel présent (2) : conseil, hypothèse, proposition"], links: ["b1-cond", "b1-si"],
  rule: { h: "Most adjectives follow the noun; a few short, common ones go before it.", pts: ["After: colour, shape, nationality, long adjectives: <i>une rue piétonne, un quartier vivant, une place animée</i>.", "Before: <i>beau, joli, grand, petit, bon, mauvais, jeune, vieux, nouveau, gros</i> — <i>un joli parc, une vieille maison</i>.", "Some change meaning: <i>un ancien quartier</i> (former) / <i>un quartier ancien</i> (old); <i>un grand homme</i> (great) / <i>un homme grand</i> (tall)."], ex: [["C'est un petit quartier animé.", "It's a small lively area."], ["Si j'étais maire, je créerais des rues piétonnes.", "If I were mayor, I'd create pedestrian streets."]] },
  sons: { t: "Le français familier à l'oral", tip: "In casual speech, <i>il y a</i> becomes « y'a », <i>tu es</i> becomes « t'es », and <i>ne</i> disappears: « J'sais pas ». Understand it; don't write it in the exam.", ex: ["Y'a plein de monde dans ce quartier.", "T'as vu le nouveau marché ?"] },
  cards: [["un quartier", "a neighbourhood", "Le quartier est très vivant le soir.", "The area is very lively in the evening."], ["une rue piétonne", "a pedestrian street", "La rue piétonne est pleine de cafés.", "The pedestrian street is full of cafés."], ["animé", "lively", "La place est animée le samedi.", "The square is lively on Saturdays."], ["les espaces verts", "green spaces", "La ville manque d'espaces verts.", "The city lacks green spaces."], ["un habitant", "a resident", "Les habitants ont voté pour le projet.", "The residents voted for the project."], ["la mairie", "the town hall", "La mairie organise une réunion publique.", "The town hall is holding a public meeting."], ["les transports en commun", "public transport", "Les transports en commun sont efficaces.", "Public transport is efficient."], ["le cadre de vie", "living environment", "Le cadre de vie s'est beaucoup amélioré.", "The living environment has improved a lot."]],
  sent: [["Mon quartier est petit, calme et très vert.", "My area is small, quiet and very green."], ["À ta place, je choisirais un logement près du métro.", "If I were you, I'd choose a flat near the metro."], ["On pourrait créer un jardin partagé dans la cour.", "We could create a shared garden in the courtyard."], ["Si la ville était plus verte, les habitants seraient plus heureux.", "If the city were greener, residents would be happier."], ["Il y a une jolie place avec un marché le dimanche.", "There's a pretty square with a market on Sundays."], ["Tu devrais aller voir le vieux port au coucher du soleil.", "You should go and see the old port at sunset."], ["Ce serait bien d'avoir plus de pistes cyclables.", "It would be good to have more cycle lanes."], ["La mairie devrait rénover les vieilles maisons du centre.", "The town hall should renovate the old houses in the centre."]],
  gap: [["C'est une ___ maison avec un grand jardin.", "belle|jolie|vieille|petite", "", "It's a beautiful house with a big garden.", ["maison belle", "beau", "bel"]], ["Si j'étais maire, je ___ plus de parcs.", "créerais", "créer", "If I were mayor, I'd create more parks.", ["créerai", "crée", "créais"]], ["Tu ___ prendre le vélo, c'est plus rapide.", "devrais", "devoir", "You should take the bike, it's quicker.", ["devras", "dois avoir", "devait"]]],
  mcq: [["Which is correct?", "un quartier animé", ["un animé quartier", "un quartier animée", "une quartier animé"], "Most adjectives follow the noun."], ["« un ancien quartier » means…", "a former neighbourhood", ["an old-fashioned area", "a very old area", "an elderly area"], "Before the noun, ancien = former."]],
  nat: [["Il habite dans une vieille maison.", "Il habite dans une maison vieille.", "Vieux/vieille goes before the noun."]],
  chat: [["Qu'est-ce qu'on pourrait faire pour améliorer notre rue ?", "On pourrait installer des bancs et planter des arbres.", ["On peut hier planter.", "On pourrait des arbres."], "Proposal: on pourrait + infinitive."], ["Tu me conseilles quel quartier ?", "À ta place, je choisirais le Marais : c'est vivant et bien desservi.", ["À ta place, je choisirai le Marais.", "Je te conseille que le Marais."], "Advice with à ta place + conditional."]]
});

CO({ id: "co-d1l4", unit: "d1", num: 4, src: "Cosmopolite 3 · Dossier 1 · Leçon 4", t: "Invitation au voyage", en: "Memories of arriving in a new city",
  task: "Imaginer son arrivée dans une ville étrangère", sf: ["Describe memories", "Describe your arrival in a foreign city"], gram: ["Les pronoms où et dont"], links: ["b1-relatifs", "b1-pc-imp"],
  rule: { h: "Où gives the place or time; dont replaces de + noun.", pts: ["<i>La ville où je suis arrivée, le jour où nous nous sommes rencontrés</i>.", "<i>Le quartier dont je me souviens</i> (se souvenir de), <i>la rue dont tu m'as parlé</i> (parler de).", "Memories: <i>je me souviens de…, je n'oublierai jamais…, ce qui m'a frappée, c'est…</i>"], ex: [["Je me souviens du jour où je suis arrivée à Paris.", "I remember the day I arrived in Paris."], ["C'est un voyage dont je garde un souvenir merveilleux.", "It's a trip I have wonderful memories of."]] },
  sons: { t: "Le français familier à l'oral", tip: "Listen for dropped sounds: <i>je suis</i> → « chuis », <i>il y avait</i> → « y'avait ».", ex: ["Je suis arrivée un dimanche, il y avait du soleil.", "Je ne savais pas où aller."] },
  cards: [["se souvenir de", "to remember", "Je me souviens de mon premier jour.", "I remember my first day."], ["un souvenir", "a memory", "C'est un très bon souvenir.", "It's a very good memory."], ["frapper", "to strike (impress)", "Ce qui m'a frappée, c'est le silence.", "What struck me was the silence."], ["dépaysé", "disoriented, in a new world", "Je me sentais complètement dépaysée.", "I felt completely out of my element."], ["se repérer", "to find one's way", "Au début, je n'arrivais pas à me repérer.", "At first I couldn't find my way around."], ["l'accueil", "the welcome", "L'accueil des habitants était chaleureux.", "The residents' welcome was warm."], ["une valise", "a suitcase", "J'avais deux valises et beaucoup d'espoir.", "I had two suitcases and a lot of hope."], ["la nostalgie", "nostalgia", "J'y pense avec un peu de nostalgie.", "I think about it with a little nostalgia."]],
  sent: [["Je me souviens très bien du jour où je suis arrivée à Paris.", "I remember the day I arrived in Paris very well."], ["Il faisait froid et je ne connaissais personne.", "It was cold and I didn't know anyone."], ["Ce qui m'a frappée, c'est la beauté des immeubles.", "What struck me was the beauty of the buildings."], ["C'est la ville dont je rêvais depuis mon enfance.", "It's the city I'd dreamt of since childhood."], ["Le café où j'ai pris mon premier croissant existe toujours.", "The café where I had my first croissant still exists."], ["Au début, je me perdais tout le temps dans le métro.", "At first I kept getting lost in the metro."], ["Je n'oublierai jamais l'accueil de ma voisine.", "I'll never forget my neighbour's welcome."], ["J'étais à la fois excitée et un peu perdue.", "I was both excited and a bit lost."]],
  gap: [["C'est le quartier ___ j'ai habité la première année.", "où", "", "It's the area where I lived the first year.", ["dont", "que", "qui"]], ["C'est un voyage ___ je me souviendrai toute ma vie.", "dont", "", "It's a trip I'll remember all my life.", ["où", "que", "qui"]], ["Le jour ___ je suis arrivée, il pleuvait.", "où", "", "The day I arrived, it was raining.", ["que", "dont", "quand que"]]],
  mcq: [["La ville ___ tu parles est magnifique.", "dont", ["où", "que", "de laquelle que"], "Parler de → dont."], ["Je me souviens ___ mon arrivée.", "de", ["à", "que", "sur"], "Se souvenir de."]],
  nat: [["Le jour où je suis arrivée, il neigeait.", "Le jour que je suis arrivée, il neigeait.", "With a time noun: où."]],
  chat: [["Qu'est-ce qui t'a marquée en arrivant en France ?", "Ce qui m'a frappée, c'est que les magasins fermaient tôt le dimanche.", ["Ce que m'a frappée, c'est…", "Ça m'a frappé hier dimanche."], "Ce qui m'a frappée, c'est…"], ["Tu te souviens de ton premier repas ici ?", "Oui ! C'est un dîner dont je garde un souvenir très drôle.", ["Oui, c'est un dîner où je garde un souvenir.", "Oui, je me souviens à ce dîner."], "Garder un souvenir de → dont."]]
});

CO({ id: "co-d2l1", unit: "d2", num: 1, src: "Cosmopolite 3 · Dossier 2 · Leçon 1", t: "Les problèmes du quotidien", en: "Feelings, complaints and solving problems",
  task: "Partager des situations problématiques du quotidien vécues à l'étranger", sf: ["Express feelings", "Understand a complaint", "Solve a problem"], gram: ["Le subjonctif pour exprimer des sentiments", "Les structures de la lettre de réclamation"], links: ["b1-subj", "b2-lettre"],
  rule: { h: "Feeling + que + subjunctive when the subject changes; de + infinitive when it's the same.", pts: ["<i>Je suis déçue que le colis ne soit pas arrivé. — Je suis déçue d'attendre si longtemps.</i>", "Discontent: <i>c'est inadmissible, j'en ai assez de, ça m'agace que…</i>", "Complaint letter: <i>je me permets de vous signaler…, je vous demande de bien vouloir…, sans réponse de votre part…</i>"], ex: [["Ça m'agace que le bus soit toujours en retard.", "It annoys me that the bus is always late."], ["Je vous demande de bien vouloir me rembourser.", "I ask you to kindly refund me."]] },
  sons: { t: "L'accent d'insistance", tip: "To insist, French stresses the first syllable of a word with emotion: « c'est IN-admissible ! », « c'est AB-solument faux ».", ex: ["C'est inadmissible !", "C'est absolument incroyable !"] },
  cards: [["être déçu", "to be disappointed", "Je suis déçue que tu ne viennes pas.", "I'm disappointed you're not coming."], ["agacer", "to annoy", "Ça m'agace d'attendre.", "Waiting annoys me."], ["en avoir assez", "to be fed up", "J'en ai assez de ce bruit !", "I'm fed up with this noise!"], ["inadmissible", "unacceptable", "Ce retard est inadmissible.", "This delay is unacceptable."], ["une réclamation", "a complaint", "J'ai fait une réclamation en ligne.", "I filed a complaint online."], ["un colis", "a parcel", "Mon colis n'est jamais arrivé.", "My parcel never arrived."], ["une panne", "a breakdown", "La machine à laver est en panne.", "The washing machine has broken down."], ["un remboursement", "a refund", "J'ai obtenu un remboursement.", "I got a refund."]],
  sent: [["Je suis vraiment déçue que la livraison soit encore en retard.", "I'm really disappointed the delivery is late again."], ["Ça m'énerve que personne ne réponde au téléphone.", "It annoys me that nobody answers the phone."], ["J'en ai assez de faire la queue pendant des heures.", "I'm fed up with queuing for hours."], ["Je me permets de vous signaler un problème de chauffage.", "I'm writing to report a heating problem."], ["Je vous demande de bien vouloir remplacer l'appareil.", "I ask you to kindly replace the appliance."], ["Je suis contente que le problème soit enfin réglé.", "I'm glad the problem is finally solved."], ["Le service client m'a proposé un geste commercial.", "Customer service offered me a goodwill gesture."], ["Sans réponse de votre part, je contacterai une association de consommateurs.", "Without a reply from you, I'll contact a consumer association."]],
  gap: [["Je suis déçue que le magasin ___ fermé.", "soit", "être", "I'm disappointed the shop is closed.", ["est", "sera", "était"]], ["Ça m'agace qu'il ne ___ jamais à l'heure.", "vienne", "venir", "It annoys me he never comes on time.", ["vient", "viendra", "venait"]], ["Je vous demande de bien ___ me rembourser.", "vouloir", "", "I ask you to kindly refund me.", ["voulez", "voulu", "vouloir de"]]],
  mcq: [["Je suis triste ___ partir.", "de", ["que", "à", "pour que"], "Same subject → de + infinitive."], ["Formal complaint opening:", "Je me permets de vous signaler un problème.", ["J'en ai marre de vous !", "Salut, ça marche pas.", "Vous êtes nuls."], "Formal register."]],
  nat: [["Je suis contente que tu sois là.", "Je suis contente que tu es là.", "Feeling → subjunctive."]],
  chat: [["Allô, service client, bonjour.", "Bonjour, je vous appelle parce que mon colis n'est toujours pas arrivé.", ["Mon colis, où il est ?!", "Je suis déçue que mon colis est arrivé."], "Explain the problem calmly."], ["Comment ça s'est passé avec ton propriétaire ?", "Je suis soulagée qu'il ait enfin réparé le chauffage.", ["Je suis soulagée qu'il a réparé.", "Je suis soulagée de il répare."], "Feeling + subjunctive (past)."]]
});

CO({ id: "co-d2l2", unit: "d2", num: 2, src: "Cosmopolite 3 · Dossier 2 · Leçon 2", t: "Urgence !", en: "Health problems, symptoms and health insurance",
  task: "Réaliser un aide-mémoire pour gérer un problème de santé en France", sf: ["Anticipate and handle a health problem", "Describe symptoms", "Understand health insurance"], gram: ["Exprimer une conséquence"], links: ["b1-cause", "b2-cause"],
  rule: { h: "Consequence: donc, alors, c'est pourquoi, si bien que, du coup (spoken).", pts: ["<i>J'avais de la fièvre, donc je suis allée chez le médecin.</i>", "Health system: <i>la carte Vitale, le médecin traitant, l'ordonnance, la mutuelle, être remboursé</i>.", "Emergencies in France: 15 (SAMU), 18 (pompiers), 112 (European number)."], ex: [["J'ai mal à la gorge depuis trois jours.", "I've had a sore throat for three days."], ["Le médecin m'a fait une ordonnance.", "The doctor wrote me a prescription."]] },
  sons: { t: "L'accent d'insistance", tip: "Under stress, people insist on the first syllable: « j'ai TRÈS mal », « c'est UR-gent ».", ex: ["C'est urgent, s'il vous plaît !", "J'ai terriblement mal au dos."] },
  cards: [["avoir mal à", "to have a pain in", "J'ai mal à la tête.", "I have a headache."], ["la fièvre", "fever", "Il a 39 de fièvre.", "He has a temperature of 39."], ["une ordonnance", "a prescription", "Le pharmacien a besoin de l'ordonnance.", "The pharmacist needs the prescription."], ["le médecin traitant", "the GP (registered doctor)", "J'ai déclaré mon médecin traitant.", "I registered my GP."], ["la carte Vitale", "French health insurance card", "N'oubliez pas votre carte Vitale.", "Don't forget your Vitale card."], ["une mutuelle", "top-up health insurance", "Ma mutuelle rembourse les lunettes.", "My top-up insurance covers glasses."], ["les urgences", "A&E, emergency room", "Elle a passé la nuit aux urgences.", "She spent the night in A&E."], ["un rendez-vous", "an appointment", "J'ai pris rendez-vous en ligne.", "I booked an appointment online."]],
  sent: [["J'ai de la fièvre et je tousse depuis hier soir.", "I've had a fever and a cough since last night."], ["Je voudrais prendre rendez-vous avec le docteur Martin.", "I'd like to make an appointment with Dr Martin."], ["Je me suis tordu la cheville en courant.", "I twisted my ankle while running."], ["Le médecin m'a prescrit des antibiotiques pendant une semaine.", "The doctor prescribed antibiotics for a week."], ["La consultation est remboursée par la Sécurité sociale.", "The consultation is reimbursed by social security."], ["J'avais très mal, donc je suis allée aux urgences.", "I was in a lot of pain, so I went to A&E."], ["En cas d'urgence, appelez le 15.", "In an emergency, call 15."], ["Il faut présenter sa carte Vitale à la pharmacie.", "You must show your Vitale card at the pharmacy."]],
  gap: [["J'ai mal ___ ventre depuis ce matin.", "au", "", "I've had a stomach ache since this morning.", ["à", "du", "de"]], ["J'avais de la fièvre, ___ je suis restée au lit.", "donc|alors|du coup", "", "I had a fever, so I stayed in bed.", ["car", "parce que", "puisque"]], ["Le pharmacien a besoin de votre ___.", "ordonnance", "", "The pharmacist needs your prescription.", ["ordonnement", "ordre", "recette"]]],
  mcq: [["The French emergency medical number is…", "15", ["17", "18", "3615"], "15 = SAMU (medical), 18 = fire brigade, 17 = police, 112 everywhere in Europe."], ["« J'ai mal ___ dents. »", "aux", ["à les", "des", "aux de"], "À + les = aux."]],
  nat: [["J'ai mal à la tête.", "J'ai mal de la tête.", "Avoir mal à."]],
  chat: [["Qu'est-ce qui ne va pas ?", "J'ai mal à la gorge et j'ai un peu de fièvre depuis deux jours.", ["J'ai malade la gorge.", "Je suis mal à la gorge."], "Describe symptoms with avoir mal à."], ["Vous avez votre carte Vitale ?", "Oui, la voici. Et j'ai aussi une mutuelle.", ["Oui, voici ma Vitale mutuelle carte.", "Non, j'ai une ordonnance de Vitale."], "Health system vocabulary."]]
});

CO({ id: "co-d2l3", unit: "d2", num: 3, src: "Cosmopolite 3 · Dossier 2 · Leçon 3", t: "Les démarches administratives", en: "Paperwork, instructions and asking for help",
  task: "Réaliser une fiche-conseil pour les démarches d'installation dans un pays francophone", sf: ["Understand formalities", "Ask for help", "Report what someone said"], gram: ["L'impératif et les pronoms personnels", "Le discours indirect"], links: ["b1-pronoms", "b1-indirect"],
  rule: { h: "In instructions, pronouns follow a positive imperative and precede a negative one.", pts: ["<i>Remplissez-le, envoyez-les-nous, n'oubliez pas de le signer, ne le perdez pas.</i>", "Asking for help: <i>pourriez-vous m'expliquer…, je ne comprends pas ce qu'il faut faire, est-ce que vous pourriez m'aider à…</i>", "Reporting: <i>l'employé m'a dit de revenir lundi / qu'il manquait un document</i>."], ex: [["Remplissez ce formulaire et renvoyez-le avant vendredi.", "Fill in this form and send it back before Friday."], ["Il m'a dit qu'il manquait un justificatif de domicile.", "He told me a proof of address was missing."]] },
  sons: { t: "Les voyelles nasales", tip: "French has three main nasal vowels: <i>an / en</i> [ɑ̃] as in <i>envoyer</i>, <i>on</i> [ɔ̃] as in <i>bon</i>, and <i>in / ain / un</i> [ɛ̃] as in <i>demain</i>. The n itself is not pronounced.", ex: ["Demain, envoyez le dossier complet.", "Un rendez-vous important à onze heures."] },
  cards: [["une démarche", "a procedure, formality", "Les démarches administratives prennent du temps.", "Administrative procedures take time."], ["un justificatif de domicile", "proof of address", "Apportez un justificatif de domicile récent.", "Bring a recent proof of address."], ["remplir un formulaire", "to fill in a form", "Il faut remplir ce formulaire en ligne.", "You must fill in this form online."], ["une pièce d'identité", "an ID document", "Une pièce d'identité est obligatoire.", "An ID document is required."], ["un dossier", "a file, an application", "Mon dossier est incomplet.", "My file is incomplete."], ["ouvrir un compte bancaire", "to open a bank account", "J'ai ouvert un compte bancaire en ligne.", "I opened a bank account online."], ["un délai", "a time limit, waiting time", "Le délai est de trois semaines.", "The processing time is three weeks."], ["un guichet", "a counter (office)", "Adressez-vous au guichet numéro deux.", "Go to counter number two."]],
  sent: [["Remplissez ce formulaire et signez-le en bas de la page.", "Fill in this form and sign it at the bottom of the page."], ["N'oubliez pas de joindre une copie de votre pièce d'identité.", "Don't forget to attach a copy of your ID."], ["Pourriez-vous m'expliquer comment ouvrir un compte bancaire ?", "Could you explain how to open a bank account?"], ["L'employée m'a dit qu'il manquait un document.", "The clerk told me a document was missing."], ["Elle m'a demandé de revenir avec un justificatif de domicile.", "She asked me to come back with a proof of address."], ["Envoyez-nous votre dossier complet avant le 15 mars.", "Send us your complete file before 15 March."], ["Le délai de traitement est d'environ un mois.", "Processing takes about a month."], ["Ne le jetez pas : vous en aurez besoin plus tard.", "Don't throw it away: you'll need it later."]],
  gap: [["Votre dossier ? Envoyez-___ par la poste.", "le", "", "Your file? Send it by post.", ["lui", "y", "en"]], ["Ce document est important : ne ___ perdez pas !", "le", "", "This document is important: don't lose it!", ["lui", "en", "y"]], ["Il m'a dit ___ revenir demain.", "de", "", "He told me to come back tomorrow.", ["que", "à", "si"]]],
  mcq: [["The form? « ___ avant lundi. »", "Renvoyez-le", ["Le renvoyez", "Renvoyez-lui", "Renvoyez-en"], "Positive imperative: verb-le."], ["« Il manque un document. » → Elle m'a dit ___ un document.", "qu'il manquait", ["qu'il manque demain", "si il manquait", "de manquer"], "Reported speech in the past: imparfait."]],
  nat: [["Ne l'oubliez pas.", "N'oubliez-le pas.", "Negative imperative: the pronoun goes before the verb."]],
  chat: [["Il vous manque le justificatif de domicile.", "D'accord, est-ce que je peux vous l'envoyer par e-mail ?", ["D'accord, je peux vous envoyer-le ?", "D'accord, envoyez-moi-le."], "Pronoun order: vous l'envoyer."], ["Qu'est-ce qu'on t'a dit à la banque ?", "On m'a dit de prendre rendez-vous en ligne.", ["On m'a dit que prendre rendez-vous.", "On m'a dit si prendre rendez-vous."], "Reported instruction: dire de + infinitive."]]
});

CO({ id: "co-d2l4", unit: "d2", num: 4, src: "Cosmopolite 3 · Dossier 2 · Leçon 4", t: "Regards de Français à l'étranger", en: "Nuancing tastes, similarities and differences",
  task: "Réaliser une grille d'observation pour découvrir un lieu", sf: ["Nuance your tastes and interest", "Describe similarities and differences"], gram: ["La négation (1) pour nuancer ses goûts"], links: ["b1-negation", "b1-compar"],
  rule: { h: "Nuance your tastes with negations and degree words.", pts: ["<i>Je n'aime pas beaucoup, je ne suis pas très fan de, ça ne me passionne pas, je n'ai rien contre.</i>", "<i>Ne… pas vraiment, ne… pas du tout, ne… plus vraiment, ne… jamais vraiment.</i>", "Similarities and differences: <i>comme, de la même façon que, contrairement à, à la différence de, alors que</i>."], ex: [["Je ne suis pas très fan du fromage fort.", "I'm not a big fan of strong cheese."], ["Contrairement aux Français, les Vietnamiens mangent tôt le soir.", "Unlike the French, Vietnamese people eat dinner early."]] },
  sons: { t: "Les voyelles nasales", tip: "Contrast <i>vin</i> [ɛ̃], <i>vent</i> [ɑ̃] and <i>vont</i> [ɔ̃]: the lips change, the n is silent.", ex: ["Le vin, le vent, ils vont.", "C'est un bon pain de campagne."] },
  cards: [["ne pas être fan de", "not to be keen on", "Je ne suis pas fan de la foule.", "I'm not keen on crowds."], ["ça ne me dit rien", "I don't fancy it", "Le karaoké ? Ça ne me dit rien.", "Karaoke? I don't fancy it."], ["contrairement à", "unlike", "Contrairement à Paris, Saïgon ne dort jamais.", "Unlike Paris, Saigon never sleeps."], ["à la différence de", "unlike, in contrast to", "À la différence de chez nous, on dîne tard ici.", "Unlike at home, people eat late here."], ["de la même façon", "in the same way", "On fête le Nouvel An de la même façon.", "We celebrate New Year in the same way."], ["un point commun", "something in common", "Nos deux pays ont un point commun : la cuisine.", "Our two countries have something in common: food."], ["étonnant", "surprising", "C'est étonnant de voir autant de vélos.", "It's surprising to see so many bikes."], ["s'habituer à", "to get used to", "Je m'habitue aux bises.", "I'm getting used to the cheek kisses."]],
  sent: [["Je n'aime pas vraiment les dîners qui finissent à minuit.", "I don't really like dinners that end at midnight."], ["Le fromage ? Je n'ai rien contre, mais je n'en mange pas beaucoup.", "Cheese? I've nothing against it, but I don't eat much."], ["Contrairement aux Français, nous partageons tous les plats.", "Unlike the French, we share all the dishes."], ["À Paris comme à Saïgon, les gens adorent les terrasses.", "In Paris as in Saigon, people love café terraces."], ["Ce qui m'étonne, c'est qu'on fasse la bise à des inconnus.", "What surprises me is that people kiss strangers on the cheek."], ["Les deux villes ont un point commun : les deux-roues.", "The two cities have something in common: two-wheelers."], ["Je ne suis pas du tout habituée à ce froid.", "I'm not at all used to this cold."], ["À la différence du Viêt Nam, ici les magasins ferment le dimanche.", "Unlike in Vietnam, shops here close on Sundays."]],
  gap: [["Je ne suis pas ___ fan de football.", "très", "", "I'm not a big fan of football.", ["trop de", "beaucoup de", "plus de"]], ["___ à Paris, on mange tard à Madrid.", "Contrairement", "", "Unlike in Paris, people eat late in Madrid.", ["Comme", "Malgré", "Ainsi"]], ["Ça ne me ___ rien d'aller en boîte.", "dit", "dire", "I don't fancy going clubbing.", ["fait", "plaît pas", "dis"]]],
  mcq: [["Which is most nuanced?", "Je n'aime pas beaucoup ça.", ["Je déteste ça !", "Beurk !", "C'est nul."], "A softened dislike."], ["___ chez nous, on enlève ses chaussures en entrant.", "Comme", ["Contrairement", "Malgré", "Bien que"], "A similarity: comme."]],
  nat: [["Je ne suis pas du tout d'accord.", "Je suis pas du tout pas d'accord.", "One negation: ne… pas du tout."]],
  chat: [["Tu aimes les fromages français ?", "Pas tous ! Je ne suis pas très fan des fromages forts, mais j'adore le comté.", ["Je suis pas fan pas.", "J'aime pas rien."], "Nuance with ne… pas très."], ["Qu'est-ce qui est différent au Viêt Nam ?", "Contrairement à la France, on dîne vers dix-huit heures et on partage tous les plats.", ["Contrairement la France…", "Comme à la France, différent."], "Contrairement à + noun."]]
});

CO({ id: "co-d3l1", unit: "d3", num: 1, src: "Cosmopolite 3 · Dossier 3 · Leçon 1", t: "Et si on sortait ?", en: "Outings, figures, advice and proposals",
  task: "Proposer une sortie pour la classe", sf: ["Talk about outings", "Comment on figures", "Advise", "Propose an outing"], gram: ["Les expressions pour conseiller", "La mise en relief"], links: ["b2-relief", "b1-cond"],
  rule: { h: "To propose: et si on + imparfait ? To highlight: c'est… qui/que, ce qui… c'est.", pts: ["<i>Et si on allait au cinéma ? Ça te dirait de… ? On pourrait…</i>", "Advise: <i>je te conseille de, tu devrais, n'hésite pas à, ça vaut le coup de</i>.", "Figures: <i>la moitié, un tiers, un quart, la majorité, 45 % des Français</i>."], ex: [["Et si on allait voir l'exposition samedi ?", "How about going to see the exhibition on Saturday?"], ["Ce que les Français préfèrent, c'est le cinéma.", "What French people prefer is the cinema."]] },
  sons: { t: "Hésitation et interrogation", tip: "Hesitation sounds: <i>euh…, ben…, bah…</i>; a question rises at the end: « On sort ce soir ? »", ex: ["Euh… on pourrait aller au cinéma ?", "Tu viens avec nous ce soir ?"] },
  cards: [["sortir", "to go out", "On sort ce soir ?", "Shall we go out tonight?"], ["une sortie", "an outing", "Une sortie au musée est prévue.", "A museum outing is planned."], ["ça te dirait de", "would you like to", "Ça te dirait de voir un concert ?", "Would you like to see a concert?"], ["ça vaut le coup", "it's worth it", "Ça vaut le coup d'y aller tôt.", "It's worth going early."], ["la moitié", "half", "La moitié des sondés vont au cinéma.", "Half of those polled go to the cinema."], ["un tiers", "a third", "Un tiers des jeunes sortent le jeudi.", "A third of young people go out on Thursdays."], ["la plupart", "most", "La plupart de mes amis préfèrent les bars.", "Most of my friends prefer bars."], ["n'hésite pas à", "don't hesitate to", "N'hésite pas à réserver.", "Don't hesitate to book."]],
  sent: [["Et si on allait au théâtre samedi soir ?", "How about going to the theatre on Saturday evening?"], ["Ça te dirait de faire un pique-nique au bord du canal ?", "Would you like a picnic by the canal?"], ["Je te conseille de réserver à l'avance.", "I advise you to book in advance."], ["Plus de la moitié des Français vont au cinéma au moins une fois par an.", "More than half of French people go to the cinema at least once a year."], ["Ce qui me plaît le plus, ce sont les concerts en plein air.", "What I like most are open-air concerts."], ["Cette exposition vaut vraiment le coup.", "This exhibition is really worth it."], ["La plupart des sorties sont gratuites le premier dimanche du mois.", "Most outings are free on the first Sunday of the month."], ["N'hésite pas à inviter tes collègues.", "Don't hesitate to invite your colleagues."]],
  gap: [["Et si on ___ au restaurant ce soir ?", "allait", "aller", "How about going to a restaurant tonight?", ["va", "irait", "aille"]], ["Ça te ___ de venir avec nous ?", "dirait", "dire", "Would you like to come with us?", ["dira", "dit", "disait"]], ["La ___ des jeunes préfèrent sortir le week-end.", "plupart|majorité", "", "Most young people prefer going out at the weekend.", ["moitié de", "beaucoup", "partie"]]],
  mcq: [["To propose an outing:", "Et si on allait au parc ?", ["Si on ira au parc ?", "Et si on va au parc hier ?", "On aurait allé au parc ?"], "Et si + imparfait."], ["25 % = ___", "un quart", ["un tiers", "la moitié", "un cinquième"], "25 % is a quarter."]],
  nat: [["Je te conseille d'y aller tôt.", "Je te conseille que tu vas tôt.", "Conseiller de + infinitive."]],
  chat: [["On fait quoi ce week-end ?", "Et si on allait voir l'exposition au Grand Palais ? Ça vaut le coup !", ["Si on ira au Grand Palais ?", "On allait hier au Grand Palais."], "Et si + imparfait to propose."], ["C'est cher, le concert ?", "Non, et je te conseille de prendre les billets en ligne.", ["Je te conseille que tu prends.", "Je conseille toi prendre."], "Conseiller de."]]
});

CO({ id: "co-d3l2", unit: "d3", num: 2, src: "Cosmopolite 3 · Dossier 3 · Leçon 2", t: "Esprit d'équipe !", en: "Team activities, convincing and hesitating",
  task: "Organiser une activité pour développer l'esprit d'équipe", sf: ["Choose a group outing", "Convince / hesitate", "Inform about an event"], gram: ["L'expression du but pour convaincre"], links: ["b2-but"],
  rule: { h: "To convince, explain the purpose: pour / afin de + infinitive, pour que / afin que + subjunctive.", pts: ["<i>On organise un escape game pour renforcer la cohésion de l'équipe.</i>", "<i>Je propose cette activité pour que chacun puisse participer.</i>", "Hesitating: <i>je ne sais pas trop, j'hésite, pourquoi pas, il faut voir, ça dépend</i>."], ex: [["Afin de mieux nous connaître, partons une journée ensemble.", "To get to know each other better, let's go away for a day."], ["J'hésite encore entre le karting et le bowling.", "I'm still hesitating between karting and bowling."]] },
  sons: { t: "Hésitation et interrogation", tip: "Long vowels and fillers show hesitation: « Bah… je sais pas trop… peut-être ? »", ex: ["Bah… je ne sais pas trop.", "Pourquoi pas, mais ça dépend du prix."] },
  cards: [["l'esprit d'équipe", "team spirit", "Ce jeu développe l'esprit d'équipe.", "This game builds team spirit."], ["la cohésion", "cohesion", "L'objectif est de renforcer la cohésion.", "The aim is to strengthen cohesion."], ["un séminaire", "an away day, seminar", "Le séminaire aura lieu en Bourgogne.", "The away day will be in Burgundy."], ["un collègue", "a colleague", "Mes collègues sont très sympathiques.", "My colleagues are very nice."], ["convaincre", "to convince", "Elle a convaincu toute l'équipe.", "She convinced the whole team."], ["hésiter", "to hesitate", "J'hésite entre deux activités.", "I'm torn between two activities."], ["participer à", "to take part in", "Tout le monde peut participer à l'atelier.", "Everyone can take part in the workshop."], ["un escape game", "an escape room", "On a fait un escape game en équipe.", "We did an escape room as a team."]],
  sent: [["Je propose un atelier de cuisine pour que tout le monde se rencontre.", "I suggest a cooking workshop so everyone meets."], ["L'objectif, c'est de renforcer l'esprit d'équipe.", "The goal is to strengthen team spirit."], ["Afin de faire plaisir à tous, on pourrait voter.", "To please everyone, we could vote."], ["Je ne sais pas trop, ça dépend du budget.", "I'm not sure, it depends on the budget."], ["Pourquoi pas, mais il faut que ce soit accessible à tous.", "Why not, but it must be accessible to all."], ["Allez, viens, tu ne le regretteras pas !", "Come on, you won't regret it!"], ["Le séminaire aura lieu le jeudi 12 juin, de 9 h à 17 h.", "The away day will take place on Thursday 12 June, 9 to 5."], ["J'hésite encore, je te réponds demain.", "I'm still hesitating, I'll answer you tomorrow."]],
  gap: [["On fait cette activité ___ que chacun participe.", "pour|afin", "", "We're doing this activity so everyone takes part.", ["parce", "bien", "malgré"]], ["Je propose ce jeu pour que l'équipe ___ mieux.", "communique", "communiquer", "I suggest this game so the team communicates better.", ["communiquera", "communiquait", "communiquer"]], ["J'___ entre le bowling et le karaoké.", "hésite", "hésiter", "I'm hesitating between bowling and karaoke.", ["hésites", "hésitais de", "hésiter"]]],
  mcq: [["Convince with a purpose:", "On y va pour se détendre ensemble.", ["On y va parce que.", "On y va bien que.", "On y va pour que se détendre."], "Pour + infinitive, same subject."], ["Hesitating:", "Je ne sais pas trop…", ["Absolument !", "Évidemment !", "Bien sûr que oui !"], "An expression of hesitation."]],
  nat: [["Je propose ça pour que tu puisses venir.", "Je propose ça pour que tu peux venir.", "Pour que + subjunctive."]],
  chat: [["Un escape game ? Je ne suis pas convaincu…", "Allez, c'est idéal pour apprendre à travailler ensemble, et on rira beaucoup !", ["Bah, comme tu veux, rien.", "C'est pour que on rit."], "Convince with a purpose and enthusiasm."], ["Tu viens au séminaire ?", "J'hésite, ça dépend si je peux faire garder le chat.", ["J'hésite de venir pour que.", "Absolument non oui."], "Express hesitation."]]
});

CO({ id: "co-d3l3", unit: "d3", num: 3, src: "Cosmopolite 3 · Dossier 3 · Leçon 3", t: "En famille", en: "Family events, customs and restriction",
  task: "Réaliser un mini-guide des codes culturels pour les événements familiaux", sf: ["Talk about family events", "Understand customs"], gram: ["Les pronoms en et y", "La négation (2) : la restriction ne… que"], links: ["b1-y-en", "b1-negation"],
  rule: { h: "Ne… que means only; en and y avoid repeating places, things and ideas.", pts: ["<i>On ne se voit qu'une fois par an. Je n'ai qu'une sœur.</i>", "<i>Le mariage ? On en parle tous les jours. À la fête du Têt, on y pense dès décembre.</i>", "Family: <i>les beaux-parents, la belle-sœur, le gendre, la belle-fille, les cousins, les petits-enfants</i>."], ex: [["Chez nous, on ne mange que des plats végétariens ce jour-là.", "At home, we only eat vegetarian dishes that day."], ["Les fiançailles ? Nous en avons fait deux : une en France, une au Viêt Nam !", "The engagement? We had two: one in France, one in Vietnam!"]] },
  sons: { t: "Variations rythmiques et mélodiques", tip: "French stresses the last syllable of each rhythm group: « Le mariage / aura lieu / à Saïgon ».", ex: ["Le mariage aura lieu à Saïgon, en janvier.", "Toute la famille sera là."] },
  cards: [["les beaux-parents", "parents-in-law", "Je déjeune chez mes beaux-parents dimanche.", "I'm having lunch at my in-laws' on Sunday."], ["la belle-sœur", "sister-in-law", "Ma belle-sœur vit à Lyon.", "My sister-in-law lives in Lyon."], ["les fiançailles", "engagement", "Nos fiançailles ont eu lieu à Hội An.", "Our engagement took place in Hội An."], ["un baptême", "a christening", "Ils nous ont invités au baptême.", "They invited us to the christening."], ["une coutume", "a custom", "C'est une coutume ancienne.", "It's an old custom."], ["faire la bise", "to kiss on the cheek", "En France, on fait la bise pour dire bonjour.", "In France, people kiss on the cheek to say hello."], ["l'autel des ancêtres", "the ancestors' altar", "On dépose des fruits sur l'autel des ancêtres.", "We place fruit on the ancestors' altar."], ["ne… que", "only", "Je n'ai qu'une semaine de vacances.", "I only have one week of holiday."]],
  sent: [["Toute la famille se réunit pour le repas de Noël.", "The whole family gets together for Christmas dinner."], ["Chez nous, on ne se réunit qu'une fois par an, pour le Têt.", "At home, we only get together once a year, for Tết."], ["Les enfants reçoivent des enveloppes rouges avec un peu d'argent.", "Children receive red envelopes with a little money."], ["Ma future belle-mère m'a appris à faire une tarte aux pommes.", "My future mother-in-law taught me to make an apple tart."], ["Le mariage ? On en parle à chaque repas !", "The wedding? We talk about it at every meal!"], ["Il ne faut pas arriver les mains vides chez des Français.", "You shouldn't arrive empty-handed at French people's homes."], ["On n'ouvre les cadeaux qu'après le dessert.", "Presents are only opened after dessert."], ["Les traditions familiales ? J'y tiens beaucoup.", "Family traditions? They mean a lot to me."]],
  gap: [["Je n'ai ___ un frère.", "qu'", "", "I only have one brother.", ["pas", "que pas", "plus qu'"]], ["Les traditions ? Ma grand-mère ___ tient beaucoup.", "y", "", "Traditions? My grandmother cares a lot about them.", ["en", "les", "lui"]], ["Des cousins ? J'___ ai une vingtaine !", "en", "", "Cousins? I have about twenty!", ["y", "les", "leur"]]],
  mcq: [["« On ne se voit qu'à Noël » means…", "We only see each other at Christmas.", ["We never see each other at Christmas.", "We see each other except at Christmas.", "We don't see each other at Christmas any more."], "Ne… que = only."], ["The mother of your spouse:", "la belle-mère", ["la grand-mère", "la marraine", "la tante"], "Belle-mère."]],
  nat: [["Je n'ai qu'une sœur.", "Je n'ai pas qu'une sœur pas.", "Ne… que, no pas."]],
  chat: [["Comment on fête le Têt chez toi ?", "On se réunit chez mes parents, on prépare des bánh chưng et on n'oublie jamais l'autel des ancêtres.", ["On réunit le Têt chez rien.", "On ne fête que pas le Têt."], "Describe a family custom."], ["Tu vas souvent chez tes futurs beaux-parents ?", "On y va une fois par mois, en Bretagne.", ["On en va une fois par mois.", "On leur va en Bretagne."], "A place → y."]]
});

CO({ id: "co-d3l4", unit: "d3", num: 4, src: "Cosmopolite 3 · Dossier 3 · Leçon 4", t: "Un air de fête", en: "New kinds of parties, describing behaviour",
  task: "Planifier une soirée originale pour la fête de la francophonie", sf: ["Discover new kinds of evenings", "Describe behaviour"], gram: ["Les pronoms démonstratifs et indéfinis"], links: ["b2-demonstr"],
  rule: { h: "Demonstratives (celui, celle, ceux) and indefinites (chacun, certains, d'autres, tout le monde, personne) describe groups and behaviour.", pts: ["<i>Ceux qui aiment danser, celles qui préfèrent discuter.</i>", "<i>Chacun apporte un plat. Certains arrivent tôt, d'autres partent tard. Personne ne s'ennuie.</i>", "<i>Tout le monde</i> takes a singular verb: <i>tout le monde est là</i>."], ex: [["Chacun apporte quelque chose à boire.", "Everyone brings something to drink."], ["Ceux qui veulent chanter peuvent s'inscrire.", "Those who want to sing can sign up."]] },
  sons: { t: "Variations rythmiques et mélodiques", tip: "Enthusiasm raises the melody and lengthens stressed syllables: « C'était su-per ! »", ex: ["C'était vraiment génial !", "Tout le monde a dansé jusqu'à minuit."] },
  cards: [["une soirée", "an evening party", "On organise une soirée karaoké.", "We're having a karaoke night."], ["chacun", "each one, everyone", "Chacun apporte un plat.", "Everyone brings a dish."], ["certains… d'autres", "some… others", "Certains dansent, d'autres discutent.", "Some dance, others chat."], ["tout le monde", "everybody", "Tout le monde est invité.", "Everybody is invited."], ["un repas partagé", "a potluck", "On fait un repas partagé dimanche.", "We're having a potluck on Sunday."], ["la francophonie", "the French-speaking world", "Le 20 mars, on fête la francophonie.", "On 20 March, we celebrate la francophonie."], ["s'amuser", "to have fun", "On s'est bien amusés !", "We had great fun!"], ["un hôte, une hôtesse", "a host, a hostess", "Remercie l'hôtesse avant de partir.", "Thank the hostess before leaving."]],
  sent: [["Pour la fête de la francophonie, chacun apporte un plat de son pays.", "For la francophonie day, everyone brings a dish from their country."], ["Ceux qui veulent danser peuvent rester après minuit.", "Those who want to dance can stay after midnight."], ["Certains invités sont arrivés tôt, d'autres très tard.", "Some guests arrived early, others very late."], ["Tout le monde a adoré le quiz sur les pays francophones.", "Everyone loved the quiz on French-speaking countries."], ["Personne n'est reparti les mains vides.", "Nobody left empty-handed."], ["Celle qui a gagné le quiz est québécoise.", "The woman who won the quiz is from Quebec."], ["On pourrait organiser une soirée jeux de société.", "We could organise a board-game night."], ["C'était une soirée vraiment réussie !", "It was a really successful evening!"]],
  gap: [["___ le monde est invité à la soirée.", "Tout", "", "Everyone is invited to the party.", ["Tous", "Toute", "Chaque"]], ["___ qui veulent chanter s'inscrivent ici.", "Ceux", "", "Those who want to sing sign up here.", ["Celui", "Ces", "Chacun"]], ["Certains dansent, d'___ discutent.", "autres", "", "Some dance, others chat.", ["autre", "uns", "certains"]]],
  mcq: [["Tout le monde ___ content.", "est", ["sont", "êtes", "sommes"], "Tout le monde + singular."], ["___ apporte un dessert.", "Chacun", ["Chaque", "Tous", "Certains"], "Chacun is a pronoun; chaque needs a noun."]],
  nat: [["Chacun a apporté un plat.", "Chaque a apporté un plat.", "Chaque must be followed by a noun; alone, use chacun."]],
  chat: [["Comment s'est passée la soirée ?", "Super ! Tout le monde a dansé, même ceux qui disaient qu'ils détestaient ça.", ["Super, tout le monde ont dansé.", "Super, chaque a dansé."], "Tout le monde + singular; ceux qui."], ["Qu'est-ce qu'on apporte ?", "Chacun apporte un plat de sa région ou de son pays.", ["Chaque apporte un plat.", "Tous apporte un plat."], "Chacun + singular verb."]]
});

CO({ id: "co-d4l1", unit: "d4", num: 1, src: "Cosmopolite 3 · Dossier 4 · Leçon 1", t: "Communautés durables", en: "Neighbourly life, quantity, adhesion and reservations",
  task: "Rendre compte d'une expérience", sf: ["Report on an experience", "Express support and reservations"], gram: ["Adjectifs et pronoms indéfinis (quantité)"], links: ["b1-pc-imp", "b2-concession"],
  rule: { h: "Indefinites express or nuance quantity: aucun, quelques, plusieurs, certains, la plupart, tous.", pts: ["<i>Quelques voisins participent, plusieurs familles ont adhéré, la plupart des habitants sont ravis.</i>", "<i>Aucun voisin ne s'est plaint</i> (aucun + ne).", "Support / reservations: <i>j'adhère complètement à, je suis pour, je suis plutôt sceptique, j'ai des doutes sur, oui, mais…</i>"], ex: [["La plupart des voisins partagent leurs outils.", "Most neighbours share their tools."], ["J'adhère à l'idée, mais j'ai quelques réserves.", "I support the idea, but I have some reservations."]] },
  sons: { t: "Les sons [y], [ɥ], [u]", tip: "<i>u</i> [y] (rue): say « i » with rounded lips; <i>ou</i> [u] (roue); <i>ui</i> [ɥ] (huit, nuit).", ex: ["Dans notre rue, tout le monde se connaît.", "Je suis venue huit fois cette nuit."] },
  cards: [["un voisin", "a neighbour", "Mon voisin m'a prêté une perceuse.", "My neighbour lent me a drill."], ["un habitat participatif", "co-housing", "Ils vivent dans un habitat participatif.", "They live in co-housing."], ["partager", "to share", "On partage une buanderie.", "We share a laundry room."], ["plusieurs", "several", "Plusieurs familles ont rejoint le projet.", "Several families joined the project."], ["la plupart des", "most", "La plupart des habitants sont satisfaits.", "Most residents are satisfied."], ["aucun", "no, not any", "Aucun voisin ne s'est plaint.", "No neighbour complained."], ["adhérer à", "to support, to join", "J'adhère totalement à ce projet.", "I fully support this project."], ["émettre des réserves", "to express reservations", "Certains émettent des réserves sur le coût.", "Some express reservations about the cost."]],
  sent: [["Nous avons testé la vie en habitat participatif pendant un an.", "We tried co-housing for a year."], ["La plupart des voisins se rendent service.", "Most neighbours help each other out."], ["Plusieurs familles partagent une voiture électrique.", "Several families share an electric car."], ["Aucun habitant n'a quitté le projet.", "No resident has left the project."], ["J'adhère à l'idée, mais je trouve que ça demande beaucoup de temps.", "I support the idea, but I find it takes a lot of time."], ["Je suis un peu sceptique sur l'organisation des réunions.", "I'm a bit sceptical about how meetings are organised."], ["Tous les mois, on organise un repas dans la cour.", "Every month we have a meal in the courtyard."], ["En résumé, l'expérience a été très positive.", "In short, the experience was very positive."]],
  gap: [["___ voisin ne s'est plaint du bruit.", "Aucun", "", "No neighbour complained about the noise.", ["Aucune", "Personne", "Pas de"]], ["La ___ des habitants sont contents.", "plupart", "", "Most residents are happy.", ["plus", "majeure", "partie"]], ["J'adhère ___ ce projet de jardin.", "à", "", "I support this garden project.", ["de", "pour", "sur"]]],
  mcq: [["___ familles ont rejoint le projet.", "Plusieurs", ["Aucunes", "Chaque", "Chacune"], "Plusieurs + plural noun."], ["Expressing a reservation:", "Oui, mais j'ai quelques doutes sur le coût.", ["J'adhère à 100 % !", "Génial, aucune question.", "Bravo !"], "A reservation."]],
  nat: [["Aucun voisin n'est venu.", "Aucun voisin n'est pas venu.", "Aucun + ne, no pas."]],
  chat: [["Alors, cette vie en communauté ?", "Très positive ! La plupart des voisins s'entraident, même si les réunions sont longues.", ["Positive, aucuns voisins s'entraident.", "Tous voisin s'entraide."], "Report with indefinites and a reservation."], ["Tu es pour la voiture partagée ?", "J'adhère à l'idée, mais j'ai des réserves sur la réservation des créneaux.", ["J'adhère de l'idée.", "Je suis pour contre."], "Adhérer à + a reservation."]]
});

CO({ id: "co-d4l2", unit: "d4", num: 2, src: "Cosmopolite 3 · Dossier 4 · Leçon 2", t: "Consommation responsable", en: "Proposing solutions and debating",
  task: "Débattre d'un sujet polémique", sf: ["Propose solutions", "Debate a controversial topic"], gram: ["Le participe présent", "Les adverbes en -ment", "Adverbes de quantité et d'intensité"], links: ["b2-participe", "b2-argu"],
  rule: { h: "Adverbs in -ment are built on the feminine adjective; -ant / -ent adjectives give -amment / -emment.", pts: ["<i>lent → lentement, heureux → heureusement, vrai → vraiment</i>.", "<i>courant → couramment, évident → évidemment, récent → récemment</i>.", "Nuance your opinion: <i>trop, assez, peu, beaucoup, tellement, plutôt, vraiment, absolument</i>."], ex: [["Évidemment, il faut réduire le gaspillage.", "Obviously we must reduce waste."], ["Les clients consommant local sont de plus en plus nombreux.", "Customers who buy local are more and more numerous."]] },
  sons: { t: "Les sons [y], [ɥ], [u]", tip: "Watch <i>tout</i> [u] vs <i>tu</i> [y], and <i>produit</i> [ɥi].", ex: ["Tu achètes tout en vrac ?", "Ce produit est vraiment utile."] },
  cards: [["le gaspillage", "waste", "Le gaspillage alimentaire est énorme.", "Food waste is huge."], ["en vrac", "loose, unpackaged", "J'achète les pâtes en vrac.", "I buy pasta loose."], ["consommer local", "to buy local", "Consommer local soutient les producteurs.", "Buying local supports producers."], ["d'occasion", "second-hand", "Mon vélo est d'occasion.", "My bike is second-hand."], ["réparer", "to repair", "Il vaut mieux réparer que jeter.", "It's better to repair than throw away."], ["évidemment", "obviously", "Évidemment, ça coûte plus cher.", "Obviously it costs more."], ["récemment", "recently", "J'ai récemment arrêté le plastique.", "I recently stopped using plastic."], ["une polémique", "a controversy", "Cette mesure crée la polémique.", "This measure is controversial."]],
  sent: [["On pourrait réduire le gaspillage en achetant uniquement ce dont on a besoin.", "We could reduce waste by buying only what we need."], ["Évidemment, les produits locaux coûtent un peu plus cher.", "Obviously local products cost a little more."], ["Je suis plutôt pour, mais il faut informer les consommateurs.", "I'm rather in favour, but consumers must be informed."], ["Les magasins vendant en vrac se multiplient.", "Shops selling loose goods are multiplying."], ["Je trouve ça vraiment absurde de jeter de la nourriture.", "I find it really absurd to throw food away."], ["Récemment, j'ai acheté un téléphone reconditionné.", "Recently I bought a refurbished phone."], ["Ce n'est pas assez : il faudrait interdire les emballages inutiles.", "It's not enough: unnecessary packaging should be banned."], ["Heureusement, de plus en plus de gens réparent leurs objets.", "Fortunately, more and more people repair their things."]],
  gap: [["Il parle ___ trois langues. (courant)", "couramment", "", "He speaks three languages fluently.", ["courrament", "courantement", "couramant"]], ["___, nous devons agir maintenant. (évident)", "Évidemment", "", "Obviously, we must act now.", ["Évidentement", "Évidamment", "Évidemmant"]], ["On réduit ses déchets en ___ en vrac.", "achetant", "acheter", "You reduce your waste by buying loose.", ["achètant", "achetent", "acheté"]]],
  mcq: [["Adverb from « gentil »:", "gentiment", ["gentilement", "gentillement", "gentilment"], "Irregular: gentiment."], ["« Les clients achetant en ligne » =", "les clients qui achètent en ligne", ["les clients en achetant", "les clients achetés en ligne", "les clients pour acheter"], "Participe présent replaces qui + verb."]],
  nat: [["Elle parle couramment vietnamien et français.", "Elle parle courantement vietnamien et français.", "Courant → couramment."]],
  chat: [["Interdire les sacs plastique, c'est utile ?", "Évidemment, mais ce n'est pas suffisant : il faut aussi réduire les emballages.", ["Évidentement oui.", "Évidemment non oui."], "Agree and nuance."], ["Comment tu réduis tes déchets ?", "En achetant en vrac et en réparant au lieu de jeter.", ["En achète en vrac.", "Achetant en vrac en."], "Manner: gérondif."]]
});

CO({ id: "co-d4l3", unit: "d4", num: 3, src: "Cosmopolite 3 · Dossier 4 · Leçon 3", t: "Local, social et solidaire", en: "Local development projects and microcredit",
  task: "Soutenir un micro-entrepreneur", sf: ["Identify a local sustainable project", "Express the purpose of an action", "Persuade"], gram: ["Verbes prépositionnels du but", "L'infinitif et le subjonctif pour exprimer le but"], links: ["b2-but", "b2-subj"],
  rule: { h: "Purpose: viser à, chercher à, servir à + infinitive; pour que + subjunctive.", pts: ["<i>Ce projet vise à créer des emplois. Le prêt sert à acheter du matériel.</i>", "<i>L'association aide les femmes pour qu'elles puissent créer leur entreprise.</i>", "Solidarity economy: <i>le microcrédit, un prêt, un micro-entrepreneur, l'économie sociale et solidaire (ESS)</i>."], ex: [["Ce prêt sert à acheter une machine à coudre.", "This loan is for buying a sewing machine."], ["Nous l'aidons pour qu'elle puisse ouvrir sa boutique.", "We're helping her so she can open her shop."]] },
  sons: { t: "L'intonation pour persuader", tip: "To persuade, the voice rises then falls on the key word, with a short pause before it: « Avec vingt euros… vous changez une vie. »", ex: ["Avec vingt euros, vous pouvez changer une vie.", "Rejoignez-nous dès aujourd'hui !"] },
  cards: [["le microcrédit", "microcredit", "Le microcrédit finance de petits projets.", "Microcredit finances small projects."], ["un prêt", "a loan", "Elle a obtenu un prêt de 2 000 euros.", "She got a 2,000-euro loan."], ["rembourser", "to pay back", "Il rembourse son prêt en un an.", "He pays back his loan in a year."], ["viser à", "to aim to", "Le projet vise à réduire la pauvreté.", "The project aims to reduce poverty."], ["servir à", "to be used for", "À quoi sert cet argent ?", "What is this money for?"], ["un micro-entrepreneur", "a small business owner", "Elle est devenue micro-entrepreneuse.", "She became a self-employed entrepreneur."], ["solidaire", "solidarity-based", "C'est une épicerie solidaire.", "It's a social grocery."], ["soutenir", "to support", "Soutenez les artisans locaux.", "Support local craftspeople."]],
  sent: [["Ce projet vise à aider les femmes à créer leur entreprise.", "This project aims to help women start their business."], ["Le prêt sert à acheter un four pour la boulangerie.", "The loan is for buying an oven for the bakery."], ["L'association accompagne les entrepreneurs pour qu'ils réussissent.", "The association supports entrepreneurs so they succeed."], ["Avec un petit prêt, Mai a ouvert un atelier de couture à Huế.", "With a small loan, Mai opened a sewing workshop in Huế."], ["Les prêteurs sont remboursés en moyenne en dix-huit mois.", "Lenders are repaid in eighteen months on average."], ["Rejoignez-nous : chaque euro compte !", "Join us: every euro counts!"], ["Nous cherchons à créer des emplois dans le quartier.", "We're trying to create jobs in the area."], ["C'est une entreprise de l'économie sociale et solidaire.", "It's a social and solidarity economy business."]],
  gap: [["Ce prêt sert ___ acheter du matériel.", "à", "", "This loan is used to buy equipment.", ["de", "pour que", "en"]], ["Nous l'aidons pour qu'elle ___ ouvrir sa boutique.", "puisse", "pouvoir", "We're helping her so she can open her shop.", ["peut", "pourra", "pouvait"]], ["Le projet ___ à créer des emplois.", "vise", "viser", "The project aims to create jobs.", ["visé", "vise de", "vises"]]],
  mcq: [["Purpose with a different subject:", "pour que + subjonctif", ["pour + subjonctif", "pour que + infinitif", "afin de + subjonctif"], "Different subjects → pour que + subjunctive."], ["« Chercher à » means…", "to try to", ["to look for", "to search at", "to find"], "Chercher à + infinitive = to try to."]],
  nat: [["Ce projet vise à créer des emplois.", "Ce projet vise de créer des emplois.", "Viser à."]],
  chat: [["À quoi sert ton don ?", "Il sert à financer l'achat d'une machine à coudre pour une artisane de Huế.", ["Il sert pour que financer.", "Il sert de financer."], "Servir à + infinitive."], ["Pourquoi soutenir le microcrédit ?", "Pour que des personnes sans accès aux banques puissent créer leur activité.", ["Pour que des personnes peuvent créer.", "Pour des personnes puissent créer."], "Pour que + subjunctive."]]
});

CO({ id: "co-d4l4", unit: "d4", num: 4, src: "Cosmopolite 3 · Dossier 4 · Leçon 4", t: "Agir au quotidien", en: "Eco-gestures, persuading, informal French",
  task: "Mettre en scène ses bonnes résolutions", sf: ["Identify eco-gestures", "Persuade someone to do something", "Describe a comic strip"], gram: ["Le français familier"], links: ["c1-registres", "b2-but"],
  rule: { h: "To persuade: imperative, il faut que, tu verras, ça vaut la peine; informal French shortens words.", pts: ["<i>Éteins la lumière ! Il faut que tu essaies. Tu verras, c'est facile.</i>", "Informal: <i>la clim, le frigo, l'appart, le resto, bosser, un truc, c'est sympa, t'inquiète</i>.", "Eco-gestures: <i>trier ses déchets, éteindre les appareils en veille, prendre une douche courte, composter</i>."], ex: [["Allez, essaie le vélo pendant une semaine, tu verras !", "Come on, try cycling for a week, you'll see!"], ["Baisse la clim, c'est mauvais pour la planète.", "Turn the air-con down, it's bad for the planet."]] },
  sons: { t: "L'intonation pour persuader", tip: "Persuasion = rising enthusiasm + a firm fall: « Allez… essaie ! »", ex: ["Allez, essaie, tu verras !", "Fais un effort, c'est pour la planète !"] },
  cards: [["trier ses déchets", "to sort one's rubbish", "On trie nos déchets depuis des années.", "We've sorted our rubbish for years."], ["la poubelle jaune", "the recycling bin", "Les bouteilles vont dans la poubelle jaune.", "Bottles go in the yellow bin."], ["en veille", "on standby", "Ne laisse pas la télé en veille.", "Don't leave the TV on standby."], ["composter", "to compost", "On composte les épluchures.", "We compost the peelings."], ["une bonne résolution", "a resolution", "Ma bonne résolution : moins de plastique.", "My resolution: less plastic."], ["la clim", "air-con (informal)", "Tu peux baisser la clim ?", "Can you turn down the air-con?"], ["le frigo", "the fridge (informal)", "Il n'y a plus rien dans le frigo.", "There's nothing left in the fridge."], ["sympa", "nice (informal)", "C'est une appli sympa.", "It's a nice app."]],
  sent: [["Éteins la lumière quand tu quittes la pièce !", "Turn off the light when you leave the room!"], ["Il faut que tu essaies le compost, c'est super simple.", "You must try composting, it's really simple."], ["Allez, fais un effort : prends le vélo au lieu de la voiture !", "Come on, make an effort: take the bike instead of the car!"], ["Ma bonne résolution, c'est de ne plus acheter de bouteilles en plastique.", "My resolution is to stop buying plastic bottles."], ["Tu verras, au bout d'une semaine, tu ne pourras plus t'en passer.", "You'll see, after a week you won't be able to do without it."], ["T'inquiète, c'est pas compliqué de trier.", "Don't worry, sorting isn't complicated."], ["Sur la première image, un homme laisse tout allumé.", "In the first picture, a man leaves everything on."], ["Une douche de cinq minutes, ça suffit largement.", "A five-minute shower is plenty."]],
  gap: [["___ la télé, personne ne la regarde ! (éteindre)", "Éteins", "éteindre", "Turn off the TV, nobody's watching it!", ["Éteint", "Éteindre", "Éteinds"]], ["Il faut que tu ___ tes déchets.", "tries", "trier", "You must sort your rubbish.", ["tris", "triais", "trieras"]], ["Tu ___, c'est facile ! (voir, future)", "verras", "voir", "You'll see, it's easy!", ["voiras", "vois", "verrais"]]],
  mcq: [["Informal for « le réfrigérateur »:", "le frigo", ["la clim", "le resto", "l'appart"], "Frigo."], ["Persuading:", "Allez, essaie, tu verras !", ["Peut-être, si tu veux…", "Je ne sais pas.", "Bof."], "Imperative + tu verras."]],
  nat: [["Éteins la lumière !", "Éteint la lumière !", "Imperative, tu form: éteins."]],
  chat: [["Le compost ? Ça sent mauvais, non ?", "Pas du tout si tu le fais bien ! Essaie un mois, tu verras.", ["Pas du tout, essayes un mois.", "Si, ça sent, laisse tomber."], "Persuade with an imperative."], ["C'est quoi ta bonne résolution ?", "Prendre le vélo pour aller au bureau, même quand il pleut !", ["Prendre la clim tout le temps.", "Bonne résolution rien."], "A resolution."]]
});

