OE({ id: "oe-u1", unit: "u1", lvl: "B1", src: "Objectif Express 2 · Unité 1", t: "Nouveaux collaborateurs", en: "Welcoming a colleague, introducing your role",
  task: "Accueillir un nouveau collègue et présenter son poste", sf: ["Introduce yourself and your role", "Welcome a newcomer", "Explain how the team works"], gram: ["Tu ou vous au travail", "Présenter une fonction : être chargé(e) de, s'occuper de"], links: ["b1-pronoms", "c1-registres"],
  repere: "In most French companies colleagues switch to <i>tu</i> quickly, but you keep <i>vous</i> with clients and often with senior managers until they suggest <i>on se tutoie ?</i> First names are common; a handshake or a simple <i>bonjour</i> to everyone in the morning is expected.",
  rule: { h: "Describe a role with être chargé(e) de, s'occuper de, être responsable de, travailler sur.", pts: ["<i>Je suis chargée de la formation en ligne. Je m'occupe des inscriptions.</i>", "Welcome: <i>Bienvenue dans l'équipe ! Je vais te faire visiter. N'hésite pas si tu as des questions.</i>", "Org chart: <i>le service, le département, le / la responsable, un(e) collaborateur(-trice), rattaché(e) à</i>."], ex: [["Je suis chargée de concevoir les modules de formation.", "I'm in charge of designing the training modules."], ["Bienvenue dans l'équipe, je vais te présenter tout le monde.", "Welcome to the team, I'll introduce you to everyone."]] },
  sons: { t: "Tu / vous", tip: "<i>Vous</i> + vowel takes a [z] liaison: « vous-z-êtes », « vous-z-avez ».", ex: ["Vous êtes dans quel service ?", "Vous avez un badge ?"] },
  cards: [["un collaborateur, une collaboratrice", "a colleague, staff member", "Je vous présente notre nouvelle collaboratrice.", "Let me introduce our new colleague."], ["être chargé(e) de", "to be in charge of", "Il est chargé du recrutement.", "He's in charge of recruitment."], ["le service", "the department", "Elle travaille au service marketing.", "She works in the marketing department."], ["un poste", "a position, job", "Elle occupe ce poste depuis 2022.", "She's held this position since 2022."], ["rattaché(e) à", "reporting to", "Je suis rattachée à la direction pédagogique.", "I report to the academic management."], ["l'intégration", "onboarding", "Son intégration s'est très bien passée.", "Her onboarding went very well."], ["se tutoyer", "to use « tu » with each other", "Ici, on se tutoie.", "Here we use tu."], ["un badge", "a staff pass", "Voici ton badge d'accès.", "Here's your access pass."]],
  sent: [["Bonjour, je m'appelle Lan Anh, je viens d'arriver au service formation.", "Hello, I'm Lan Anh, I've just joined the training department."], ["Je suis chargée de la conception des cours en ligne.", "I'm in charge of designing online courses."], ["Bienvenue ! Je vais te faire visiter les locaux.", "Welcome! I'll show you around the premises."], ["Je suis rattachée à la directrice pédagogique.", "I report to the academic director."], ["Si tu as la moindre question, n'hésite pas.", "If you have any question at all, don't hesitate."], ["On se tutoie ? Ici, tout le monde se tutoie.", "Shall we use tu? Everyone does here."], ["La réunion d'équipe a lieu tous les lundis à dix heures.", "The team meeting is every Monday at ten."], ["Je travaille en étroite collaboration avec le service informatique.", "I work closely with the IT department."]],
  gap: [["Je suis chargée ___ recrutement.", "du", "", "I'm in charge of recruitment.", ["de le", "au", "le"]], ["Elle s'occupe ___ inscriptions.", "des", "", "She handles registrations.", ["de les", "aux", "les"]], ["Je suis rattachée ___ directeur commercial.", "au", "", "I report to the sales director.", ["du", "à le", "le"]]],
  mcq: [["Welcoming a newcomer:", "Bienvenue dans l'équipe !", ["Au revoir et merci.", "Vous êtes en retard.", "Qui êtes-vous ?"], "Bienvenue."], ["To a client you've just met:", "vous", ["tu", "toi", "te"], "Vous with clients."]],
  nat: [["Je m'occupe des clients.", "Je m'occupe les clients.", "S'occuper de."]],
  chat: [["Tu fais quoi exactement dans l'entreprise ?", "Je suis chargée de la formation en ligne : je conçois les modules et je suis les apprenants.", ["Je suis chargée la formation.", "Formation, voilà."], "Être chargé(e) de."], ["Bonjour, je suis le nouveau stagiaire.", "Bienvenue ! Je vais te présenter l'équipe et te faire visiter.", ["Ah. Bonjour.", "Bienvenu à toi la visite."], "Welcome and help."]]
});

OE({ id: "oe-u2", unit: "u2", lvl: "B1", src: "Objectif Express 2 · Unité 2", t: "Produits et services", en: "Describing an offer and its advantages",
  task: "Présenter un produit ou un service et ses avantages", sf: ["Describe a product's characteristics", "Highlight advantages", "Compare with competitors"], gram: ["La comparaison et le superlatif", "Les relatifs pour caractériser"], links: ["b1-compar", "b1-relatifs"],
  repere: "French sales talk values arguments and precision over hype: clients expect figures, guarantees and a clear <i>rapport qualité-prix</i>. Superlatives like « le meilleur du marché » must be justified (advertising law forbids misleading claims).",
  rule: { h: "Sell with characteristics → advantages → benefits for the client.", pts: ["<i>Ce logiciel est plus simple que les autres et il coûte deux fois moins cher.</i>", "<i>C'est la solution la plus complète du marché. C'est un service qui vous fait gagner du temps.</i>", "Vocabulary: <i>une gamme, un atout, le rapport qualité-prix, la concurrence, sur mesure, haut de gamme</i>."], ex: [["Notre plateforme est plus intuitive que celle de nos concurrents.", "Our platform is more intuitive than our competitors'."], ["C'est un outil qui vous permet de suivre vos apprenants en temps réel.", "It's a tool that lets you follow your learners in real time."]] },
  sons: { t: "Convaincre", tip: "Stress the benefit, with a slight rise then fall: « Vous gagnez… DEUX heures par semaine. »", ex: ["Vous gagnez deux heures par semaine.", "Et tout ça, sans frais supplémentaires."] },
  cards: [["une gamme", "a product range", "Nous élargissons notre gamme.", "We're expanding our range."], ["un atout", "an asset, strength", "Sa simplicité est son principal atout.", "Its simplicity is its main strength."], ["le rapport qualité-prix", "value for money", "Le rapport qualité-prix est excellent.", "Value for money is excellent."], ["la concurrence", "the competition", "Nous sommes moins chers que la concurrence.", "We're cheaper than the competition."], ["sur mesure", "tailor-made", "Nous proposons des formations sur mesure.", "We offer tailor-made training."], ["haut de gamme", "high-end", "Un service haut de gamme.", "A high-end service."], ["une fonctionnalité", "a feature", "Cette fonctionnalité est très demandée.", "This feature is in high demand."], ["un devis", "a quote", "Je vous envoie un devis demain.", "I'll send you a quote tomorrow."]],
  sent: [["Notre application est plus simple à utiliser que celle de la concurrence.", "Our app is easier to use than the competition's."], ["C'est la solution la plus complète du marché.", "It's the most complete solution on the market."], ["Son principal atout, c'est le suivi personnalisé.", "Its main strength is personalised follow-up."], ["Nous proposons des formations sur mesure pour les entreprises.", "We offer tailor-made training for companies."], ["Cette fonctionnalité vous fait gagner un temps précieux.", "This feature saves you precious time."], ["Le rapport qualité-prix est imbattable.", "The value for money is unbeatable."], ["Je peux vous envoyer un devis d'ici vendredi.", "I can send you a quote by Friday."], ["C'est un service qui s'adapte à vos besoins.", "It's a service that adapts to your needs."]],
  gap: [["Notre offre est ___ chère que la leur.", "moins", "", "Our offer is cheaper than theirs.", ["moindre", "pire", "plus moins"]], ["C'est la plateforme la ___ intuitive.", "plus", "", "It's the most intuitive platform.", ["meilleur", "très", "mieux"]], ["C'est un outil ___ vous fait gagner du temps.", "qui", "", "It's a tool that saves you time.", ["que", "dont", "où"]]],
  mcq: [["« Value for money »:", "le rapport qualité-prix", ["le devis", "la gamme", "le haut de gamme"], "Rapport qualité-prix."], ["Comparative of « bon »:", "meilleur", ["plus bon", "mieux", "bonner"], "Bon → meilleur."]],
  nat: [["C'est le meilleur service.", "C'est le plus bon service.", "Bon → meilleur."]],
  chat: [["Pourquoi choisir votre solution ?", "Parce qu'elle est plus simple que les autres et qu'elle s'adapte à vos besoins.", ["Parce que plus bonne.", "Parce que c'est."], "Comparison + relative."], ["Vous pouvez m'envoyer un devis ?", "Bien sûr, je vous l'envoie d'ici vendredi.", ["Bien sûr, je le vous envoie.", "Non."], "Polite commitment."]]
});

OE({ id: "oe-u3", unit: "u3", lvl: "B1", src: "Objectif Express 2 · Unité 3", t: "Organiser son travail", en: "Appointments, meetings and minutes",
  task: "Fixer un rendez-vous et rédiger un compte rendu de réunion", sf: ["Set, move or cancel an appointment", "Run a meeting", "Write short minutes"], gram: ["Le futur et le conditionnel de politesse", "La nominalisation dans le compte rendu"], links: ["b1-futur", "c1-nominal"],
  repere: "Meetings usually have an <i>ordre du jour</i> (agenda) sent in advance; someone is appointed to take the <i>compte rendu</i>, written in nominal style (« Validation du budget », « Report de la livraison »). Calendar invitations via Outlook or Google are the norm.",
  rule: { h: "Polite scheduling uses the conditional; minutes use nouns.", pts: ["<i>Seriez-vous disponible jeudi ? Est-ce que mardi vous conviendrait ? Je dois malheureusement reporter notre rendez-vous.</i>", "Meeting: <i>l'ordre du jour, prendre la parole, passer au point suivant, faire un tour de table</i>.", "Minutes: <i>Présents, Excusés, Décisions, Actions (qui ? quand ?)</i>; <i>Validation du planning. Lancement du projet le 3 mars.</i>"], ex: [["Est-ce que jeudi quatorze heures vous conviendrait ?", "Would Thursday at 2 pm suit you?"], ["Décision : report de la formation au mois de mai.", "Decision: training postponed to May."]] },
  sons: { t: "Les dates et heures", tip: "Say times in full: <i>quatorze heures trente</i>, <i>neuf heures et quart</i>; liaison in <i>deux heures</i> « deu-z-heures ».", ex: ["La réunion est à quatorze heures trente.", "Rendez-vous à neuf heures et quart."] },
  cards: [["un ordre du jour", "an agenda", "Voici l'ordre du jour de la réunion.", "Here's the meeting agenda."], ["un compte rendu", "minutes, a report", "Qui rédige le compte rendu ?", "Who's writing the minutes?"], ["reporter", "to postpone", "Je dois reporter notre rendez-vous.", "I have to postpone our meeting."], ["convenir", "to suit", "Est-ce que lundi vous convient ?", "Does Monday suit you?"], ["un tour de table", "a round-table (each speaks)", "Commençons par un tour de table.", "Let's start with a round-table."], ["passer au point suivant", "to move to the next item", "Passons au point suivant.", "Let's move on to the next item."], ["un créneau", "a time slot", "J'ai un créneau mardi matin.", "I have a slot on Tuesday morning."], ["être excusé(e)", "to send apologies (absent)", "Paul est excusé aujourd'hui.", "Paul sends his apologies today."]],
  sent: [["Seriez-vous disponible jeudi après-midi pour faire le point ?", "Would you be available Thursday afternoon to catch up?"], ["J'ai un créneau mardi à dix heures, est-ce que ça vous convient ?", "I have a slot Tuesday at ten; does that suit you?"], ["Je suis désolée, je dois reporter notre rendez-vous.", "I'm sorry, I have to postpone our meeting."], ["Commençons par un rapide tour de table.", "Let's start with a quick round-table."], ["Le premier point à l'ordre du jour concerne le budget.", "The first item on the agenda is the budget."], ["Si personne n'a de questions, passons au point suivant.", "If nobody has questions, let's move on."], ["Décision : lancement du nouveau module le premier mars.", "Decision: new module launched on 1 March."], ["Je vous enverrai le compte rendu demain matin.", "I'll send you the minutes tomorrow morning."]],
  gap: [["Est-ce que lundi vous ___ ?", "conviendrait|convient", "convenir", "Would Monday suit you?", ["convenez", "conviens", "conviendra pas"]], ["___-vous disponible demain ?", "Seriez|Êtes", "être", "Would you be available tomorrow?", ["Serez-tu", "Étiez", "Soyez"]], ["Je vous ___ le compte rendu demain.", "enverrai", "envoyer", "I'll send you the minutes tomorrow.", ["envoierai", "envoyerai", "envoie-rai"]]],
  mcq: [["Nominal style for « On a validé le budget »:", "Validation du budget.", ["Valider le budget on a.", "Le budget, on valide.", "Validé, budget."], "Minutes use nouns."], ["To postpone:", "reporter", ["rapporter", "porter", "supporter"], "Reporter un rendez-vous."]],
  nat: [["Est-ce que ce créneau vous convient ?", "Est-ce que ce créneau vous convenit ?", "Convenir → convient."]],
  chat: [["On peut se voir cette semaine ?", "Oui, j'ai un créneau jeudi à quatorze heures, ça vous conviendrait ?", ["Oui jeudi peut-être je sais pas.", "Ça vous convenirait ?"], "Propose a slot politely."], ["Qui prend le compte rendu ?", "Je m'en occupe, je l'enverrai à tout le monde demain.", ["Je m'en occupe, je l'envoierai.", "Pas moi."], "Volunteer, future tense."]]
});

OE({ id: "oe-u4", unit: "u4", lvl: "B1", src: "Objectif Express 2 · Unité 4", t: "Vendre", en: "Questioning a client, sales talk, terms of sale",
  task: "Mener un entretien de vente et négocier les conditions", sf: ["Find out a client's needs", "Answer objections", "Discuss price, delivery and payment"], gram: ["Les questions de découverte", "L'hypothèse avec si"], links: ["b1-si", "b1-indirect"],
  repere: "Business negotiations in France often start formally and move step by step. Typical terms: <i>remise</i> (discount), <i>délai de livraison</i>, <i>paiement à 30 jours</i>, <i>conditions générales de vente (CGV)</i>. Prices are quoted <i>HT</i> (before tax) between companies and <i>TTC</i> (with VAT) for consumers.",
  rule: { h: "Discover needs with open questions; negotiate with si-clauses.", pts: ["<i>Quels sont vos besoins ? Combien de personnes sont concernées ? Quel est votre budget ?</i>", "<i>Si vous commandez avant la fin du mois, nous vous offrons la livraison. Si vous preniez trois licences, nous pourrions vous faire une remise.</i>", "Objections: <i>Je comprends votre point de vue, mais… C'est vrai, cependant…</i>"], ex: [["Si vous signez aujourd'hui, nous vous accordons dix pour cent de remise.", "If you sign today, we'll give you a ten percent discount."], ["Quel délai de livraison souhaitez-vous ?", "What delivery time would you like?"]] },
  sons: { t: "Les chiffres", tip: "Practise prices: <i>mille deux cents euros hors taxes</i>, <i>quatre-vingt-dix-neuf euros</i>.", ex: ["Le prix est de mille deux cents euros hors taxes.", "L'abonnement coûte quatre-vingt-dix-neuf euros par mois."] },
  cards: [["une remise", "a discount", "Nous pouvons vous accorder une remise.", "We can give you a discount."], ["hors taxes (HT)", "excluding tax", "Le prix est de 500 € hors taxes.", "The price is €500 excluding tax."], ["toutes taxes comprises (TTC)", "including tax", "Le prix TTC est affiché.", "The price including tax is displayed."], ["un délai de livraison", "a delivery time", "Le délai de livraison est de dix jours.", "Delivery time is ten days."], ["une objection", "an objection", "Il faut répondre aux objections du client.", "You must answer the client's objections."], ["un bon de commande", "a purchase order", "Signez le bon de commande, s'il vous plaît.", "Please sign the purchase order."], ["négocier", "to negotiate", "Nous avons négocié le prix.", "We negotiated the price."], ["les besoins", "needs", "Quels sont vos besoins exacts ?", "What are your exact needs?"]],
  sent: [["Pour commencer, pouvez-vous me parler de vos besoins ?", "To start, can you tell me about your needs?"], ["Combien de collaborateurs seraient concernés par la formation ?", "How many staff would be involved in the training?"], ["Je comprends votre point de vue, mais notre offre inclut le suivi.", "I understand your view, but our offer includes follow-up."], ["Si vous commandez avant la fin du mois, la livraison est offerte.", "If you order before the end of the month, delivery is free."], ["Si vous preniez dix licences, nous pourrions vous accorder une remise.", "If you took ten licences, we could give you a discount."], ["Le paiement se fait à trente jours fin de mois.", "Payment is at 30 days end of month."], ["Tous nos prix sont indiqués hors taxes.", "All our prices are shown excluding tax."], ["Je vous propose de signer le bon de commande dès aujourd'hui.", "I suggest signing the purchase order today."]],
  gap: [["Si vous ___ aujourd'hui, la livraison est offerte.", "commandez", "commander", "If you order today, delivery is free.", ["commanderez", "commanderiez", "commandiez"]], ["Si vous preniez cinq licences, nous ___ baisser le prix.", "pourrions", "pouvoir", "If you took five licences, we could lower the price.", ["pourrons", "pouvons", "pourrions pas"]], ["Quels sont vos ___ en matière de formation ?", "besoins", "", "What are your training needs?", ["besoin", "besoins de", "nécessaires"]]],
  mcq: [["Price for a business client is usually quoted…", "HT", ["TTC", "TVA", "CGV"], "Hors taxes."], ["Answering an objection:", "Je comprends, cependant…", ["Vous avez tort.", "Tant pis.", "Ce n'est pas mon problème."], "Acknowledge then argue."]],
  nat: [["Si vous signez, je vous fais une remise.", "Si vous signerez, je vous fais une remise.", "No future after si."]],
  chat: [["C'est un peu cher pour nous.", "Je comprends ; si vous preniez un engagement d'un an, nous pourrions vous faire une remise.", ["Si vous prendriez…", "Alors c'est non."], "Si + imparfait, conditional."], ["Quels sont vos délais ?", "Nous livrons sous dix jours ouvrés après réception du bon de commande.", ["Dix.", "On livre quand on peut."], "Precise terms."]]
});

OE({ id: "oe-u5", unit: "u5", lvl: "B1", src: "Objectif Express 2 · Unité 5", t: "À l'international", en: "Business trips and travel problems",
  task: "Préparer une mission à l'étranger et gérer un imprévu", sf: ["Organise a business trip", "Book transport and hotel", "Deal with a travel problem"], gram: ["Le passé composé et l'imparfait pour raconter un imprévu", "La réclamation polie"], links: ["b1-pc-imp", "b1-cond"],
  repere: "Business travel in France often goes through a company travel agency or tool; you keep receipts for a <i>note de frais</i> (expense report). Train is preferred over plane for trips under about four hours. Delays give rights to compensation (rail and EU air passenger rules).",
  rule: { h: "Tell what went wrong (imparfait for context, passé composé for events), then ask for a solution politely.", pts: ["<i>Mon vol était prévu à 8 h, mais il a été annulé. J'attendais depuis deux heures quand on nous a informés.</i>", "<i>Pourriez-vous me trouver une autre solution ? Je souhaiterais être remboursée.</i>", "Trip: <i>une mission, un déplacement, un billet aller-retour, une correspondance, une note de frais, un retard</i>."], ex: [["Mon train avait deux heures de retard, j'ai donc raté ma correspondance.", "My train was two hours late, so I missed my connection."], ["Pourriez-vous me réserver une chambre près du centre de congrès ?", "Could you book me a room near the conference centre?"]] },
  sons: { t: "Les annonces", tip: "Station and airport announcements are fast: listen for the key words <i>retard, annulé, voie, porte, embarquement</i>.", ex: ["Le train à destination de Lyon partira voie sept.", "Embarquement immédiat porte vingt-deux."] },
  cards: [["un déplacement", "a business trip", "Je suis en déplacement à Lille cette semaine.", "I'm on a business trip in Lille this week."], ["une mission", "an assignment", "Elle part en mission au Vietnam.", "She's going on assignment to Vietnam."], ["une note de frais", "an expense report", "N'oublie pas ta note de frais.", "Don't forget your expense report."], ["une correspondance", "a connection", "J'ai raté ma correspondance.", "I missed my connection."], ["annulé", "cancelled", "Le vol a été annulé.", "The flight was cancelled."], ["être remboursé", "to be refunded", "Je souhaiterais être remboursée.", "I'd like to be refunded."], ["un aller-retour", "a return ticket", "Un aller-retour Paris-Marseille.", "A Paris–Marseille return."], ["l'embarquement", "boarding", "L'embarquement commence à 9 h.", "Boarding starts at 9."]],
  sent: [["Je pars en mission à Hanoï du 3 au 10 mars.", "I'm going on assignment to Hanoi from 3 to 10 March."], ["Pourriez-vous me réserver un hôtel près du centre de congrès ?", "Could you book me a hotel near the conference centre?"], ["Mon vol a été annulé à cause d'une grève.", "My flight was cancelled because of a strike."], ["Le train avait une heure de retard, j'ai raté ma correspondance.", "The train was an hour late; I missed my connection."], ["Je souhaiterais être remboursée ou partir sur le prochain vol.", "I'd like a refund or to leave on the next flight."], ["Je garde tous les reçus pour ma note de frais.", "I keep all receipts for my expense report."], ["Je vous préviens : j'arriverai avec deux heures de retard.", "Just to warn you: I'll be two hours late."], ["Merci de votre compréhension, je vous tiens au courant.", "Thanks for your understanding; I'll keep you posted."]],
  gap: [["Le vol ___ annulé ce matin.", "a été", "être", "The flight was cancelled this morning.", ["était été", "est été", "avait"]], ["J'___ depuis une heure quand on m'a appelée.", "attendais", "attendre", "I'd been waiting an hour when they called me.", ["ai attendu", "attends", "attendrai"]], ["___-vous me réserver une chambre ?", "Pourriez", "pouvoir", "Could you book me a room?", ["Pourrez", "Pouvais", "Puissiez"]]],
  mcq: [["Expense report:", "une note de frais", ["un devis", "un bon de commande", "une facture client"], "Note de frais."], ["Polite request:", "Je souhaiterais être remboursée.", ["Remboursez-moi !", "Je veux l'argent.", "Rends-moi."], "Conditional."]],
  nat: [["J'ai raté ma correspondance.", "J'ai manqué ma correspondance de.", "Rater / manquer sa correspondance."]],
  chat: [["Allô ? Tu es où ? La réunion commence !", "Désolée, mon train avait une heure de retard ; j'arriverai vers onze heures.", ["Mon train a eu retard demain.", "Je suis où ?"], "Explain the incident, give an ETA."], ["Que puis-je faire pour vous ?", "Mon vol a été annulé ; pourriez-vous me proposer une autre solution ?", ["Vol annulé, solution.", "Pouvez-tu m'aider ?"], "Polite request."]]
});

OE({ id: "oe-u6", unit: "u6", lvl: "B1", src: "Objectif Express 2 · Unité 6", t: "Événements professionnels", en: "Invitations, short speeches, reviewing an event",
  task: "Inviter à un événement, prononcer un petit discours et en faire le bilan", sf: ["Write an invitation", "Give a short welcome speech", "Assess an event"], gram: ["Les formules de l'invitation et du discours", "Exprimer la satisfaction"], links: ["b1-ecrire", "b2-relief"],
  repere: "Professional events in France — <i>séminaire</i>, <i>salon</i>, <i>pot de départ</i>, <i>afterwork</i> — follow codes: invitations ask for an answer (<i>RSVP</i>, <i>merci de confirmer votre présence</i>); a short speech thanks people by role before name; a <i>pot</i> often ends with a toast.",
  rule: { h: "Invitations and speeches have set phrases.", pts: ["Invitation: <i>Nous avons le plaisir de vous inviter à… Merci de confirmer votre présence avant le…</i>", "Speech: <i>Chers collègues, je suis très heureuse de vous accueillir… Je tiens à remercier… Je vous souhaite une excellente soirée.</i>", "Assessment: <i>L'événement a été un vrai succès. Les participants se sont déclarés satisfaits. Points à améliorer : …</i>"], ex: [["Nous avons le plaisir de vous inviter à notre séminaire annuel.", "We're pleased to invite you to our annual seminar."], ["Je tiens à remercier toute l'équipe pour son travail.", "I'd like to thank the whole team for its work."]] },
  sons: { t: "Le discours", tip: "Speak slower than in conversation and pause after each thank-you: « Je tiens à remercier… [pause] Claire… [pause] et toute l'équipe. »", ex: ["Je tiens à remercier Claire et toute l'équipe.", "Je vous souhaite une excellente soirée."] },
  cards: [["un séminaire", "a seminar, offsite", "Le séminaire aura lieu en Normandie.", "The offsite will be in Normandy."], ["un salon", "a trade fair", "Nous exposons au salon de l'éducation.", "We're exhibiting at the education fair."], ["un pot de départ", "a farewell drinks", "Tu viens au pot de départ de Marc ?", "Are you coming to Marc's farewell drinks?"], ["confirmer sa présence", "to confirm attendance", "Merci de confirmer votre présence.", "Please confirm your attendance."], ["tenir à", "to be keen to", "Je tiens à vous remercier.", "I'd like to thank you."], ["un intervenant", "a speaker", "Les intervenants étaient passionnants.", "The speakers were fascinating."], ["un succès", "a success", "La soirée a été un succès.", "The evening was a success."], ["lever son verre", "to raise one's glass", "Levons nos verres à cette réussite !", "Let's raise our glasses to this success!"]],
  sent: [["Nous avons le plaisir de vous inviter au lancement de notre nouvelle plateforme.", "We're pleased to invite you to the launch of our new platform."], ["Merci de confirmer votre présence avant le quinze juin.", "Please confirm your attendance before 15 June."], ["Chers collègues, je suis très heureuse de vous accueillir ce soir.", "Dear colleagues, I'm delighted to welcome you tonight."], ["Je tiens à remercier nos intervenants pour leur présence.", "I want to thank our speakers for being here."], ["Levons nos verres au succès de ce projet !", "Let's raise our glasses to this project's success!"], ["L'événement a réuni plus de deux cents participants.", "The event brought together over two hundred participants."], ["Les participants se sont déclarés très satisfaits.", "Participants said they were very satisfied."], ["Point à améliorer : l'accueil était un peu long.", "To improve: reception took a bit long."]],
  gap: [["Nous avons le ___ de vous inviter à notre salon.", "plaisir", "", "We're pleased to invite you to our fair.", ["joie de", "content", "heureux"]], ["Je tiens ___ remercier toute l'équipe.", "à", "", "I'd like to thank the whole team.", ["de", "pour", "en"]], ["Merci de ___ votre présence.", "confirmer", "", "Please confirm your attendance.", ["confirmez", "confirmé", "confirmant"]]],
  mcq: [["Opening a speech:", "Chers collègues, …", ["Salut tout le monde, bon…", "Bref.", "Allez, on mange."], "Formal greeting."], ["A trade fair:", "un salon", ["un pot", "un séminaire", "un afterwork"], "Salon professionnel."]],
  nat: [["Je tiens à vous remercier.", "Je tiens de vous remercier.", "Tenir à."]],
  chat: [["Tu peux dire un petit mot pour le départ de Marc ?", "Bien sûr : « Cher Marc, je tiens à te remercier pour ces cinq belles années… »", ["Marc part, voilà.", "Je tiens de te remercier."], "Speech formula."], ["Alors, ce séminaire ?", "Un vrai succès ! Les intervenants étaient passionnants, même si l'accueil était un peu long.", ["Bof, rien.", "Succès mais pas."], "Nuanced assessment."]]
});

OE({ id: "oe-u7", unit: "u7", lvl: "B2", src: "Objectif Express 2 · Unité 7", t: "Travailler en collaboration", en: "Brainstorming, shared tools, planning together",
  task: "Animer un remue-méninges et organiser un travail en équipe", sf: ["Suggest ideas", "React to others' ideas", "Share tasks and deadlines"], gram: ["Proposer et suggérer : et si…, on pourrait…", "Le futur antérieur pour les échéances"], links: ["b2-futant", "b1-cond"],
  repere: "Collaborative work relies on shared drives, project tools and messaging (Teams, Slack). Brainstorming rules: no criticism at first, quantity before quality. Deadlines are often set as « d'ici vendredi » or « pour la fin du mois », and a <i>rétroplanning</i> plans backwards from the deadline.",
  rule: { h: "Suggest with the conditional or « et si + imparfait »; set deadlines with the futur antérieur.", pts: ["<i>Et si on organisait un webinaire ? On pourrait aussi… Pourquoi ne pas… ?</i>", "Reacting: <i>Bonne idée ! Je rebondis sur ce que dit Paul… Je ne suis pas sûre que ce soit faisable.</i>", "<i>Quand tu auras fini la maquette, envoie-la à Léa. D'ici lundi, nous aurons validé le planning.</i>"], ex: [["Et si on créait une FAQ partagée ?", "What if we created a shared FAQ?"], ["D'ici vendredi, j'aurai terminé la première version.", "By Friday I'll have finished the first version."]] },
  sons: { t: "Rebondir", tip: "Use a rising tone on suggestions: « Et si on essayait… ? » — it invites reaction.", ex: ["Et si on essayait une autre approche ?", "On pourrait peut-être demander l'avis des clients ?"] },
  cards: [["un remue-méninges", "a brainstorm", "Faisons un remue-méninges de dix minutes.", "Let's brainstorm for ten minutes."], ["rebondir sur", "to build on (an idea)", "Je rebondis sur ton idée.", "I'll build on your idea."], ["faisable", "feasible", "Ce n'est pas faisable en une semaine.", "It's not feasible in a week."], ["un document partagé", "a shared document", "J'ai mis le lien vers le document partagé.", "I've posted the link to the shared doc."], ["une échéance", "a deadline", "L'échéance est fixée au 30 avril.", "The deadline is set for 30 April."], ["un rétroplanning", "a backward schedule", "Établissons un rétroplanning.", "Let's draw up a backward schedule."], ["répartir les tâches", "to divide up tasks", "Répartissons les tâches.", "Let's divide up the tasks."], ["d'ici", "by (a date)", "D'ici lundi, tout sera prêt.", "By Monday everything will be ready."]],
  sent: [["Et si on organisait un webinaire pour présenter la nouvelle offre ?", "What if we held a webinar to present the new offer?"], ["Je rebondis sur l'idée de Paul : on pourrait aussi faire une vidéo.", "Building on Paul's idea: we could also make a video."], ["Pour l'instant, on note toutes les idées sans les juger.", "For now we note every idea without judging."], ["Je ne suis pas sûre que ce soit faisable avant l'été.", "I'm not sure it's feasible before summer."], ["Répartissons les tâches : qui s'occupe de la maquette ?", "Let's divide the tasks: who's doing the mock-up?"], ["Quand tu auras terminé la maquette, partage-la dans le dossier commun.", "When you've finished the mock-up, share it in the common folder."], ["D'ici vendredi, nous aurons validé le planning.", "By Friday we'll have approved the schedule."], ["J'ai ajouté mes commentaires directement dans le document partagé.", "I've added my comments directly in the shared doc."]],
  gap: [["Et si on ___ une enquête auprès des clients ?", "faisait|lançait", "faire", "What if we did a customer survey?", ["fera", "ferait", "fasse"]], ["Quand tu ___ fini, préviens-moi.", "auras", "avoir", "When you've finished, let me know.", ["as", "aurais", "avais"]], ["Je ne suis pas sûre que ce ___ possible.", "soit", "être", "I'm not sure it's possible.", ["est", "sera", "serait"]]],
  mcq: [["Suggesting:", "On pourrait demander aux clients.", ["On peut pas.", "Demandez !", "Les clients, non."], "Conditional suggestion."], ["Deadline phrasing:", "d'ici lundi", ["depuis lundi", "il y a lundi", "pendant lundi"], "D'ici = by."]],
  nat: [["Et si on essayait autre chose ?", "Et si on essaierait autre chose ?", "Et si + imparfait."]],
  chat: [["On manque d'idées pour le lancement.", "Et si on organisait un atelier gratuit en ligne ? On pourrait le filmer ensuite.", ["Et si on organiserait…", "Pas d'idée."], "Et si + imparfait."], ["Tu pourras m'envoyer la maquette ?", "Oui, dès que je l'aurai terminée, je la mets dans le dossier partagé.", ["Dès que je la termine hier.", "Oui, quand je l'ai terminerai."], "Futur antérieur."]]
});

OE({ id: "oe-u8", unit: "u8", lvl: "B2", src: "Objectif Express 2 · Unité 8", t: "Ressources humaines", en: "Contracts, annual review, leaving a job",
  task: "Préparer son entretien annuel et comprendre un contrat", sf: ["Understand contract types", "Present your results and goals", "Write a resignation letter"], gram: ["Le discours rapporté au passé", "Les formules de la lettre administrative"], links: ["b2-concordance", "b2-lettre"],
  repere: "Main contracts: <i>CDI</i> (permanent), <i>CDD</i> (fixed-term), <i>intérim</i>, <i>alternance</i>, <i>stage</i>. A <i>période d'essai</i> (trial period) comes first. The <i>entretien annuel d'évaluation</i> reviews objectives. Resigning from a CDI requires a <i>préavis</i> (notice) set by your contract or collective agreement — check yours before writing.",
  rule: { h: "Report what was said in a review with tense shifts; letters follow fixed formulas.", pts: ["<i>Ma manager m'a dit que j'avais atteint mes objectifs et qu'elle soutiendrait ma demande de formation.</i>", "Review: <i>atteindre / dépasser un objectif, un point fort, un axe d'amélioration, une augmentation, une évolution de poste</i>.", "Letter: <i>Madame, Monsieur, Je vous informe par la présente de ma décision de… Je vous prie d'agréer, Madame, l'expression de mes salutations distinguées.</i>"], ex: [["Elle m'a dit que mes résultats étaient excellents.", "She told me my results were excellent."], ["Je vous informe par la présente de ma décision de démissionner.", "I hereby inform you of my decision to resign."]] },
  sons: { t: "Les sigles", tip: "Spell acronyms letter by letter: CDI « cé-dé-i », CDD « cé-dé-dé », RH « air-ache ».", ex: ["J'ai signé un CDI.", "Le service RH m'a contactée."] },
  cards: [["un CDI", "a permanent contract", "Elle vient de signer un CDI.", "She's just signed a permanent contract."], ["un CDD", "a fixed-term contract", "C'est un CDD de six mois.", "It's a six-month fixed-term contract."], ["la période d'essai", "the trial period", "Ma période d'essai dure trois mois.", "My trial period lasts three months."], ["l'entretien annuel", "the annual review", "Mon entretien annuel est mardi.", "My annual review is on Tuesday."], ["un axe d'amélioration", "an area for improvement", "Quels sont tes axes d'amélioration ?", "What are your areas for improvement?"], ["une augmentation", "a pay rise", "J'ai demandé une augmentation.", "I asked for a pay rise."], ["démissionner", "to resign", "Il a décidé de démissionner.", "He decided to resign."], ["le préavis", "the notice period", "Mon préavis est d'un mois.", "My notice period is one month."]],
  sent: [["Cette année, j'ai dépassé mes objectifs de dix pour cent.", "This year I beat my targets by ten percent."], ["Mon point fort, c'est la relation avec les apprenants.", "My strength is my relationship with learners."], ["Mon axe d'amélioration : déléguer davantage.", "My area for improvement: delegating more."], ["Ma manager m'a dit qu'elle soutiendrait ma demande de formation.", "My manager told me she'd support my training request."], ["Elle m'a demandé quels étaient mes objectifs pour l'année suivante.", "She asked me what my goals were for the following year."], ["Je souhaiterais évoluer vers un poste de coordinatrice.", "I'd like to move into a coordinator role."], ["Je vous informe par la présente de ma décision de démissionner.", "I hereby inform you of my decision to resign."], ["Je vous prie d'agréer, Madame, l'expression de mes salutations distinguées.", "Yours faithfully."]],
  gap: [["Elle m'a dit que j'___ atteint mes objectifs.", "avais", "avoir", "She told me I had reached my targets.", ["ai", "aurai", "aurais eu"]], ["Il m'a demandé ce que je ___ faire l'an prochain.", "voulais", "vouloir", "He asked what I wanted to do next year.", ["veux", "voudrai", "veuille"]], ["Je vous ___ d'agréer l'expression de mes salutations distinguées.", "prie", "prier", "Yours faithfully.", ["prends", "demande", "pries"]]],
  mcq: [["Permanent contract:", "un CDI", ["un CDD", "un stage", "l'intérim"], "Contrat à durée indéterminée."], ["« Elle a dit : « Je te soutiendrai. » » →", "Elle a dit qu'elle me soutiendrait.", ["Elle a dit qu'elle me soutiendra.", "Elle a dit je te soutiendrai.", "Elle a dit qu'elle me soutient demain."], "Future → conditional."]],
  nat: [["Il m'a dit qu'il viendrait.", "Il m'a dit qu'il viendra hier.", "Past reporting: conditional."]],
  chat: [["Alors, ton entretien annuel ?", "Très bien : ma manager m'a dit que j'avais dépassé mes objectifs et qu'elle soutiendrait ma formation.", ["Elle m'a dit que j'ai dépassé et elle soutiendra.", "Bof, entretien."], "Reported speech in the past."], ["Tu es en CDI ?", "Oui, depuis janvier, après une période d'essai de trois mois.", ["Oui CDD indéterminé.", "Je suis en essai CDI."], "Contract vocabulary."]]
});

OE({ id: "oe-u9", unit: "u9", lvl: "B2", src: "Objectif Express 2 · Unité 9", t: "Litiges", en: "Handling complaints and disputes",
  task: "Formuler une réclamation et y répondre", sf: ["Write a complaint", "Calm an unhappy client", "Propose compensation"], gram: ["Exprimer le mécontentement avec mesure", "Le conditionnel passé pour le reproche"], links: ["b2-condpasse", "b2-lettre"],
  repere: "In France a written complaint (<i>réclamation</i>) should state facts, dates, references (order, invoice) and what you expect. If unresolved, a <i>lettre recommandée avec accusé de réception</i> (registered letter) and then a <i>médiateur</i> are the usual next steps before going to court.",
  rule: { h: "Complain firmly but politely; answer with apology + explanation + solution.", pts: ["<i>Nous constatons que la livraison n'a toujours pas été effectuée. Vous auriez dû nous prévenir. Nous attendons un geste commercial.</i>", "Answering: <i>Nous sommes sincèrement désolés de ce désagrément. Cela est dû à… Afin de nous faire pardonner, nous vous proposons…</i>", "<i>une réclamation, un litige, un dédommagement, un avoir, un geste commercial, une facture erronée</i>."], ex: [["Vous auriez dû nous informer de ce retard.", "You should have told us about this delay."], ["Afin de nous excuser, nous vous offrons un avoir de cent euros.", "By way of apology, we're offering you a €100 credit note."]] },
  sons: { t: "Rester calme", tip: "Keep a steady, low tone when a client is angry; slow down and repeat their words: « Si je comprends bien, vous n'avez pas reçu… »", ex: ["Si je comprends bien, vous n'avez pas reçu la commande.", "Je comprends tout à fait votre mécontentement."] },
  cards: [["une réclamation", "a complaint", "Nous avons bien reçu votre réclamation.", "We've received your complaint."], ["un litige", "a dispute", "Le litige porte sur la facture.", "The dispute concerns the invoice."], ["un geste commercial", "a goodwill gesture", "Nous vous proposons un geste commercial.", "We're offering you a goodwill gesture."], ["un avoir", "a credit note", "Vous recevrez un avoir.", "You'll receive a credit note."], ["un dédommagement", "compensation", "Le client demande un dédommagement.", "The client is asking for compensation."], ["erroné", "incorrect", "La facture est erronée.", "The invoice is incorrect."], ["un désagrément", "an inconvenience", "Veuillez nous excuser pour ce désagrément.", "Please excuse this inconvenience."], ["le mécontentement", "dissatisfaction", "Je comprends votre mécontentement.", "I understand your dissatisfaction."]],
  sent: [["Nous constatons que la commande du 12 mai n'a toujours pas été livrée.", "We note that the 12 May order still hasn't been delivered."], ["De plus, la facture que nous avons reçue est erronée.", "Moreover, the invoice we received is incorrect."], ["Vous auriez dû nous prévenir de ce retard.", "You should have warned us about this delay."], ["Nous vous demandons de corriger la facture dans les meilleurs délais.", "We ask you to correct the invoice as soon as possible."], ["Nous sommes sincèrement désolés de ce désagrément.", "We're truly sorry for this inconvenience."], ["Ce retard est dû à un problème chez notre transporteur.", "This delay is due to a problem with our carrier."], ["Afin de nous excuser, nous vous proposons un avoir de dix pour cent.", "By way of apology, we offer a ten percent credit."], ["Si je comprends bien, vous avez été facturé deux fois ?", "If I understand correctly, you were invoiced twice?"]],
  gap: [["Vous ___ dû nous prévenir.", "auriez", "avoir", "You should have warned us.", ["aviez", "aurez", "avez"]], ["Ce retard est dû ___ une grève.", "à", "", "This delay is due to a strike.", ["de", "par", "pour"]], ["Nous sommes désolés ___ ce désagrément.", "de|pour", "", "We're sorry for this inconvenience.", ["à", "par", "avec"]]],
  mcq: [["A credit note:", "un avoir", ["un devis", "un litige", "une remise en main"], "Avoir."], ["Reproach (past):", "Vous auriez dû appeler.", ["Vous devez appeler hier.", "Vous devriez appelé.", "Vous aviez devoir appeler."], "Conditionnel passé."]],
  nat: [["Vous auriez dû nous informer.", "Vous auriez dû de nous informer.", "Devoir + infinitive, no de."]],
  chat: [["C'est inadmissible, ça fait trois semaines que j'attends !", "Je comprends tout à fait votre mécontentement ; ce retard est dû à notre transporteur, et nous vous offrons la livraison.", ["Calmez-vous.", "Ce n'est pas ma faute."], "Apology, cause, solution."], ["Qu'est-ce que vous attendez de nous ?", "Une facture corrigée et un geste commercial pour le retard.", ["Rien.", "Que vous auriez dû."], "State expectations."]]
});

OE({ id: "oe-u10", unit: "u10", lvl: "B2", src: "Objectif Express 2 · Unité 10", t: "Projets", en: "Roles, scoping and corrective action",
  task: "Présenter un projet, son avancement et les mesures correctives", sf: ["Present roles in a project", "Describe progress and risks", "Propose corrective measures"], gram: ["Le but et la conséquence", "Le passif pour l'avancement"], links: ["b2-but", "b2-passif"],
  repere: "French project vocabulary mixes French and English: <i>chef de projet</i>, <i>cahier des charges</i> (specifications), <i>jalon</i> (milestone), <i>livrable</i> (deliverable), <i>comité de pilotage</i> (steering committee), and often « kick-off », « reporting ».",
  rule: { h: "Report progress with the passive; justify actions with goal and consequence.", pts: ["<i>La phase de test a été achevée. Deux livrables ont été validés.</i>", "Goal: <i>afin de, pour que + subjonctif, de sorte que</i>. Consequence: <i>donc, par conséquent, c'est pourquoi, si bien que</i>.", "Project: <i>le cahier des charges, un jalon, un livrable, le comité de pilotage, prendre du retard, une mesure corrective</i>."], ex: [["Le cahier des charges a été validé la semaine dernière.", "The specifications were approved last week."], ["Nous avons pris du retard, c'est pourquoi nous renforçons l'équipe.", "We've fallen behind, so we're strengthening the team."]] },
  sons: { t: "Présenter", tip: "Signpost your presentation: « Premièrement… Deuxièmement… Pour finir… », with a pause after each.", ex: ["Premièrement, l'état d'avancement.", "Pour finir, les mesures correctives."] },
  cards: [["un chef de projet", "a project manager", "La cheffe de projet présente le planning.", "The project manager presents the schedule."], ["le cahier des charges", "specifications", "Le cahier des charges est très précis.", "The specs are very precise."], ["un jalon", "a milestone", "Nous avons atteint le deuxième jalon.", "We've reached the second milestone."], ["un livrable", "a deliverable", "Le premier livrable est prêt.", "The first deliverable is ready."], ["le comité de pilotage", "the steering committee", "Le comité de pilotage se réunit jeudi.", "The steering committee meets Thursday."], ["prendre du retard", "to fall behind", "Le projet a pris deux semaines de retard.", "The project is two weeks behind."], ["une mesure corrective", "a corrective action", "Quelles mesures correctives proposez-vous ?", "What corrective actions do you suggest?"], ["l'état d'avancement", "progress status", "Voici l'état d'avancement du projet.", "Here's the project status."]],
  sent: [["Voici l'état d'avancement du projet de plateforme en ligne.", "Here's the progress of the online platform project."], ["Le cahier des charges a été validé par le client en janvier.", "The specs were approved by the client in January."], ["Deux livrables sur trois ont déjà été livrés.", "Two of three deliverables have been delivered."], ["Nous avons pris deux semaines de retard sur le développement.", "We're two weeks behind on development."], ["C'est pourquoi nous proposons de renforcer l'équipe technique.", "That's why we propose strengthening the tech team."], ["Afin de respecter l'échéance, les tests seront faits en parallèle.", "To meet the deadline, tests will run in parallel."], ["Le prochain comité de pilotage aura lieu le 4 juin.", "The next steering committee is on 4 June."], ["Il faut agir vite pour que le lancement ne soit pas reporté.", "We must act fast so the launch isn't postponed."]],
  gap: [["Le premier livrable a ___ validé.", "été", "", "The first deliverable has been approved.", ["est", "était", "ayant"]], ["Nous recrutons un développeur ___ rattraper le retard.", "afin de|pour", "", "We're hiring a developer to catch up.", ["afin que", "pour que", "donc"]], ["Il faut agir pour que le projet ___ à l'heure.", "soit livré", "", "We must act so the project is delivered on time.", ["est livré", "sera livré", "serait livré"]]],
  mcq: [["Milestone:", "un jalon", ["un livrable", "un cahier", "un comité"], "Jalon."], ["Pour que + …", "subjonctif", ["indicatif", "infinitif", "conditionnel"], "Pour que + subjunctive."]],
  nat: [["Nous avons pris du retard.", "Nous avons pris un retard de.", "Prendre du retard."]],
  chat: [["Où en est le projet ?", "Deux livrables ont été validés, mais nous avons pris une semaine de retard sur les tests.", ["Deux livrables ont validé.", "Ça avance bien je crois."], "Passive progress report."], ["Qu'est-ce que vous proposez ?", "De faire les tests en parallèle afin de respecter l'échéance du 30 juin.", ["Afin que respecter.", "Rien, c'est trop tard."], "Goal: afin de."]]
});

OE({ id: "oe-u11", unit: "u11", lvl: "B2", src: "Objectif Express 2 · Unité 11", t: "S'informer", en: "Social conflict, economic news, debating",
  task: "Comprendre l'actualité économique et sociale et en débattre", sf: ["Understand economic news", "Explain a social conflict", "Take part in a debate"], gram: ["La cause et la conséquence", "Exprimer son accord et son désaccord"], links: ["b2-cause", "b2-argu"],
  repere: "Workplace dialogue in France goes through <i>syndicats</i> (unions) and the <i>CSE</i> (works council). A <i>grève</i> (strike) is a constitutional right; <i>négociations annuelles obligatoires</i> cover pay. Economic news uses terms like <i>croissance</i>, <i>chômage</i>, <i>pouvoir d'achat</i> and <i>inflation</i>.",
  rule: { h: "Explain causes and effects; agree or disagree with nuance.", pts: ["Cause: <i>en raison de, à cause de, grâce à, suite à, étant donné que</i>. Effect: <i>entraîner, provoquer, si bien que, d'où</i>.", "Agree: <i>Je partage votre avis. C'est tout à fait juste.</i> Disagree: <i>Je ne suis pas tout à fait d'accord. Permettez-moi de nuancer.</i>", "<i>la croissance, le chômage, le pouvoir d'achat, une grève, un syndicat, une revendication, des négociations</i>."], ex: [["En raison de la hausse des prix, les salariés réclament une augmentation.", "Because of rising prices, employees are demanding a raise."], ["Permettez-moi de nuancer : la grève a aussi des effets positifs.", "Let me qualify that: the strike also has positive effects."]] },
  sons: { t: "Débattre", tip: "To take the floor, use a short phrase and a breath: « Si je peux me permettre… », « Pour rebondir… ».", ex: ["Si je peux me permettre, je voudrais ajouter un point.", "Pour rebondir sur ce qui vient d'être dit…"] },
  cards: [["la croissance", "growth", "La croissance a ralenti.", "Growth has slowed."], ["le chômage", "unemployment", "Le chômage est en baisse.", "Unemployment is falling."], ["le pouvoir d'achat", "purchasing power", "Le pouvoir d'achat est au cœur du débat.", "Purchasing power is central to the debate."], ["une grève", "a strike", "Les salariés sont en grève.", "The employees are on strike."], ["un syndicat", "a trade union", "Le syndicat a appelé à la grève.", "The union called a strike."], ["une revendication", "a demand", "Leur principale revendication porte sur les salaires.", "Their main demand concerns wages."], ["en raison de", "due to", "Le vol est annulé en raison de la grève.", "The flight is cancelled due to the strike."], ["nuancer", "to qualify, nuance", "Je voudrais nuancer ce point.", "I'd like to qualify this point."]],
  sent: [["En raison de l'inflation, le pouvoir d'achat des ménages a baissé.", "Due to inflation, household purchasing power has fallen."], ["Les syndicats ont appelé à une grève nationale jeudi.", "The unions called a national strike on Thursday."], ["Leur principale revendication porte sur la hausse des salaires.", "Their main demand is about wage increases."], ["Le chômage a reculé grâce à la reprise de l'activité.", "Unemployment fell thanks to the economic recovery."], ["La hausse des taux a entraîné un ralentissement de l'immobilier.", "Rising rates led to a slowdown in property."], ["Je partage votre avis sur ce point.", "I share your view on this point."], ["Je ne suis pas tout à fait d'accord : il faut nuancer.", "I don't fully agree: it needs nuance."], ["Si je peux me permettre, les chiffres montrent l'inverse.", "If I may, the figures show the opposite."]],
  gap: [["Le train est supprimé en raison ___ la grève.", "de", "", "The train is cancelled due to the strike.", ["à", "par", "pour"]], ["Le chômage a baissé ___ à la croissance.", "grâce", "", "Unemployment fell thanks to growth.", ["à cause", "en raison", "suite"]], ["Je ne suis pas tout à fait ___.", "d'accord", "", "I don't entirely agree.", ["accord", "en accord de", "accordé"]]],
  mcq: [["Positive cause:", "grâce à", ["à cause de", "en raison de", "faute de"], "Grâce à = thanks to."], ["Polite disagreement:", "Permettez-moi de nuancer.", ["N'importe quoi.", "Vous avez tort.", "Taisez-vous."], "Nuancer."]],
  nat: [["La hausse des prix a entraîné des grèves.", "La hausse des prix a entraîné à des grèves.", "Entraîner + direct object."]],
  chat: [["Pourquoi tout le monde est en grève ?", "En raison de l'inflation, les salariés réclament une hausse des salaires.", ["Grâce à l'inflation…", "Parce que grève."], "Explain the cause."], ["Les grèves ne servent à rien, non ?", "Permettez-moi de nuancer : elles ont parfois permis d'obtenir des accords importants.", ["Oui, rien.", "Je suis pas d'accord, voilà."], "Nuanced disagreement."]]
});

OE({ id: "oe-u12", unit: "u12", lvl: "B2", src: "Objectif Express 2 · Unité 12", t: "Rendre compte", en: "Reports, figures and results",
  task: "Rédiger un rapport et présenter des résultats chiffrés", sf: ["Describe figures and trends", "Structure a report", "Make recommendations"], gram: ["Décrire une évolution", "La nominalisation et les connecteurs du rapport"], links: ["c1-nominal", "c1-synthese"],
  repere: "A French <i>rapport</i> has a clear plan: <i>introduction (contexte, objectif)</i>, <i>constat</i>, <i>analyse</i>, <i>recommandations</i>, <i>conclusion</i>. Figures use a comma for decimals (<i>3,5 %</i>) and a space for thousands (<i>12 500 €</i>).",
  rule: { h: "Describe trends precisely with verbs, nouns and adverbs.", pts: ["Up: <i>augmenter, progresser, une hausse, une progression</i>. Down: <i>baisser, diminuer, reculer, une baisse, un recul</i>. Flat: <i>se stabiliser, stagner</i>.", "Degree: <i>légèrement, nettement, fortement, de 5 %, passer de… à…</i>", "Report connectors: <i>Il ressort de cette analyse que…, Au vu de ces résultats…, Nous recommandons de…</i>"], ex: [["Le chiffre d'affaires a progressé de huit pour cent en un an.", "Turnover grew by eight percent in a year."], ["Au vu de ces résultats, nous recommandons de développer l'offre en ligne.", "Given these results, we recommend developing the online offer."]] },
  sons: { t: "Les nombres", tip: "Decimals are read with <i>virgule</i>: 3,5 % « trois virgule cinq pour cent »; 12 500 « douze mille cinq cents ».", ex: ["Les ventes ont augmenté de trois virgule cinq pour cent.", "Nous avons formé douze mille cinq cents apprenants."] },
  cards: [["le chiffre d'affaires", "turnover, revenue", "Le chiffre d'affaires est en hausse.", "Revenue is up."], ["une hausse", "a rise", "On observe une hausse des inscriptions.", "We see a rise in registrations."], ["un recul", "a decline", "Les ventes sont en recul.", "Sales are declining."], ["se stabiliser", "to level off", "Le taux s'est stabilisé.", "The rate has levelled off."], ["nettement", "markedly", "Les résultats sont nettement meilleurs.", "Results are markedly better."], ["un constat", "a finding", "Premier constat : la demande augmente.", "First finding: demand is rising."], ["il ressort que", "it emerges that", "Il ressort de l'enquête que les clients sont satisfaits.", "The survey shows clients are satisfied."], ["une recommandation", "a recommendation", "Le rapport contient trois recommandations.", "The report contains three recommendations."]],
  sent: [["Ce rapport a pour objectif d'analyser les résultats du premier semestre.", "This report aims to analyse first-half results."], ["Le chiffre d'affaires a progressé de huit pour cent par rapport à l'an dernier.", "Revenue rose eight percent on last year."], ["Le nombre d'inscriptions est passé de mille deux cents à mille cinq cents.", "Registrations went from 1,200 to 1,500."], ["En revanche, les ventes en magasin ont légèrement reculé.", "On the other hand, in-store sales fell slightly."], ["Le taux de satisfaction s'est stabilisé autour de quatre-vingt-dix pour cent.", "Satisfaction levelled off at around ninety percent."], ["Il ressort de cette analyse que la formation en ligne est porteuse.", "This analysis shows online training is promising."], ["Au vu de ces résultats, nous recommandons d'investir dans le numérique.", "Given these results, we recommend investing in digital."], ["En conclusion, le semestre est globalement positif.", "In conclusion, the half-year is broadly positive."]],
  gap: [["Les ventes ont augmenté ___ cinq pour cent.", "de", "", "Sales rose by five percent.", ["à", "par", "en"]], ["Le nombre de clients est passé de 200 ___ 260.", "à", "", "Customers went from 200 to 260.", ["de", "en", "vers"]], ["Il ___ de l'enquête que les clients sont satisfaits.", "ressort", "ressortir", "The survey shows that clients are satisfied.", ["sort", "ressortit", "ressortent"]]],
  mcq: [["A fall in figures:", "un recul", ["une hausse", "une progression", "un essor"], "Recul = decline."], ["« 3,5 % » is read…", "trois virgule cinq pour cent", ["trois point cinq pour cent", "trois et demi pourcent virgule", "trente-cinq pour cent"], "Comma = virgule."]],
  nat: [["Les ventes ont augmenté de 10 %.", "Les ventes ont augmenté par 10 %.", "Augmenter de."]],
  chat: [["Alors, ces résultats ?", "Plutôt bons : le chiffre d'affaires a progressé de huit pour cent, même si les ventes en magasin ont reculé.", ["Bons, plus huit par cent.", "Ça monte, ça descend."], "Precise trend description."], ["Que recommandez-vous ?", "Au vu de ces résultats, nous recommandons de développer l'offre en ligne.", ["Au vu de, rien.", "Recommandons développer."], "Recommendation formula."]]
});

